"use strict";
window.SPACR_LESSON_CATALOG = Object.freeze({"schema": 1, "title": "spaCR complete tutorial library", "series": [{"number": 1, "title": "Getting started and core analysis"}, {"number": 2, "title": "Time-resolved analysis and segmentation models"}, {"number": 3, "title": "Annotation quality control and biological assays"}, {"number": 4, "title": "Operations, reporting, and data utilities"}, {"number": 5, "title": "Additional registered modules"}], "lessons": [{"id": "01_pypi_github", "number": 1, "slug": "pypi_github", "title": "PyPI, GitHub, and conda-forge", "series": 1, "app_key": null, "section": "spaCR", "description": "Find the official package and installer sources, compare the release available on each channel, and choose the matching installation tutorial.", "objectives": ["Identify spaCR's official PyPI, GitHub and conda-forge pages.", "Distinguish release assets, development source and independently updated package channels.", "Choose an installation route and check the version actually installed."], "prerequisite": "No installation is performed in this overview. The live pages were captured on 2026-09-10: PyPI and GitHub offer 1.5.0.5, while conda-forge offers 1.5.0.4. Channel versions and available files can change; read the current page and verify your installed version. Browser captures use an anonymous profile with page text, badges and release history left intact. Platform-specific installation and hardware choices belong to the linked installation lessons.", "scenes": [{"visual": "01_pypi_current_release", "narration": "Before installing spaCR, choose its official distribution source. PyPI and conda-forge provide Python packages; GitHub provides source code, release records and desktop installers. These routes are related, but they do not necessarily publish the same version at the same time.", "hold_after": 0.7}, {"visual": "01_pypi_current_release", "narration": "On PyPI, read the release header and the installation command. The header here is spaCR one point five point zero point five. Check this live value instead of inferring the release from an old screenshot, a badge or a tutorial's date.", "hold_after": 0.7, "focus": [770, 237, 2300, 305]}, {"visual": "02_pypi_project_links", "narration": "Project links connects the package to its documentation, homepage, issue tracker and source repository. Use these links to move between the official resources. A package page describes that published release; it is not a guarantee that every development feature is already included.", "hold_after": 0.7, "focus": [2510, 798, 500, 399]}, {"visual": "03_github_main_branch", "narration": "On GitHub, the branch selector identifies the source line you are reading. Main is the release line and nightly contains ongoing development. Choose a release for routine installation; use nightly only when you deliberately need newer work and can tolerate changes.", "hold_after": 0.7, "focus": [704, 412, 214, 64]}, {"visual": "04_github_current_assets", "narration": "Open a release and expand Assets. Match the installer to Windows, macOS or Linux. The wheel and source distribution are Python package files, not desktop installers. Download the checksum list for the exact release and file you selected, rather than comparing hashes from another channel.", "hold_after": 0.7, "focus": [738, 1103, 2364, 758], "related_lessons": ["04_platform_installers"]}, {"visual": "05_conda_current_package", "narration": "The conda-forge page has its own version selector. At this recording it offers one point five point zero point four, while PyPI offers one point five point zero point five. That difference is visible and intentional in this demonstration; do not assume a channel update has already arrived.", "hold_after": 0.7, "focus": [60, 710, 2435, 635]}, {"visual": "05_conda_current_package", "narration": "The channel-qualified command is conda install conda-forge colon colon spacr. Run it inside the environment you intend to use. The Conda tutorial covers that route; creating a Conda environment and installing with pip is a different route, even though both use an environment manager.", "hold_after": 0.7, "focus": [60, 710, 2435, 635], "related_lessons": ["02_conda_install"]}, {"visual": "01_pypi_current_release", "narration": "Choose the pip lesson for a Python virtual environment, the Conda lesson for the channel package, or Platform installers for a private runtime managed by the installer. Afterwards, verify the installed version and run spacr-doctor before following the module tutorials.", "hold_after": 0.7, "related_lessons": ["02_conda_install", "03_pip_install", "04_platform_installers"]}], "poster": "01_pypi_github/poster.jpg", "silent": "01_pypi_github/video/01_pypi_github_silent.mp4"}, {"id": "02_conda_install", "number": 2, "slug": "conda_install", "title": "Installation with Conda", "series": 1, "app_key": null, "section": "spaCR", "description": "Install the official conda-forge package in a separate environment, verify the actual channel version, and recognize when that version differs from the current module tutorials.", "objectives": ["Create and activate a dedicated Conda environment.", "Verify the installed channel package, Qt and diagnostic results.", "Choose the newer pip or desktop-installer route when the channel still has the older interface."], "prerequisite": "A Conda-compatible manager must already be installed. This recording verifies conda-forge spaCR 1.5.0.4 on Linux, with Python 3.12.14 and Qt 6.11.2, on 2026-09-10. The clean installation used a new private prefix, only conda-forge, and the pinned channel version; command cards illustrate the corresponding named-environment workflow rather than replaying installation output. The actual GUI still has Home (63), not the new nested layout in PyPI/installer 1.5.0.5. Default spacr-doctor performed its small CUDA allocation check successfully but warned about optional CZI support; this is not a speed benchmark or verification of every analysis or format. The native capture uses a private dark profile at font scale 1.5 with the tour already dismissed, unchanged preload defaults and no unsupported --no-setup flag. Other platforms were not tested. Original authoring and published narration differ, so unchanged audio reuse is not claimed.", "scenes": [{"visual": "02_conda_environment", "narration": "Use a dedicated Conda environment for spaCR, and check which release the channel actually provides. At this recording, conda-forge installs one point five point zero point four. PyPI and the desktop installer already offer one point five point zero point five; these are not interchangeable version labels.", "hold_after": 0.7}, {"visual": "07_create_conda", "narration": "Open a Conda-enabled shell and create a new environment with Python three point twelve. The command card uses the name spacr-conda. Choose another unused name if it already exists, and keep this environment separate from ongoing analyses.", "hold_after": 0.7}, {"visual": "08_activate_conda", "narration": "Activate the environment and print sys dot prefix to confirm where Python belongs. The actual verification uses a longer private prefix instead of the short example name. A terminal prompt alone is not proof that you are using the intended interpreter.", "hold_after": 0.7}, {"visual": "09_install_conda", "narration": "Install the channel-qualified conda-forge package, then use conda list spacr to inspect the version and channel. Our recorded installation used only conda-forge and pinned the channel release. Its installation completed before the verification frames; these cards are instructions, not fabricated terminal output.", "hold_after": 0.7}, {"visual": "03_installed_versions", "narration": "Check the spaCR version, Qt version and package location in the installed environment. Here the package is one point five point zero point four and Qt imports successfully. This proves which package is active, not that every scientific workflow or optional format has been validated.", "hold_after": 0.7}, {"visual": "05_doctor", "narration": "Run spacr-doctor and read the warnings too. Here its small GPU allocation check succeeds, while optional CZI support has a missing dependency. Skipped checks are not passes. The suggested repair concerns that feature; assess any environment changes before applying it, especially when mixing package managers.", "hold_after": 0.7}, {"visual": "06_installed_home", "narration": "The installed Conda package opens and closes normally, but this is its older Home with sixty-three tiles. It does not have the new nested module layout. Do not assume that a successful installation means every screen matches tutorials for a newer release.", "hold_after": 0.7}, {"visual": "10_current_release_choice", "narration": "For the newer nested interface shown in the refreshed module tutorials, use the current pip or Platform installers lesson in a separate environment. If you need the Conda channel, keep track of its actual release and check again for updates. Preserve the version used for an ongoing analysis.", "related_lessons": ["01_pypi_github", "03_pip_install", "04_platform_installers"], "hold_after": 0.7}], "poster": "02_conda_install/poster.jpg", "silent": "02_conda_install/video/02_conda_install_silent.mp4"}, {"id": "03_pip_install", "number": 3, "slug": "pip_install", "title": "Install spaCR with pip", "series": 1, "app_key": null, "section": "spaCR", "description": "Create an isolated Python environment, install the public package, verify its dependencies, and launch the installed Qt application.", "objectives": ["Keep spaCR's dependencies in a dedicated Python environment.", "Verify the installed package, Qt and optional-feature warnings.", "Launch Home and update the intended environment deliberately."], "prerequisite": "This lesson verifies public PyPI spaCR 1.5.0.5 on Linux with Python 3.12.13, not an editable checkout. Command-reference cards are instructions, not recorded terminal output; Windows and macOS commands were not executed here. The actual clean installation completed before the recorded verification. Current base dependencies include Qt. Doctor reports an optional CZI warning; its GPU allocation probe is explicitly skipped. The native GUI capture uses --no-setup, a private dark profile at font scale 1.5, and an already-dismissed tour. It proves a normal Home launch and close, not every module, optional format, GPU computation or another platform.", "scenes": [{"visual": "01_python_version", "narration": "Install spaCR in its own Python environment. This demonstration uses Python three point twelve on Linux and the public PyPI release, not a source checkout. Check python dash dash version before choosing the interpreter for your environment.", "hold_after": 0.7}, {"visual": "07_create_environment", "narration": "Create a new virtual environment with the command for your platform. Here dot venv is a new folder in your working directory. Python three point twelve must already be installed; this command creates an environment, not Python itself.", "hold_after": 0.7}, {"visual": "08_activate_environment", "narration": "Activate that environment using the command for your shell. PowerShell, Command Prompt, bash and zsh use different activation commands. If PowerShell blocks the script, use Command Prompt or call the environment's Python directly; do not weaken machine-wide security settings.", "hold_after": 0.7}, {"visual": "02_pip_environment", "narration": "Run python dash m pip dash dash version. Its location should point inside the environment you chose. This actual terminal shows the longer private path used for the recording. Using python dash m pip ties package installation to that interpreter.", "hold_after": 0.7}, {"visual": "09_install_package", "narration": "Upgrade pip, then install spacr. Pinning one point five point zero point five reproduces this lesson's release. The clean installation completed before these verification frames. Allow time and disk space for scientific dependencies; current base dependencies already include the Qt desktop components.", "hold_after": 0.7}, {"visual": "03_installed_versions", "narration": "Check the installed spaCR version, Qt version and package path. All three come from the new environment here. An import alone does not prove that every optional format or analysis works, and it does not prove the window will open.", "hold_after": 0.7}, {"visual": "04_dependency_check", "narration": "Run python dash m pip check. No broken requirements means the installed dependency declarations are consistent. If it reports a conflict, resolve it before proceeding; a successful check is not a scientific validation of an analysis.", "hold_after": 0.7}, {"visual": "05_doctor", "narration": "Run spacr-doctor and read warnings as well as passes. This installation has an optional CZI warning, with its repair command shown. The recording uses dash dash no gpu probe, so it detects the device but does not test a GPU allocation. Skipped checks are not passes.", "hold_after": 0.7}, {"visual": "10_launch_commands", "narration": "Launch spacr from the same activated environment. A normal first launch may ask setup questions. This bounded verification explicitly uses dash dash no setup and a prepared recording profile, so it does not demonstrate answering those questions.", "hold_after": 0.7}, {"visual": "06_installed_home", "narration": "This is the actual Home window from the installed wheel, with the six core modules and the Data, Tools and Assays groups. It opened and closed normally without starting an analysis. Continue with Home for navigation, nested tools and the module tutorials.", "related_lessons": ["05_home"], "hold_after": 0.7}, {"visual": "11_update_intentionally", "narration": "For an update, close spaCR and activate the environment you intend to change. Upgrade the package, repeat pip check and spacr-doctor, and record the resulting version with your analysis. Upgrades can change dependencies and behaviour; do not silently change an environment supporting ongoing work.", "related_lessons": ["01_pypi_github", "04_platform_installers"], "hold_after": 0.7}], "poster": "03_pip_install/poster.jpg", "silent": "03_pip_install/video/03_pip_install_silent.mp4"}, {"id": "04_platform_installers", "number": 4, "slug": "platform_installers", "title": "Platform installers", "series": 1, "app_key": null, "section": "spaCR", "description": "Choose an official desktop installer, understand automatic accelerator selection and optional privacy choices, and verify the actual installed Linux runtime.", "objectives": ["Select the official installer for the operating system.", "Distinguish automatic acceleration from an explicit CPU-only choice.", "Read privacy choices, installed versions and diagnostic warnings."], "prerequisite": "This recording verifies the checksum-matched public Linux x86-64 online installer for spaCR 1.5.0.5 on 2026-09-10, with Python 3.12.13, Qt 6.11.2 and Torch 2.14.0+cu132. The real install finished before these verification frames. It used a new private runtime and launcher directory, existing system GUI libraries, --skip-system-deps and --no-launch; no existing environment or system dependency was changed. Four reference cards are instructions, not recorded Windows/macOS installations or fabricated terminal output. Windows/macOS guidance was checked against current installer source only. The GUI recording uses a private dark profile at font scale 1.5, a dismissed tour, on-demand preload and --no-setup, which does not bypass the separate privacy prompt. Native Escape rejects that prompt with every optional choice off; the private preferences were read back. Doctor used --no-gpu-probe; no allocation, speed, analysis or other-platform validation is claimed. Earlier failed recorder takes are retained, not counted as application defects.", "scenes": [{"visual": "08_official_release", "narration": "Use the official spaCR GitHub release and match the installer to your operating system. The online installers download a private Python runtime and scientific dependencies; an existing Conda environment is not required. For this Linux example, we checked the downloaded file against the release checksum before running it.", "hold_after": 0.7}, {"visual": "09_windows_guidance", "narration": "On Windows, select the online setup executable. The current installer source preselects automatic acceleration; its optional component can be unticked for CPU-only operation. This card explains that choice, but it is not a Windows installation recording or a compatibility test on your computer.", "hold_after": 0.7}, {"visual": "10_macos_guidance", "narration": "On macOS, select the universal online package for Intel and Apple silicon. The app launcher starts per-user setup if its runtime is missing. Verify the official source before approving security prompts, and allow time for downloads. This is source-reviewed guidance, not an executed macOS installation.", "hold_after": 0.7}, {"visual": "11_linux_commands", "narration": "On Linux, make the verified download executable and run it from its folder. Automatic accelerator selection is now the default; request the CPU backend explicitly if that is what you need. Our isolated run reused existing system libraries and used private paths, so it did not demonstrate installing system dependencies.", "hold_after": 0.7}, {"visual": "02_installer_backend", "narration": "Read the actual install profile rather than inferring the backend from a successful launch. Here the request was auto and the selected backend is CUDA on NVIDIA hardware. The installed Torch build is CUDA thirteen point two. This identifies the selection; it is not a GPU speed benchmark.", "hold_after": 0.7}, {"visual": "03_installed_versions", "narration": "Check the installed package version, Qt import and package path. This private runtime contains spaCR one point five point zero point five. Its files come from the installation, not an editable source checkout. Successful imports do not validate every analysis or optional file format.", "hold_after": 0.7}, {"visual": "07_privacy_keep_off", "narration": "The real first launch asks about optional diagnostic sharing, public issue reports and account setup. Reports would be public, so read the explanation. This recording rejects the dialog with Escape, equivalent to Skip, keep all off. No accounts are connected, and the private preferences confirm that sharing and issue actions remain off.", "hold_after": 0.7}, {"visual": "06_installed_home", "narration": "After that choice, the installed application opens its current Home with twenty-one tiles and six core modules. The window closes normally too. Continue with the Home lesson to learn the nested workflows and their example data; opening Home alone is not an analysis test.", "related_lessons": ["05_home"], "hold_after": 0.7}, {"visual": "05_doctor", "narration": "Run spacr-doctor from the installed runtime and read warnings as well as passes. Here it confirms the installer backend but warns about a missing optional CZI dependency. This run skipped GPU allocation, database and settings checks. A skipped check is not a pass; assess the suggested repair before changing the environment.", "hold_after": 0.7}, {"visual": "12_logs_and_versions", "narration": "Keep install dot log and install-profile dot json from the chosen installation directory when diagnosing a problem. Review logs for private information before sharing them. Record the version used for each analysis, and treat updates deliberately. The pip and Conda lessons describe the separate environment-based installation routes.", "related_lessons": ["01_pypi_github", "02_conda_install", "03_pip_install"], "hold_after": 0.7}], "poster": "04_platform_installers/poster.jpg", "silent": "04_platform_installers/video/04_platform_installers_silent.mp4"}, {"id": "05_home", "number": 5, "slug": "home", "title": "Home screen and navigation", "series": 1, "app_key": null, "section": "spaCR", "description": "Find the six-step Core workflow, explore the current Home categories, and locate related tools inside their host modules.", "objectives": ["Follow the current Core workflow from images to regression results.", "Find Data, Tools, and Assays without mistaking a folded action for a missing module.", "Distinguish real test-data downloads from generated demos and find the matching specialist tutorials."], "prerequisite": "Install spaCR and open the desktop application. The recording uses the dark theme with larger interface text.", "scenes": [{"visual": "00_home", "narration": "Home organizes spaCR into Core, Data, Tools, and Assays. These are workflow categories. Related tools can also live inside a parent module, so the tiles are not a list of every capability.", "hold_after": 0.7}, {"visual": "01_core  (6)", "narration": "Core follows the screen-analysis pipeline: Mask, Measure, Annotate, Classify, Map Barcodes, and Regression. Start at the step that matches your inputs. You do not need to repeat segmentation when you already have compatible measurements or crops.", "hold_after": 0.7, "focus_modules": ["mask", "measure", "annotate", "classify_merged", "map_barcodes", "regression"], "related_lessons": ["07_mask", "08_measure", "09_annotate", "41_classify", "12_map_barcodes", "13_regression"]}, {"visual": "02_data  (6)", "narration": "Data brings together Import, Run Compare, Experiment Design, Power and Design, Dose Response, and quality control. Import is also the entry point for Import Images, Format Converter, and External Masks. Open the parent first to find those workflows.", "hold_after": 0.7, "focus_modules": ["foreign", "run_compare", "experiment_design", "power", "dose_response", "qc_dashboard"], "related_lessons": ["36_import", "35_converter", "31_external_masks"]}, {"visual": "03_tools  (5)", "narration": "Tools contains Make Masks, Align and Stitch, Image UMAP, Gate Editor, and Graph Builder. Each is a workbench with related actions. For example, Make Masks hosts model training and comparison, while Graph Builder hosts Plate Viewer and Small Multiples.", "hold_after": 0.7, "focus_modules": ["make_masks", "align", "umap", "gate_editor", "graph_builder"], "related_lessons": ["14_make_masks", "32_align_stitch", "15_image_umap", "64_gate_editor", "58_graph_builder"]}, {"visual": "04_assays  (4)", "narration": "Assays groups Plaque Assay, Recruitment, Invasion Assay, and Replication Assay. Choose a workflow that matches the experiment and its required inputs. A module's maturity color is separate from its category; read its tooltip before relying on an experimental feature.", "hold_after": 0.7, "focus_modules": ["analyze_plaques", "recruitment", "invasion", "replication"], "related_lessons": ["24_plaque", "25_recruitment", "26_invasion", "27_replication"]}, {"visual": "05_classify_host", "narration": "Classify is one module. Its Classifier family setting chooses image-based computer vision or machine learning from measured features. The older computer-vision and machine-learning tutorials remain focused walkthroughs of those two routes, not separate Home tiles.", "hold_after": 0.7, "focus": [345, 540, 1160, 170], "related_lessons": ["41_classify", "10_classify_cv", "11_classify_ml"]}, {"visual": "05_classify_host", "narration": "The icons at the top of Classify open Classifier Evaluation, Explain CV Model, Activation, Training Runs, and Feature Explorer. Hover for the name and description. Use the linked specialist lesson when you are ready to inspect a trained model or its results.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["39_classifier_evaluation", "70_explain_cv", "16_activation", "28_training_runs", "65_feature_explorer"]}, {"visual": "06_mask_host", "narration": "Core tutorials use the real datasets offered by Load test data. Downloading fills the relevant inputs and compatible settings. The generated demos under Help are a different option. In Mask, the Time and three-D switches reveal time-series and volumetric workflows; Live opens the preview.", "hold_after": 0.7, "related_lessons": ["07_mask", "17_timelapse"]}, {"visual": "07_help", "narration": "Use Help to return to walkthroughs and tutorials. Keep the tutorial for your current module beside the application, and follow its dataset, settings, and output checks. The next lesson shows how the same workflows connect to the Python API and command line.", "hold_after": 0.7, "related_lessons": ["06_api"]}], "poster": "05_home/poster.jpg", "silent": "05_home/video/05_home_silent.mp4"}, {"id": "06_api", "number": 6, "slug": "api", "title": "Python API and current headless workflows", "series": 1, "app_key": null, "section": "spaCR", "description": "Discover the installed batch routes, distinguish interactive tools from Python functions, and inspect a real example's dry run without claiming an analysis was executed.", "objectives": ["Confirm the package version in the active Python environment.", "Discover current command keys and the functions they actually call.", "Distinguish an interactive workflow, a Python function and a batch command.", "Read a dry run's settings, exit status and limitations before unattended work."], "prerequisite": "Complete an installation lesson first. For the demonstrated preflight, use the downloaded paired data and saved settings from the Regression lesson; replace this machine's paths with your own. No analysis or report is generated in this recording.", "scenes": [{"visual": "01_version", "focus": [200, 100, 1900, 650], "narration": "In the environment where you installed spaCR, import the package and print its version. This real terminal reports version one point five point zero point four. Confirm your own version before following commands, because an older environment can expose different functions and settings.", "related_lessons": ["02_conda_install", "03_pip_install", "04_platform_installers"], "hold_after": 0.7}, {"visual": "02_list", "focus": [200, 100, 2800, 1900], "narration": "Run spacr-run with the list option. Its batch section prints exact command keys and Python entry points, including mask, measure and classify_merged. Home screen names and nested buttons are not automatically batch commands. Use the installed list rather than guessing a key from a tutorial title.", "hold_after": 0.7}, {"visual": "03_describe", "focus": [200, 100, 2250, 900], "narration": "Describe regression to see the function perform_regression in spacr.ml, its defaults provider and its input requirements. This connects the command to the actual analysis function. The saved paired-data settings used here come from the linked Regression example, not an invented measurements folder.", "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "04_gui_only", "focus": [200, 100, 2800, 700], "narration": "Annotate is an interactive workflow. Calling spacr-run annotate really returns exit status two and explains that there is no batch equivalent. Use Annotate in the desktop application to label crops. This expected refusal is not evidence that the installation is broken.", "related_lessons": ["09_annotate"], "hold_after": 0.7}, {"visual": "05_report_api", "focus": [200, 100, 2800, 700], "narration": "Other capabilities have a Python API without a matching batch key. Here we import build_report from spacr.report and inspect its real signature. We do not call it or generate a report. Check the function's documentation and arguments instead of assuming that spacr-run report exists.", "hold_after": 0.7}, {"visual": "06_dry_run", "focus": [200, 1320, 3440, 680], "narration": "Pass regression the saved settings file and add the dry-run option. The real command resolves settings and runs its preflight checks, then explicitly says perform_regression was not called. Read the exit status and messages; this recording did not start another regression or write its analysis outputs.", "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "06_dry_run", "focus": [200, 1320, 3440, 680], "narration": "A clean preflight is not proof that the full analysis or its science will succeed. This build's generic plan mentions a measurements database even though our regression uses paired tables. Inspect the module's actual inputs, and test a bounded run before relying on unattended execution.", "hold_after": 0.7}, {"visual": "03_describe", "focus": [200, 100, 2250, 900], "narration": "Remove dry-run only when you intend to execute the analysis. Keep the exact settings, input identifiers, package version and console log with its outputs. Follow the linked module lesson for a demonstrated run and inspect the function's current API reference when writing Python scripts.", "related_lessons": ["13_regression", "15_image_umap"], "hold_after": 0.7}], "poster": "06_api/poster.jpg", "silent": "06_api/video/06_api_silent.mp4"}, {"id": "07_mask", "number": 7, "slug": "mask", "title": "Mask: live filters, a real run and verified overlay export", "series": 1, "app_key": "mask", "section": "Core", "description": "Use the real downloadable microscopy example, test live area and diameter changes, run two fields with Plot enabled, and recover a missing overlay through an explicit Python plotting workaround.", "objectives": ["Find Mask on Home and its nested Live, Time and 3D controls.", "Check source metadata and channel identities before testing segmentation.", "Distinguish a reversible display filter from a model-parameter rerun.", "Inspect genuine batch output, preserve the partial-overlay warning and export both arrays explicitly.", "Keep QC limitations, original data and an unsent AI question distinct from scientific validation."], "example_files": ["Mask_overlay_API_workaround.zip"], "prerequisite": "Use the actual Mask download, retaining known channel identities and filename metadata. Preserved live-preview footage is reused only after confirming live_preview.py and preview_contract.py are byte-identical to their recorded source; its saved masks independently reproduce 51→25→51 at minimum area 5642 and 42 after diameter 30→60. The new two-field batch is a separate example, not a direct count benchmark: Plot=True, test_images=2, batch_size=2, n_jobs=2, diameters 30/30/15 and explicit cell/nucleus/pathogen flow thresholds 0.4. Archive value 100 disables flow filtering and is not taught as recommended. The native overlay loop STILL fails on .spacr_plane_layout.json: one of two overlays is missing despite Finished. Do not delete the layout or enable pickle loading. The linked helper calls spacr.plot.plot_image_mask_overlay on regular .npy files only, requiring four intensity planes followed by cell/nucleus/pathogen at 4/5/6. It writes a new opaque-background PNG folder, never changes source arrays, and does not fix the GUI loop. Both source array hashes match the native run journal. Final labels are 25/19/8 and 52/50/58; first-field pathogen QC warns near_empty_field. Cell QC precedes mask adjustment. Independent checks cover 95,424,864 channel RGB array values and 7,952,072 combined-foreground pixels, not biological accuracy. Previous failed runs and transparent-plot probes are preserved but not presented as complete. No AI request, training, scientific approval or publication. API: spacr.core.preprocess_generate_masks and spacr.plot.plot_image_mask_overlay. OPS remains unproven and is not taught here.", "scenes": [{"visual": "native_01_module", "narration": "Open Mask from Home. It is a main module; Live, Time and three-dimensional settings are reached inside it. Time has its own linked tutorial under Mask in the submodule section. This lesson covers a two-dimensional example, live comparisons and a plotting workaround, not an automatically validated segmentation.", "related_lessons": ["05_home", "17_timelapse"], "hold_after": 0.7}, {"visual": "native_02_download", "narration": "Click Load test data and let the real microscopy example finish downloading. Keep its folder structure and original images. The recording uses a fresh private copy, so a previous run cannot supply stale results. For your own data, confirm the filename metadata and channel identities before copying any example settings.", "hold_after": 0.7}, {"visual": "native_03_data_ready", "narration": "Here nucleus intensity is channel zero, cell intensity is channel one, and pathogen intensity is channel two. The example also contains channel three. These are intensity-channel identities, not the mask-plane numbers in a merged output. Check the images themselves and retain the layout metadata when moving results.", "hold_after": 0.7}, {"visual": "preview_04_live_image", "narration": "Turn on Live and select a field for inspection. Preview is where you compare the image with the proposed masks before a larger run. The preserved preview uses a different field from the two batch fields shown later. A displayed preview count is not directly comparable with a batch total.", "hold_after": 0.7}, {"visual": "preview_05_live_settings", "narration": "Open Live settings and inspect the cell controls. This recording uses the installed CPSAM model; available model choices depend on your installation. Run the preview before interpreting its outlines. Diameter and filtering controls are different operations, and neither the selected model name nor a colourful mask guarantees accuracy.", "hold_after": 0.7}, {"visual": "preview_09_filters_after", "narration": "The baseline contains fifty-one cell labels. Raising minimum area to five thousand six hundred forty-two pixels leaves twenty-five visible labels. This is a reversible filter of the existing result: the raw mask stays unchanged and the model is not rerun. The threshold is a demonstration, not an optimal biological cutoff.", "hold_after": 0.7}, {"visual": "preview_10_filters_restored", "narration": "Restore the original area limit and all fifty-one labels return. Inspect which objects disappear and why before adopting a filter. Small objects may be genuine objects or segmentation errors; removing them does not itself answer that question. Keep the raw result and the chosen filter values separately identifiable.", "hold_after": 0.7}, {"visual": "preview_12_model_result", "narration": "Changing diameter from thirty to sixty pixels and running again is a model-parameter comparison, not just a display filter. This produces forty-two labels in the recorded field. Compare boundaries with the image, not only the count. Fewer labels do not establish a better model, and these settings are not a universal recommendation.", "hold_after": 0.7}, {"visual": "native_20_batch_settings", "narration": "For the separate batch, use two test images and keep Plot enabled. Here all three flow thresholds are explicitly zero point four. The downloaded settings had one hundred, which disables flow filtering; we do not recommend that value by default. Review the console's device and processing messages instead of assuming how the run executed.", "hold_after": 0.7}, {"visual": "native_23_batch_finished", "narration": "Read the whole console. Although the worker says Finished, the overlay ledger reports one of two plots missing: it tried to load the layout JSON as an image. The merged mask arrays exist, but this is not a complete native plotting run. Keep the warning and do not silently treat it as success.", "hold_after": 0.7}, {"visual": "command_01_explicit_numeric_inputs", "narration": "The workaround is an explicit external step. Keep the layout JSON: it describes the intensity and mask planes and is not an image. Never enable pickle loading to silence this error. Download the linked helper, inspect it, and use the merged folder belonging to this particular run, not an older result directory.", "focus": [190, 80, 3450, 1120], "related_lessons": ["06_api"], "hold_after": 0.7}, {"visual": "command_02_explicit_plotting_api", "narration": "Run the helper with the merged source and a new destination. It calls the real plotting API separately for each numeric array and saves both overlays. It refuses a different plane layout or an existing output folder. This bypasses the faulty directory scan for this export; it does not repair the application's plotting loop.", "focus": [190, 80, 3450, 1000], "hold_after": 0.7}, {"visual": "viewer_09_saved_plate1_E01_17_1", "narration": "These are the saved plots in an external image viewer, not figures inserted into spaCR. The first field has twenty-five cell, nineteen nucleus and eight pathogen labels after adjustment. Its pathogen QC still warns that eight objects are too few for the per-field size checks. A readable overlay does not remove that limitation.", "focus": [200, 680, 3440, 880], "hold_after": 0.7}, {"visual": "viewer_10_saved_plate1_L02_18_1", "narration": "The second field has fifty-two cell, fifty nucleus and fifty-eight pathogen labels. The first four panels show the recorded intensity channels and their outlines; the last combines the object masks. Percentile normalization here is for display only. The source arrays are unchanged, and these label counts are not ground-truth accuracy measurements.", "focus": [200, 680, 3440, 880], "hold_after": 0.7}, {"visual": "command_03_verified_saved_overlays", "narration": "Keep the output checks, original journal, settings and QC files together. We independently checked the plotted channel arrays, combined foreground coverage and unchanged source hashes. Cell QC was recorded before cell-mask adjustment, so its counts need not equal the final merged counts. Inspect segmentation quality yourself before continuing to Measure.", "focus": [190, 80, 3450, 1150], "related_lessons": ["08_measure", "54_qc_dashboard"], "hold_after": 0.7}, {"visual": "viewer_30_ai_unsent_question", "narration": "The console's optional spaCR AI control can help you discuss settings, but this example question is unsent and no provider answer is shown. Verify any advice against the real files and warnings. The Python pipeline and per-file plotting API follow the same data contracts; the linked lessons cover measurement and the nested time workflow.", "related_lessons": ["06_api", "08_measure", "17_timelapse"], "hold_after": 0.7}], "poster": "07_mask/poster.jpg", "silent": "07_mask/video/07_mask_silent.mp4"}, {"id": "08_measure", "number": 8, "slug": "measure", "title": "Measure: live field views, real measurements and saved outputs", "series": 1, "app_key": "measure", "section": "Core", "description": "Use the downloadable sixteen-field example to inspect live fields and channels, restore raw-crop settings, read quality warnings, run with Plot enabled and verify saved measurements.", "objectives": ["Load the current Measure example and distinguish intensity channels from label-mask planes.", "Inspect fields and channels live, distinguish the view selector from shared crop settings, and restore normalization before the batch.", "Run the full example, inspect real figures and console output, and locate verified measurements and crop files.", "Find the nested Illumination, AnnData Export and Motility workflows and understand the limits of the AI console and stale-output warning."], "prerequisite": "Open Measure from Home/Core and use Load test data. The measured subset is sixteen 1994x1994 merged uint16 arrays: intensity planes 0–3 and mask planes 4/5/6 for cells/nuclei/pathogen objects. Before the first Live preview, enable the main Normalize toggle; the panel initializes contrast at percentiles 1/99. Do not Run with that toggle on. Channel zero is a view-only choice, but the main Normalize setting also concerns saved crops. Turn Live off and restore Normalize off before running. The preview shows 27 objects in E02_1_1 and 15 in E02_9_1; channel changes preserve labels, areas and categories, and restoring All channels restores the original pixels. Preview and batch source arrays are byte-identical. Crop settings is oversized in this build; inaccessible normalization/propagation/filter-dialog scenes are deliberately not taught as usable. The background QC banner flags 3 failures and 16 warnings across 156 object-field records from the larger 52-field mask download, not just the 16 merged fields measured here. The data are illustrative, not certified clean. The full run uses Plot on, Test mode off, one worker, save_measurements/save_png on, normalize off and RGB224x224 cell crops. With no voxel calibration, areas are pixels squared. Independent checks cover 5409 area/intensity values including five source-supported label merges, not every feature or biological correctness. Outputs: 601 cell records/crops, 622 nuclei, 373 pathogen objects, 48 saved plots (47 in the GUI queue). Runtime-added hash_inputs and _intensity_rescale_plan cause this run's stale-output warning; arbitrary warnings and automatic handoff are not certified safe. A separate test-mode run registered the wrong database path; this lesson uses verified normal-mode outputs. API: spacr.measure.measure_crop. See Illumination, Motility and AnnData Export separately; AnnData teaches an explicit API workaround, not a repaired GUI. No AI question is sent, no response is demonstrated, and no human listening approval or publication is claimed.", "scenes": [{"visual": "preview_01_module", "narration": "Open Measure from the Core modules. It turns existing image arrays and object masks into measurements and crops; it does not create a new segmentation. Illumination, AnnData Export and Motility are nested workflows under this main module. Their separate lessons belong under Measure in the tutorial navigation.", "related_lessons": ["07_mask", "43_illumination", "18_motility", "59_anndata_export"], "hold_after": 0.7}, {"visual": "preview_03_data_ready", "narration": "Choose Load test data and wait for the actual example to finish loading. This download supplies sixteen merged fields. Check the source folder and channel mapping: intensity channels zero to three, cell mask four, nucleus mask five, and pathogen mask six. Mask labels are not intensity measurements.", "hold_after": 0.7}, {"visual": "preview_04_preview_normalization_setup", "narration": "Before opening Live for the first time, search for Normalize in the main settings and turn it on. This initializes a readable preview because the raw sixteen-bit crops look dark. This is also a saved-crop setting, not just a display preference. Do not press Run; we will restore it first.", "hold_after": 0.7}, {"visual": "preview_05_live_all_channels", "narration": "Switch Live on and paste the merged-array path for field E zero two, one, one. The grid shows twenty-seven candidates, grouped by mask relationships; scroll to inspect the remaining categories. These labels are not independently reviewed biological annotations, and displayed candidates are not a promise of the final measured-cell count.", "hold_after": 0.7}, {"visual": "preview_06_live_channel_zero", "narration": "Choose channel zero in the displayed-channel selector. The same twenty-seven objects now appear in grayscale; their labels, areas and categories are unchanged. Unlike the main Normalize setting, this selector changes only the preview view. Return to All channels to restore the original color pixels without changing the batch settings.", "hold_after": 0.7}, {"visual": "preview_07_live_second_field", "narration": "Use the field selector to open E zero two, nine, one. This field has fifteen displayed candidates: inspect more than one field before trusting an attractive image. Also read the red segmentation-quality banner. Its flagged masks come from the larger downloaded set; successful preview rendering does not resolve those warnings or certify clean data.", "hold_after": 0.7}, {"visual": "preview_08_saved_normalization_restored", "narration": "Turn Live off, search for Normalize again, and switch it off before running. We verified that all batch settings return to their original values and both source arrays remain unchanged. Per-crop normalization can remove intensity differences from saved images. Keep the original arrays; this lesson does not use the oversized Crop settings dialog.", "related_lessons": ["09_annotate"], "hold_after": 0.7}, {"visual": "batch_20_batch_settings", "narration": "Keep Plot enabled, save measurements and crops, and use one worker for this demonstration. Test mode is off: this run processes all sixteen example fields into the main project output. A short test uses a separate test folder in this build, so do not confuse its database with the full-run result.", "hold_after": 0.7}, {"visual": "batch_26_measure_console_complete", "narration": "Press Run and follow the console. Check the attempted, succeeded and failed counts, not merely the presence of a finished message. Here all sixteen fields succeeded. Large plots can trigger an explicit export-resolution limit; read that warning as well. A successfully completed computation is not a biological quality certificate.", "hold_after": 0.7}, {"visual": "batch_25_measure_figure_00", "narration": "Use the figure list to inspect the actual before-filtering and after-filtering views. Drag the divider to give the figures more room. Size filters and parent-child merging can change which labels are measured. In this example, five saved cell objects combine source labels connected by a shared nucleus or pathogen mask.", "hold_after": 0.7}, {"visual": "batch_25_measure_figure_02", "narration": "Inspect the crop figure too, then keep the measurements database and its image paths together. This run saved six hundred one cell records and matching crops. Independent pixel checks verified area and four-channel intensity sums and means, including those merges; this does not validate every feature or the segmentation's biological correctness.", "related_lessons": ["09_annotate", "11_classify_ml"], "hold_after": 0.7}, {"visual": "batch_24_batch_figure", "narration": "This build can still display a stale-output warning after a successful run with unchanged visible settings. We traced this example to runtime-added metadata, but have not fixed the application. Verify the actual saved run and settings before continuing; do not dismiss other warnings or assume that automatic handoff has been validated. Also check the files: this recording's figure queue showed forty-seven of forty-eight saved plots.", "hold_after": 0.7}, {"visual": "batch_30_ai_unsent_question", "narration": "The console also offers optional spaCR AI assistance. Here we enable the toggle and prepare a question without sending it, so no answer or external analysis is demonstrated. Treat any later response as advice to verify against the settings, API and saved results. Use the separate nested-workflow lessons for the next task.", "related_lessons": ["06_api", "43_illumination", "18_motility", "59_anndata_export"], "hold_after": 0.7}], "poster": "08_measure/poster.jpg", "silent": "08_measure/video/08_measure_silent.mp4"}, {"id": "09_annotate", "number": 9, "slug": "annotate", "title": "Annotate: real example crops, saved labels and review tools", "series": 1, "app_key": "annotate", "section": "Core", "description": "Load the downloadable crop dataset, create a separate annotation column, verify real saved labels, adjust the crop view and find the review and training tools in the current Annotate module.", "objectives": ["Choose the appropriate downloadable crop or streaming example and open its actual project folder.", "Use a separate annotation column, distinguish queued labels from persisted labels, and clear a demonstration label without changing the original annotations.", "Inspect class counts and coverage and change display colours without modifying image files.", "Locate the nested Agreement workflow, current training routes, annotation-database generator and optional AI console."], "prerequisite": "Open spaCR and choose Annotate from the Core modules. This recording uses the downloadable Load dataset: 2,341 exported PNG crops and their measurements database. No model training or AI service is required. Define your biological class scheme before a real annotation pass; the temporary label here demonstrates saving, not a biological judgement.", "scenes": [{"visual": "01_module", "narration": "Open Annotate from the Core modules. Its main workspace is a crop grid backed by a measurements database. The current module also contains coverage checks, learning and training controls, database generation, and a nested Annotator Agreement tool.", "hold_after": 0.7}, {"visual": "02_data_choice_load", "focus": [1680, 914, 460, 393], "narration": "Choose Load test data, then inspect the two routes. Load supplies exported image crops and a database. The example contains two thousand three hundred and forty-one PNG crops. This recording reuses the complete downloaded cache; it does not invent images or labels.", "hold_after": 0.7}, {"visual": "02_data_choice_stream", "focus": [1680, 914, 460, 393], "narration": "Stream supplies merged image arrays and the database for obtaining crops on demand. Choose the route that matches how you want to read images; downloading one is not evidence that you have the other. We use Load throughout this demonstration.", "hold_after": 0.7}, {"visual": "04_open_source_dialog", "focus": [1577, 810, 1300, 950], "narration": "If the grid still says no source selected after the download, choose Open source. Select the plate folder containing the measurements subfolder and its database, not the database file itself. This is the real extra step needed by the application build shown here.", "hold_after": 0.7}, {"visual": "05_loaded_crops", "narration": "Confirm that the real crops appear and that the page counter matches the expected dataset. The number of images on a page depends on the window and image size. A successfully opened folder is not enough: inspect the images before making annotation decisions.", "hold_after": 0.7}, {"visual": "06_annotation_settings", "focus": [1536, 309, 748, 1462], "narration": "Open Settings and create a separate annotation column for this demonstration. Keep the original labels intact. Before real work, document what each class means and agree on a consistent view; the example label we will assign is only a test of the save path.", "hold_after": 0.7}, {"visual": "08_class_one_pending", "narration": "Left-click the first crop to assign class one. Right-click assigns class two, and repeating the same class clears it. The class-coloured ring shows the current decision; the extra white ring marks focus. A changed ring alone does not prove the label has reached the database.", "hold_after": 0.7}, {"visual": "08_next_page_saved", "narration": "Press Next to leave the page. In this build, changing pages submits queued labels to the background save worker. We checked the actual database and confirmed that class one was written. Do not teach yourself to treat an unsaved visual change as completed storage.", "hold_after": 0.7}, {"visual": "08_class_one_saved", "narration": "Press Back and check the same crop. Its saved class loads again from the database. For keyboard work, the visible legend lists class keys one to nine, zero to clear, navigation, undo and Enter for the next batch. Keep the focused crop in view when using shortcuts.", "hold_after": 0.7}, {"visual": "09_class_counts", "focus": [1768, 972, 285, 136], "narration": "Class counts now reports one saved example in class one. Counts help reveal imbalance, but a single demonstration label is not a training set and says nothing about biological accuracy. Keep machine suggestions separate from reviewed answers.", "hold_after": 0.7}, {"visual": "09_annotation_coverage", "focus": [1450, 730, 920, 620], "narration": "Coverage asks where the annotations came from, not just how many exist. Review representation across the groups shown in the report before training. One labelled crop cannot establish representative coverage, even when the software correctly records it.", "hold_after": 0.7}, {"visual": "10_class_cleared", "narration": "Click that same class again, then use Next and Back to save and reload the cleared state. The demonstration column is empty again. Read-only checks confirmed the transitions from empty to one to empty, while every original annotation column and downloaded PNG remained unchanged.", "hold_after": 0.7}, {"visual": "11_display_colour_settings", "focus": [1536, 309, 748, 1462], "narration": "Settings also controls the view. Channel colours changes the display palette; Display order changes which source channel occupies each colour slot. These are not instructions to rewrite a file's channel order. Here we select CMY, then return to RGB.", "hold_after": 0.7}, {"visual": "12_cmy_view", "narration": "The actual crops change colour immediately after applying the view settings. Restoring RGB restores the same displayed pixels, and the source files are unchanged. Use a consistent, interpretable view for annotation. A palette change is not new segmentation, measurement or evidence of a different phenotype.", "hold_after": 0.7}, {"visual": "15_agreement_fold", "narration": "Annotator Agreement now lives at the right of Annotate's header. Hover over the icon to identify it. Keep the existing specialist tutorial for comparing annotation columns and investigating disagreements; it is linked here rather than repeated as another Home-module lesson.", "focus_buttons": "FoldButton", "hold_after": 0.7, "related_lessons": ["23_agreement"]}, {"visual": "16_training_routes", "focus": [1836, 204, 416, 80], "narration": "Train now opens a menu with two routes: the images, using a neural image classifier, or the measured features, using boosted trees. Follow the linked computer-vision and machine-learning lessons inside Classify. We are showing the routes only; no training was started with this empty demonstration column.", "hold_after": 0.7, "related_lessons": ["41_classify", "10_classify_cv", "11_classify_ml"]}, {"visual": "14_restored_rgb", "narration": "Retrain, Suggest and Rounds support a review loop once suitable labels exist. A model's proposed class is not automatically a human answer. Review its coverage and held-out performance before relying on it. None of those operations was run or given an invented success result in this demonstration.", "hold_after": 0.7}, {"visual": "17_generate_database_entry", "narration": "Generate annotation database is now available here for creating an annotation crop set from suitable source data. The downloaded Load example already has its database and crops, so we do not generate another set. Scripted generation uses generate_annotation_dataset in the annotation-dataset module; consult the current API for its required inputs.", "hold_after": 0.7, "related_lessons": ["06_api", "08_measure"]}, {"visual": "18_annotation_console", "narration": "Open Console when you need the real source, label and status messages, then hide it to give space back to the grid. Annotate's demonstrated output is a database label, not a Plot-enabled analysis figure. The visible crops and saved-state checks are the outputs to inspect here.", "hold_after": 0.7}, {"visual": "30_ai_unsent_question", "narration": "AI enables optional help through the provider configured in Preferences. It is separate from training a classifier or accepting predicted labels. This is an unsent example question: no service was contacted and no answer was fabricated. Keep your class definitions, saved labels and review decisions grounded in the data.", "hold_after": 0.7}], "poster": "09_annotate/poster.jpg", "silent": "09_annotate/video/09_annotate_silent.mp4"}, {"id": "10_classify_cv", "number": 10, "slug": "classify_cv", "title": "Classify: a checked computer-vision example", "series": 1, "app_key": "classify", "host_app_key": "classify_merged", "section": "Core", "description": "Prepare unchanged downloaded crops with explicit well identities, run the current computer-vision family, and inspect a deliberately small model without overstating its performance.", "objectives": ["Find the computer-vision family inside the main Classify module.", "Prepare an explicit existing split from downloaded annotations without modifying source images or labels.", "Keep actual wells separate, show training figures and distinguish workflow completion from useful prediction.", "Locate saved models, predictions and related nested workflows."], "example_files": ["Classify_existing_split_example.zip"], "prerequisite": "Use the Annotate lesson's Load test data download, not Stream, retaining plate1/measurements/measurements.db and its png crops. This recording uses spaCR 1.5.0.6. Download the helper ZIP and run prepare_classify_split.py in the spaCR environment with --source pointing to plate1 and --destination to a NEW folder. The helper is deliberately restricted to this four-well example: eight existing infected=1 and eight infected=2 labels per well, deterministically ranked before fitting, 64 byte-identical RGB crops. It gives copied files canonical database prcfo names; the original legacy filename parser is NOT fixed. The balanced subset does NOT preserve population prevalence. Select that prepared folder in Classify, Computer Vision (Torch), with Generate training dataset OFF. Native settings: ResNet18, epochs=1, batch_size=8, image_size=128, n_jobs=0, init_weights=False, augment=False, val_split=0.5, test_split=0.5, cv_group_by=well, random_seed=42, train_channels=['r','g','b'], train/test/plot=True; all leakage guards remain enabled. The prepared train folder has 32 crops split into 16 train and 16 validation; test has 32. Actual well sets are disjoint but share one plate. This tiny run predicts class zero for all test crops: accuracy=0.5, majority accuracy=0.5, macro F1=1/3. All 32 prediction identities, labels and probability sums, accuracy, support and macro F1 were independently checked; not every reported metric was validated. Outputs are under model/resnet18/rgb/epochs_1. API: spacr.classify.classify dispatches to spacr.deep_spacr.train_test_model. No model quality, biological validation, new-experiment generalization or submitted AI answer is claimed.", "scenes": [{"visual": "gui_19_setting_classifier_family", "narration": "Open Classify from Home and choose Computer Vision, Torch. Computer vision learns from object images; the tabular family learns from saved measurements. Both now belong to the same main module. This lesson runs a small, checked image example, with a separate preparation workaround that does not repair the application's legacy filename parser.", "focus": [350, 190, 1730, 430], "related_lessons": ["41_classify", "11_classify_ml"], "hold_after": 0.7}, {"visual": "prepare_01_source_example", "narration": "Follow Annotate's linked tutorial to Load the real example, keeping its measurements database and image crops. The terminal lists the existing annotation labels across four actual wells. We preserve those labels; they are not independently validated biological truth. The source project remains unchanged throughout this demonstration.", "focus": [190, 80, 3450, 1250], "related_lessons": ["09_annotate", "08_measure"], "hold_after": 0.7}, {"visual": "prepare_02_prepare_existing_split", "narration": "Download the helper and run it in your spaCR environment. Source is the downloaded plate folder; destination must be a new folder. It copies eight images from each of two existing classes in each well: sixty-four images total. Selection is deterministic and happens before training, not after looking at model performance.", "focus": [190, 80, 3450, 1300], "hold_after": 0.7}, {"visual": "prepare_03_exported_manifest", "narration": "Read the manifest before continuing. Copied filenames use the database's canonical object identities, and every image retains its original bytes. Two whole wells go into the training folder and two into test. This explicitly balanced teaching subset changes the class prevalence; it is not a representative estimate of the original population.", "focus": [190, 80, 3450, 1300], "hold_after": 0.7}, {"visual": "gui_18_source_folder_choice", "narration": "In Classify, choose the prepared dataset folder, not the original project or one class subfolder. It contains train and test directories, each with two class folders. The source chooser opens that existing dataset. Do not overwrite the source project or reuse a destination containing results from an earlier run.", "hold_after": 0.7}, {"visual": "gui_19_setting_generate_training_dataset", "narration": "Turn Generate training dataset off because the split is already prepared. Train and Test remain on; applying the model to a full dataset stays off. The prepared class folders preserve labels one and two, while the model uses class indices zero and one. Those numbering systems are different, not contradictory.", "focus": [350, 190, 1730, 520], "hold_after": 0.7}, {"visual": "gui_19_setting_model_type", "narration": "Choose ResNet18 for this bounded example: one epoch, batches of eight, image size one hundred twenty-eight, and zero loader workers. Use all three RGB channels and leave pretrained weights and augmentation off. These settings make the demonstration small; they are not a recommended recipe for an accurate classifier.", "focus": [350, 190, 1730, 700], "hold_after": 0.7}, {"visual": "gui_19_setting_val_split", "narration": "Keep grouping by well and every leakage check enabled. A validation fraction of one half splits the thirty-two training-folder images into sixteen training and sixteen validation images, with one whole well each. The other thirty-two images remain test-only. All four wells share one plate, so this is not an independent-experiment validation.", "focus": [350, 190, 1730, 900], "hold_after": 0.7}, {"visual": "gui_19_setting_plot", "narration": "Turn Plot on, clear the settings search, and press Run. Watch the console for the resolved split, leakage audits, training and saved paths. Both well-grouped boundary checks pass in this recorded run. A software pass only has meaning when the names agree with the actual sample identities, which we checked separately.", "focus": [350, 190, 1730, 650], "hold_after": 0.7}, {"visual": "gui_24_batch_figure", "narration": "The Figures panel shows loss, accuracy and per-class validation accuracy. With only one epoch, these are individual points, not evidence of convergence. Our separate test check finds every image predicted as class zero: fifty percent accuracy, exactly the balanced majority baseline. Successful execution has not produced a useful classifier.", "focus": [2090, 180, 1720, 1320], "hold_after": 0.7}, {"visual": "gui_23_batch_finished", "narration": "Keep the model directory with its checkpoint, model card, leakage audits and result tables. Here it is under model, resnet18, rgb, epochs underscore one. Compare saved prediction identities and class labels, not just an accuracy number. Misclassified review images are outputs, not additional independent training or test samples.", "focus": [2090, 180, 1720, 1320], "related_lessons": ["39_classifier_evaluation", "28_training_runs", "16_activation"], "hold_after": 0.7}, {"visual": "gui_30_ai_unsent_question", "narration": "The AI control can help you ask about settings or outputs after you configure a provider. This is an unsent question, not an answer or an analysis result. In Python, classify dispatches to train_test_model for this family. Keep the split manifest and verify advice before planning a larger, independently validated experiment.", "focus": [2090, 950, 1720, 1130], "related_lessons": ["06_api", "41_classify", "65_feature_explorer"], "hold_after": 0.7}], "poster": "10_classify_cv/poster.jpg", "silent": "10_classify_cv/video/10_classify_cv_silent.mp4"}, {"id": "11_classify_ml", "number": 11, "slug": "classify_ml", "title": "Classify: tabular machine learning", "series": 1, "app_key": "ml_analyze", "host_app_key": "classify_merged", "section": "Core", "description": "Use the merged Classify screen with downloadable measured cells, explicit metadata labels, a bounded random forest, real console output and saved predictions.", "objectives": ["Choose the tabular family and load the measured example through the native data chooser.", "Define plate-column classes and distinguish the requested split from actual held-out wells.", "Inspect plots, missing scores and model outputs without treating demonstration accuracy as biological validation."], "prerequisite": "Use Load test data in Classify and choose Load, not Stream. The example has 2,341 cell/crop identities across four wells. The recorded ML join retains 2,153 objects and excludes 188 lacking nucleus rows. Classes are columnID=c1 (zero) and c2 (one), not independently verified phenotypes. The native run uses random_forest, channel_of_interest=1, n_estimators=16, n_jobs=2, n_repeats=1, top_features=10, batch_correction=none, prune_features=False, cross_validation=False and plot=True. Match test_size=0.1 to the merged test_split=0.1: the current normalization otherwise discards the ML-specific request; this defect is reported, not hidden. Actual holdout: two of four wells, 1,035 of 2,153 objects, with no database well overlap. Feature filtering precedes splitting and permutation importance uses training data; these are not independently validated feature discoveries. Nine saved metric values and all 2,153 database predictions were independently checked. Held-out accuracy is 0.6202898551 versus majority-class accuracy 0.5632850242. API: spacr.classify.classify dispatches to spacr.ml.generate_ml_scores; outputs are under results/random_forest/channel_1. Database predictions holds the binary class and ml_pred the class-one probability. Only three real GUI figures are claimed; no SHAP, calibrated probability, causal effect or biological validation claim. No AI request was submitted.", "scenes": [{"visual": "19_setting_classifier_family", "narration": "Open Classify from Home and choose Tabular Machine Learning as the classifier family. This is the merged Classify screen, not a separate ML application. It learns from saved per-object measurements. Computer-vision settings can remain visible but greyed out because they belong to the other family.", "focus": [460, 230, 1680, 650], "related_lessons": ["41_classify", "10_classify_cv"], "hold_after": 0.7}, {"visual": "02_data_choice_load", "narration": "Click Load test data and choose Load. This downloads the measured example and prepares its paths; Stream is a different route. For your own project, complete Measure first and select its project folder. Do not assume an arbitrary image folder already contains the required measurement database.", "focus": [1010, 550, 1800, 1040], "related_lessons": ["08_measure", "09_annotate"], "hold_after": 0.7}, {"visual": "19_setting_classes", "narration": "Use the metadata basis and define two Classes from column I D: c1 and c2. Here those are plate-column labels used to teach the workflow, not independently verified healthy and affected cells. Annotation-based training instead needs genuine labels from Annotate. Never turn missing annotations into invented ground truth.", "focus": [460, 230, 1680, 1190], "hold_after": 0.7}, {"visual": "19_setting_channel_of_interest", "narration": "Channel of interest selects the measurement features. We use channel one without assigning it an unverified biological meaning. Check your acquisition and measurement settings before choosing a channel in your own data. Selecting a feature channel here does not re-segment images or measure them again.", "focus": [460, 230, 1680, 820], "hold_after": 0.7}, {"visual": "19_setting_n_estimators", "narration": "Choose Random Forest and sixteen estimators for this small demonstration, with two worker jobs. This is not an optimized model recommendation. We leave supervised feature pruning and cross-validation off. Cross-validation being off does not remove the separate held-out test split used by this run.", "focus": [460, 230, 1680, 820], "hold_after": 0.7}, {"visual": "19_setting_test_size", "narration": "Set test size to one tenth and keep grouping by well. A requested fraction is not an exact object count: this four-well example holds out two whole wells, about forty-eight percent of its retained objects. Both classes appear on each side, and no actual well appears in both training and test.", "focus": [460, 230, 1680, 820], "hold_after": 0.7}, {"visual": "19_setting_plot", "narration": "Turn Plot on, clear the search and press Run. The console records the resolved settings, filtering, split and model report. Keep that record with the results. A finished badge does not establish that your labels, validation design or biological interpretation were appropriate.", "focus": [460, 230, 3340, 1640], "hold_after": 0.7}, {"visual": "23_batch_finished", "narration": "This run scores two thousand one hundred fifty-three objects. One hundred eighty-eight lack matching nucleus data and remain unscored, not negative. The saved test accuracy is about sixty-two percent, versus fifty-six percent for the majority class. Four wells on one plate do not establish generalization to a new experiment.", "focus": [2140, 240, 1670, 1270], "hold_after": 0.7}, {"visual": "24_batch_figure", "narration": "Three figures are available: permutation importance, tree feature importance and this plate heatmap. With Predictions and mean grouping, the heatmap averages binary predicted classes, not their probabilities. Importance is not causality; the permutation calculation uses training data. Inspect the saved tables before drawing conclusions from a colourful plot.", "focus": [2140, 240, 1670, 1270], "hold_after": 0.7}, {"visual": "30_ai_unsent_question", "narration": "The AI toggle enables provider-assisted questions about the workflow. This is an unsent draft, not a generated answer. Keep results with their settings and verify any advice. Nested tools have their own input requirements: the Explain tutorial uses computer-vision scores, not these ML outputs. AI does not replace checking labels and split identities.", "focus": [2140, 970, 1670, 1080], "related_lessons": ["70_explain_cv", "28_training_runs", "06_api"], "hold_after": 0.7}], "poster": "11_classify_ml/poster.jpg", "silent": "11_classify_ml/video/11_classify_ml_silent.mp4"}, {"id": "12_map_barcodes", "number": 12, "slug": "map_barcodes", "title": "Map Barcodes", "series": 1, "app_key": "map_barcodes", "section": "Core", "description": "This tutorial is not available yet. Please explore the other tutorials.", "objectives": [], "prerequisite": "", "scenes": [], "status": "coming_soon", "availability_title": "Coming soon"}, {"id": "13_regression", "number": 13, "slug": "regression", "title": "Regression: a real example from paired tables to results", "series": 1, "app_key": "regression", "section": "Core", "description": "Load the downloadable example screen, configure a bounded guide-permutation analysis, inspect its real console and figures, and find the specialist tools now nested inside Regression.", "objectives": ["Load four paired score/count tables through the visible test-data control and choose a separate output folder.", "Distinguish inference method, reported level and analysis unit, and reproduce the bounded example without treating its permutation count as a final-analysis recommendation.", "Inspect real results, figures and diagnostic limitations; distinguish interactive inspection from a live analysis preview.", "Locate Regression's nested tools, optional AI assistance and current Python entry point."], "prerequisite": "Open spaCR and choose Regression from the Core modules. The example downloads or reuses cached score/count files. No measurement database, image crops, external annotation service or AI subscription is required for the recorded analysis. The short permutation run demonstrates the workflow, not definitive biological discovery.", "scenes": [{"visual": "01_module", "narration": "Open Regression from the Core modules. It connects phenotype scores with guide abundance, then reports associations using the inference method you choose. The tools across the top now belong inside this module; they are not separate Home tiles.", "focus_buttons": "FoldButton", "hold_after": 0.7}, {"visual": "02_cached_load", "narration": "In Input Tables, choose Load test data. The application downloads the example screen or reuses verified cached files; this recording uses the cache. The console reports four score tables and four count tables, paired by plate.", "hold_after": 0.7}, {"visual": "19_setting_paired_data", "narration": "Inspect all four paired rows. Each plate needs its matching score and count file; the optional measurement-database column is empty here. Widen the settings panel if needed, and use a new output directory so this demonstration does not mix with an existing analysis.", "hold_after": 0.7}, {"visual": "19_setting_inference", "narration": "Switch from Essentials to All settings and use the search box to find a setting by its label or API key. Here inference is nonparametric: guide permutation testing. This differs from fitting all predictors together in a parametric regression, which needs an identifiable design.", "hold_after": 0.7}, {"visual": "19_setting_level", "narration": "Level answers a different question: what should be reported? Choose both for separate guide and gene results. That choice does not itself select the inference method. Guide and gene results are different testing families, so inspect the intended family before interpreting adjusted significance.", "hold_after": 0.7}, {"visual": "19_setting_analysis_unit", "narration": "Use well as the analysis unit for this example. The loaded preset supplies the response column, transformations, controls and exclusions; inspect those assumptions before adapting the workflow to your own screen. A downloaded preset is an example design, not a universal recommendation.", "hold_after": 0.7}, {"visual": "19_setting_guide_min_wells", "narration": "Set the minimum guide support to two wells for this bounded run. This is a filter on the guides tested, not proof of adequate statistical power. A guide represented in very few wells still needs careful interpretation.", "hold_after": 0.7}, {"visual": "19_setting_guide_permutations", "narration": "Set one hundred and ninety-nine permutations to reproduce the short demonstration. That limits the smallest attainable empirical p-value to zero point zero zero five, which may be too coarse after multiple-testing correction. Plan a suitable permutation count for your real experiment.", "hold_after": 0.7}, {"visual": "19_setting_guide_permutation_seed", "narration": "Set the permutation seed to zero for the demonstrated run. Keep the example's plate blocks and row and column nuisance terms unless your design justifies changing them. A fixed seed supports reproducibility; it does not repair invalid exchangeability assumptions.", "hold_after": 0.7}, {"visual": "19_setting_regression_backend", "narration": "The Regression backend field is not a universal accelerator switch. It applies to supported fitted estimators; this guide-permutation demonstration does not turn into a GPU regression by changing that field. Other spaCR modules expose their own device choices, so follow the controls and console for the operation actually running.", "hold_after": 0.7}, {"visual": "19_setting_annotation_source", "narration": "Choose none for the annotation source in this self-contained example. The statistical results do not require an external gene-annotation lookup. On your own screen, use annotations appropriate to the organism and identifier system instead of assuming that every guide label will resolve.", "hold_after": 0.7}, {"visual": "21_batch_running", "narration": "Clear the search, check the output folder, and press Run. Follow the real console as it aligns inputs, applies the selected filters and calculates the results. Regression produces diagnostic figures directly; there is no separate Plot switch to enable for this recording.", "hold_after": 0.7}, {"visual": "23_batch_finished", "narration": "The completed example produced four hundred and thirty-four guide results and three hundred and twenty-five gene results, with five figures. Finished means the software completed; it does not certify the experimental design or establish biological discoveries. Read the diagnostic warnings as well as the completion line.", "hold_after": 0.7}, {"visual": "25_result_runs", "narration": "Runs identifies the saved analysis; Results displays the selected run. Confirm the folder and settings when comparing runs. Changing a form value does not recompute the result you are looking at: run the analysis again when you intend to test a new choice.", "hold_after": 0.7, "related_lessons": ["73_parameter_sweep"]}, {"visual": "25_result_results", "narration": "Results contains the coefficient table and interactive views beside the generated figures. The run contains seven hundred and fifty-nine rows across both levels; this view selects the four hundred and thirty-four guide results. Use Level to choose the testing family. Inspecting saved output interactively does not rerun inference.", "hold_after": 0.7}, {"visual": "26_detail_p_values", "narration": "Open the p-values view to inspect the result distribution. Interpret it together with the selected testing family, permutation resolution and diagnostics, not as automatic evidence of an effect. The separate Diagnostics tutorial explains the saved design and inference panels in detail.", "hold_after": 0.7, "related_lessons": ["75_regression_diagnostics"]}, {"visual": "25_result_measurements", "narration": "Measurements provides the controls for examining additional measurement responses. This example has no measurement database attached, and opening the tab does not create one or perform a measurement sweep. Supply the required measured data before using those tools on your own experiment.", "hold_after": 0.7, "related_lessons": ["08_measure"]}, {"visual": "25_result_cells", "narration": "Cells can connect selected results with underlying objects when suitable measurement data and images are available. Here the database column is empty, so there is no cell montage to show. Do not confuse an unavailable object view with a failed score-and-count analysis.", "hold_after": 0.7, "related_lessons": ["71_investigate_hit"]}, {"visual": "26_detail_coefficients", "narration": "The nested tools are Volcano Explorer, Hit List, Methods and Results, Investigate Hit, Prediction Profiler, and Diagnostics. Hover over their icons to identify them. Their linked tutorials cover each workflow; for example, a prediction profiler needs suitable fitted-model output, which this permutation run does not provide.", "focus_buttons": "FoldButton", "hold_after": 0.7, "related_lessons": ["72_volcano_explorer", "48_hit_list", "49_methods_results", "71_investigate_hit", "53_prediction_profiler", "75_regression_diagnostics"]}, {"visual": "30_ai_unsent_question", "narration": "The AI control enables optional assistance through the provider configured in Preferences, under AI. Ask a focused question about the output or settings, and review any advice against the data. This is an unsent example question: no provider was contacted and no answer was generated for the recording.", "hold_after": 0.7}, {"visual": "26_detail_coefficients", "narration": "For scripted work, use the perform_regression function in the spaCR machine-learning module with the corresponding settings, and consult its current API documentation. Keep the input tables, saved settings, outputs and diagnostic interpretation together. Use Parameter Sweep deliberately for comparisons, and keep exploratory choices separate from final analysis decisions.", "hold_after": 0.7, "related_lessons": ["06_api", "73_parameter_sweep"]}], "poster": "13_regression/poster.jpg", "silent": "13_regression/video/13_regression_silent.mp4"}, {"id": "14_make_masks", "number": 14, "slug": "make_masks", "title": "Make Masks: reversible editing, recropping and local detection", "series": 1, "app_key": "make_masks", "section": "Tools", "description": "Edit genuine downloaded cell labels with real gestures, distinguish display changes from mask changes, create a recoverable training crop, and inspect an actual Cellpose detection and its intermediate views.", "objectives": ["Open paired two-dimensional images and instance masks without modifying the downloaded source.", "Use reversible object deletion, drawing, division and area filtering, and distinguish these from display contrast.", "Save a curated mask and recrop a field while retaining its parent in the recovery archive.", "Find nested segmentation tools and inspect a real local Cellpose detection, probability map and flow view."], "prerequisite": "Obtain Measure's real downloadable example first. The recording uses two isolated TIFF pairs extracted without changing pixels from its seven-plane uint16 merged fields: ER intensity plane 1 and cell-label plane 4. The exact preparation recipe is prepare_fields in tools/tutorials/capture_make_masks.py. For your own experiment, supply two-dimensional images with same-stem instance-label TIFFs in the masks subfolder; do not assume every dataset has this example's plane order.", "scenes": [{"visual": "01_module", "narration": "Open Make Masks in Home's Tools category. This is the manual mask editor, distinct from the Core Mask pipeline. Its toolbar edits the current field; its header opens related segmentation workflows that now live under this parent.", "hold_after": 0.7, "related_lessons": ["07_mask"]}, {"visual": "02_folder_picker", "narration": "This example uses two real fields from Measure's downloaded dataset. We extracted the intensity and existing cell-label planes into separate TIFF copies and kept the original stacks unchanged. The preparation recipe records their source planes and hashes. Other datasets may use a different plane order.", "hold_after": 0.7, "related_lessons": ["08_measure"]}, {"visual": "03_real_labels", "narration": "Open the image folder. Matching instance masks live in its masks subfolder, under the corresponding image stem. The first field loads sixty-three labelled objects. A missing companion starts empty; a label image uses object identifiers, not merely a foreground colour.", "hold_after": 0.7}, {"visual": "03_real_labels", "narration": "Brush and Erase work on pixels, while Erase object removes a complete label. Wand controls grow connected intensity regions. Draw, Divide, Zoom and Recrop now share this toolbar. Choose the operation that matches the mistake, and inspect the result before saving it.", "hold_after": 0.7, "focus": [345, 195, 2500, 65]}, {"visual": "04_erase_one_object", "narration": "Click Erase object, then an interior cell. The real click removes exactly label seventeen, changing the count from sixty-three to sixty-two without touching other labels. This is a demonstration of the operation, not a judgment that this cell should be excluded biologically.", "hold_after": 0.7}, {"visual": "06_redo", "narration": "Undo restores every original label pixel. Redo repeats that same deletion; Undo restores it again before we continue. These are actual history steps from the clicks, not masks swapped into the viewer by the recording script.", "hold_after": 0.7}, {"visual": "07_draw_demo_not_annotation", "narration": "Draw closes and fills an outline as one object. Here a small background outline demonstrates the tool, briefly producing a sixty-fourth label. It is not a biological annotation, and we undo it. Trace a real boundary carefully when preparing training labels.", "hold_after": 0.7}, {"visual": "08_divide_demo", "narration": "Divide cuts across an existing object and assigns a new identifier to the separated piece. Start and finish the gesture on the image and cross the whole object. This real cut produces sixty-four labels; we undo it rather than treating a demonstration split as ground truth.", "hold_after": 0.7}, {"visual": "08b_contrast_only", "narration": "Display percentiles change visibility, not the raw intensities or label geometry. Raising the lower percentile visibly changes this rendering while both arrays remain identical. Restoring it restores the display. Contrast is a viewing aid, not a way to alter the measurements.", "hold_after": 0.7}, {"visual": "08c_filter_edits_labels", "narration": "The editor's object filter does change labels. Here the measured demonstration threshold of twenty-one thousand and twenty-two pixels removes thirty-two objects when Apply filter now is pressed. No model reruns. This threshold is not a recommended biological cutoff, and this action is not merely hiding objects.", "hold_after": 0.7}, {"visual": "11_saved_restored_mask", "narration": "Undo the filter and set its bounds back to zero, which disables them for later fields. Save mask writes the restored labels and their curation record. We verify that its foreground geometry is unchanged; preserve source images separately from the masks you curate.", "hold_after": 0.7}, {"visual": "09_fold_train_cellpose", "narration": "The header provides Train Cellpose and Mask the whole folder. Training and applying a model are different tasks, with existing specialist lessons linked here. Make Masks remains their parent in the tutorial's Submodules section, even when a tool opens its own window.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["19_train_cellpose", "20_cellpose_masks"]}, {"visual": "09_fold_napari_bridge", "narration": "The same header contains Model Compare, Model Zoo, Curate and Open in napari. Use their retained lessons for side-by-side model inspection, available weights, curation and the external-editor round trip. We show their actual locations here without repeating or inventing those workflows.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["21_model_compare", "22_model_zoo", "42_curate", "46_napari_bridge"]}, {"visual": "12_recrop_written", "narration": "Recrop changes the training field, not just the zoom. Drag a box around a complete object. This gesture immediately writes a new image and matching mask, keeping the original intensity pixels. Labels cut by the boundary are dropped; inspect the resulting object count, not just the box.", "hold_after": 0.7}, {"visual": "13_child_and_recovery_archive", "narration": "Next opens the new one-object crop and retires the copied parent into recropped_originals. That recovery folder preserves its image bytes. This affects the editor's folder queue; it does not rebuild Annotate's crop database. Here only our private tutorial copy is archived, never the downloaded source.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "14_cellpose_settings", "narration": "Cellpose-SAM can detect objects in the open field. Our small crop uses cpsam, normalization on, cell-probability threshold zero, flow threshold zero point four and diameter zero, which leaves the model's default sizing. The replacement mode matters: it is different from adding detections to existing labels.", "hold_after": 0.7}, {"visual": "15_cellpose_detected", "narration": "Press Cellpose-SAM detect and inspect its real result. This run finds one object in the three-hundred-and-thirty-one by two-hundred-and-sixty-seven pixel crop. The new boundary differs from the existing mask; matching object counts alone do not establish that either boundary is correct.", "hold_after": 0.7}, {"visual": "16_cell_probability", "narration": "Cell probability shows the actual score map from that detection, not a calibrated probability that the biological interpretation is correct. Use it to understand where the model supports foreground. A changed detection threshold requires another detection; these panes describe the run that produced them.", "hold_after": 0.7}, {"visual": "17_flows", "narration": "Flows displays the model's directional information. The flow-consistency threshold has a different meaning from the foreground score threshold: lower values are stricter, while zero disables that check. Inspect masks and intermediate views together instead of assuming a larger number always gives a better segmentation.", "hold_after": 0.7}, {"visual": "19_detection_undone", "narration": "Undo restores the crop's pre-detection labels without changing its image. Cellpose uses local model weights, not a chat-provider response. The application's device resolver supports available acceleration and a CPU fallback; the options depend on the installation, so do not promise identical results across backends.", "hold_after": 0.7}, {"visual": "19_detection_undone", "narration": "For scripts, the editor's load_image_and_mask, save_mask and write_recrop operations live in spacr.qt.mask_engine. Keep the image-mask pairing and provenance with your curated training data. Use the linked API and training lessons when moving from a reviewed example to a reproducible workflow.", "hold_after": 0.7, "related_lessons": ["06_api", "19_train_cellpose"]}], "poster": "14_make_masks/poster.jpg", "silent": "14_make_masks/video/14_make_masks_silent.mp4"}, {"id": "15_image_umap", "number": 15, "slug": "image_umap", "title": "Image UMAP: real measurements and interactive crop inspection", "series": 1, "app_key": "umap", "section": "Tools", "description": "Build a bounded embedding from the downloaded example measurements, inspect real crops interactively and locate the nested projection tools.", "objectives": ["Reuse the downloaded project and select its measurement tables.", "Configure a small reproducible embedding and inspect its preprocessing and outputs.", "Click fitted points to inspect their actual crops without changing annotations.", "Find nested Image Scatter and PCA, search controls, optional acceleration and AI assistance."], "prerequisite": "Use Annotate's Load test data route first to obtain the 2,341 PNG crops and measurements database. Image UMAP reuses that project; it does not download another dataset in this recording. The example uses measured features on CPU, not neural image features.", "scenes": [{"visual": "01_module", "narration": "Open Image UMAP from the Home screen's Tools section. It places objects using their measured features, then lets you inspect the corresponding microscopy crops. A nearby group on this exploratory map is not automatically a biological class.", "hold_after": 0.7}, {"visual": "19_setting_src", "narration": "Reuse the project downloaded through Annotate's Load test data route. It contains two thousand three hundred and forty-one crops and their measurements database. Follow the linked Annotate lesson for the actual download; this module now opens the existing project.", "related_lessons": ["09_annotate", "08_measure"], "hold_after": 0.7}, {"visual": "19_setting_src", "narration": "Source uses Add project folders. Select the plate folder, not an individual image. The control reports the databases, rows and shared columns before merging. When comparing several projects, inspect source-related structure before interpreting a cluster as biology.", "hold_after": 0.7}, {"visual": "19_setting_tables", "narration": "Choose the measurement tables that define the question. This example uses cell, cytoplasm, nucleus and pathogen measurements. Review missing data and correlated-feature removal. Leave Resnet features off: raw-crop neural embeddings are not implemented by this route.", "hold_after": 0.7}, {"visual": "19_setting_row_limit", "narration": "Set Row limit to four hundred for a small demonstration. This caps the sampled objects; it does not make the sample representative of every experiment. Two workers keep the job bounded, and the original database remains available for a larger analysis.", "hold_after": 0.7}, {"visual": "19_setting_reduction_method", "narration": "Reduction method selects UMAP here. The current form also offers other reducers, with their own controls. A PCA or t-SNE setting is not interchangeable with a UMAP setting. Only UMAP was fitted in this demonstration.", "hold_after": 0.7}, {"visual": "19_setting_n_neighbors", "narration": "We use fifteen neighbours and a minimum distance of zero point one. Neighbourhood size affects how local structure is represented; minimum distance affects how tightly points can pack. These are demonstration choices, not universally optimal biological settings.", "hold_after": 0.7}, {"visual": "19_setting_random_seed", "narration": "Keep the reducer seed at forty-two when comparing the same inputs. The seeded CPU implementation may use one thread for reproducibility even when more workers are requested. A seed does not make different feature selections or different backends equivalent.", "hold_after": 0.7}, {"visual": "19_setting_clustering", "narration": "Clustering is separate from dimensionality reduction. This DBSCAN example assigns all four hundred objects to cluster zero, and we keep noise removal off. That single label is a computed grouping, not a finding that all cells share one phenotype.", "hold_after": 0.7}, {"visual": "19_setting_plot_images", "narration": "Enable crop images and points together. Twelve small crop glyphs make the static map inspectable without covering the point cloud. Display choices help you read the result; they do not replace reviewing the features that produced its geometry.", "hold_after": 0.7}, {"visual": "23_batch_finished", "narration": "Press Run and read the real console. This run reports median imputation of missing measurements and a four-hundred-by-two embedding. Inspect those preprocessing decisions, not just the Finished mark. No image segmentation or classifier training occurred here.", "hold_after": 0.7}, {"visual": "24_batch_figure", "narration": "Inspect the saved embedding figure and the results folder. The exported table contains the selected measurement rows, metadata and cluster labels. Do not assume that this build also exports the two plotted coordinates into that table.", "hold_after": 0.7}, {"visual": "25_interactive_embedding", "narration": "Turn on Interactive to explore the already fitted map. This is not a live refit of changing settings. Clicking points, zooming and selecting regions helps inspect the current result; changing the analysis still requires another run.", "hold_after": 0.7}, {"visual": "26_point_0", "narration": "Click a point and inspect its actual crop at the right. The displayed path ties the image to its source object. Here the crop was loaded by the real application after the click, not substituted with a representative image.", "hold_after": 0.7}, {"visual": "26_point_200", "narration": "Click another point to compare its morphology. The sidebar also offers selection labelling and automatic-cluster propagation. Those actions write annotations, unlike simply viewing a crop. We did not press them, and verified that the database remained unchanged.", "hold_after": 0.7}, {"visual": "27_fold_image_scatter", "narration": "Image Scatter and PCA now sit in Image UMAP's header. Use Image Scatter for direct feature relationships and PCA for a linear projection and its loadings. Their existing specialist lessons remain linked under this parent module.", "focus_buttons": "FoldButton", "related_lessons": ["55_image_scatter", "60_pca"], "hold_after": 0.7}, {"visual": "28_hyperparameter_controls", "narration": "Hyperparameter search opens a separate comparison panel. Keep any search small and inspect the resulting layouts before propagating settings. This recording shows the actual controls only; no search was started and no chosen result was invented.", "hold_after": 0.7}, {"visual": "24_batch_figure", "narration": "The GPU control is optional. This recording used CPU. Supported reducers can use the optional RAPIDS backend when it is available; that is a different acceleration path from Torch's device selection. Read the reported backend and do not promise identical coordinates across devices.", "hold_after": 0.7}, {"visual": "30_ai_unsent_question", "narration": "AI enables optional provider assistance, not automatic biological interpretation. This question was not sent. For scripts, the corresponding entry point is generate_image_umap in spacr.core; keep the input tables, preprocessing and saved settings with the resulting figure.", "related_lessons": ["06_api"], "hold_after": 0.7}], "poster": "15_image_umap/poster.jpg", "silent": "15_image_umap/video/15_image_umap_silent.mp4"}, {"id": "16_activation", "number": 16, "slug": "activation", "title": "Activation Maps: real saliency outputs and their limits", "series": 1, "app_key": "activation", "host_app_key": "classify_merged", "section": "Classify", "description": "Open Activation Maps inside Classify, match a trusted model to real example crops, compare two saliency outputs and inspect their actual saved grids without mistaking attribution for validation.", "objectives": ["Find the current Classify fold and preserve the model's input contract.", "Distinguish input preprocessing, display contrast and attribution methods.", "Inspect actual saved outputs when the GUI figure panel is empty.", "Separate numerical verification, model predictions and scientific validity."], "prerequisite": "Use four unchanged RGB crops from Annotate's downloaded example and the trusted local one-epoch ResNet18 checkpoint from the earlier Classify demonstration. That demonstration shares wells across its split and provides NO independent accuracy claim. The private TAR contains the original crop bytes and .spacr_crop_format.json declaring format 3 and RGB order. Copy the checkpoint and its model card; never load an untrusted artifact merely to follow this example. Actual settings: image_size=128, batch_size=4, channels=[1,2,3], normalize_input=True, normalize=True, shuffle=False, correlation=False, n_jobs=1, Plot/Save on. CPU is deliberately used for both recorded runs; no live preview or AI request. saliency_channel/overlay=True and saliency_image/overlay=False each complete on four crops. Independent differentiation of predicted-class logits verifies 196608 transformed input values and 262144 saved saliency pixel components across both methods, with at most one 8-bit level rounding tolerance. Full source identities and map database rows match. Original database, crops, model, card and private inputs remain unchanged. The false src warning and empty GUI Figures card are NOT repaired; actual saved PNG grids are opened in the real external viewer. Four unused slots remain blank in the fixed eight-column layout. No deletion/insertion, randomization, integrated-gradient, occlusion, biological-validation or publication claim. API: spacr.deep_spacr.generate_activation_maps and spacr.utils.SaliencyMapGenerator.", "scenes": [{"visual": "02_activation_fold", "narration": "Open Classify, then its nested Activation Maps tool. This workflow examines how a trained model's prediction responds to image pixels. It does not train a classifier or establish what caused an observed phenotype. We will show two real saliency runs, their console output, and an explicit saved-file viewing route.", "related_lessons": ["09_annotate", "70_explain_cv"], "hold_after": 0.7}, {"visual": "03_00_dataset", "narration": "Use the actual crop archive, not a folder placeholder. Our small archive contains four unchanged RGB cell crops from Annotate's downloaded example, plus their crop-format marker. We preserve the source files and work in a private project. Four convenient images illustrate operation; they are not a representative validation cohort.", "hold_after": 0.7}, {"visual": "03_03_image_size", "narration": "Choose the matching trusted model and retain its model card. This is a ResNet eighteen checkpoint trained for only one epoch in the earlier demonstration. Its split shared wells, so we make no independent accuracy claim. A convincing attribution picture cannot rescue an inadequately validated model. Do not load an untrusted checkpoint for convenience.", "hold_after": 0.7}, {"visual": "03_05_channels", "narration": "Match the training input contract: size one hundred twenty-eight and the declared RGB channel order. Here the actual channel selector uses one, two, three. Do not swap channels because another tool uses zero-based indices. We independently checked the center-cropped, transformed input values against the training loader before comparing any saliency output.", "hold_after": 0.7}, {"visual": "03_06_normalize_input", "narration": "Distinguish input normalization from display normalization. Input normalization must match training; here it is enabled with the recorded symmetric preprocessing. Display normalization changes how the overlaid input looks, not the model's accuracy or the meaning of a color. Preserve both settings when comparing runs, and do not confuse a brighter picture with stronger evidence.", "hold_after": 0.7}, {"visual": "04_channel_saliency_method_and_overlay", "narration": "Choose saliency channel with Overlay enabled, and keep Plot and Save on. We use one worker, a batch of four and CPU for this small demonstration. The screen has no live-preview control; changing a method requires another run. Channel saliency keeps the input channels separate when saving the derivative-based maps.", "hold_after": 0.7}, {"visual": "04_channel_saliency_finished_console", "narration": "Read the actual console. The calculation completes, but this build incorrectly complains about missing src even though Activation uses Dataset. Its Figures panel also stays empty. We independently checked the input, saved maps and database identities; we did not repair those GUI defects. Other errors still require investigation.", "hold_after": 0.7}, {"visual": "04_channel_saliency_09_saved_batch_0_grid", "narration": "Open the saved batch grid in an image viewer. This is the real external viewer, not a figure inserted into spaCR. Four occupied slots correspond to our four crops; the remaining four slots are unused. Corner labels zero and one are model predictions, not ground truth. The overlay is a sensitivity visualization, not a segmentation mask.", "hold_after": 0.7}, {"visual": "05_image_saliency_method_and_overlay", "narration": "Now choose saliency image, disable Overlay and run again on the same inputs. This method combines the absolute derivatives across channels before the saved grayscale map is rescaled. It is not occlusion or integrated gradients. Keep method-specific outputs separate so a second run cannot be mistaken for the first.", "hold_after": 0.7}, {"visual": "05_image_saliency_09_saved_batch_0_grid", "narration": "The second saved grid shows the maps without the underlying images. Its colors show the displayed saliency scale, not class probabilities or proof of biological importance. Independent checks compare every saved map component with a separately computed gradient, allowing at most one eight-bit rounding level. That checks implementation, not whether the explanation is useful.", "hold_after": 0.7}, {"visual": "03_11_correlation", "narration": "Map quantification is off in this example. We have not run deletion, insertion, model-randomization or other attribution-validation tests, and two visually different methods do not substitute for them. Before drawing conclusions, use representative failures and successes, meaningful controls, and independently held-out data. Treat this limited demonstration as a workflow check.", "related_lessons": ["39_classifier_evaluation", "70_explain_cv"], "hold_after": 0.7}, {"visual": "05_image_saliency_11_back_to_actual_gui", "narration": "Keep the crop identities, original images, model and card, settings, logs, maps and database together. The source files stayed unchanged and both methods retained all four identities. AI assistance is optional; no request was submitted here. Check any later advice against the actual API and evidence, rather than treating a fluent explanation as validation.", "related_lessons": ["06_api"], "hold_after": 0.7}], "poster": "16_activation/poster.jpg", "silent": "16_activation/video/16_activation_silent.mp4"}, {"id": "17_timelapse", "number": 17, "slug": "timelapse", "title": "Timelapse", "series": 2, "app_key": "timelapse", "section": "Core", "host_app_key": "mask", "description": "Use the nested Mask workflow, run a synthetic eight-frame demo and compare real cached-mask linking through the current Track preview.", "objectives": ["Find Timelapse under Mask and preserve the time axis and original images.", "Compare baseline, excessive-overlap and explicitly re-linked restored tracks on the same masks.", "Distinguish tracking indicators, playback speed, model inference and measured biological motion."], "example_files": ["SYNTHETIC_timelapse_preview.zip"], "prerequisite": "Use Help > Demos > Timelapse demo in a new folder. The generated data are synthetic: eight 256-by-256 timepoints, nucleus channel 0 and cell channel 1. They are not an acquired experiment or a segmentation-accuracy benchmark. The recording uses the current Mask > Time fold, Plot and Keep original images on, IoU tracking of cells, frame slice [0, 8] and displacement 50. All sixteen generated TIFFs survive byte-identically in orig; older tutorial inputs remain unchanged. The actual run writes eight merged arrays, five displayed figures, four eight-frame MP4 files and 128 cell-table rows for sixteen eight-frame tracks. Independent checks cover every saved centroid and mask membership. The companion ZIP contains only exact exported cell intensity and cell label planes, a manifest and teaching instructions; it is not a second acquired dataset. Its grayscale preview channel is 0, whereas the original cell channel was 1. Choose image_sequences/field_A01 and label_sequences/field_A01 separately, with one displayed field and eight frames. IoU 0.1 gives sixteen complete tracks; 1.0 gives 128 single-frame tracks. Restore 0.1, wait until idle, then explicitly click Re-link: typing can trigger an intermediate-value pass. Actual worker signals confirm the final requested value and no segmentation during this loaded-mask exercise. The IoU threshold is not propagated to the batch form. The normal font preference (1.0) keeps preview controls readable; the larger 1.5 setting clipped them in this layout. The build reports inherited flow-threshold, relationships-table and settings-status warnings; those are disclosed, not suppressed. Its measurement database has count/status tables, not measured object relationships. Figure intensities are display-normalized, not raw pixel values. This is bounded tutorial validation, not release certification, physical velocity calibration, native-language listening approval or biological validation. API entry point: spacr.core.preprocess_generate_masks; tracking implementations: spacr.timelapse. spaCR AI was kept off and no provider request was sent.", "scenes": [{"visual": "02_timelapse_fold", "narration": "Open Mask and enable its Time switch. Timelapse is now nested inside Mask, not a separate Home tile. It adds time-axis and tracking settings to the segmentation workflow. Motility measurements belong to Measure, which is a later step.", "hold_after": 0.7, "focus": [3535, 1905, 280, 85], "related_lessons": ["07_mask", "18_motility"]}, {"visual": "03_actual_demo_menu", "narration": "Choose Help, Demos, then Timelapse demo, and select a new folder. This creates eight synthetic frames with drifting objects and loads their settings. These are teaching images, not a biological experiment or evidence of segmentation accuracy.", "hold_after": 0.7, "focus": [70, 20, 535, 230]}, {"visual": "05_demo_loaded", "narration": "Check the populated source and channels. This demo has nucleus intensity in channel zero and cell intensity in channel one, with no pathogen channel. Its filenames encode time separately from field and channel. Do not substitute the ordinary static test plate for a time series.", "hold_after": 0.7, "focus": [235, 175, 1185, 470]}, {"visual": "05_setting_timelapse_frame_limits", "narration": "Frame limits are zero-based slice boundaries: zero to eight includes all eight frames, while the end is excluded. Keep a single field's timepoints together. A playback rate cannot supply a missing acquisition interval, and this demo does not establish velocities in physical units.", "hold_after": 0.7, "focus": [235, 1225, 1185, 300]}, {"visual": "05_setting_timelapse_mode", "narration": "Track cells with the overlap-based mode, labelled iou. It links masks by intersection over union between adjacent frames. The other backends have different assumptions and optional dependencies. A displacement setting is not an overlap threshold; use controls that the chosen backend actually reads.", "hold_after": 0.7, "focus": [235, 1500, 1185, 490]}, {"visual": "05_setting_keep_original_images", "narration": "Turn Keep original images on before Run. The pipeline can otherwise remove its intermediate and original-image folders during cleanup. This recording keeps all sixteen generated TIFFs unchanged, and never touches the older tutorial data. Always keep a separate backup of an acquired experiment.", "hold_after": 0.7, "focus": [235, 1140, 1185, 300]}, {"visual": "05_setting_plot", "narration": "Turn Plot on and run this small example. The current pipeline processes the complete eight-frame sequence together even if the requested batch size is smaller. Watch the console and resource monitor; more frames, larger images and additional objects can require much more memory.", "hold_after": 0.7, "focus": [235, 1070, 1185, 230]}, {"visual": "08_actual_figure_04", "narration": "The run produces five figures and eight merged arrays. In this normalized display, the first two planes are intensities; the last two are cell and nucleus labels, not extra acquisition channels. The saved cell table contains sixteen tracks, each spanning eight frames.", "hold_after": 0.7, "focus": [1440, 140, 2370, 355]}, {"visual": "07_actual_finished", "narration": "Read the warnings as well as Finished. This build warns about inherited flow-threshold values and an unavailable relationships table, and shows a settings-status warning. We verified the saved masks and tracks separately; this is not a clean release test or a substitute for running Measure.", "hold_after": 0.7, "focus": [1440, 500, 2370, 1260]}, {"visual": "09_actual_track_preview", "narration": "Open Track preview. For a reproducible linking exercise, download and extract the synthetic preview archive linked below. It contains exact cell-image and cell-mask planes from this recorded batch. Loading those masks tests linking without running another segmentation model.", "hold_after": 0.7, "focus": [1440, 755, 2370, 1150]}, {"visual": "10_actual_image_sequence_folder", "narration": "Choose the image-sequence folder for field A zero one. These exported images contain only the original cell-intensity plane, so choose channel zero here. Keep image and label sequences under separate parent folders, and set Frames previewed to eight and Fields to one.", "hold_after": 0.7}, {"visual": "11_actual_mask_sequence_folder", "narration": "Choose the corresponding label-sequence folder using Masks. These are computed masks, not ground truth. Leave Keep only full-length tracks off and do not click Propagate settings. The model controls do not create new masks when an existing mask sequence is being read.", "hold_after": 0.7}, {"visual": "12_actual_linked_preview", "narration": "Run preview with the overlap threshold at zero point one. It reports sixteen tracks of eight frames, with no short tracks in this example. The fragmentation and jump values are indicators computed without ground truth; small values alone do not prove that identities are biologically correct.", "hold_after": 0.7, "focus": [1440, 755, 2370, 800]}, {"visual": "13_actual_strict_overlap", "narration": "Raise the overlap threshold to one. Requiring exact overlap breaks this moving example into one hundred twenty-eight one-frame tracks. The images and masks are unchanged; only the links change. This deliberately excessive value demonstrates fragmentation, not a recommended analysis setting.", "hold_after": 0.7, "focus": [1440, 755, 2370, 800]}, {"visual": "14_actual_overlap_restored", "narration": "Restore zero point one, wait for the current preview to finish, then click Re-link. Typing can start a pass for an intermediate value, so confirm the final pass explicitly. The sixteen complete tracks return. Do not click Propagate settings: the overlap threshold is not transferred to the batch form.", "hold_after": 0.7, "focus": [1440, 755, 2370, 1150]}, {"visual": "15_actual_final_frame", "narration": "Scrub to frame eight to inspect the linked objects. Playback speed only changes viewing speed, not the acquisition time. Continue to Measure and Motility for measurements using a validated interval and scale. The API and spaCR AI can help explain settings, but neither replaces checking images, tracks and warnings.", "hold_after": 0.7, "focus": [1440, 1250, 2370, 320], "related_lessons": ["08_measure", "18_motility", "06_api"]}], "poster": "17_timelapse/poster.jpg", "silent": "17_timelapse/video/17_timelapse_silent.mp4"}, {"id": "18_motility", "number": 18, "slug": "motility", "title": "Motility assay", "series": 2, "app_key": "motility", "section": "Core", "host_app_key": "measure", "description": "Use Measure’s nested Motility workflow and reproducible synthetic tracks to explore live filters, unknown units and an explicitly hypothetical calibration.", "objectives": ["Find Motility inside Measure and load the exact tracked-array example.", "Compare live length and straightness filters without rereading images or rerunning a model.", "Distinguish pixel velocities, hypothetical unit conversion, infection labels and saved-figure limitations."], "example_files": ["SYNTHETIC_motility_tracks.zip"], "prerequisite": "Complete the Timelapse lesson or extract the linked synthetic tracked-array archive into a new folder. These are exact outputs from Help > Demos > Timelapse demo: eight 256-by-256 uint16 arrays with nucleus intensity 0, cell intensity 1, tracked cell masks 2 and nucleus masks 3. Sixteen cell tracks span all eight frames. Masks are computed outputs, not ground truth; there is no pathogen plane or acquired physical calibration. Select the extracted root containing merged, not an ordinary static test plate. The recorded native batch uses cell tracking, channels [0,1], no pathogen channel, reuse_existing_measurements=False, n_jobs=1, displacement 50, straightness filtering off, infection QC scope none, QC graphs on and plot bounds [-30,30]. The batch numeric widgets cannot represent None; 2 pixels/um and 60 seconds/frame are explicitly hypothetical arithmetic inputs, not measured acquisition metadata. The live preview independently uses two intensity channels, tracked plane 2, pathogen plane -1, eight frames and unknown calibration 0/0. Minimum length 3 -> 9 -> 3 retains 16 -> 0 -> 16 usable tracks. Drop over-straight tracks at 0.95 retains one; disabling restores sixteen. A single supplied calibration value leaves px/frame; both hypothetical values change the mean from 1.4001441642 px/frame to 0.7000720821 um/min without changing tracks or the pixel trajectory axes. Independent checks verify all 128 observations, 256 saved centroid coordinates, 256 saved raw channel means, the well summary and every preview state. The batch saves tables and two PDF files but queues no GUI figures. Native PDFs have low-contrast marks; Screen export did not repair them. The tutorial shows genuine readable live plots and discloses this limitation, not a publication-ready PDF. Uninfected here means no supplied pathogen mask, not validated negative infection status. No XGBoost classifier or biological comparison was validated. API entry point: spacr.timelapse.automated_motility_assay. spaCR AI stayed off; no provider request was sent. Technical tutorial validation is not native-speaker/listening approval or release certification.", "scenes": [{"visual": "01_measure_host", "narration": "Open Measure, then its Time shortcut to reach the Motility Assay tab. This is a nested module, not a separate Home tile. Timelapse under Mask creates tracks; Motility measures them. Review the Timelapse lesson first if your images are not already tracked.", "focus": [3570, 1900, 220, 90], "related_lessons": ["08_measure", "17_timelapse"], "hold_after": 0.7}, {"visual": "03_actual_setting_src", "narration": "Download the synthetic tracked-array example linked below and extract it into a new folder. Set Source to the folder containing merged. Its eight frames contain sixteen cell tracks. Choose cell, nucleus channel zero and cell channel one, with no pathogen channel.", "focus": [250, 305, 1185, 285], "hold_after": 0.7}, {"visual": "03_actual_setting_pixels_per_um", "narration": "For an acquired experiment, use the actual pixel scale and frame interval. Here, two pixels per micrometre and sixty seconds per frame are deliberately hypothetical, solely to demonstrate arithmetic. The batch form requires numbers; its defaults are not evidence of your microscope calibration.", "focus": [250, 600, 1185, 150], "hold_after": 0.7}, {"visual": "03_actual_setting_infection_intensity_qc_graphs", "narration": "Leave Reuse existing measurements off for this fresh copy, and enable the quality-control graphs. There is no pathogen channel, so infection quality control is disabled in this run. Optional infection classifiers are not being tested, and these teaching tracks cannot establish an infection effect.", "focus": [250, 810, 1185, 760], "hold_after": 0.7}, {"visual": "05_actual_finished", "narration": "Run the small example and read the console. The batch saves one hundred twenty-eight frame observations and a sixteen-track well summary, plus P D F files. Those files do not appear in the figure queue. This build warns about faint export colours; inspect exports before using them in a report.", "focus": [1440, 305, 2375, 850], "hold_after": 0.7}, {"visual": "07_actual_preview", "narration": "Enable Live to open Motility preview. Fold Console and System if they crowd the plots, then choose the same extracted plate folder. Preview metrics and batch settings are separate. Leave Propagate settings off while experimenting so a temporary filter does not change the next full run.", "focus": [1440, 305, 2375, 550], "hold_after": 0.7}, {"visual": "09_actual_plane_and_unit_settings", "narration": "Set two intensity channels, tracked mask plane two, and pathogen mask plane minus one, meaning none. Preview all eight frames. A nucleus mask is not a pathogen mask. Set both calibration fields to zero here to represent unknown units, then click Run preview.", "focus": [1455, 395, 2340, 300], "hold_after": 0.7}, {"visual": "10_actual_uncalibrated_preview", "narration": "The preview reads one hundred twenty-eight object observations and reports sixteen usable tracks at minimum length three. Mean speed is about one point four pixels per frame. Without both calibration values, it must not be described as micrometres per minute.", "focus": [1455, 1600, 2340, 200], "hold_after": 0.7}, {"visual": "11_actual_all_short", "narration": "Raise Min track length to nine. Each track has only eight frames, so all sixteen are excluded from the usable summary and mean speed becomes unavailable. This does not delete the underlying tracks or images. It demonstrates why an empty summary is not a zero speed.", "focus": [1455, 405, 2340, 1390], "hold_after": 0.7}, {"visual": "12_actual_length_restored", "narration": "Restore the minimum to three. Sixteen usable tracks return, along with the length distribution and velocity points. The preview recomputes these metrics from cached observations. Changing a metric here does not rerun segmentation or prove that the original tracking identities were correct.", "focus": [1455, 690, 2340, 1110], "hold_after": 0.7}, {"visual": "13_actual_straightness_filter", "narration": "Enable Drop over-straight tracks at a threshold of zero point nine five. Straightness is net displacement divided by path length. Fifteen nearly straight teaching tracks are excluded, leaving one. Straight motion can be genuine; this filter is not an automatic proof of drift or an analysis recommendation.", "focus": [1455, 405, 2340, 1390], "hold_after": 0.7}, {"visual": "14_actual_filter_restored", "narration": "Switch that filter off and confirm all sixteen tracks return. Compare the plots and retained count before accepting any filtering rule. The uninfected label here only reflects the absent pathogen plane; it is not a validated biological negative group.", "focus": [1455, 690, 2340, 1110], "hold_after": 0.7}, {"visual": "15_actual_one_unit_unknown", "narration": "Enter two pixels per micrometre but leave the frame interval unknown. The preview still reports pixels per frame. Spatial scale alone cannot supply missing time, and video playback speed is not the acquisition interval.", "focus": [3010, 400, 785, 255], "hold_after": 0.7}, {"visual": "16_actual_hypothetical_calibration", "narration": "Now enter sixty seconds per frame. With both hypothetical values supplied, mean speed changes from about one point four pixels per frame to zero point seven micrometres per minute. Track identities do not change. The trajectory panel still labels displacement in pixels; only the velocity unit has changed here.", "focus": [1455, 405, 2340, 1390], "hold_after": 0.7}, {"visual": "17_actual_unknown_units_restored", "narration": "Return both preview calibration fields to zero. The original pixel-unit summary returns exactly. Keep this arithmetic exercise separate from real acquisition metadata, and use the API reference for the batch function. spaCR AI can explain settings, but it cannot certify calibration, infection status or scientific validity.", "focus": [1455, 405, 2340, 1390], "related_lessons": ["06_api", "17_timelapse", "34_database"], "hold_after": 0.7}], "poster": "18_motility/poster.jpg", "silent": "18_motility/video/18_motility_silent.mp4"}, {"id": "19_train_cellpose", "number": 19, "slug": "train_cellpose", "series": 3, "app_key": "train_cellpose", "host_app_key": "make_masks", "section": "Tools", "title": "Train Cellpose: verified pairs and an explicit API workaround", "description": "Find Train inside the Cellpose Workbench, recognise the current source-import defect, and follow a real two-epoch Python training demonstration using six downloadable cell-image/mask pairs.", "objectives": ["Find Train and Apply within Make Masks rather than looking for separate Home tiles.", "Check matching cell-image/mask filenames and distinguish existing labels from reviewed ground truth.", "Recognise partial settings import and keep the explicit API route separate from the broken GUI route.", "Inspect actual training inputs, warm-up rates, changed weights and the verified checkpoint path.", "Distinguish training loss, placeholder test slots and checkpoint deserialization from independent model accuracy."], "example_files": ["Train_Cellpose_API_example.zip"], "prerequisite": "Use the linked six-pair bundle with the recorded helper and source manifest. The corrected examples preserve cell intensity channel 1 and cell mask plane 4 from real downloaded fields; plane 6 is pathogen. Existing labels and edge-cut instances are NOT independently reviewed ground truth. The native Train CSV import still drops required src and keeps model_name=new_model, although numerical controls import. No GUI training starts. The explicit spacr.submodules.train_cellpose call uses a new private destination, two epochs, minibatch 1, learning_rate=1e-5, weight_decay=1e-5, target_size=512 and no extra spaCR augmentations. normalize=False disables spaCR percentile preprocessing, not maximum scaling or Cellpose's internal normalisation. Cellpose still rotates/resizes and uses internal 256-pixel patches. Seed 19 is set at entry; internal randomisation remains. CUDA is bounded to 65 percent on the recorded RTX 3090, with a 100 GiB system-RAM guard appropriate only to this workstation. All 3,145,728 image/label values and twelve preview arrays were checked. All six pairs remained in training. Actual warm-up rates were 0 and 1.1111111111111112e-6; 345 of 347 trainable parameter tensors changed. Loss rose from 1.496740683913231 to 1.5215517828861873. No test data were supplied; zero test-loss slots are placeholders. The checkpoint under models/cellpose_model/models was read with weights_only=True; the generic console path omits the second models directory. Deserialization is not inference or accuracy validation. The real figure is shown in an external viewer, never inserted into GUI Figures. Original data, previous failed captures and the old GUI hold are preserved. No AI request, provider response, scientific approval or publication.", "scenes": [{"visual": "gui_01_make_masks_host", "narration": "Open Make Masks, then its nested Cellpose Workbench. Train and Apply are tabs inside that workbench, not separate Home tiles. This lesson shows the current route, a settings-import problem and an explicit Python workaround. The linked Make Masks lesson covers inspecting and editing masks before any training.", "related_lessons": ["14_make_masks", "20_cellpose_masks"], "hold_after": 0.7}, {"visual": "gui_02_actual_train_tab", "narration": "On Train, inspect the starting point and training schedule. Do not copy the initial epoch count or learning rate as a recommendation. Training needs matching images and instance masks, plus a source folder and an output name. Merely seeing a form does not mean those requirements are satisfied.", "hold_after": 0.7}, {"visual": "gui_02a_real_settings_import_picker", "narration": "The real Import settings picker opens a CSV with our bounded example settings. After import, two epochs, minibatch one and the small learning rate appear. However, the required source is dropped and the requested model name stays new model. This is a partial import, not a ready configuration; do not press Run.", "hold_after": 0.7}, {"visual": "gui_02b_actual_imported_values", "narration": "The Python route below is separate from this GUI defect. It does not secretly set a hidden source or repair the form. Use the linked example bundle in a fresh folder. Its helper refuses an existing destination, preserves the original pairs, and records exactly which API implementation and inputs were used.", "related_lessons": ["06_api"], "hold_after": 0.7}, {"visual": "command_01_verified_cell_pairs", "narration": "There are six real, five-hundred-and-twelve-pixel image and mask pairs with matching filenames. Original settings identify cell intensity as channel one and cell masks as plane four; plane six is pathogen. These existing labels are not independently reviewed ground truth. Check boundaries and edge-cut objects before using any such labels for production training.", "focus": [190, 80, 3450, 900], "hold_after": 0.7}, {"visual": "gui_09_saved_actual_training_pairs", "narration": "This is the actual six-pair figure saved by the API run and opened in an external viewer, not inserted into spaCR. Each top image corresponds to the mask directly below it. We checked all input image and label values and these twelve displayed arrays against the source pairs. That verifies correspondence, not annotation quality.", "focus": [560, 610, 2750, 970], "hold_after": 0.7}, {"visual": "command_02_actual_two_epoch_api", "narration": "Run the helper with its data source and a new destination. This bounded CUDA example uses all six pairs, two epochs and minibatch one. The input target is five hundred twelve pixels; Cellpose internally trains on two-hundred-and-fifty-six-pixel patches. Disabling spaCR's extra augmentations does not disable Cellpose's own normalisation, rotation and resizing.", "focus": [190, 80, 3450, 1150], "hold_after": 0.7}, {"visual": "command_03_actual_checkpoint_checks", "narration": "The first warm-up epoch has zero learning rate. The second uses a small positive rate, allowing actual weight updates. We compared the saved checkpoint with the initial trainable weights: three hundred forty-five of three hundred forty-seven parameter tensors changed. A changed diameter setting alone would not pass that check. Changed weights still do not establish a good model.", "focus": [190, 80, 3450, 950], "hold_after": 0.7}, {"visual": "command_03_actual_checkpoint_checks", "narration": "Training loss rose slightly, from about one point four nine seven to one point five two two. No test set was supplied. The zero test-loss slots are placeholders, not perfect test performance. This is a short mechanics demonstration, not convergence, improved segmentation or held-out accuracy. Keep an independent evaluation separate from training.", "focus": [190, 80, 3450, 950], "hold_after": 0.7}, {"visual": "command_03_actual_checkpoint_checks", "narration": "Use the checkpoint path in the verified checks file. It includes a second models directory that the generic console summary omits. Keep the checkpoint with its settings, source manifest and checks. Loading its tensors safely verifies a readable checkpoint, not an inference result; the downloadable bundle contains the pairs and helper, not a certified model.", "focus": [190, 80, 3450, 950], "hold_after": 0.7}, {"visual": "gui_12_actual_apply_tab_no_inference", "narration": "Apply has a separate source folder, custom-model field and live preview. Opening this tab does not select our external checkpoint or run inference. Follow its linked lesson before applying a model, and validate on independent images. The optional spaCR AI console control is unused here: no question or provider response substitutes for inspecting the real evidence.", "related_lessons": ["20_cellpose_masks", "14_make_masks", "06_api"], "hold_after": 0.7}], "poster": "19_train_cellpose/poster.jpg", "silent": "19_train_cellpose/video/19_train_cellpose_silent.mp4"}, {"id": "20_cellpose_masks", "number": 20, "slug": "cellpose_masks", "series": 3, "app_key": "cellpose_masks", "host_app_key": "make_masks", "section": "Tools", "title": "Apply Cellpose: saved masks and live-filter checks", "description": "Apply stock CPSAM to three downloadable real images through the nested Workbench, inspect native figures and console output, and test live filters without confusing preview with batch inference.", "objectives": ["Find Apply inside Make Masks and its Cellpose Workbench.", "Use the recorded source, channel and stock-model settings on preserved real-image copies.", "Inspect the three actual saved masks and their original, outline and flow figures.", "Demonstrate reversible live filtering and synchronized wheel zoom.", "Recognise the measured preview-versus-batch mismatch and avoid accuracy claims."], "example_files": ["Apply_Cellpose_stock_example.zip"], "prerequisite": "Extract the linked three-image example into a new directory and set src to its images folder; recorded_settings.json contains historical resolved values, not a demonstrated portable GUI import. These real 512-square uint16 cell crops are not ground truth. Stock CPSAM is selected, not the Train lesson checkpoint. Batch choices are channels=[0], normalize=True, percentiles=[2,99], diameter=30, CP_prob=0, flow_threshold=0.4, batch_size=1, save=True and verbose=True; rescale, resample, resize, fill_in, invert and remove_background are False. The actual CUDA run saves 9/94/46 labels and three GUI figures. Direct reference calls independently reproduce all mask pixels and all three figure arrays. Outlines show external foreground contours, not every touching instance border; the flow panel is one visualization channel, not measured motion. Live preview of image 02 yields 95, not 94: it matches raw-image Cellpose defaults rather than the batch preprocessing/resampling path. Displayed 2/99 controls do not establish equivalence. Area cutoff 1838 gives 95->47->95, every restored pixel checked without model rerun; saved batch masks are unchanged. Native wheel zoom synchronizes both canvases but crops the view and does not fix the narrow preview card. Earlier holds and source data remain preserved. No biological accuracy certification, AI request, publication or application modification.", "scenes": [{"visual": "02_actual_train_and_apply_tabs", "narration": "From Make Masks, open the nested Cellpose Workbench and choose Apply. Train and Apply share this workbench; Apply is not a separate Home tile. This lesson uses the stock model on three real images. It does not use the demonstration checkpoint from the linked Train lesson.", "related_lessons": ["14_make_masks", "19_train_cellpose"], "hold_after": 0.7}, {"visual": "04_setting_src", "narration": "Extract the linked example into a new folder. Set source to its images directory, preserving the original download. These are three single-channel cell images, each five hundred twelve pixels square. They are demonstration inputs, not segmentation ground truth. Use the recorded settings as a reference, replacing the historical source path with your own.", "hold_after": 0.7}, {"visual": "05_setting_model_name", "narration": "Select CPSAM and leave custom model empty. For these images, the channel list is zero, normalization uses the second and ninety-ninth percentiles, diameter is thirty, flow threshold is zero point four, and cell probability is zero. These are bounded example choices, not recommended settings for every experiment.", "hold_after": 0.7}, {"visual": "14_actual_inference_outcome", "narration": "With Save and Verbose enabled and batch size one, run Apply. This route creates figures without a separate Plot switch. The real console identifies an RTX thirty-ninety using CUDA and finishes all three images. Check the source and saved settings there; a Finished message alone is not an accuracy measurement.", "hold_after": 0.7}, {"visual": "15_actual_mask_and_flow_figures", "narration": "Three same-named mask TIFFs are saved in the source folder's masks subdirectory. The counts are nine, ninety-four and forty-six. These genuine figures show the input, red foreground contours and a flow visualization. The contours do not trace every touching instance boundary, and flow colours are not physical motion or segmentation accuracy.", "focus": [1000, 450, 2780, 640], "hold_after": 0.7}, {"visual": "17_actual_preview_image_picker", "narration": "Turn on Live preview and use its actual image picker to choose cell pair zero two. Collapse Console and System when you need more viewing space. Preview has its own controls: check channel zero and the displayed percentile values in Live settings rather than assuming every Apply option was copied.", "hold_after": 0.7}, {"visual": "20_actual_preview_result", "narration": "This preview finds ninety-five objects, while the saved batch mask for the same image has ninety-four. Independent checks reproduce both results: the preview follows Cellpose's raw-image defaults, not the batch's explicit preprocessing and resampling choices. Treat it as an exploratory view, not a guarantee of identical saved masks.", "focus": [1000, 1160, 2780, 610], "hold_after": 0.7}, {"visual": "20a_actual_zoomed_preview", "narration": "The preview card remains narrow in this build. Wheel zoom enlarges a detail on both canvases together; it does not enlarge the card, and the full image is now cropped. This is useful for inspecting local outlines, but keep whole-field review separate from a zoomed detail.", "focus": [1010, 1280, 2750, 455], "hold_after": 0.7}, {"visual": "22_native_filter_reduces_objects", "narration": "Open Live settings and set the minimum cell area to eighteen hundred thirty-eight pixels. This is a demonstration cutoff, not an optimal biological threshold. Close the dialog to see the result. The live filter removes forty-eight objects, leaving forty-seven, without rerunning Cellpose or changing its raw segmentation.", "hold_after": 0.7}, {"visual": "22b_actual_zoomed_filtered_preview", "narration": "Here is the filtered preview with the dialog closed and wheel zoom reapplied. The original image is unchanged while small mask objects disappear. The counter now says forty-seven. These changes affect the preview; they do not rewrite the three batch TIFFs already saved on disk.", "focus": [1010, 1280, 2750, 455], "hold_after": 0.7}, {"visual": "23b_actual_zoomed_restored_preview", "narration": "Return minimum area to zero, close the dialog and inspect again. Ninety-five objects return, and every restored label pixel matches the baseline. Keep the inputs, settings and model identity with the saved masks. The optional spaCR AI console is unused here; independent validation remains your responsibility before drawing scientific conclusions.", "focus": [1010, 1280, 2750, 455], "related_lessons": ["07_mask", "06_api"], "hold_after": 0.7}], "poster": "20_cellpose_masks/poster.jpg", "silent": "20_cellpose_masks/video/20_cellpose_masks_silent.mp4"}, {"id": "21_model_compare", "number": 21, "slug": "model_compare", "title": "Model Compare", "series": 2, "app_key": "model_compare", "section": "Segmentation models", "description": "This tutorial is not available yet. Please explore the other tutorials.", "objectives": [], "prerequisite": "", "scenes": [], "host_app_key": "make_masks", "status": "coming_soon", "availability_title": "Coming soon"}, {"id": "22_model_zoo", "number": 22, "slug": "model_zoo", "title": "Model Zoo", "series": 2, "app_key": "model_zoo", "section": "Segmentation models", "description": "This tutorial is not available yet. Please explore the other tutorials.", "objectives": [], "prerequisite": "", "scenes": [], "host_app_key": "make_masks", "status": "coming_soon", "availability_title": "Coming soon"}, {"id": "23_agreement", "number": 23, "slug": "agreement", "title": "Annotator Agreement", "series": 3, "app_key": "agreement", "host_app_key": "annotate", "section": "Results and quality control", "description": "Open the nested agreement tool, compare explicitly artificial teaching labels on copies of real downloaded crops, and distinguish pairwise agreement from a multi-pass summary.", "objectives": ["Open Annotator Agreement from the Annotate module.", "Compare labels, missing observations and confusion matrices without changing annotations.", "Inspect disagreement crops and interpret two-pass versus three-pass summaries."], "prerequisite": "The sixteen crop images are unchanged copies from Annotate's downloadable example, but DEMO_A, DEMO_B and DEMO_C are deliberately artificial teaching labels added to a new private database. They are not biological classifications, human-reviewer scores or model predictions. Existing source labels and images remain unchanged; png_path is made relative only in the demonstration copy. Use real independent annotation passes for your own quality assessment. Current known model-output columns are excluded from the GUI's default discovery; model validation is a different question. Independent integer/fraction calculations verify every demonstrated pair, confusion matrix and aggregate. Three selected previews match their source crop pixels exactly. This small example is for learning the controls, not validating assay reliability. The existing video repeated an empty screen, and its old automatic prediction-discovery wording no longer matches the API, so this is not merely a moved lesson.", "scenes": [{"visual": "02_agreement_fold", "narration": "Open Annotate, then its Annotator Agreement button. This is a nested tool, not another Home module. The comparison view reads annotation columns without editing them; return to Annotate when you actually want to change a label.", "related_lessons": ["09_annotate"], "hold_after": 0.7}, {"visual": "04_demo_database", "narration": "Open the prepared demonstration database. Its sixteen images are real downloadable example crops, but the three DEMO columns are artificial teaching labels. They do not measure a person's skill or a biological phenotype. The original labels and images were preserved in a separate source copy.", "hold_after": 0.7}, {"visual": "05_one_column_not_a_comparison", "narration": "Check the selected columns explicitly rather than accepting the first defaults. A single column cannot measure agreement. The current discovery excludes known model-output columns by default; comparing a classifier with a person is model validation, not agreement between people.", "hold_after": 0.7}, {"visual": "06_two_columns", "narration": "Select DEMO A and DEMO B, then press Compute agreement. There are twelve crops labelled by both passes, three labelled by only one, and one labelled by neither. Missing labels are not silently converted into disagreements.", "hold_after": 0.7}, {"visual": "07_pairwise_results", "narration": "The two teaching passes agree on nine of twelve compared crops: seventy-five percent, with Cohen's kappa zero point five. Read the raw agreement, overlap and class balance together. The screen warns that twelve shared labels are too few for a stable reliability estimate; these invented labels are only a demonstration.", "hold_after": 0.7}, {"visual": "08_confusion_matrix", "narration": "Read rows as DEMO A and columns as DEMO B. Five crops have class one in both passes, and four have class two in both. The off-diagonal counts, one and two, identify three disagreements. A summary label such as moderate is a convention, not an acceptance threshold for your assay.", "hold_after": 0.7}, {"visual": "09_disagreement_crop_1", "narration": "Select a disagreement to inspect the corresponding crop and both labels. We checked all three previews against their original pixels. For a real study, review representative images and the class definitions before deciding how to adjudicate; this read-only screen does not make that decision for you.", "hold_after": 0.7}, {"visual": "10_three_columns", "narration": "Add DEMO C and compute again. Changing a checkbox is not a new computation by itself. The table now compares three pairs, whose shared-label counts differ, while the overall Fleiss summary uses only the twelve crops labelled by every selected pass.", "hold_after": 0.7}, {"visual": "11_three_pass_results", "narration": "The teaching example's Fleiss kappa is about zero point six six three, not the average of the three pairwise kappas. Overall raw agreement here counts unanimous complete rows. The fourth review row has a missing A label but disagreement between B and C, so it can appear for review without entering the complete-case summary.", "hold_after": 0.7}, {"visual": "12_pairwise_restored", "narration": "Selecting just A and B and computing again restores the original comparison. We verified that the database and crop files remain unchanged through all three computations. Use genuinely independent annotation passes for your own analysis, and return to the Annotate tutorial for collecting those labels.", "related_lessons": ["09_annotate", "34_database"], "hold_after": 0.7}], "poster": "23_agreement/poster.jpg", "silent": "23_agreement/video/23_agreement_silent.mp4"}, {"id": "24_plaque", "number": 24, "slug": "plaque-assay", "title": "Plaque Analysis", "series": 3, "app_key": "analyze_plaques", "section": "Toxoplasma assays", "description": "Reuse constructed masks, explicitly select a plaque checkpoint for live preview, test reversible area filters and inspect the real saved tables.", "objectives": ["Distinguish saved-mask analysis from fresh model predictions.", "Select the current plaque checkpoint and verify live filtering without rerunning segmentation.", "Inspect counts and pixel areas without inventing physical calibration or biological effects."], "example_files": ["SYNTHETIC_plaque_example.zip"], "prerequisite": "Download and extract the accompanying explicitly SYNTHETIC example into a new folder. Its four grayscale TIFFs and four precomputed label TIFFs are byte-identical to the preserved teaching inputs; no old database, settings or model weights are included. Set Source to SYNTHETIC_plaque and Masks off. The example has ten constructed objects (four, three, two and one), no acquired images and no physical calibration. Control/treatment filenames are not experimental evidence. The current GUI run creates masks/plaques_analysis.db. Its three saved tables are checked independently, including all 68 numeric or null fields. A separately downloaded Model Zoo checkpoint, toxoplasma_plaque_v1 / cpsam_plaque_r3, is checksum-verified and predicts four objects in the first synthetic image. Its masks differ from the supplied masks; this is not an accuracy benchmark. A minimum-area threshold of 26211 retains two, and zero restores all four without a model rerun. The preview does not initially inherit plaque_model, and model/filter changes must not be assumed to propagate to batch settings. Well detection and physical calibration are not demonstrated. The actual Help > Database browser opens the output read-only. Original and private inputs and the inspected output remain unchanged. No native-language listening approval, biological validation or publication is claimed. The form resolves plaque_model even with Masks off: choose an existing checkpoint path before Run. API entry point: spacr.submodules.analyze_plaques. No batch run with newly generated masks is claimed.", "scenes": [{"visual": "01_module", "narration": "Open Plaque Analysis in the Assays section of Home. This lesson uses four synthetic images with constructed masks, not acquired infection data. We will count the saved masks, try a separate model preview, and inspect the actual database without presenting these teaching shapes as biological results.", "focus": [346, 50, 1200, 155], "hold_after": 0.7}, {"visual": "03_setting_src", "narration": "Download the synthetic example linked below and extract it into a new folder. Set Source to the folder containing the four TIFF images and the masks subfolder. Keep the originals intact; use another copy before trying segmentation that could replace those masks.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "04_setting_masks", "narration": "Leave Masks switched off to reuse the supplied masks. The saved counts are four, three, two and one for the four images. Switching Masks on requests segmentation instead, so diameter, normalization and the selected model then affect a different computation. Reusing masks does not test that model.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "08_setting_well_diameter_mm", "narration": "Well detection is off because each teaching image already represents one field. Physical area needs genuine well geometry and a known well size; this example supplies neither. Leave calibration unset. A well name, a guessed diameter or a successful run cannot establish a scale in millimetres.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "05_setting_plaque_model", "narration": "Plaque model needs an available checkpoint even when masks are reused. This recording starts with an existing bundled checkpoint. On a new installation, download the plaque checkpoint through Model zoo and enter its local path here. The preview has its own model selector, which we check next.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "11_preview_settings_unmatched", "narration": "Open Live preview and then Live settings. Check the Model field explicitly: this build initially shows the general model, even when Plaque model names a different checkpoint. Do not assume that preview settings and the analysis form are synchronized. Match their model choices deliberately before creating new masks.", "focus": [1020, 456, 1800, 380], "hold_after": 0.7}, {"visual": "12c_actual_download_verified", "narration": "Choose Model zoo and select the plaque model. Its checkpoint is about one point two gigabytes, so choose a suitable Save to folder and download it once. This recording uses bytes verified against the published checksum. On this machine means the file is available; it does not validate your experiment.", "focus": [1025, 568, 1790, 1035], "hold_after": 0.7}, {"visual": "16_readable_preview", "narration": "Choose the first synthetic image and Run preview. The selected plaque checkpoint finds four objects here. View can switch between outlines and coloured masks; neither display is a measurement of model accuracy. The preview is a fresh segmentation, separate from the supplied masks used by the completed analysis.", "focus": [1510, 1248, 2300, 598], "hold_after": 0.7}, {"visual": "18_actual_filter_changed", "narration": "In Live settings, raise Min area to twenty-six thousand two hundred eleven pixels. This removes the two smaller predicted objects. The filtering reuses cached masks rather than running the model again. Change one setting at a time so you can see which objects it removes.", "focus": [1980, 286, 432, 660], "hold_after": 0.7}, {"visual": "19_actual_filter_restored", "narration": "Return Min area to zero and all four predicted objects return with exactly the original pixels. Zero disables this lower area filter. These preview adjustments do not rewrite the saved input masks or the existing results database; do not mistake an attractive preview for a completed batch analysis.", "focus": [3040, 1570, 760, 230], "hold_after": 0.7}, {"visual": "09_actual_completion", "narration": "The mask-reuse run writes a database in the masks folder. This path produces result tables, not an embedded plot, so an empty Figures area is not evidence of failure here. Read the console. The AI switch stays off in this demonstration; an assistant response would not replace checking the saved outputs.", "focus": [1510, 170, 2300, 1450], "hold_after": 0.7}, {"visual": "20_actual_database_help_route", "narration": "Open Database browser from Help, then open the plaques analysis database in the masks folder. Leave Edit mode off. The browser shows the actual saved tables rather than a screenshot of invented results, and inspecting this example leaves the database bytes unchanged.", "related_lessons": ["34_database"], "hold_after": 0.7}, {"visual": "21_actual_summary_table", "narration": "Select summary and match every row by its filename rather than its display position. Object count comes from the supplied masks: four, three, two and one. Average size is the mean labelled area in pixels. The control and treatment names are arbitrary teaching labels, not evidence of a treatment effect.", "focus": [345, 278, 1420, 225], "hold_after": 0.7}, {"visual": "22_actual_stats_table", "narration": "Select stats for the plaque count, mean size and size spread for each image. The standard deviation describes the individual plaque areas in that image; it is not an uncertainty interval for a biological experiment. Interpret technical counts only after validating the image scale and the segmentation on real data.", "focus": [345, 278, 1930, 225], "hold_after": 0.7}, {"visual": "23_actual_details_table", "narration": "Select details to inspect each individual plaque area. Physical-area columns remain empty because no calibration was supplied. Keep the images, masks, settings and result database together, and use independent experimental replicates for biological comparisons. This tutorial verifies software behaviour on synthetic shapes, not infection or drug efficacy.", "focus": [345, 278, 1420, 410], "hold_after": 0.7}], "poster": "24_plaque/poster.jpg", "silent": "24_plaque/video/24_plaque_silent.mp4"}, {"id": "25_recruitment", "number": 25, "slug": "recruitment", "series": 3, "app_key": "recruitment", "section": "Assays", "title": "Recruitment: verify compartment ratios on real measurements", "description": "Run a bounded, real measurement-table analysis, inspect the current filters and figures, and distinguish host-cell ratios from well summaries and biological conclusions.", "objectives": ["Select a measured project with linked cell, nucleus, pathogen and cytoplasm tables.", "Keep the target channel, auxiliary ratios, plate metadata and filters consistent.", "Interpret archived overlays, host-cell outputs, well averages and standard-deviation error bars at their correct scope.", "Check actual exported identities and calculations rather than accepting a completion message alone."], "prerequisite": "Use an already measured project and a new working copy. The recording uses four real fields from the archived HeLa siRNA tutorial experiment: 453 cell, 588 nucleus, 998 pathogen and 453 cytoplasm rows. ER channel 1 and the control labels come from recorded metadata, not independent biological validation. Original tables and image arrays remain unchanged. Recruitment has no separate example-download or Live preview control; obtain and validate measurements first.", "scenes": [{"visual": "01_module", "narration": "Open Recruitment in Home's Assays category. This workflow calculates compartment-intensity ratios from existing measurements; it does not rerun segmentation. Start with a measured project whose cell, nucleus, pathogen and cytoplasm records share valid object identities.", "hold_after": 0.7, "related_lessons": ["08_measure"]}, {"visual": "19_setting_src", "narration": "Set Source to a new working copy containing measurements slash measurements dot D B and the merged images. Here we copy four real fields, preserving all selected rows and identities. The source contains four hundred fifty-three cells, not the complete original plate.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_channel_of_interest", "narration": "Choose channel of interest one, the second plane in zero-based indexing. The archived settings identify this as the E R signal. Check your own acquisition metadata; a plausible ratio cannot establish that you selected the right biological marker.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_channel_dims", "narration": "Set Channel dims to one alone for this example. The current auxiliary ratio columns are overwritten for each listed channel, so a multi-channel list can leave them describing a different signal from the main recruitment column. A single matching channel avoids that ambiguity.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_cell_chann_dim", "narration": "The recorded image-channel mapping is cell one, nucleus zero and pathogen three. These are not the old mask-plane controls, which are no longer present here. Preserve the mapping with the measurements rather than copying these values into a different experiment.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_pathogen_plate_metadata", "narration": "The three group labels map column one to positive control, column two to negative control, and columns three through fourteen to screen. This subset contains only four wells in the first three columns. The labels are recorded experimental annotations, not control identities inferred from the images.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_pathogen_size_range", "narration": "The example uses cell area between thirty-five hundred and one hundred thousand pixels, nucleus area between seven hundred and four thousand, and pathogen area between one hundred and one thousand. Bounds are strict. Pathogen area is summed within each host cell before this last filter; it is not a separate size test for every parasite.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_nuclei_limit", "narration": "Allow at most one nucleus and ten pathogens per host cell. Child-count limits run before the later area filters. Here the one-nucleus limit removes one hundred three cells from the join; those cells do have nucleus records in the original table, despite the generic console warning suggesting a database gap.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_nucleus_intensity_range", "narration": "Cell intensity filtering is disabled. For nucleus and pathogen intensity, use minus one and sixty-five thousand five hundred thirty-six: the GUI retains these explicit bounds, and every used source mean is independently verified within the unsigned sixteen-bit range, so they remove no rows in this example.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_pathogen_intensity_range", "narration": "Do not tune those bounds by their names alone. With this mapping, the current nucleus intensity filter reads channel three and the pathogen filter reads channel one. The broad demonstrated ranges avoid additional exclusions; they are not a recommendation for selecting positive cells in another dataset.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_cells_per_well", "narration": "Cells per well is ten here, but this threshold uses the selected source's cell count before the analysis filters, not the final retained count. The target-intensity minimum also requires the cell's channel-one ninety-fifth percentile to exceed one. These are raw measurement filters, not normalization or statistical significance thresholds.", "hold_after": 0.7, "focus": [450, 220, 1700, 560]}, {"visual": "19_setting_plot_nr", "narration": "Keep Plot on. In the current implementation, Plot number zero includes the first enumerated archived image, not necessarily the earliest acquired field; the recruitment charts are generated separately. There is no interactive segmentation preview on this screen. Use Mask or Measure for their own live preview workflows before relying on the measurements.", "hold_after": 0.7, "focus": [450, 220, 1700, 560], "related_lessons": ["07_mask", "08_measure"]}, {"visual": "21_batch_running", "narration": "Press Run and follow the genuine console output. This bounded calculation uses the local measurement tables and does not require an A I provider or a model-training job. Wait for the analysis and figure generation to finish before inspecting the exported results.", "hold_after": 0.7}, {"visual": "25_recruitment_figure_00", "narration": "Inspect the real archived image and its stored mask overlay. Its label areas differ from the measurement table. Recorded filtering and merging can explain that difference, but we have not reconstructed the exact historical masks. The overlay is context, not proof that an individual displayed boundary produced a particular recruitment ratio.", "hold_after": 0.7, "focus": [1300, 230, 2520, 1060]}, {"visual": "25_recruitment_figure_01", "narration": "The compartment-intensity charts summarize retained host cells. Although the labels say by P V, the current reader has already grouped pathogen measurements within each cell. It averages pathogen mean intensities without area weighting; do not interpret these rows as independent parasitophorous vacuoles or pooled-pixel measurements.", "hold_after": 0.7, "focus": [1300, 230, 2520, 1060]}, {"visual": "25_recruitment_figure_02", "narration": "The main recruitment value divides the host cell's aggregated pathogen mean by its cytoplasm mean on channel one. Additional panels use percentile, periphery or outside measurements. These ratio axes start at one, so they cannot show all sub-unity values; inspect the numeric exports when assessing depletion or low ratios.", "hold_after": 0.7, "focus": [1450, 280, 900, 520]}, {"visual": "25_recruitment_figure_04", "narration": "Each well averages its retained cell ratios, rather than dividing well-mean intensities. The chart then averages those well values by condition. Error bars show between-well standard deviation, not confidence intervals. Two positive-control wells can supply a spread estimate, but single negative-control and screen wells cannot. This small, unbalanced demonstration does not establish a treatment effect.", "hold_after": 0.7, "focus": [1450, 280, 900, 520]}, {"visual": "26_recruitment_console_counts", "narration": "The actual run retains two hundred twenty-three host-cell rows and four well rows. We independently check the exact identities, child aggregates, sixteen ratio columns and well means against the private source tables. A Finished message alone would not prove those joins or calculations correct.", "hold_after": 0.7, "focus": [1300, 620, 2510, 960]}, {"visual": "26_recruitment_console_counts", "narration": "Keep results slash cells dot C S V and wells dot C S V with the saved settings and source provenance. Pathogen area and pathogen count in the well table are means per retained cell, not totals. The slope columns contain constants, not fitted estimates. Review near-zero denominators and nonfinite values before drawing conclusions.", "hold_after": 0.7, "focus": [1300, 620, 2510, 960]}, {"visual": "30_ai_unsent_question", "narration": "The A I toggle can route a question through a configured assistant. This recording only drafts a question and does not send it or generate an answer. Review provider configuration and privacy before sharing console or image context; an assistant response does not validate the experiment.", "hold_after": 0.7, "focus": [1300, 1320, 2520, 560]}, {"visual": "26_recruitment_console_counts", "narration": "In Python, spacr.submodules.analyze_recruitment runs this same analysis from a settings dictionary and returns the cell and well tables. Keep the demonstrated calculation separate from biological validation: verify acquisition channels, segmentation provenance, experimental units and suitable controls before applying it to your own screen.", "hold_after": 0.7, "related_lessons": ["06_api", "08_measure", "54_qc_dashboard"]}], "poster": "25_recruitment/poster.jpg", "silent": "25_recruitment/video/25_recruitment_silent.mp4"}, {"id": "26_invasion", "number": 26, "slug": "invasion-assay", "title": "Invasion Assay", "series": 3, "app_key": "invasion", "section": "Toxoplasma assays", "description": "Configure the current two-colour assay, separate stain-baseline wells from experimental conditions, and inspect actual thresholds, distributions and output files. The worked database is explicitly synthetic.", "objectives": ["Map the outside and total stains to their correct measurement columns.", "Use the renamed stain-baseline control and inspect the threshold sensitivity.", "Read real figures and per-well denominators without turning synthetic patterns into biological claims."], "prerequisite": "This lesson preserves the existing synthetic Invasion database and runs the current GUI on a new byte-identical copy. Its 1,800 invented parasite measurements comprise 360 stain-baseline objects and 1,440 assay objects across twelve artificial wells. It has no acquired two-colour images, and the general downloaded plate does not establish the required pre- and post-permeabilisation staining design. Vehicle and inhibitor are arbitrary teaching labels, not tested treatments. The example uses mean intensity because those are the available columns, not because mean is generally the best statistic for a surface stain. Independent arithmetic checks parasite calls, field thresholds, well counts, condition summaries and plotted geometry; no image validation, experimental efficacy or inferential-statistics approval is claimed. Original and private input databases remain unchanged. The current GUI uses stain_baseline_wells in place of the older control_wells name, and its six-decimal bimodality cutoff is recorded exactly.", "scenes": [{"visual": "01_module", "narration": "Open Invasion Assay in the Assays section of Home. This module scores already measured parasites; it does not segment the images here. Our worked database is explicitly synthetic. The figures demonstrate settings and arithmetic, not observed invasion or a treatment effect.", "focus": [346, 50, 1140, 155], "related_lessons": ["08_measure"], "hold_after": 0.7}, {"visual": "02_setting_src", "narration": "Choose the experiment folder containing measurements slash measurements dot db. This new private copy has eighteen hundred invented parasite rows. Three hundred sixty are staining-baseline objects; fourteen hundred forty belong to assay wells. The ordinary downloaded plate is not a substitute for a validated two-colour staining experiment.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "03_setting_outside_channel", "narration": "Outside channel is the stain applied before permeabilisation, here channel one. Total channel is the stain applied afterwards, here channel zero. An outside-positive parasite is called attached; a parasite at or below the outside threshold is called invaded. Weak outside staining can therefore create false invaded calls.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "05_setting_intensity_statistic", "narration": "We select mean intensity because this teaching database contains mean-intensity columns. That is not a general recommendation for a surface stain. For real data, inspect which boundary or percentile measurements are available and appropriate. A local background ring is also different from the outside-stain channel itself.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "06_setting_stain_baseline_wells", "narration": "Set Stain baseline wells to column one. This replaces the older control wells name and identifies the artificial negative-stain baseline, not the vehicle condition. These objects establish the staining cutoff and are excluded from the assay result denominators. Vehicle and inhibitor remain in columns two and three.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "07_setting_control_quantile", "narration": "Control quantile is zero point nine nine. The three hundred sixty baseline objects give a cutoff of about twenty-two point eight intensity units. We leave the fixed Outside threshold empty, so the baseline-derived cut is used. The automatic method is not the applied threshold in this run.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "08_setting_threshold_sensitivity", "narration": "Threshold sensitivity is zero point two five, which brackets the cutoff twenty-five percent lower and higher. Raising the cutoff can label more parasites invaded. Inspect the resulting efficiency bracket and quality-control flags before interpreting a change; a successful run does not prove that the stain is reliable.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "10_setting_extracellular_class", "narration": "Extracellular class decides how objects without a host link are handled. This example uses classify, leaving that decision to the stain, and every teaching row already has a host link. In real data, choose deliberately between attached, exclude and classify after checking the host segmentation.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "15_figure_02", "narration": "Run produces three actual figures. The threshold page shows one distribution per well, not one per parasite. Here the applied line comes from the baseline, and all twelve wells are visible. Inspect whether a cutoff falls between plausible populations; these invented distributions cannot replace reviewing representative stained images.", "focus": [1685, 260, 2125, 875], "hold_after": 0.7}, {"visual": "16_legend_00", "narration": "If a legend extends beyond the canvas, open Figure settings and select best for Legend position in the axes tab. Confirm the dialog to keep the labels visible. This is a display adjustment only: we verified that it leaves plotted values and saved result tables unchanged.", "focus": [1420, 330, 1000, 1500], "related_lessons": ["27_replication"], "hold_after": 0.7}, {"visual": "17_readable_figure_00", "narration": "The per-well bars show attached and invaded fractions, with one hundred twenty scored parasites above each bar. Baseline wells are absent. Keep the denominator beside the proportion: a large fraction based on very few objects is not equivalent to the same fraction from a well-sampled well.", "focus": [1685, 260, 2125, 875], "hold_after": 0.7}, {"visual": "17_readable_figure_01", "narration": "The two invented conditions contain seven hundred twenty scored parasites each. Their invaded fractions are approximately thirty-nine point seven and sixty-eight point nine percent. The summary also reports the mean across wells, which is not generally the same as pooling objects. Neither these labels nor any p-value establishes a biological effect here.", "focus": [1685, 260, 2125, 875], "hold_after": 0.7}, {"visual": "14_actual_completion", "narration": "Review the console and the results folder for parasite calls, field thresholds, well efficiencies, condition summaries and comparison tables. Use independent experimental wells for inference, not individual parasites as interchangeable replicates. spaCR AI is optional and was not used for this local analysis. Validate the stain and images before drawing biological conclusions.", "focus": [1510, 1200, 2300, 370], "related_lessons": ["08_measure", "13_regression"], "hold_after": 0.7}], "poster": "26_invasion/poster.jpg", "silent": "26_invasion/video/26_invasion_silent.mp4"}, {"id": "27_replication", "number": 27, "slug": "replication", "title": "Replication Assay", "series": 3, "app_key": "replication", "section": "Toxoplasma assays", "description": "Count parasites by explicit vacuole identity, inspect the resulting distributions, and adjust figure legends without changing the analysis. The complete worked example is synthetic and does not demonstrate a treatment effect.", "objectives": ["Choose the vacuole, rather than the host cell, as the counting unit.", "Keep non-power-of-two counts visible and inspect both well and condition summaries.", "Use the actual figure controls and review export warnings without changing the underlying data."], "prerequisite": "This lesson uses a new copy of the preserved synthetic replication tutorial database, not acquired assay images or the core modules' downloadable plate. Its 1,992 invented parasite rows form 480 explicit vacuoles in 240 host-cell groups across twelve artificial wells. Vehicle and inhibitor are teaching names, not observed treatments; the six wells in each group deliberately repeat the same distribution. The module currently has no dedicated live-data download button. For biological work, supply genuinely measured parasites with validated vacuole relationships and independent experimental replicates. The original database remains unchanged. Independent counts verify 6,588 output CSV fields; actual plotted heights and stacked bases are checked separately. The example does not validate image segmentation, inferential p-values or efficacy. Its new explanation replaces the older script's unsupported implication that synthetic data include reviewable vacuole images.", "scenes": [{"visual": "01_module", "narration": "Open Replication Assay in the Assays section of Home. It counts measured parasites per vacuole; it does not segment images here. This worked example is explicitly synthetic, so its charts teach the controls and counting rules, not a biological treatment effect.", "focus": [346, 50, 1140, 155], "hold_after": 0.7, "related_lessons": ["08_measure"]}, {"visual": "03_setting_src", "narration": "Choose the prepared experiment folder containing measurements slash measurements dot db. Our new private copy contains one thousand nine hundred ninety-two invented parasite rows. We preserve the original database and start without old result files, so every output shown belongs to this run.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "04_setting_vacuole_key", "narration": "Set Vacuole key to the explicit vacuole ID column. The example contains four hundred eighty vacuoles but only two hundred forty host-cell groups: two vacuoles share each host. Counting by host cell would merge them and answer a different question. Validate this relationship in real images before analysing your own data.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "05_setting_require_host_cell", "narration": "Require host cell excludes objects without a valid host link. That prevents unassigned objects entering this readout, but it can also remove real parasites if the host segmentation failed. All teaching rows have valid links; this example does not validate your segmentation.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "07_setting_max_parasites_per_vacuole", "narration": "The largest named power-of-two bucket is sixteen, not a limit that clips every larger count. Larger powers have an overflow bucket, and off-ladder counts remain separate. Each artificial well includes two three-parasite vacuoles; do not round a count of three up to four.", "focus": [346, 170, 1150, 215], "hold_after": 0.7}, {"visual": "09_setting_pathogen_plate_metadata", "narration": "Check the condition-to-well mapping. Here column one is called vehicle and column two inhibitor, with six artificial wells in each group. Those names are part of the invented teaching design. They are not evidence that a drug was applied, and a convincing-looking difference is not proof of efficacy.", "focus": [346, 170, 1150, 560], "hold_after": 0.7}, {"visual": "11_actual_run", "narration": "Run only after checking the source, assignment key, filters and output settings. This is table analysis, not a new Cellpose segmentation or a GPU benchmark. The actual worker produces both the per-well and by-condition figures.", "focus": [1510, 170, 2310, 1840], "hold_after": 0.7}, {"visual": "15_readable_legend_00", "narration": "Read each stacked bar as the distribution of vacuole counts in one well. The vehicle example has two hundred twenty-eight parasites in forty vacuoles; the inhibitor example has one hundred four in forty. Both retain five percent off-ladder vacuoles. We checked the displayed bar heights against independent counts, not merely the saved filenames.", "focus": [1510, 170, 2310, 1020], "hold_after": 0.7}, {"visual": "14_legend_settings_00", "narration": "If the legend is clipped, open Figure settings and the axes tab, then change Legend position. We choose an inside position through these real controls. This is a presentation change: all bar values and the output data files remain unchanged.", "hold_after": 0.7, "focus": [1420, 330, 1000, 1500]}, {"visual": "15_readable_legend_01", "narration": "The condition view pools the example's vacuoles into two distributions. All six wells in each group repeat the same invented pattern. Do not cite the resulting significance tests as a treatment finding; real inference needs genuine replication and a defensible independent experimental unit.", "focus": [1510, 170, 2310, 1020], "hold_after": 0.7}, {"visual": "12_actual_completion", "narration": "Read the console as well as the chart. This run warns that some selected colours have poor contrast on a light exported page. Check your exported figures and choose an accessible palette; a readable dark on-screen view does not automatically guarantee a readable saved figure.", "focus": [1510, 1190, 2310, 440], "hold_after": 0.7}, {"visual": "10_setting_save", "narration": "With Save enabled, results go under results slash analyze replication: vacuole counts, well distributions, condition summaries, statistical tables and figures. Keep the settings and source identifiers with them. For your own assay, review real images and biological controls before interpreting these summaries.", "focus": [346, 170, 1150, 215], "hold_after": 0.7, "related_lessons": ["08_measure", "34_database"]}], "poster": "27_replication/poster.jpg", "silent": "27_replication/video/27_replication_silent.mp4"}, {"id": "28_training_runs", "number": 28, "slug": "training_runs", "series": 4, "app_key": "train_compare", "host_app_key": "classify_merged", "section": "Tools", "title": "Training Runs: practise comparison controls with synthetic logs", "description": "Open Training Runs within Classify and use explicitly synthetic progress logs to inspect recorded metrics, automatic settings differences and fold-display modes without training or evaluating a model.", "objectives": ["Discover existing log folders and distinguish usable curves from an incomplete fixture.", "Compare recorded metrics while preserving each series' own epoch range.", "Read automatic configuration differences separately from execution-related settings.", "Distinguish best and last recorded epochs, fold sample standard deviation and scientific validation."], "prerequisite": "Use the existing, explicitly disclosed synthetic/training_runs tutorial folder. Its baseline, tuned and cross_validated curves, fold values and settings were generated as interface examples; no classifier produced these values. Its incomplete .pth file contains only placeholder text and must not be loaded as a model. This lesson demonstrates the real CSV parser and comparison controls, not training, checkpoint evaluation or biological performance. For your own analysis, retain genuine train.csv and validation.csv logs with their settings and dataset provenance. Training Runs has no separate example-download control.", "scenes": [{"visual": "01_module", "narration": "Open Classify, then its nested Training Runs tool. This lesson uses explicitly synthetic progress logs: every curve, fold and configuration is an example, not a measured classifier result. We demonstrate the comparison interface without training or evaluating a model.", "hold_after": 0.7, "related_lessons": ["41_classify"]}, {"visual": "01_current_training_runs_fold", "narration": "Training Runs has its own folder selector, run list, Metric and Folds controls, and Overlay selected button. It reads saved train.csv and validation.csv tables and recovers settings. The parent Classify training form is a separate workflow; do not press its Run button for this exercise.", "hold_after": 0.7, "focus": [465, 310, 3350, 1650]}, {"visual": "02_synthetic_source_folder_picker", "narration": "Click Choose folder…, select the existing synthetic training_runs directory and confirm Choose. Select the folder above the example projects, not an individual CSV. Keep these original fixtures unchanged; there is no need to regenerate them, copy a run or create a new checkpoint.", "hold_after": 0.7, "focus": [1555, 790, 1410, 965]}, {"visual": "03_synthetic_runs_and_real_warnings", "narration": "Scan discovers four fixture folders: a twenty-epoch baseline, a twenty-five-epoch tuned example, an eighteen-epoch example with three folds, and one incomplete entry. Baseline and tuned are demonstration labels. The model names in these paths do not mean those models were trained for this lesson.", "hold_after": 0.7, "focus": [465, 530, 940, 285]}, {"visual": "03_synthetic_runs_and_real_warnings", "narration": "Read the incomplete entry's warnings. It has no settings, no train.csv and no validation.csv, so it contributes no curve or settings comparison. Its file ending in dot p t h is only text that exercises discovery; the application does not load or evaluate that placeholder.", "hold_after": 0.7, "focus": [465, 1845, 3350, 175]}, {"visual": "04b_actual_metric_choices", "narration": "Tick the baseline and tuned examples, then choose accuracy under Metric. The menu contains numeric columns actually present in these logs, including loss and prauc. Their values are synthetic too; a familiar metric name does not turn a generated number into an experimental measurement.", "hold_after": 0.7, "focus": [465, 1680, 940, 300]}, {"visual": "05_actual_synthetic_accuracy_overlay", "narration": "Click Overlay selected. Four series appear from the two selected examples: train is dashed and validation is solid. Each retains its own epoch range, twenty or twenty-five. The shorter curve is neither padded nor truncated to match its neighbour; read the run and split in the legend.", "hold_after": 0.7, "focus": [1390, 530, 2420, 960]}, {"visual": "06_actual_synthetic_settings_diff", "narration": "The settings comparison is automatic. Here four of eleven shared settings differ: batch_size changes from sixty-four to thirty-two, epochs from twenty to twenty-five, learning_rate from zero point zero zero zero one to zero point zero zero zero three, and src names different synthetic projects.", "hold_after": 0.7, "focus": [1390, 1490, 2420, 360]}, {"visual": "06_actual_synthetic_settings_diff", "narration": "The separate env row shows n_jobs changing from thirty to eight, an execution-related setting. This is one environment difference and zero schema differences. These are example settings, not evidence of hardware use or elapsed training time. The table does not establish that any setting caused a curve difference.", "hold_after": 0.7, "focus": [1390, 1490, 2420, 360]}, {"visual": "07_actual_series_pick_best_and_last_epochs", "narration": "Click the baseline validation curve. Its detail line reports last accuracy zero point seven four nine six at epoch twenty and best accuracy zero point seven eight six zero at epoch fifteen. These are recorded CSV epochs, not separately evaluated checkpoints. Selecting the best point on the same curve explains the optimistic warning.", "hold_after": 0.7, "focus": [465, 2000, 3350, 105]}, {"visual": "08_actual_synthetic_loss_overlay", "narration": "Choose loss under Metric. The same four series and settings remain, but the vertical axis now shows the logged loss values. The late validation upturns were deliberately generated in these fixtures. This demonstrates switching metrics, not observed deterioration of a trained model.", "hold_after": 0.7, "focus": [1390, 530, 2420, 960]}, {"visual": "08b_actual_fold_choices", "narration": "Keep the tuned example selected and replace the baseline with the eighteen-epoch, three-fold example. Return Metric to accuracy, press Overlay selected, then open Folds. Its actual choices are per fold, mean ± sd, and both. These change the display; they do not create new folds.", "hold_after": 0.7, "focus": [465, 1730, 940, 175]}, {"visual": "09_actual_synthetic_fold_mean_sd", "narration": "Choose mean ± sd. Four series are shown: the tuned example's two splits and the three-fold example's train and validation means. Each band is plus or minus one sample standard deviation across three synthetic folds at that epoch, not a confidence interval or biological uncertainty estimate.", "hold_after": 0.7, "focus": [1390, 530, 2420, 960]}, {"visual": "10_actual_synthetic_folds_and_mean", "narration": "Choose both to display ten series: two from the tuned example, six individual fold series and two fold means. The mean curves are summaries of those same fold values, not additional independent runs. All three synthetic folds contribute throughout their eighteen recorded epochs.", "hold_after": 0.7, "focus": [1390, 530, 2420, 960]}, {"visual": "11_actual_synthetic_per_fold_curves", "narration": "Choose per fold to remove the two means, leaving eight series. The fold curves stop at epoch eighteen while the tuned example continues to twenty-five. The updated table reports five configuration differences and one environment difference; changing the selected examples changes the settings comparison too.", "hold_after": 0.7, "focus": [1390, 530, 2420, 1315]}, {"visual": "11_actual_synthetic_per_fold_curves", "narration": "For this recording, we check the returned numeric rows, plotted curves, settings differences and sample-standard-deviation bands against the existing CSVs. The original files remain unchanged. That verifies this software demonstration only; these synthetic examples cannot establish predictive performance, generalization or a scientifically reproducible winner.", "hold_after": 0.7}, {"visual": "11_actual_synthetic_per_fold_curves", "narration": "In Python, spacr.train_compare.find_runs discovers folders and load_run reads one run. compare_runs builds the comparison and settings differences; plot_curves draws a chosen metric. The compare_runs folds argument accepts per_fold, mean or both. Keep genuine logs and dataset provenance together when applying these read-only tools to your own results.", "hold_after": 0.7, "related_lessons": ["06_api", "41_classify"]}], "poster": "28_training_runs/poster.jpg", "silent": "28_training_runs/video/28_training_runs_silent.mp4"}, {"id": "29_report", "number": 29, "slug": "report", "series": 4, "app_key": "report", "section": "Help", "title": "Report: inspect and share recorded results without rerunning analysis", "description": "Generate a report from the real External Masks example, distinguish processing completion from missing quality-control evidence, and inspect the actual self-contained HTML before sharing it.", "objectives": ["Find Report under Help and scan a separate copy of an existing project.", "Distinguish processing stamps, unavailable quality checks and missing run provenance.", "Generate HTML using the actual format, figure-cap and output controls.", "Inspect recorded tables, listed vector figures and saved settings without claiming a new analysis or automatic privacy redaction."], "prerequisite": "Use the real two-field project produced in External Masks, with103 cells and supplied cell labels. This recording uses a complete, byte-verified private copy so the accepted project is protected. The earlier direct-source scan created an empty SQLite WAL and a shared-memory sidecar without changing existing data; do not interpret read-only analysis as a guarantee that SQLite creates no bookkeeping files. No pipeline or QC is rerun. There is no matching run journal for the private copy. The103 cytoplasm rows duplicate cell-only regions, not an independent compartment. Report has no separate test-data download, live segmentation preview or AI interaction in this demonstration.", "scenes": [{"visual": "00a_help_report_menu", "narration": "Open Help, then Report. This utility collects existing project artifacts into a document; it does not rerun segmentation, measurements or quality-control analyses. It is a Help workflow, not a separate Home tile.", "hold_after": 0.7, "related_lessons": ["31_external_masks", "54_qc_dashboard"]}, {"visual": "02_existing_project_picker", "narration": "Choose run folder… and select the private copy of our completed External Masks project. It contains two acquired image fields and their measured outputs. The copy preserves every original file, and the accepted source project remains unchanged throughout this recording.", "hold_after": 0.7, "related_lessons": ["31_external_masks"]}, {"visual": "03_actual_completion_not_qc_pass", "narration": "After scanning, read the green Complete message carefully. It says every stamped processing step handled every item. That is a processing-completion statement, not proof that segmentation is accurate or that quality control passed.", "hold_after": 0.7, "focus": [450, 275, 3000, 150]}, {"visual": "04_read_only_missing_sections", "narration": "The section list is an availability inventory, not an inclusion checklist. Five of eight sections are found here. Run provenance, Segmentation QC and Plate QC are not available, and their explanations remain in the generated report rather than disappearing.", "hold_after": 0.7, "focus": [450, 330, 2800, 350]}, {"visual": "05_actual_output_format_choices", "narration": "The actual Format choices are HTML, PDF and Both. We keep HTML for this demonstration. PDF is described as a matplotlib transcription; it is not a promise of an identical browser-page layout. Only HTML is generated and inspected in this recording.", "hold_after": 0.7}, {"visual": "06_actual_figure_cap", "narration": "Set Embed at most to three figures. This limits embedded raster figures. Our project instead contains six vector PDFs, which Report lists without embedding. Raising the cap would not turn those PDFs into image previews.", "hold_after": 0.7, "focus": [450, 1900, 1650, 130]}, {"visual": "07_separate_output_picker", "narration": "Choose output… and save to a new HTML filename outside the source project. There are no title, authorship or privacy-exclusion controls in this GUI. Review paths and metadata before sharing; Report does not automatically redact them.", "hold_after": 0.7}, {"visual": "09_actual_report_written", "narration": "Press Generate report and wait for the written-file confirmation. This run creates only the selected HTML file in its output directory. Open can hand it to your desktop viewer; here we inspect that exact generated file directly in Chrome, without clicking Open.", "hold_after": 0.7, "focus": [450, 1975, 3370, 160]}, {"visual": "browser_01_report_top_completion_and_contents", "narration": "The real document opens as one local HTML file, with no external resource requests. Its contents links identify the eight sections. The banner retains the completion statement and says zero of six figures are embedded; it does not hide the missing evidence.", "hold_after": 0.7}, {"visual": "browser_02_run_status", "narration": "Run status reproduces the actual measure_crop stamp: two attempted, two succeeded and zero failed. We did not manufacture a completion record. These counts describe processed fields, not the number of cells or a scientific validation score.", "hold_after": 0.7}, {"visual": "browser_03_provenance", "narration": "No journalled run names this copied folder. The report explicitly says its fallback versions describe the machine generating this report, not reconstructed provenance for the analysis. The missing segmentation and plate QC sections also remain visible: not available is not the same as passed.", "hold_after": 0.7, "related_lessons": ["54_qc_dashboard"]}, {"visual": "browser_06_figures", "narration": "Key figures lists all six source PDFs and explains why they are not embedded. Their paths identify before-filtering, after-filtering and crop figures for both fields. Refer back to External Masks to see those actual figures; this report does not rasterize them.", "hold_after": 0.7, "related_lessons": ["31_external_masks"]}, {"visual": "browser_07_statistics", "narration": "Statistics and result tables reports one hundred and three cell rows, the same number of cytoplasm rows and PNG links. In this cell-only example, cytoplasm duplicates the cell regions. Do not add those tables together and call them independent cells. Database totals include settings and other bookkeeping rows.", "hold_after": 0.7, "related_lessons": ["34_database", "31_external_masks"]}, {"visual": "browser_09_settings_first_native_disclosure", "narration": "Expand the actual saved-settings disclosure to inspect its preview. These values come from the project's saved settings file, not a recovered run journal. The displayed row count does not establish that every setting is distinct, and this recording does not read every row aloud.", "hold_after": 0.7}, {"visual": "browser_10_appendix", "narration": "In Python, spacr.report.collect_report collects a Report object. build_report collects and writes the requested format, returning a list of output paths. Use the GUI or API to share recorded evidence with its limitations intact; neither replaces missing QC, establishes biological validity or removes sensitive metadata for you.", "hold_after": 0.7, "related_lessons": ["06_api", "34_database"]}], "poster": "29_report/poster.jpg", "silent": "29_report/video/29_report_silent.mp4"}, {"id": "30_plate_queue", "number": 30, "slug": "plate_queue", "series": 4, "app_key": "queue", "section": "Data and batch runs", "title": "Plate Queue: run, stop between jobs and continue", "description": "Queue two isolated replays of the verified Recruitment example, check actual saved results and distinguish a controlled stop from untested crash recovery.", "objectives": ["Import a validated module configuration and find Plate queue through Help.", "Add the current settings and a prepared project folder as separate jobs.", "Observe sequential processing, stop between jobs and continue without repeating success.", "Check numeric results and clear finished queue records without deleting projects."], "prerequisite": "Complete the Recruitment lesson first. This recording copies its accepted four-field measurement subset into two separate replay folders; these are the same acquired data, not independent plates or biological replicates. Each folder has measurements/measurements.db and settings/recruitment_settings.csv. The first CSV is imported through the actual module picker; the second folder is dropped onto the queue. No stub runner, model or AI request is used. Plate Queue has no separate Load test data or live-preview panel. Import CSV is not demonstrated: its current implementation creates Mask jobs, not arbitrary module jobs. Long labels may be elided; verify full paths and settings before enqueueing. Crash recovery and failed-job retry are not verified here.", "scenes": [{"visual": "00a_import_recruitment_settings", "narration": "Start with the validated Recruitment example. We copied its four-field measurement database into two separate project folders, each with its own settings file. These are two replays of the same real data, not independent plates. In Recruitment, choose Import settings and open the first folder's CSV.", "hold_after": 0.7, "related_lessons": ["25_recruitment"]}, {"visual": "00b_current_recruitment_settings", "narration": "The console confirms that settings loaded. Check the source and channel mapping before enqueueing; the recording verified every requested setting after import. Use the Recruitment lesson for its figures, console and preview workflow. A queue does not validate whether your biological choices are appropriate.", "hold_after": 0.7}, {"visual": "01_help_queue", "narration": "Open Help, then Plate queue. This shared tool is reached through the menu, not a new Home tile. Its current runner processes one queued item at a time; this screen has no worker-limit or resume-policy selector.", "hold_after": 0.7}, {"visual": "03_added_replay_1", "narration": "Choose Add current plate. The first row contains a snapshot of the Recruitment configuration we just loaded. Check its module and source before running. The table shows identity, module, label, status and elapsed time; it is not a full settings editor.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "03_added_replay_2", "narration": "Drag the second prepared project folder onto the queue. Its saved Recruitment settings identify the module, and the dropped folder becomes its source. Both rows are queued. Separate folders keep these replay outputs separate; merely adding the same folder twice would not provide that isolation.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "04_first_job_running", "narration": "Choose Run queue. The first item becomes running while the second remains queued. This is the real Recruitment pipeline, not a simulated progress display. The list tracks jobs; it does not expose every intermediate image or processing step.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "05_stop_requested", "narration": "Press Stop during the first job. Stop asks this runner to finish the current item and stop before starting another. It is not immediate cancellation: wait for the active job to finish instead of assuming its output has already stopped changing.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "06_stopped_between_jobs", "narration": "Now the first row says success and the second still says queued. Choose Run queue again to process only the remaining item. We verified that the first job's timestamps did not change. This controlled stop does not establish recovery after a computer crash.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "07_both_jobs_finished", "narration": "Both jobs now say success. Each project contains cells and wells CSV results: two hundred and twenty-three retained cells across four wells. Object identities and recruitment ratios were independently checked against the measurements; a green status alone would not prove those numbers correct.", "hold_after": 0.7, "focus": [450, 160, 2120, 420]}, {"visual": "07_both_jobs_finished", "narration": "Plot was enabled in the saved settings, but this queue runner does not display or save the Recruitment figures. Use the dedicated module tutorial for that figure workflow. The queue also has no AI conversation panel; no AI request or model run was needed here.", "hold_after": 0.7, "related_lessons": ["25_recruitment"]}, {"visual": "08_finished_records_cleared", "narration": "Clear finished removes completed queue entries, not their project folders or results. We preserved the queue record before clearing and verified that both projects remained. For scripting, PlateQueue in the Qt plate queue module manages persisted job records; it is not itself the Recruitment analysis function.", "hold_after": 0.7, "related_lessons": ["06_api", "25_recruitment"]}], "poster": "30_plate_queue/poster.jpg", "silent": "30_plate_queue/video/30_plate_queue_silent.mp4"}, {"id": "31_external_masks", "number": 31, "slug": "external_masks", "series": 4, "app_key": "external_masks", "host_app_key": "foreign", "section": "Data", "title": "External Masks: measure existing cell labels without resegmenting", "description": "Reuse real microscopy images and existing cell labels, review their assignments, preview without project writes, and verify a newly measured spaCR project while distinguishing display crops and duplicated cytoplasm from independent biological evidence.", "objectives": ["Find External Masks within Import and review actual image and Cell-mask assignments.", "Preserve source provenance while distinguishing original, TIFF and merged-array plane indices.", "Use a non-writing preview before calculating measurements and cell crops in a separate project.", "Interpret all six figures and verify raw per-cell values without claiming segmentation accuracy or an independent cytoplasmic compartment."], "prerequisite": "Reuse the two image and cell-mask TIFF pairs already prepared for Import Project from Measure's downloaded microscopy example. fov01_C1.tif and fov02_C1.tif preserve original intensity plane 1; fov01_cell_mask.tif and fov02_cell_mask.tif preserve cell-label plane 4. Their original arrays are plate1_E01_1_1 and plate1_L02_9_1, with 44 and 59 labels respectively. The 1994-by-1994 images are real acquired data, but their neutral filenames and newly assigned A01 fields do not preserve original wells. Existing labels are not certified ground truth. This lesson imports no measurement CSV and makes no physical pixel-calibration claim. External Masks has no separate example-download control; reuse the preserved inputs. The visible AI control is not used.", "scenes": [{"visual": "01b_current_external_masks_fold", "narration": "Open Import in Home's Data category, then its nested External Masks tool. This workflow measures supplied segmentation labels; it does not segment the images again. The parent Import Project form adopts an existing measurement table, whereas External Masks calls Measure to calculate new features.", "hold_after": 0.7, "related_lessons": ["36_import", "08_measure"]}, {"visual": "02_choose_real_images", "narration": "Reuse the two real image and cell-mask pairs prepared for Import Project from the downloaded microscopy example. Each field is nineteen hundred and ninety-four pixels square. The neutral fov01 and fov02 filenames are demonstration names, not the original acquisition wells.", "hold_after": 0.7, "related_lessons": ["36_import"]}, {"visual": "04_review_detected_roles", "narration": "Use Add folder… for the image folder and again for the cell-mask folder. The table contains two groups and four TIFFs. Review Use as: Image for intensity files and Mask for labels, with Mask type set to Cell. Confidence describes the detected assignment, not segmentation accuracy.", "hold_after": 0.7, "focus": [470, 815, 1660, 350]}, {"visual": "04b_image_ignored_not_submitted", "narration": "Change the image group's Use as to Ignore. This removes that group from the settings submitted for a run; it does not delete its files. Do not run with the required intensity group ignored.", "hold_after": 0.7, "focus": [470, 815, 1660, 350]}, {"visual": "04c_image_role_restored", "narration": "Restore Image before continuing. The original image and Cell-mask assignments are now back in place, with both source groups included. Review these editable roles before configuring the destination or starting the preview.", "hold_after": 0.7, "focus": [470, 815, 1660, 350]}, {"visual": "05_setting_recursive", "narration": "Set Dst to a new project folder separate from the sources. Use Layout flat, Z handling first and Plate naming index, with Recursive and Overwrite off. These inputs each have one two-dimensional intensity plane. Their assigned coordinates will be plate1, A01 and fields one and two, not recovered original wells.", "hold_after": 0.7, "focus": [470, 1120, 1660, 380]}, {"visual": "05_setting_channels", "narration": "Use Channels zero and leave Normalize off. The TIFF's only intensity plane has array index zero, but its pixels were extracted from index one in the original seven-plane array. The supplied cell labels came from original index four and will occupy merged plane one. Do not interchange these indexing contexts.", "hold_after": 0.7, "focus": [470, 1515, 1660, 270]}, {"visual": "05_setting_cytoplasm", "narration": "Measure cytoplasm is enabled in this recording, but only Cell masks are supplied. There are no nucleus or other interior masks to subtract. The derived cytoplasm therefore duplicates the cell region; it is not an independently identified cytoplasmic compartment. Keep that limitation when reading the later figures and tables.", "hold_after": 0.7, "focus": [470, 815, 1660, 395]}, {"visual": "05_setting_png_size", "narration": "Under Object Crops, enable Save PNG, choose cell in Crop mode and set PNG size to two hundred and twenty-four by two hundred and twenty-four. PNG dims and all three PNG channel mapping entries use zero. Cell min size is zero and Keep uninfected cells is on; these choices retain this example's supplied labels.", "hold_after": 0.7, "focus": [470, 980, 1660, 805]}, {"visual": "05_setting_test_mode", "narration": "Use N jobs one, with Resume, Dry run and Test mode off. Enable Plot and Save measurements. Correlation, spatial, radial, homogeneity and object-distance calculations are disabled for this bounded example. Review these choices for your own analysis; the settings are not a validated biological protocol.", "hold_after": 0.7, "focus": [470, 810, 1660, 975]}, {"visual": "07_preview_plan_no_project_written", "narration": "Enable Preview only and press this tool's Run button. The actual plan reports two intensity mappings, two ready fields, one intensity channel and cell masks. The recorded full console output also confirms two mask pairs at merged plane one. At this point the destination does not exist: the preview has written no project data.", "hold_after": 0.7, "focus": [2140, 840, 1670, 440]}, {"visual": "08_preview_only_disabled", "narration": "Disable Preview only and press Run again, without changing the reviewed assignments. External Masks writes the converted images, stacks, cell masks and two-plane merged arrays, then runs the normal Measure pipeline. No measurement CSV is imported, and the original source files remain unchanged.", "hold_after": 0.7, "focus": [470, 805, 1660, 535]}, {"visual": "10_external_figure_00_preview_menu", "narration": "The run produces six figures. For the first five, use the figure's actual right-click menu, Save figure with a preview…, to inspect a larger native preview. This is an export dialog, not the embedded viewer. We press Cancel each time; no figure export is saved.", "hold_after": 0.7, "focus": [2620, 1020, 440, 515]}, {"visual": "10_external_figure_00_export_preview", "narration": "The first displayed field is the fifty-nine-cell example, assigned field two. This figure places the intensity image beside its supplied cell labels. The colours identify label regions; they do not measure confidence or prove that each boundary is biologically correct.", "hold_after": 0.7, "focus": [50, 550, 3730, 1450]}, {"visual": "10_external_figure_01_export_preview", "narration": "The next figure shows C. zero, C. one with fifty-nine objects, and C. two with fifty-nine objects. Here these are intensity, cell and derived cytoplasm. Different label colours do not make the last two independent compartments: their geometry is identical because no interior masks were supplied.", "hold_after": 0.7, "focus": [50, 550, 3730, 1450]}, {"visual": "10_external_figure_02_export_preview", "narration": "The third figure is the fifty-nine-object cell montage from that same field, not a new set of cells. Use it to inspect the extracted views. Display colours and crop scaling are not raw measurement values; the source intensity arrays and database retain the quantitative evidence.", "hold_after": 0.7, "focus": [50, 550, 3730, 1450]}, {"visual": "10_external_figure_03_export_preview", "narration": "The fourth figure shows the other acquired field's intensity image and supplied labels. This is the forty-four-cell example, assigned field one. Figure order is not field numbering. Together the two fields contain one hundred and three distinct cell labels.", "hold_after": 0.7, "focus": [50, 550, 3730, 1450]}, {"visual": "10_external_figure_04_export_preview", "narration": "The fifth figure repeats the intensity, cell and derived-cytoplasm view for the forty-four-cell field. Again the two mask panels describe the same cell regions, not two independent measurements of different compartments. Close this final export preview with Cancel; the actual six-figure queue remains available.", "hold_after": 0.7, "focus": [50, 550, 3730, 1450]}, {"visual": "10_external_figure_05", "narration": "The sixth figure is the forty-four-object montage in the ordinary embedded Figures viewer. Across both fields, the project has one hundred and three readable cell PNGs with exact per-object database links. These display crops are not claimed to preserve raw intensity pixels. The data folder can be reviewed later in Annotate.", "hold_after": 0.7, "focus": [1305, 775, 2500, 660], "related_lessons": ["09_annotate"]}, {"visual": "11_console_preferences_font_scale_125", "narration": "To inspect the completed console, open Preferences and reduce Font scale from two hundred to one hundred and twenty-five percent, then Save. Return through the Import Project and External Masks tabs. This is a native display adjustment; it does not rerun measurement or edit the recorded results.", "hold_after": 0.7, "focus": [1015, 275, 1810, 345]}, {"visual": "11_console_preferences_font_scale_100", "narration": "That first reduction still leaves too little console space, so set Font scale to one hundred percent, Save and return through the tabs again. We verify that the measurement settings, complete console history and all six ordered figure images remain unchanged. No AI request is sent.", "hold_after": 0.7, "focus": [1015, 275, 1810, 345]}, {"visual": "11_external_measurement_summary", "narration": "Read the completed operation's summary, not just its earlier preview. It reports two prepared fields and measurements.db tables: cell, cytoplasm, intensity_rescale, png_list, run_status, settings and settings_history. Annotation crops are under data. The later console review occurs after writing; it is not another non-writing preview.", "hold_after": 0.7, "focus": [990, 1330, 2440, 90]}, {"visual": "11_external_measurement_summary", "narration": "Independent checks match every output intensity and label pixel to the preserved inputs, and all one hundred and three cell identities, pixel areas and raw mean intensities to those labels. Mean-intensity error is zero in this run. The one hundred and three cytoplasm rows exactly duplicate cell values. This verifies data handling, not segmentation ground truth or biological validity.", "hold_after": 0.7, "focus": [990, 1330, 2440, 90]}, {"visual": "11_external_measurement_summary", "narration": "In Python, spacr.external_masks.plan_external_masks returns an ExternalMaskPlan without writing. run_external_masks accepts that plan and returns an ExternalMaskResult after measurement. prepare_external_masks returns the plan when preview_only is true, otherwise the result. Retain the source manifest, conversion_map.csv and project together so assigned coordinates cannot be mistaken for original acquisition metadata.", "hold_after": 0.7, "related_lessons": ["06_api", "35_converter"]}], "poster": "31_external_masks/poster.jpg", "silent": "31_external_masks/video/31_external_masks_silent.mp4"}, {"id": "32_align_stitch", "number": 32, "slug": "align_stitch", "series": 4, "app_key": "align", "section": "Tools", "title": "Align & Stitch: inspect a real plan and verify the written mosaic", "description": "Run the current stitching interface on preserved real microscopy pixels, inspect the solved layout, write bounded image bands and verify both the mosaic and its coordinate records.", "objectives": ["Distinguish this known-geometry crop example from an independently acquired tiled experiment.", "Set grid, overlap, order and reference channel through the current GUI.", "Inspect registration before writing and distinguish the band-buffer budget from total memory use.", "Keep the stitched image, coordinate records and source provenance together."], "prerequisite": "For your own run, prepare tiles with known order, overlap and a useful registration channel; your counts and results will differ. The recording reuses nine preserved exact 800 × 800 × 4 crops from one real 2,000 × 2,000 × 4 field, with a 600-pixel step. These emulate a 3 × 3 acquisition, not nine independently acquired fields. The tutorial_A01 names are demonstration coordinates, not the original plate and well. Align & Stitch has no separate example-download button.", "scenes": [{"visual": "01_module", "narration": "Open Align and Stitch in Home's Tools category. Planning and writing are separate actions, so you can inspect a layout before creating its mosaic. This screen shows a tile layout and a textual report; the coloured rectangles are not a microscopy-image preview.", "hold_after": 0.7}, {"visual": "02_preserved_real_pixel_tiles", "narration": "Choose the preserved tutorial tile folder. Its nine tiles are exact crops from one real four-channel image, deliberately arranged to emulate an acquisition with known geometry. They are not nine independent fields, and their tutorial plate and well names are demonstration identifiers.", "hold_after": 0.7}, {"visual": "03_actual_layout_and_budget", "narration": "Set a three-by-three grid, row-major order and overlap zero point two five. These eight-hundred-pixel tiles step by six hundred pixels. For your own data, use the actual acquisition order and nominal overlap; a serpentine scan must not be described as row-major.", "hold_after": 0.7, "focus": [450, 300, 1800, 170]}, {"visual": "03_actual_layout_and_budget", "narration": "Set reference channel one, the second plane in this zero-based example. Registration uses that plane's structure and applies one placement to all four channels. Choose a meaningful registration channel; this operation is not independent chromatic alignment of each channel.", "hold_after": 0.7, "focus": [450, 300, 1800, 170]}, {"visual": "03_actual_layout_and_budget", "narration": "Use minimum confidence zero point three, neighbour radius one and feather blending. Set the band-buffer budget to eight megabytes for this bounded example. That setting limits the writer's image bands; it does not cap every allocation or the application's total memory use.", "hold_after": 0.7, "focus": [450, 300, 1800, 170]}, {"visual": "04_registered_plan_not_yet_written", "narration": "Press Plan. All nine example tiles register, with no nominal-position fallback, and the proposed canvas is two thousand by two thousand pixels with four channels. No output image has been written yet. Inspect the registered, nominal and unplaced counts rather than treating any completed plan as acceptable.", "hold_after": 0.7, "focus": [1700, 440, 2100, 850]}, {"visual": "05_actual_tile_detail", "narration": "Click the middle tile to inspect its coordinates, confidence, residual and contributing pairs. Here its origin is six hundred pixels in each direction, matching the known crop layout. Perfectly matching overlaps in this constructed example do not predict registration quality on a new acquisition.", "hold_after": 0.7}, {"visual": "05_actual_tile_detail", "narration": "Choose a new output folder and a separate coordinate database, leaving Overwrite off. Write stack is enabled only after a plan exists and a destination is supplied. Keep source tiles unchanged; assigning an output path is not a substitute for reviewing the registration.", "hold_after": 0.7, "focus": [450, 1990, 3370, 140]}, {"visual": "06_real_stitch_complete", "narration": "Press Write stack. The actual output contains all nine tiles, and every pixel in all four channels matches the original field in this example. The result reports the output path and band-buffer use. This is a measured result for these known crops, not a promise of lossless registration for arbitrary images.", "hold_after": 0.7, "focus": [1700, 440, 2100, 1100]}, {"visual": "06_real_stitch_complete", "narration": "The coordinate database contains nine records. We check each source file, demonstration plate and well, field identifier, canvas position and output stack path, not just the row count. Preserve those records with the image and source manifest so downstream coordinates remain interpretable.", "hold_after": 0.7, "focus": [450, 1990, 3370, 140]}, {"visual": "06_real_stitch_complete", "narration": "In Python, spacr.align.scan_tiles reads the tile layout and estimate_offsets builds the plan. write_stack creates the mosaic; save_coordinates and read_coordinates write and recover its coordinate table. The separate OPS workflow is not validated by this small stitch. Review real acquisition geometry before using either workflow for scientific conclusions.", "hold_after": 0.7, "related_lessons": ["06_api", "36_import", "74_import_images"]}], "poster": "32_align_stitch/poster.jpg", "silent": "32_align_stitch/video/32_align_stitch_silent.mp4"}, {"id": "33_plate_viewer", "number": 33, "slug": "plate_viewer", "title": "Plate Viewer", "series": 4, "app_key": "plate_view", "section": "Results and quality control", "description": "Explore measurements as plate heatmaps and detect spatial artifacts or edge effects.", "objectives": ["Build an appropriate plate heatmap.", "Recognize spatial and low-count artifacts.", "Inspect and export traceable well summaries."], "prerequisite": "Measure a plate with stable plate and well identifiers.", "scenes": [{"narration": "Plate Viewer turns object measurements into well-level heatmaps with spatial quality checks beside them.", "visual": "01_overview", "hold_after": 0.7, "focus_key": "screen", "speech_text": "Plate Viewer turns object measurements into well-level heat maps with spatial quality checks beside them."}, {"narration": "Open a measurements database or run folder. The source is queried read-only.", "visual": "02_database", "hold_after": 0.7, "focus_key": "source", "speech_text": "Open a measurements database or run folder. The source is queryd read-only."}, {"narration": "Choose the object table, numeric feature, and plate to display.", "visual": "03_measurement", "hold_after": 0.7, "focus_key": "selection", "speech_text": "Choose the object table, numeric feature, and plate to display."}, {"narration": "Select aggregation, color scaling, and the minimum evidence required for a well. Count is useful for spotting segmentation or seeding differences.", "visual": "04_options", "hold_after": 0.7, "focus_key": "options", "speech_text": "Select aggregation, color scaling, and the minimum evidence required for a well. Count is useful for spotting segmentation or seeding differences."}, {"narration": "Render the view, then compare the heatmap with row, column, ring, and edge diagnostics.", "visual": "05_render", "hold_after": 0.7, "focus_key": "render", "speech_text": "Render the view, then compare the heat map with row, column, ring, and edge diagnostics."}, {"narration": "Select a well to inspect its identifier, object count, displayed value, and position.", "visual": "07_well_detail", "hold_after": 0.7, "focus_key": "well_detail", "speech_text": "Select a well to inspect its identifier, object count, displayed value, and position."}, {"narration": "Wells below the evidence threshold become explicit blanks rather than misleading zeros.", "visual": "11_filtered_result", "hold_after": 0.7, "focus_key": "result", "speech_text": "Wells below the evidence threshold become explicit blanks rather than misleading zeros."}, {"narration": "Export the current tidy well grid with counts and spatial annotations for audit or replotting.", "visual": "13_export", "hold_after": 0.7, "focus_key": "export", "speech_text": "Export the current tidy well grid with counts and spatial annotations for audit or replotting."}], "host_app_key": "graph_builder", "poster": "33_plate_viewer/poster.jpg", "silent": "33_plate_viewer/video/33_plate_viewer_silent.mp4"}, {"id": "34_database", "number": 34, "slug": "database", "title": "Database Browser", "series": 4, "app_key": "db_browser", "section": "Data", "description": "Browse, filter, and export spaCR measurement databases without a command line.", "objectives": ["Open and page through a database safely.", "Filter a complete table without confusing it with the preview.", "Export a traceable subset."], "prerequisite": "Have a spaCR SQLite database or run folder available.", "scenes": [{"narration": "Database Browser inspects large spaCR databases in a bounded, read-only view.", "visual": "01_overview", "hold_after": 0.7, "focus_key": "screen", "speech_text": "Database Browser inspects large spacer databases in a bounded, read-only view."}, {"narration": "Choose a measurements database or its run folder and open it.", "visual": "02_open", "hold_after": 0.7, "focus_key": "source", "speech_text": "Choose a measurements database or its run folder and open it."}, {"narration": "Select a table after reviewing its purpose and read-only status.", "visual": "03_tables", "hold_after": 0.7, "focus_key": "tables", "speech_text": "Select a table after reviewing its purpose and read-only status."}, {"narration": "The preview loads a bounded page while reporting the complete row and column counts separately.", "visual": "04_cell_table", "hold_after": 0.7, "focus_key": "preview", "speech_text": "The preview loads a bounded page while reporting the complete row and column counts separately."}, {"narration": "Search columns to make wide feature tables readable without changing the underlying rows.", "visual": "05_column_search", "hold_after": 0.7, "focus_key": "column_search", "speech_text": "Search columns to make wide feature tables readable without changing the underlying rows."}, {"narration": "Build a structured filter. Column names and operators are validated, and values are bound safely.", "visual": "08_filter", "hold_after": 0.7, "focus_key": "filter", "speech_text": "Build a structured filter. Column names and operators are validated, and values are bound safely."}, {"narration": "The exact filtered count describes the full query even though only one page is drawn.", "visual": "09_filtered", "hold_after": 0.7, "focus_key": "status", "speech_text": "The exact filtered count describes the full query even though only one page is drawn."}, {"narration": "Export the complete current filter and visible-column selection. The source database remains unchanged.", "visual": "10_export", "hold_after": 0.7, "focus_key": "export", "speech_text": "Export the complete current filter and visible-column selection. The source database remains unchanged."}], "poster": "34_database/poster.jpg", "silent": "34_database/video/34_database_silent.mp4"}, {"id": "35_converter", "number": 35, "slug": "converter", "series": 4, "app_key": "convert", "host_app_key": "foreign", "section": "Data", "title": "Format Converter: review identities before writing real images", "description": "Reach Format Converter through Import, preview two real image mappings, write a separate destination and verify checkpoint reuse without changing the originals.", "objectives": ["Distinguish image-format conversion from importing measurements and label masks.", "Review source, target and acquisition identities before writing.", "Preserve the source images, mapping CSV and field checkpoint together.", "Interpret a zero-write Resume correctly without treating it as a pixel-integrity guarantee."], "prerequisite": "Reuse the two single-channel TIFFs prepared from real measured images in the Import Project tutorial. Each is the exact second image plane from its original array; the neutral fov01_C1.tif and fov02_C1.tif filenames no longer contain the original plate or well identities. This deliberately bounded example demonstrates two-dimensional TIFF conversion, not vendor readers, multichannel acquisition, Z projection or time series. There is no separate example-download, Plot, Live preview or AI control in Format Converter.", "scenes": [{"visual": "01_module", "narration": "Open Import from Home's Data category, then choose Format Converter in its nested tools. This converts image formats and filenames. Import Project handles the different task of bringing images, label masks and measurement tables together; do not mix the parent screen's controls with the converter inside it.", "hold_after": 0.7, "related_lessons": ["36_import", "74_import_images"]}, {"visual": "01b_current_converter_fold", "narration": "The Format Converter tab has its own Source, Destination, Preview and Convert controls. Its preview is a source-to-target table, not a live microscopy image or segmentation preview. The parent Import destination and Import button below the tab belong to the other workflow.", "hold_after": 0.7, "focus": [460, 600, 3370, 1190]}, {"visual": "02_real_source_folder", "narration": "Choose a source folder, not an individual image. This example reuses the two real single-channel TIFFs from the Import lesson. Their pixels come from measured microscopy images, but the neutral field names are demonstration names, not the original acquisition coordinates.", "hold_after": 0.7, "related_lessons": ["36_import"]}, {"visual": "03_new_private_destination", "narration": "Choose a new, empty destination folder separate from the source. Keep the original images and their provenance unchanged. Conversion creates new TIFFs and a mapping file; it does not reconstruct experimental metadata that was removed when these demonstration files were named.", "hold_after": 0.7}, {"visual": "04_explicit_flat_single_plane_settings", "narration": "Set Layout to images directly in source, because both files sit in one folder. Use indexed plate names and leave Resume off for this first run. For a real plate-and-well directory tree, select the matching layout and check the resulting assignments rather than copying this flat-folder choice.", "hold_after": 0.7, "focus": [460, 815, 3370, 200]}, {"visual": "04_explicit_flat_single_plane_settings", "narration": "Keep every Z plane. Max projection and first-plane-only options deliberately discard Z information; neither is demonstrated here. These inputs each contain one two-dimensional channel, so this recording does not establish how a particular vendor file, time series or multichannel acquisition will be interpreted.", "hold_after": 0.7, "focus": [460, 870, 3370, 100]}, {"visual": "05_preview_no_output_written", "narration": "Press the converter's Preview button. The actual plan lists two outputs from two source files, and the destination remains empty. Inspect the complete source-to-target mapping before Convert; a finished preview is not evidence that its well and channel assignments match your experiment.", "hold_after": 0.7, "focus": [460, 995, 3370, 790]}, {"visual": "05_preview_no_output_written", "narration": "Here the generated names use plate one, well A zero one, fields one and two, and channel one. Those are assigned demonstration identities. The source images originally came from different acquired wells, so this mapping must not be presented as recovered plate metadata or used to combine their treatments.", "hold_after": 0.7, "focus": [465, 1020, 1950, 180]}, {"visual": "06_preview_source_channel_and_plane_provenance", "narration": "Check the From field and From channel columns alongside the generated names. The TIFF's only plane has array index zero, although its preserved pixels were extracted from channel index one in the original seven-plane array. The output filename's channel one is one-based; these three numbering contexts are not interchangeable.", "hold_after": 0.7, "focus": [460, 1020, 2750, 180]}, {"visual": "05_preview_no_output_written", "narration": "The preview table is read-only. If identities are wrong, fix the source layout or conversion settings and preview again; there are no per-row edits or separate series and time selectors in this screen. Keep the original metadata available when reviewing automatic assignments.", "hold_after": 0.7, "focus": [460, 1020, 2750, 180]}, {"visual": "07_actual_conversion_complete", "narration": "Press Convert and read its summary. This actual run writes two new TIFFs with no failed or skipped mappings. We independently compare every output pixel, shape and data type with its source, and verify the source, field and channel identities in the mapping file. The originals remain unchanged.", "hold_after": 0.7, "focus": [460, 1580, 3370, 210]}, {"visual": "07_actual_conversion_complete", "narration": "Keep conversion underscore map dot C S V with the converted images and the original acquisition manifest. The map preserves source and target paths, assigned identities, source-channel metadata and conversion status. A separate run-status file records the operation, and a hidden field checkpoint supports later Resume.", "hold_after": 0.7, "focus": [460, 1580, 3370, 210]}, {"visual": "08_resume_enabled", "narration": "Enable Resume and press Convert again with the same source, plan and destination. The application checks the compatible field checkpoint and readable TIFF metadata before reusing completed fields. It does not compare every pixel with the original source; do not describe Resume as a complete corruption audit.", "hold_after": 0.7, "focus": [2700, 825, 1130, 190]}, {"visual": "09_completed_fields_reused", "narration": "The second run says zero files converted and two targets already existed. That is expected here: both planned outputs are present and unchanged. The table still displays the preview's planned status, so read the operation summary and mapping file for the actual result, not that table column alone.", "hold_after": 0.7, "focus": [460, 1580, 3370, 210]}, {"visual": "10_resume_checkpoint_summary", "narration": "Scroll the summary to see that two completed fields were resumed. The latest run-ledger entry reports empty because no source needed conversion; the first complete entry remains preserved. We accept this specific zero-write result only after verifying both reused outputs and their exact identities independently.", "hold_after": 0.7, "focus": [460, 1580, 3370, 210]}, {"visual": "10_resume_checkpoint_summary", "narration": "In Python, spacr.convert.scan reads source descriptions, plan builds the reviewed mappings, and convert writes the outputs. convert_folder is the settings-dictionary entry point. Keep conversion separate from segmentation and measurement, and validate your own acquisition dimensions before passing its images to Mask or Measure.", "hold_after": 0.7, "related_lessons": ["06_api", "07_mask", "08_measure", "36_import"]}], "poster": "35_converter/poster.jpg", "silent": "35_converter/video/35_converter_silent.mp4"}, {"id": "36_import", "number": 36, "slug": "import", "series": 5, "title": "Import Project: review real masks, measurements and provenance", "app_key": "foreign", "section": "Data", "description": "Import an actual two-field microscopy subset, review object joins and column names before writing, and distinguish imported measurements from a fresh spaCR measurement run.", "objectives": ["Find Import Project and its three nested input tools.", "Pair images, instance masks and a measurement table, with explicit units and object identities.", "Review inferred names, demonstrate and resolve a reserved-name conflict, and save and reload the mapping.", "Verify imported pixels, per-object values and provenance without claiming that import remeasures the data."], "prerequisite": "Download Measure's example first. prepare_inputs in tools/tutorials/capture_foreign.py extracts unchanged ER intensity plane 1 and cell-label plane 4 from plate1_E01_1_1 and plate1_L02_9_1. It recomputes exact pixel areas and raw mean intensities from those same labels, producing 103 real measurement rows. Neutral fov01/fov02 TIFF names deliberately require the saved source manifest to recover original acquisition wells; they do not preserve plate layout automatically. No physical pixel calibration is asserted.", "scenes": [{"visual": "01_module", "narration": "Open Import in Home's Data category. This parent workflow adopts existing images, instance masks and measurements. It is different from starting with raw microscope files and generating new masks and measurements in spaCR.", "hold_after": 0.7}, {"visual": "02_fold_import_images", "narration": "The header now hosts Import Images, Format Converter and External Masks. Use Import Images for raw acquisitions, Format Converter for supported format conversion, and External Masks for existing segmentation labels. Their specialist lessons remain under Import in the Submodules section.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["74_import_images", "35_converter", "31_external_masks"]}, {"visual": "03_choose_images", "narration": "This recording reuses two real fields from Measure's downloaded example. Separate TIFF copies preserve the original intensity and label pixels. Our preparation recipe measures pixel area and mean intensity from those exact labels, instead of mixing masks with an independently versioned measurement table.", "hold_after": 0.7, "related_lessons": ["08_measure"]}, {"visual": "04_choose_masks", "narration": "Choose the image folder, then the Cell mask folder and press Add. These are instance labels, not a binary foreground image. Our example contains one intensity channel and one mask class. Add other classes only when they genuinely describe the corresponding fields.", "hold_after": 0.7}, {"visual": "05_choose_table", "narration": "Choose the actual measurement CSV. ImageNumber identifies each prepared image, and ObjectNumber identifies its label inside that field. A label number alone is not unique across images. The table contains one hundred and three measured objects, not synthetic rows added to make a join pass.", "hold_after": 0.7}, {"visual": "06_inputs_unknown_calibration", "narration": "Leave micrometres per pixel blank when calibration is unknown. Our area column explicitly uses pixels squared, and intensity is a raw image mean. Do not enter an invented scale. Physical-unit columns require separate review; an uncalibrated value must not be described as a converted pixel measurement.", "hold_after": 0.7, "focus": [350, 440, 3450, 65]}, {"visual": "06b_safe_inferred_names", "narration": "Preview writes no project data. The current importer conservatively proposes foreign-prefixed column names, including foreign_cell_area for a source already called cell_area. Its note is not a blocking error: inference has avoided overwriting a spaCR feature, but the scientific meaning still needs your review.", "hold_after": 0.7, "focus": [350, 500, 2650, 155]}, {"visual": "07_conflict_refused", "narration": "Select a target cell and press F two to edit it. Here we deliberately change the area target to the reserved name cell_area. With Refuse the import selected, this actual conflicting edit disables Import. Nothing has been written; do not treat the demonstration target as a recommended mapping.", "hold_after": 0.7}, {"visual": "08b_join_report", "narration": "Choosing the Rename policy resolves the conflict without overwriting spaCR's feature. Read the join report: all one hundred and three table rows match real mask objects, with no unmeasured objects in this subset. Row counts alone would not detect values assigned to the wrong field or label.", "hold_after": 0.7, "focus": [350, 1830, 3450, 195]}, {"visual": "09_mapping_edited", "narration": "Give the area an explicit reviewed target, foreign_reviewed_area_px2. The mapping updates in place. Review the source, target, transform and units together: renaming a column does not establish that two laboratories measured the same biological quantity.", "hold_after": 0.7, "focus": [350, 500, 2650, 155]}, {"visual": "10_save_mapping", "narration": "Save mapping writes the reviewed column definitions to a CSV. It is not a backup of your images or a complete acquisition manifest. Keep the source files and their identity records as well as the mapping, so the decisions can be audited later.", "hold_after": 0.7}, {"visual": "12_mapping_reloaded", "narration": "Load mapping reads those definitions back into the current plan. We first make a temporary unsaved target change; selecting the saved CSV then restores the reviewed name. Check the plan again when source files, labels or units differ. A reusable mapping is not automatic approval of a new experiment.", "hold_after": 0.7}, {"visual": "13_imported", "narration": "Press Import for the reviewed plan and inspect the actual report. This run converts two image files, writes two masks and two merged arrays, and stores one hundred and three rows in each of two object tables. The status total of two hundred and six counts both tables, not twice as many distinct objects.", "hold_after": 0.7}, {"visual": "14_import_scope", "narration": "The summary explicitly says spaCR did not re-extract measurements. The foreign_columns table records which values came from this import. Our checks confirm original pixels, labels, and each object's area and mean intensity survive the conversion; that is different from validating the biological interpretation.", "hold_after": 0.7, "focus": [350, 1830, 3450, 195], "related_lessons": ["08_measure"]}, {"visual": "14_import_scope", "narration": "Our neutral fov names become new fields in A zero one; they do not reconstruct the original acquisition wells. Retain the preparation manifest and conversion map. For a real plate experiment, resolve acquisition identities before downstream analysis instead of treating newly assigned coordinates as original metadata.", "hold_after": 0.7, "related_lessons": ["74_import_images"]}, {"visual": "14_import_scope", "narration": "In Python, spacr.foreign provides plan_import, save_column_map, load_column_map and run_import for the same review-and-apply boundary. Keep the reviewed mapping with the completed project. Use Measure when you actually want spaCR to compute new features, rather than assuming an import already did so.", "hold_after": 0.7, "related_lessons": ["06_api", "08_measure"]}], "poster": "36_import/poster.jpg", "silent": "36_import/video/36_import_silent.mp4"}, {"id": "37_batch", "number": 37, "slug": "batch", "series": 5, "app_key": "batch", "section": "Data and batch runs", "title": "Batch Runner: validated jobs, dependencies and separate logs", "description": "Use the real threaded interface and file pickers to configure three channel-preserving conversions, check dependency order, save and reload the queue, then stop and continue real subprocess jobs.", "objectives": ["Find Batch runner under Help and add module settings with explicit dependencies and overrides.", "Observe an invalid dependency order, restore it and save the validated plan.", "Reload the plan, stop between real jobs and continue without repeating completed work.", "Inspect separate logs and independently verified pixels, channel identities and conversion records."], "prerequisite": "Use the three acquired four-channel fields from the tutorial test dataset and separate source and destination folders per job. The tutorial helper tools/tutorials/batch_data.py copies the originals byte-for-byte into explicit fov01_C1 through fov01_C4 TIFF names. Each converted example uses the demonstration coordinate A01; original plate/well coordinates are not reconstructed. The older recording incorrectly mapped its original filenames to four separate C01 fields, so it is not evidence of preserved channel metadata. This lesson executes only convert, not a full Mask-to-Classify chain. No model, AI request or biological finding is claimed. The queue has no dedicated Load test data, live image preview or plotting panel; use the Format Converter lesson for its Preview and Resume controls. Failure policies are shown but failing analyses, hard-crash recovery and GPU-driver isolation are not tested here.", "scenes": [{"visual": "01_help_batch", "narration": "Open Help, then Batch runner. This shared menu tool combines headless module jobs, settings files, dependencies and separate logs. It runs its own jobs sequentially; that does not prevent another application or queue from using the same computer's resources.", "hold_after": 0.7, "related_lessons": ["30_plate_queue"]}, {"visual": "03_choose_settings_1", "narration": "Choose convert and use Choose settings to open the first JSON file. We prepared three real microscopy fields in separate folders, each with four explicitly named channel files. Their pixels are unchanged, but A zero one is a demonstration coordinate, not a recovered original well.", "hold_after": 0.7, "related_lessons": ["35_converter"]}, {"visual": "04_configure_job_1", "narration": "The settings specify source, destination and actual conversion, with preview and resume disabled. Add a descriptive label, then choose Add job. The first identifier is convert one. Validate the conversion and channel mapping on a small example before scheduling a larger batch.", "hold_after": 0.7, "focus": [450, 235, 3370, 255]}, {"visual": "04_configure_job_2", "narration": "For the second job, After names convert one. The override plate naming equals name changes its plate-name convention without rewriting the saved settings file. This dependency controls eligibility and order; it does not automatically make the second job consume the first job's output.", "hold_after": 0.7, "focus": [450, 235, 3370, 255]}, {"visual": "05_added_job_3", "narration": "Add the third job with no dependency or override. All three use different output folders. The table shows their identifiers, labels, dependencies and pending state. Selecting a row loads its configuration into the editor; the displayed table is not an editable spreadsheet.", "hold_after": 0.7, "focus": [450, 530, 3360, 235]}, {"visual": "06b_dependency_error_scrolled", "narration": "Move the second job above its prerequisite. Validation reports the later dependency and disables Run queue. The small problem pane may require scrolling to read the explanation and suggested fix. This verifies an actual refusal, not just a claim that the validator protects you.", "hold_after": 0.7, "focus": [450, 1225, 3350, 180]}, {"visual": "07_valid_reordered_queue", "narration": "Move it back below convert one, then move the independent third job above it. The valid order is now one, three, two. Choose Validate again: no problems remain. Ordering constraints are satisfied, but validation cannot establish whether an analysis answers your scientific question.", "hold_after": 0.7, "focus": [450, 530, 3360, 235]}, {"visual": "09_continue_policy", "narration": "On failure offers continuation for independent jobs or stopping at the first failure. We inspected both and restored continuation. Stop after is three consecutive failures here; it counts failures, not proof that their causes are identical. This successful example does not exercise either failure outcome.", "hold_after": 0.7, "focus": [450, 440, 1760, 95]}, {"visual": "10_save_queue_picker", "narration": "Use Save queue to preserve the ordered plan as JSON. We then removed the third job from this disposable in-memory queue and used Load queue to restore the saved three-job plan. The project folders were not deleted. Keep the settings files and inputs with that plan.", "hold_after": 0.7}, {"visual": "14_stopped_between_jobs", "narration": "After Run queue starts the first real subprocess, press Stop. It finishes the active job before stopping: the first row says success and the other two say not run. This is not an immediate kill, and this controlled stop does not prove recovery from a computer crash.", "hold_after": 0.7, "focus": [450, 530, 3360, 235]}, {"visual": "15_completed_real_queue", "narration": "Choose Run queue again. Only the two remaining jobs execute, in the saved order; the first job's timestamps stay unchanged. All three now show success. Separate subprocesses isolate ordinary job execution, but this demonstration does not guarantee protection against a system-wide GPU or memory failure.", "hold_after": 0.7, "focus": [450, 530, 3360, 235]}, {"visual": "16_log_convert-2", "narration": "Select each row to read its own log. Here the converter reports one well, one field and four channel identifiers, then four converted files and exit code zero. The name override appears in the second job's outputs. Logs provide evidence to inspect, not automatic proof of correct scientific results.", "hold_after": 0.7, "focus": [450, 1380, 3350, 705]}, {"visual": "16_log_convert-1", "narration": "Across all three jobs, twelve output images matched every original pixel and the intended channel identities. Each conversion record also reports four attempts, four successes and no failures. Originals remain unchanged. For scripting, spacr.batch provides Job, Queue and run_queue; see the API lesson and the converter's dedicated preview tutorial.", "hold_after": 0.7, "related_lessons": ["06_api", "35_converter", "30_plate_queue"]}], "poster": "37_batch/poster.jpg", "silent": "37_batch/video/37_batch_silent.mp4"}, {"id": "38_distributed_jobs", "number": 38, "slug": "distributed_jobs", "title": "Distributed Jobs", "series": 5, "app_key": "distributed_jobs", "section": "Data and batch runs", "description": "Prepare a real execution profile from Help, understand backend and path choices, and distinguish saved configuration from verified remote execution.", "objectives": ["Find Distributed Jobs in Help and save a reusable execution profile.", "Distinguish path mapping from copying data and credentials from profile settings.", "Prepare SSH, Slurm or custom-command settings without claiming an untested remote run."], "prerequisite": "This lesson records configuration only, with an isolated local profile store and no submitted job or remote connection. researcher@workstation.invalid and the displayed local/shared directories are illustrative, not working targets. Before submission, arrange authorised access, compatible spaCR/dependencies and existing data on the target. Use the actual module's exported settings, not this example profile as an experiment configuration. API: spacr.remote_execution.ExecutionProfile, ProfileStore and RemoteJobManager. Profiles do not store passwords; authenticate outside spaCR. Dataset roots rewrite matching absolute path prefixes; images are not automatically copied. The recording proves save/reopen and cancelled-edit preservation, not scheduler success, remote outputs or model validity.", "scenes": [{"visual": "01_help_route", "narration": "Open Help, then Distributed jobs. This utility is reached from Help, not a separate core Home tile. We prepare a real execution profile and inspect the current controls. No remote connection or submitted job is demonstrated; saving a profile does not prove that its target works.", "focus": [80, 0, 1200, 1500], "related_lessons": ["05_home"], "hold_after": 0.7}, {"visual": "02_empty_actual_workbench", "narration": "Use this workbench to send a module's settings to another execution target. Before submitting, arrange authorised access, a compatible spaCR installation and data available on that target. Profiles store connection settings, not passwords. Configure SSH keys or your cloud command-line authentication outside spaCR.", "focus": [455, 155, 3350, 430], "related_lessons": ["06_api", "37_batch"], "hold_after": 0.7}, {"visual": "03_empty_profile_refused", "narration": "Choose New profile. Saving an empty form is refused with an inline message. Give the profile a clear name and choose its backend. Our example is explicitly named NOT CONNECTED, so it cannot be mistaken for a tested workstation or a successful job.", "focus": [695, 195, 2210, 1220], "hold_after": 0.7}, {"visual": "06_saved_profile_reopened", "narration": "For SSH, enter the host, remote work directory and spaCR runner. The displayed dot-invalid host and directories are examples, not usable credentials or verified locations. We saved this profile and reopened it; the visible values match the stored configuration exactly.", "focus": [695, 380, 2210, 390], "hold_after": 0.7}, {"visual": "06_saved_profile_reopened", "narration": "Local and remote dataset roots describe the same data through different absolute path prefixes. Set both, or leave both blank when paths are identical. This maps settings paths; it does not copy an image collection to the server. Arrange the actual shared storage or transfer separately.", "focus": [695, 595, 2210, 170], "hold_after": 0.7}, {"visual": "07_slurm_controls_not_submitted", "narration": "Choosing Slurm enables scheduler options while keeping the host and path controls. Partition names, time limits and accelerator requests must match your cluster's allocation. The displayed partition is a placeholder. Changing this selector neither reserves a GPU nor verifies that the scheduler is reachable.", "focus": [695, 450, 2210, 430], "hold_after": 0.7}, {"visual": "08_custom_argument_templates", "narration": "Cloud or custom command enables separate submit, status and cancel argument templates, with optional log retrieval. Use the required settings and external-ID placeholders. These are tokenised arguments, not a shell script. The greyed connection controls belong to the other backends; no custom command runs in this lesson.", "focus": [695, 805, 2210, 350], "hold_after": 0.7}, {"visual": "05_profile_saved_not_connected", "narration": "Cancel closes our unsaved backend changes and preserves the original SSH profile byte for byte. Save is for changes you intend to retain. Poll interval controls suggested monitoring frequency, not computation speed. A saved execution target is still only configuration until a real, authorised job has been checked.", "focus": [455, 220, 3350, 205], "hold_after": 0.7}, {"visual": "09_submission_controls_no_job", "narration": "For an actual run, select the matching module and its exported settings before Submit. Begin with a small authorised check, then inspect job status, logs and the local record. Cancel job targets a selected job; deleting a profile is different. Our table stays empty because we submit nothing and claim no remote outputs.", "focus": [455, 220, 3350, 1510], "related_lessons": ["37_batch", "40_run_history", "06_api"], "hold_after": 0.7}], "poster": "38_distributed_jobs/poster.jpg", "silent": "38_distributed_jobs/video/38_distributed_jobs_silent.mp4"}, {"id": "39_classifier_evaluation", "number": 39, "slug": "classifier_evaluation", "title": "Classifier evaluation", "series": 3, "app_key": "classifier_evaluation", "section": "Tools", "host_app_key": "classify_merged", "description": "Inspect real saved classifier predictions inside Classify, use live table filters, and recognise a test split with known well overlap.", "objectives": ["Open Classify’s nested evaluation inspector with the downloadable saved-results bundle.", "Read confusion counts, confidence lists, per-plate metrics and calibration without rerunning a model.", "Distinguish an interactive results view from independent validation or evidence of incorrect labels."], "example_files": ["REAL_evaluation_known_overlap.zip"], "prerequisite": "Extract REAL_evaluation_known_overlap.zip into a new folder and select the extracted root containing evaluation_manifest.json. This inspection-only archive contains 234 actual one-epoch test predictions and the native saved tables/PNGs, not a trained model, crops or an annotation database. The two inherited class names infected_1 and infected_2 do not establish infection status. Standard spacr.classifier_evaluation.evaluate_predictions and write_evaluation_bundle prepared the results from the original saved probabilities; load_evaluation_bundle is the inspector reader. Database identities expose all three test wells in the training split; no retraining or correction of that split occurred. Generic out-of-fold file names and plot titles do not turn a single test split into cross-validation. Counts [[104,11],[8,111]] give 215/234 correct; confidence threshold 0.75 -> 0.95 changes the selected eleven-disagreement cell from high/low 6/5 to 2/9 without altering class calls. The Predictions filter r5_c2 gives 234 -> 128 -> 234 rows after clearing. Calibration method none and five bins per class were fixed when the bundle was prepared, not entered in this GUI. Every numeric cell is preserved; only sample display paths became explicit crops-not-included references. The matching original experiment must already be open in Annotate for crop routing; this standalone example does not demonstrate that route. One plate cannot establish whether a disagreement is caused by the model, plate, well or a wrong annotation. Native calibration PNG is readable, but the confusion PNG has weak dark-on-blue number contrast; neither generic-OOF export is endorsed as publication-ready. No model inference, GPU benchmark or spaCR AI request occurs during inspection. Native-speaker/listening approval and publication remain separate from these technical checks.", "scenes": [{"visual": "01_classify_host", "narration": "Open Classify, then its Classifier Evaluation shortcut. This is a nested results inspector, not a separate Home module or a model-training form. The Classify lesson covers producing predictions; here we inspect an existing saved bundle.", "focus": [3510, 105, 320, 80], "related_lessons": ["41_classify"], "hold_after": 0.7}, {"visual": "03_actual_bundle_folder", "narration": "Download the saved-results example linked below and extract it into a new folder. Click Browse and choose the folder containing evaluation manifest dot json. This small archive includes real saved predictions and tables, but no crops, annotation database or trained model.", "focus": [1563, 798, 1400, 950], "hold_after": 0.7}, {"visual": "04_actual_summary", "narration": "Summary reports two hundred thirty-four test predictions from a one-epoch run. The names infected one and infected two are inherited dataset labels, not newly verified infection states. Loading this bundle reads saved results; it does not train, predict or repair the dataset.", "focus": [475, 650, 3335, 1170], "hold_after": 0.7}, {"visual": "05_actual_leakage_requires_review", "narration": "Check Leakage audit before interpreting accuracy. All three test wells also occur in training, so the audit fails. Database identities revealed overlap that the older filename audit missed. These numbers demonstrate the inspector, not performance on independent wells or biological validation.", "focus": [475, 650, 3335, 1390], "hold_after": 0.7}, {"visual": "06_actual_confusion_counts", "narration": "In Confusion matrix, rows are the recorded classes and columns are predictions. The diagonal counts are one hundred four and one hundred eleven. The other cells contain eleven and eight disagreements: nineteen in total. Agreement with these labels is not proof that the labels are correct.", "focus": [475, 600, 3335, 265], "hold_after": 0.7}, {"visual": "07_actual_error_cell", "narration": "Click the eleven-count cell: recorded infected one, predicted infected two. At confidence zero point seven five, six disagreements enter the high-confidence list and five the low-confidence list. These are two inspection queues for the same selected cell, not new classification results.", "focus": [475, 1090, 3335, 530], "hold_after": 0.7}, {"visual": "08_actual_confidence_threshold", "narration": "Raise the confidence threshold to zero point nine five. The high list now contains two crops and the low list nine. Probabilities, class calls and the eleven-count cell remain unchanged. This live control partitions the queue; it does not recalibrate the model or rerun inference.", "focus": [475, 1090, 3335, 700], "hold_after": 0.7}, {"visual": "07_actual_error_cell", "narration": "Treat the automatic explanations cautiously. A confident disagreement does not prove a wrong annotation, and one plate cannot establish a plate-level cause. The displayed model-versus-well suggestions are hypotheses. Review acquisition, labels and genuinely independent data before deciding what needs correction.", "focus": [475, 1170, 3335, 160], "hold_after": 0.7}, {"visual": "09_actual_per_plate", "narration": "Per-plate metrics contains one row with all two hundred thirty-four predictions. It helps locate results by plate, but this example cannot compare plates or estimate a plate effect. The high accuracy does not remove the shared-well problem shown in Leakage audit.", "focus": [475, 595, 3335, 205], "hold_after": 0.7}, {"visual": "10_actual_calibration_table", "narration": "Calibration compares mean predicted probability with observed class frequency in five bins per class. The count column matters: sparse bins are uncertain. This saved bundle used no calibration correction. There is no calibration-fitting control on this tab; the table describes results prepared earlier.", "focus": [475, 595, 3335, 450], "hold_after": 0.7}, {"visual": "12_actual_prediction_filter", "narration": "In Predictions, type r five underscore c two to inspect that well. The table narrows from two hundred thirty-four to one hundred twenty-eight rows. This is a live text filter over saved records, not image filtering, segmentation or a change to the underlying result files.", "focus": [475, 595, 3335, 400], "hold_after": 0.7}, {"visual": "13_actual_filter_cleared", "narration": "Clear the filter and all two hundred thirty-four rows return. The sample paths explicitly say crops not included. To open disagreement crops in your own project, first open its matching experiment in Annotate. This archive cannot supply that database, and its disabled buttons are not a demonstrated crop workflow.", "focus": [475, 595, 2350, 460], "related_lessons": ["09_annotate"], "hold_after": 0.7}, {"visual": "04_actual_summary", "narration": "The download also preserves the native calibration and confusion figures. Inspect their contrast before reporting them. Generic out-of-fold titles and filenames do not make this one test split cross-validated. The saved probabilities and counts are unchanged; only private sample paths were replaced by explicit references.", "focus": [475, 650, 3335, 1170], "hold_after": 0.7}, {"visual": "14_actual_final_leakage", "narration": "Finish by keeping the leakage warning with any exported metrics. The API reference explains bundle preparation and loading; Training Runs covers comparing saved progress logs. spaCR AI may help explain terminology, but it cannot certify labels or independence. No provider request was needed for this example.", "focus": [475, 650, 3335, 1390], "related_lessons": ["28_training_runs"], "hold_after": 0.7}], "poster": "39_classifier_evaluation/poster.jpg", "silent": "39_classifier_evaluation/video/39_classifier_evaluation_silent.mp4"}, {"id": "40_run_history", "number": 40, "slug": "run_history", "series": 5, "app_key": "run_history", "section": "Data and batch runs", "title": "Run History: inspect real journals and restore available settings", "description": "Find recorded jobs through Help, check settings, file inventories, warnings and failures, and reopen a real Recruitment configuration without rerunning or deleting anything.", "objectives": ["Find Run history under Help and combine module, status and text filters.", "Distinguish recorded file inventories and successful execution from scientific validation.", "Read saved settings, environment details, warnings and an actual failure traceback.", "Copy the journal path and restore available Recruitment controls without running analysis."], "prerequisite": "Use journals from your own completed example runs. This recording reads an isolated copy of the normal local journal location, ~/.spacr/runs, containing real tutorial jobs rather than fabricated results. The Batch Runner and Recruitment lessons explain the acquired test inputs; Regression supplies actual recorded warnings, and an earlier Model Zoo attempt supplies a real failure. Run History has no dedicated dataset download, live image preview, plotting or AI panel. No analysis, deletion or external file-manager launch is performed here. All 496 journal files remain byte-identical. The example restores 27 exposed Recruitment settings; the recorded hash_inputs key is not represented in that GUI. Recorded hashes describe the past run, not a fresh verification of today's project files.", "scenes": [{"visual": "01_help_history", "narration": "Open Help, then Run history. This shared tool reads the local run journal, not every project folder on your computer. We use genuine records from the other tutorial runs. You do not need to repeat those analyses just to inspect their history.", "hold_after": 0.7, "related_lessons": ["37_batch", "25_recruitment"]}, {"visual": "02_loaded_history", "narration": "Refresh loads the available journal records. The table shows module, status, duration, CPU time and recorded file counts and sizes. Drag the divider to enlarge the detail area. These are saved execution measurements, not a live performance monitor or an independent assessment of scientific quality.", "hold_after": 0.7}, {"visual": "03_batch_search", "narration": "Choose convert and Success, then search for the shared example-folder name. Three actual Batch Runner jobs remain. Module, status and text filters work together; text search can find settings, paths, versions or recorded problems. There are no separate date or resource filters on this screen.", "hold_after": 0.7, "focus": [340, 175, 3480, 180]}, {"visual": "04_batch_empty_inventory", "narration": "Files and models is empty for these successful conversions because their journal skipped file hashing. That does not mean they produced no images. The Batch Runner lesson separately checked all twelve outputs. Treat a missing inventory as missing evidence, not as proof of missing data.", "hold_after": 0.7, "focus": [345, 710, 1500, 580], "related_lessons": ["37_batch"]}, {"visual": "05_no_match", "narration": "An unmatched search leaves an empty table, clears the detail panes and disables selected-run actions. Restoring the previous search brings back the same three records. Check your filters before concluding that a run disappeared; this search does not delete journal files.", "hold_after": 0.7}, {"visual": "07_recruitment_overview", "narration": "Now select the real Recruitment run. Overview shows about eighteen seconds elapsed and forty-five seconds of process CPU time; those are different measurements. Six input and six output file records are available. These counts describe recorded files, not cell numbers or a guarantee of complete inventory.", "hold_after": 0.7, "focus": [345, 710, 2200, 580], "related_lessons": ["25_recruitment"]}, {"visual": "09_settings_source", "narration": "Settings displays the saved configuration, including source, channels, object filters and Plot enabled. Scroll to read the full snapshot. The source is the tutorial's private example project. These historical values do not automatically change if you edit the project or the current module settings later.", "hold_after": 0.7, "focus": [345, 710, 3000, 1380]}, {"visual": "10_recorded_files", "narration": "Files and models lists recorded paths, sizes and hashes when available. Inspect both inputs and outputs, and remember that the same database may have different before-and-after hashes. Opening history reads those saved records; it does not recompute every current file's hash or validate the biological result.", "hold_after": 0.7, "focus": [345, 710, 3000, 1380]}, {"visual": "12_hashes_and_seeds", "narration": "Environment includes recorded software versions, seed information and snapshot hashes. These help investigate differences between runs, but do not alone guarantee reproducibility. Copy path places this run's journal-folder path on the clipboard. Preserve its settings and manifest together with the separate project inputs and results.", "hold_after": 0.7, "focus": [345, 710, 2650, 1380]}, {"visual": "14_recorded_warning", "narration": "A successful Regression record still has warnings about saved-figure contrast and missing provenance files. Warnings and failure separates those messages from a traceback. Success means execution finished; it does not certify readable figures, complete provenance or a valid statistical design. Read the dedicated Regression lesson for those checks.", "hold_after": 0.7, "focus": [345, 710, 3400, 340], "related_lessons": ["13_regression"]}, {"visual": "16_failure_exception", "narration": "The Failed filter exposes a genuine earlier Model Zoo attempt. Its traceback ends with an unsupported invert argument to Cellpose, which identifies a compatibility problem, not a segmentation result. We inspect the recorded failure without repeating it. Share relevant versions and error details when reporting a problem.", "hold_after": 0.7, "focus": [345, 710, 2450, 730]}, {"visual": "18_restored_recruitment", "narration": "Return to Recruitment and choose Load settings in module. All twenty-seven available controls match the saved values, and no analysis starts. The journal also contains hash inputs, which is not represented in this form. Review restored settings and current inputs before running; this is not an exact replay guarantee.", "hold_after": 0.7, "related_lessons": ["25_recruitment"]}, {"visual": "17_ready_to_restore", "narration": "Clear all deletes journal records; it is not a filter reset. We used neither that button nor the row menu's delete action, and every journal file stayed unchanged. For programmatic searches, use search_runs in spacr.run_journal. For a project report, use the separate Report lesson.", "hold_after": 0.7, "related_lessons": ["06_api", "29_report"]}], "poster": "40_run_history/poster.jpg", "silent": "40_run_history/video/40_run_history_silent.mp4"}, {"id": "41_classify", "number": 41, "slug": "classify", "title": "Classify: the main module and its nested tools", "series": 4, "app_key": "classify_merged", "section": "Core", "description": "Choose image or measurement-based classification, start from downloadable examples, inspect real results, and find the five tools now nested inside Classify.", "objectives": ["Choose the classifier family from the unified Home module.", "Use the linked real-data CV and tabular lessons with their explicit limitations.", "Find Classifier Evaluation, Explain CV, Activation, Training Runs and Feature Explorer under Classify.", "Keep saved evidence and distinguish AI assistance from verified analysis."], "prerequisite": "Recorded with spaCR 1.5.0.6. The main-module section contains this overview; specialized and nested lessons remain grouped under Classify in the submodule section. This overview reuses genuine, previously verified CV and ML recordings rather than rerunning models. They use DIFFERENT labels and example subsets and are NOT a head-to-head benchmark. Tabular example: Load test data → Load; measured cells, metadata classes columnID=c1/c2, random forest, Plot on, 2153 scored objects and 188 unscored objects missing nucleus data; actual test wells are separate but share one plate. CV example: the linked lesson explicitly prepares 64 unchanged downloaded annotated crops with canonical database filenames, Generate training dataset off, ResNet18 for one epoch, 16 train/16 validation/32 test, disjoint actual wells on one plate, accuracy 0.5 equal to the majority baseline. The old filename parser is not repaired. Follow the specialized lessons for reproducible settings, saved paths and limitations. Current nested routes: classifier_evaluation, explain_cv, activation, train_compare, feature_explorer. Explain CV fits measured features to existing CV predictions; it is not proof of causality. Activation visualizes image-model responses. No AI request, new model-quality claim, biological validation or direct family comparison is made. API: spacr.classify.classify dispatches by classifier_family to spacr.deep_spacr.train_test_model or spacr.ml.generate_ml_scores.", "scenes": [{"visual": "main_00_home", "narration": "Classify is one of the main modules on Home. Open it here, then choose your classifier family inside the module. The tutorial player follows the same structure: this overview belongs to main modules, while specialized workflows and nested tools are grouped under Classify in the submodule section.", "focus_modules": ["classify_merged"], "related_lessons": ["05_home", "10_classify_cv", "11_classify_ml"], "hold_after": 0.7}, {"visual": "main_02_family_choices", "narration": "Computer Vision uses object images; Tabular Machine Learning uses saved measurements. Choose according to your inputs and scientific question, not the name that sounds more powerful. Changing family does not redo segmentation. The linked Mask and Measure lessons cover their own live image and crop controls.", "related_lessons": ["07_mask", "08_measure"], "hold_after": 0.7}, {"visual": "ml_02_data_choice_load", "narration": "For the tabular example, click Load test data and choose Load rather than Stream. Keep the downloaded project and measurements database together. For your own images, complete measurement first. The detailed tabular lesson records the actual download, label choices, settings and completed random-forest run.", "related_lessons": ["11_classify_ml", "09_annotate"], "hold_after": 0.7}, {"visual": "ml_24_batch_figure", "narration": "These are that real run's plots and console, with Plot enabled. Its teaching labels are plate columns, not independently validated phenotypes. Objects missing required nucleus data remain unscored, not negative. Inspect saved predictions and the held-out wells; colourful figures alone do not establish generalization to another experiment.", "focus": [2140, 240, 1670, 1270], "related_lessons": ["11_classify_ml"], "hold_after": 0.7}, {"visual": "cv_24_batch_figure", "narration": "The separate computer-vision lesson uses an explicit filename-preparation workaround and sixty-four unchanged downloaded crops. Its one-epoch model achieves only the majority baseline. These two examples use different labels and subsets; do not compare their accuracies as a benchmark. Follow the linked lesson before preparing your own split.", "focus": [2090, 180, 1720, 1320], "related_lessons": ["10_classify_cv"], "hold_after": 0.7}, {"visual": "main_05_classifier_evaluation_tooltip", "narration": "The icons at the top right open nested tools, not separate Home tiles. Hover to identify each one. Classifier Evaluation is for inspecting a saved evaluation bundle, including predictions and leakage information. Its own lesson explains the required files and why a displayed metric still needs a sound validation design.", "focus": [2690, 65, 1120, 280], "related_lessons": ["39_classifier_evaluation"], "hold_after": 0.7}, {"visual": "main_05_explain_cv_tooltip", "narration": "Explain CV uses measured features to model existing computer-vision predictions. It is a separate explanatory model, not the original image network and not a causal explanation. Its tutorial shows the correct prediction input and the available results. Do not assume tabular-classifier outputs satisfy that input contract.", "focus": [2480, 65, 1330, 280], "related_lessons": ["70_explain_cv"], "hold_after": 0.7}, {"visual": "main_05_activation_tooltip", "narration": "Activation opens the image-model interpretation workflow. Use the matching checkpoint, image channels and preprocessing. The linked tutorial demonstrates genuine saved saliency maps and explains its external-viewer workaround. A highlighted image region is not proof of biological mechanism or of a well-performing classifier.", "focus": [2930, 65, 880, 280], "related_lessons": ["16_activation"], "hold_after": 0.7}, {"visual": "main_05_train_compare_tooltip", "narration": "Training Runs compares saved training histories and settings. It does not create independent evidence merely by putting two curves together. Keep runs in separate preserved directories and compare compatible metrics and data splits. Its dedicated tutorial covers the controls without repeating them in this main-module overview.", "focus": [2600, 65, 1210, 300], "related_lessons": ["28_training_runs"], "hold_after": 0.7}, {"visual": "main_06_feature_explorer_nested", "narration": "Feature Explorer opens directly from the final icon. It can rank measured features for a chosen comparison before a classifier is trained. Its lesson uses the real downloaded measurements and demonstrates live filters. Check the selected comparison again after filtering; a ranking is neither causality nor a trained image model.", "related_lessons": ["65_feature_explorer"], "hold_after": 0.7}, {"visual": "cv_30_ai_unsent_question", "narration": "The console also offers optional spaCR AI assistance. Here the question is unsent; no provider response or analysis result is demonstrated. Keep model outputs, settings and split evidence, and verify advice against them. In Python, classify dispatches to the image or tabular implementation selected by classifier family.", "focus": [2090, 950, 1720, 1130], "related_lessons": ["06_api", "10_classify_cv", "11_classify_ml"], "hold_after": 0.7}], "poster": "41_classify/poster.jpg", "silent": "41_classify/video/41_classify_silent.mp4"}, {"id": "42_curate", "number": 42, "slug": "curate", "title": "Curate: practice edits and preserve their history", "series": 5, "app_key": "curate", "host_app_key": "make_masks", "section": "Make Masks", "example_files": ["Curate_SYNTHETIC_practice.zip"], "description": "Practice reversible mask and track edits in the nested Curate tool, with explicitly synthetic data and external checkpoints for the current mask-history limitation.", "objectives": ["Find Curate inside Make Masks and open unchanged copies of the teaching mask and tracks.", "Paint, undo and save a mask without treating a practice mark as a biological correction.", "Preserve saved masks and sidecars outside the application before reopening.", "Split and join tracks, save their history and discard an unsaved deletion."], "prerequisite": "Extract Curate_SYNTHETIC_practice.zip and work on copies. The TIFF preserves label plane 2 of the recorded synthetic Timelapse output: 256 by 256 pixels, sixteen labels numbered 2 through 17. The CSV has sixteen tracks and 128 rows across eight frames. These are not acquired biological data. The current NPY picker path failed to load; this example uses exact integer TIFF labels. Brush radius 8, New label 18 and an empty-area click are practice settings, not biological corrections. Independent array checks verify every pixel after paint, undo, save and reload. Save mask writes the selected file and its .curation.json sidecar. The native mask reload loses its three-entry in-memory log, and the next save replaces the sidecar with one new entry. This defect remains unfixed. Before reopening, run the separate companion curate_checkpoint.py with the saved mask path and a NEW backup folder; it preserves both files byte-for-byte and refuses overwrite. Keep separate checkpoints and notes; it does not restore app history or merge ledgers. Reopening adds a second viewer mask layer, so changed colour intensity is not changed label identity. Track 2 split at frame 4 creates track 18; joining the non-overlapping halves restores all 128 rows. Joining tracks 2 and 3 is refused because frames overlap. A saved split/join log survives reloading after an unsaved deletion of track 3. All CSV values and original source hashes are checked. No accuracy claim, new segmentation, GPU, AI request, app modification or publication. API: spacr.curation.MaskCuration and TrackCuration; GUI persistence differs as disclosed.", "scenes": [{"visual": "02_actual_curate_page", "narration": "Open Make Masks, then its nested Curate tool. Curate belongs under Make Masks in the submodule section, not on a separate Home tile. It edits label masks and tracks. This lesson uses synthetic teaching outputs from Timelapse, not acquired biological observations or evidence that manual edits improve accuracy.", "related_lessons": ["14_make_masks", "17_timelapse"], "hold_after": 0.7}, {"visual": "04_original_sixteen_label_mask", "narration": "Download the linked practice archive and work on copies. Browse to its integer mask TIFF: sixteen original labels occupy this two hundred fifty-six pixel square. The picker also advertises NPY, but that route failed in this build. The TIFF preserves the exact label plane; do not replace labels with a coloured screenshot.", "hold_after": 0.7}, {"visual": "05_practice_disk_not_a_real_object", "narration": "Set brush radius to eight and click New to select label eighteen. Paint once in the empty practice area. This disk is deliberately invented to learn the control; it is not a missing cell. The brush changes label pixels in memory, while the saved file remains unchanged until Save mask.", "focus": [355, 470, 3450, 660], "hold_after": 0.7}, {"visual": "06_undo_restores_every_original_pixel", "narration": "Undo stroke restores every original pixel in this exercise. Paint again, then inspect the result before saving. The recorded ledger contains paint, undo and paint; undo is itself part of the history. Your precise mouse position may change the painted pixel count, so do not treat our practice footprint as a biological target.", "focus": [3380, 480, 425, 710], "hold_after": 0.7}, {"visual": "07_saved_mask_and_ledger", "narration": "Save mask writes back to the selected working TIFF and saves its curation sidecar. Before reopening, run the separate checkpoint script supplied with the download, specifying this saved mask and a new backup folder. It copies both files exactly. This is an explicit external backup step, not a hidden application feature.", "focus": [3380, 480, 425, 710], "hold_after": 0.7}, {"visual": "10_second_session_saved_history", "narration": "Here is the current limitation: reopening the mask resets its in-memory log, and another save replaces the sidecar with the new session's edit. Our earlier checkpoint still preserves the original three entries. Keep separate backups and notes; the script does not repair or restore app history. Reopening also adds a viewer layer, so colour brightness is not label identity.", "hold_after": 0.7}, {"visual": "13_overlapping_tracks_cannot_join", "narration": "Browse to the working tracks CSV. It has sixteen tracks over eight frames, with one hundred twenty-eight rows. Selecting tracks two and three and pressing Join is refused because both exist in the same frames. Read that message; forcing unrelated trajectories together would not be a valid correction.", "focus": [3380, 480, 425, 1250], "hold_after": 0.7}, {"visual": "14_split_tail_starts_at_frame_four", "narration": "Select track two, set Split at frame to four, and click Split. Frames four through seven move to new track eighteen, while frames zero through three remain in track two. Coordinates and original labels stay unchanged. This is a controlled editing exercise, not evidence of a real cell division.", "focus": [3380, 480, 425, 1250], "hold_after": 0.7}, {"visual": "16_saved_tracks_and_history", "narration": "Select tracks two and eighteen together and click Join. Their non-overlapping halves combine, restoring all original rows. Click Save tracks to write the CSV and its own sidecar. The independent check compares every frame, identifier and coordinate, not just the number of tracks. Keep the mask and track histories distinct.", "focus": [3380, 480, 425, 1250], "hold_after": 0.7}, {"visual": "17_unsaved_delete_removes_eight_rows", "narration": "Deleting track three removes its eight rows in memory. Do not save this demonstration deletion. Reopen the saved CSV to discard that unsaved change. This illustrates the difference between current edits and disk contents; deleting a trajectory in real data requires a documented reason, not simply an unwanted result.", "focus": [3380, 480, 425, 1250], "hold_after": 0.7}, {"visual": "19_saved_tracks_and_two_actions_return", "narration": "All one hundred twenty-eight rows and the saved split-and-join history return. Unlike mask reopening in this build, track reopening retains that history in our test. Preserve original data, checkpoints and reasons for edits. Python provides MaskCuration and TrackCuration; this workflow needs neither a GPU nor an AI provider, and successful editing is not scientific validation.", "related_lessons": ["06_api", "17_timelapse"], "hold_after": 0.7}], "poster": "42_curate/poster.jpg", "silent": "42_curate/video/42_curate_silent.mp4"}, {"id": "43_illumination", "number": 43, "slug": "illumination", "title": "Illumination", "series": 5, "app_key": "illumination", "host_app_key": "measure", "section": "Data", "description": "Estimate a flat-field from downloaded images through Measure’s Illumination page, inspect its actual exported QC, and keep numerical improvement separate from biological validation.", "objectives": ["Open the nested Illumination page and select real merged-field intensity channels.", "Compare correction off and on, and inspect the saved model and exported QC image.", "Reuse a reviewed model deliberately without confusing in-sample diagnostics with independent validation."], "prerequisite": "This lesson uses new byte-identical copies of all sixteen downloaded plate1 merged fields, each 1994 by 1994 pixels with seven stored planes. Channel zero is a persisted intensity-axis index, not a claimed stain identity; label planes must not be used as intensities. The native off/on runs preserve all originals and copies. An independent formula checks 7,952,072 corrected pixels through the public API after the GUI run, not as substituted GUI output. The model and QC are estimated from the same sixteen fields: the diagnostics are in-sample, not biological or optical ground truth. Dark zero is the demonstration setting, not a measured camera calibration. The current embedded Figures panel remains empty; the real saved PNG is opened in the separate system image viewer. No application code, generated measurements or original images are modified. The old five-scene in-memory simulation does not demonstrate the current nested page and is replaced, not merely relocated.", "scenes": [{"visual": "01_measure_host", "narration": "Open Measure, then its Illumination button. This nested page estimates a correction model before a larger analysis. It is different from simply enabling correction inside a measurement run, and it does not turn the whole application into an automatically corrected session.", "focus": [3625, 65, 110, 100], "related_lessons": ["08_measure"], "hold_after": 0.7}, {"visual": "05_setting_src", "narration": "Point Source at the merged folder containing the image arrays, not the measurements database. We use new copies of all sixteen fields from the downloadable plate example. The originals remain unchanged, and the saved illumination model goes beside this merged folder.", "focus": [363, 375, 1140, 160], "related_lessons": ["07_mask", "08_measure"], "hold_after": 0.7}, {"visual": "05_setting_channels", "narration": "The Channels setting names positions in the stored intensity array. Here we select channel zero. Check your own acquisition mapping instead of assuming that zero always means the same stain, and never select a label-mask plane as if it were fluorescence intensity.", "focus": [374, 475, 850, 65], "hold_after": 0.7}, {"visual": "04_correction_off_finished", "narration": "First, correction is off. Run finishes, but the console explicitly says that no field was estimated. We verified that no model was created. A successful completion message alone therefore does not prove that correction happened.", "focus": [1518, 405, 2280, 260], "hold_after": 0.7}, {"visual": "05_setting_illumination_degree", "narration": "Turn Illumination correction on. This example uses the polynomial estimator with degree four and leaves Illumination model empty to estimate a new field. More flexibility is not automatically better: a correction that follows cells or treatment patterns can remove the biology you wanted to measure.", "focus": [363, 550, 1140, 300], "hold_after": 0.7}, {"visual": "05_setting_illumination_max_fields", "narration": "Keep acquisition groups separate with Illumination per plate. We sample all sixteen available fields here. Representative coverage matters more than increasing a number blindly; a model fitted from one crowded corner can confuse biological structure with uneven illumination.", "focus": [363, 858, 1140, 160], "hold_after": 0.7}, {"visual": "05_setting_illumination_dark", "narration": "Illumination dark is an additive camera offset in raw counts, not a learned biological background. Zero is the setting used for this demonstration, not a calibration result. Choose the offset from appropriate acquisition controls rather than adjusting it until a desired phenotype disappears.", "focus": [374, 775, 1110, 61], "hold_after": 0.7}, {"visual": "05_setting_illumination_on_missing", "narration": "Keep Illumination QC enabled and check the missing-model policy. We use error so an unavailable plate correction stops the operation instead of silently mixing corrected and uncorrected fields. These checks do not replace examining the estimated field.", "focus": [363, 1020, 1140, 150], "hold_after": 0.7}, {"visual": "06_correction_on_finished", "narration": "Run again with correction enabled. The console now reports the fitted field, the diagnostic slopes and the saved model path. This standalone step leaves the image files unchanged; it has not rerun segmentation or produced new cell measurements.", "focus": [1518, 405, 2280, 485], "hold_after": 0.7}, {"visual": "08_exported_qc_system_viewer", "narration": "In this build, the QC image is saved but does not appear in the embedded Figures panel. Open illumination underscore QC underscore plate one dot PNG from the illumination folder in your image viewer. This is the actual exported figure in a separate viewer, not a simulated spaCR panel.", "focus": [200, 100, 3440, 1920], "hold_after": 0.7}, {"visual": "08_exported_qc_system_viewer", "narration": "The left panel shows the estimated, mean-one illumination field. Correction subtracts the camera offset and divides by this field. Although the title calls it gain, do not multiply intensities by that displayed map: the correction uses its reciprocal. Check for biological structures leaking into the estimate.", "focus": [400, 680, 790, 825], "hold_after": 0.7}, {"visual": "08_exported_qc_system_viewer", "narration": "The radial slope changes from approximately minus zero point one eight one to plus zero point zero two six. The reported eighty-five point four percent reduction matches our independent calculation, but the after curve is not flat. These are the same fields used to fit the model, so this is not independent validation.", "focus": [1270, 680, 1080, 840], "hold_after": 0.7}, {"visual": "09_return_to_illumination", "narration": "For later reuse, provide the saved model path and explicitly enable correction in the intended Mask or Measure workflow. Preserve the model, channel mapping, plate identities and settings together. Review independent fields and avoid applying correction twice to already corrected intensities before interpreting biological differences.", "focus": [363, 370, 1140, 800], "related_lessons": ["07_mask", "08_measure"], "hold_after": 0.7}], "poster": "43_illumination/poster.jpg", "silent": "43_illumination/video/43_illumination_silent.mp4"}, {"id": "44_data_manager", "number": 44, "slug": "data_manager", "series": 5, "app_key": "data_manager", "section": "Data and batch runs", "title": "Data Manager: inspect, prune and archive a real example safely", "description": "Inspect registered and unregistered files, cancel and confirm an exact crop cleanup, then move a private example project with its archive records.", "objectives": ["Find Data manager under Help and inspect actual project usage.", "Read the exact deletion plan, kept reasons and complete confirmation list.", "Distinguish irreversible cleanup from archiving and verify Cancel preserves files.", "Rescan the archive and retain its manifest, origin ledger and original backup."], "prerequisite": "Follow External Masks to obtain the genuine two-field example with 103 measured objects and saved figures. This recording uses an isolated, byte-verified copy of that completed project; its original absolute registry paths resolve only to the disposable copy inside the recording process. All 131 original files remain unchanged. Data Manager has no separate dataset download, live image preview, Plot control or AI panel. Its displayed sizes count bytes on disk, not scientific quality. Cleanup removes 103 PNG crops and their format JSON from the copy only, retains the measured database and recorded recipe, and does not demonstrate regeneration. Archiving moves the remaining project; it is not a backup or a guarantee that every historical absolute path has been rewritten. External resource logs stay outside this whole-project move.", "scenes": [{"visual": "01_help_data_manager", "narration": "Open Help, then Data manager. This shared tool manages project files; it does not run image analysis. We use a disposable copy of the real External Masks example, including its measurements and saved figures. Keep an independent backup before trying cleanup yourself.", "hold_after": 0.7, "related_lessons": ["31_external_masks"]}, {"visual": "03_actual_usage", "narration": "Choose project selects the project root. Usage shows about ninety-one megabytes in one hundred twenty-nine files after scanning. Registered and Unregistered are different: files can exist without a registry record. Folder-based category labels are estimates, not proof of the files' scientific content.", "hold_after": 0.7, "focus": [345, 175, 3400, 570]}, {"visual": "04_prune_choices", "narration": "On Prune, choose which kinds to consider. A selected switch does not itself authorize deletion. Leave measurement databases and model weights unchecked here, then choose Show what can be deleted. Read both the proposed files and the reasons other artifacts are kept.", "hold_after": 0.7, "focus": [345, 245, 3470, 230]}, {"visual": "05_real_prune_plan", "narration": "This plan contains only the data crop folder: one hundred three object images and one format file, not one hundred four cells. It proposes freeing about three point four megabytes. Get it back by names Measure, but regeneration still requires the original inputs, settings and suitable software.", "hold_after": 0.7, "focus": [345, 320, 3450, 160]}, {"visual": "09_confirmation_locked", "narration": "Delete opens a second confirmation with the actual file list. It cannot be undone. Resize the dialog and scroll through the paths before acknowledging them. The final Delete button starts disabled; enabling the acknowledgment is a separate action from deleting anything.", "hold_after": 0.7}, {"visual": "11_acknowledged_not_deleted", "narration": "The acknowledgment enables Delete. Turning it off disables Delete again. In this first demonstration we choose Cancel instead, and every project file remains unchanged. Cancel is the correct choice whenever the paths, file counts or expected recovery procedure are uncertain.", "hold_after": 0.7}, {"visual": "14_actual_cleanup_result", "narration": "We reopen the same verified plan and confirm deletion only on our disposable copy. The result reports three point four megabytes freed in one hundred four files. All twenty-four other non-registry files remain byte-identical, including the measurement database and saved figures.", "hold_after": 0.7, "focus": [345, 175, 2500, 240]}, {"visual": "15_usage_after_cleanup", "narration": "The automatic rescan now reports one registered artifact missing from disk: the deliberately removed crop folder. Its recipe remains in the registry with cleanup metadata. That record is not an undo buffer, and we have not rerun Measure to regenerate the crops.", "hold_after": 0.7, "focus": [345, 170, 3450, 580]}, {"visual": "16_updated_archive_plan", "narration": "Archive is different: it moves the remaining project. Choose an empty destination outside the source, then Show what would move. After cleanup, this plan contains twenty-five files totaling about eighty-eight megabytes. Read the source and destination carefully; this screen plans the whole project.", "hold_after": 0.7}, {"visual": "17_archive_default_no", "narration": "Move asks for confirmation, with No selected by default. First we choose No and verify that the source remains unchanged and the destination empty. A plan and a cancelled confirmation move nothing. Do not treat the archive destination as an extra backup copy.", "hold_after": 0.7}, {"visual": "19_archive_confirm_yes", "narration": "We confirm Yes only for this private example. The remaining files move to the destination. A manifest is written there and an archive log remains at the origin. The original project used to create our disposable copy stays completely unchanged.", "hold_after": 0.7}, {"visual": "22_rescan_archived_project", "narration": "Choose the destination as the project and scan again. The archived measurement database is registered at its new path, and every non-registry file matches its pre-move bytes. The extra manifest explains the new file count. Historical records and external logs are not automatically rewritten or relocated.", "hold_after": 0.7, "focus": [345, 80, 3470, 670]}, {"visual": "22_rescan_archived_project", "narration": "For Python automation, spacr.data_manager exposes scan_project, plan_prune, prune, plan_archive and archive. Inspect the plan before supplying its confirmation token. For browsing measurements use Database Browser; for a readable project summary use Report. Keep the separate backup and archive records together with your research documentation.", "hold_after": 0.7, "related_lessons": ["06_api", "34_database", "29_report"]}], "poster": "44_data_manager/poster.jpg", "silent": "44_data_manager/video/44_data_manager_silent.mp4"}, {"id": "45_project_browser", "number": 45, "slug": "project_browser", "series": 5, "app_key": "project_browser", "section": "Data and batch runs", "title": "Project Browser: discover real projects and interpret their evidence", "description": "Find registered and unregistered example projects, control search depth, sort actual disk usage and read recorded evidence without launching analysis or deleting files.", "objectives": ["Open Project browser under Help and choose bounded search folders.", "Use Depth and Scan to discover projects and sort by real byte counts.", "Distinguish missing provenance and declared-output stages from actual run history.", "Read details, remove only search roots and use the separate tools for journals and data."], "prerequisite": "Use completed examples from External Masks and Batch Runner. The recording compares a byte-verified private copy of the two-field measured project with a private copy of one four-channel conversion output, including its hidden checkpoint and two other conversion records. These are different examples, not a before-and-after comparison. All 131 original measured-project files and seven original conversion files remain unchanged. The original artifact paths resolve to the measured copy only inside the recording namespace; provenance is not rewritten. Project Browser has no dedicated download, live image preview, Plot control or AI panel. Scan reads project evidence, not every journal. Sorting, depth and root removal use real controls; no analysis, deletion, external file-manager launch or automatic handoff is performed. Normal SQLite access removes only the private registry's empty WAL and 32768-byte SHM. The original databases and other files remain byte-identical.", "scenes": [{"visual": "01_help_project_browser", "narration": "Open Help, then Project browser. This shared screen finds project folders and summarizes what is recorded or present on disk. We use real outputs from External Masks and Batch Runner on private copies. It is an inventory tool, not an image-analysis run.", "hold_after": 0.7, "related_lessons": ["31_external_masks", "37_batch"]}, {"visual": "04_depth_zero_no_projects", "narration": "Add folder selects a place to search. At Depth zero, only that folder itself is checked. Our chosen parent contains a project one level below, so the table is empty. An empty result at this depth does not mean the project or its images are missing.", "hold_after": 0.7, "focus": [345, 170, 3450, 360]}, {"visual": "05_real_unregistered_conversion", "narration": "Set Depth to one and choose Scan. The converted image folder appears: about thirty-two megabytes in seven files. Those are four acquired channel images, a conversion map, a status record and a hidden checkpoint. File counts are not counts of cells or independent experiments.", "hold_after": 0.7, "focus": [345, 180, 3450, 660]}, {"visual": "05_real_unregistered_conversion", "narration": "State says unknown, nothing recorded, because this folder has no artifact registry. Stage says nothing run and Last run says never, even though the conversion genuinely completed. These columns reflect declared workflow outputs and recorded artifacts, not every conversion history. Unknown is not evidence that the data are clean or unprocessed.", "hold_after": 0.7, "focus": [345, 300, 3450, 560], "related_lessons": ["37_batch", "40_run_history"]}, {"visual": "07_two_real_projects", "narration": "Add the measured project as a second search root. Its row shows Measure, about ninety-one megabytes, one hundred twenty-nine files and a registry timestamp. If rescan leaves a selected row's details blank, select another row and return. We demonstrate that workaround without changing the application.", "hold_after": 0.7, "focus": [345, 225, 3450, 260]}, {"visual": "09_enlarged_details", "narration": "Select the measured project and drag the divider to widen its details. Three artifact records are current here, but roughly eighty-seven megabytes remain unregistered. Current describes the recorded comparison, not complete provenance or scientific validity. The Last run detail explicitly says that its timestamp comes from the registry.", "hold_after": 0.7, "focus": [2020, 300, 1790, 260]}, {"visual": "10_stages_and_next_steps", "narration": "Read Stages before interpreting a completion label. This example reports Mask outputs complete because imported arrays, counts and masks exist; it does not prove that Mask segmentation ran. What could run next lists workflow suggestions, not buttons or validation that every suggested analysis suits these experimental data.", "hold_after": 0.7, "focus": [2020, 520, 1790, 650], "related_lessons": ["31_external_masks"]}, {"visual": "12_size_descending", "narration": "Click the Size header to change sort order. We checked both ascending and descending order against actual byte counts, and row selection still points to the correct project. This screen has no separate stage, age, module-status or stale-result filter controls; use its actual sortable columns and search roots.", "hold_after": 0.7, "focus": [345, 300, 1680, 170]}, {"visual": "14_depth_zero_keeps_direct_project", "narration": "With both roots present, Depth zero still finds the directly selected measured project, but not the conversion nested under its parent. Returning to Depth one restores both rows. Depth changes the search scope; it does not remove data or change how much analysis has been completed.", "hold_after": 0.7, "focus": [345, 175, 3450, 340]}, {"visual": "16_remove_search_root_only", "narration": "Remove stops searching the selected root; it does not delete that folder. We remove the measured root, then add the unchanged project back. Double-clicking its row in this build emits its selection but stays on Project Browser, so do not expect a project or latest-run window to open automatically.", "hold_after": 0.7}, {"visual": "18_restored_project_inventory", "narration": "For actual journal details use Run History, for measurement tables use Database Browser, and for cleanup or archiving use Data Manager. In Python, spacr.projects provides discover, scan and browse. All original files remain unchanged; no new analysis was launched. Follow the relevant workflow lesson before acting on a suggested next step.", "hold_after": 0.7, "related_lessons": ["06_api", "40_run_history", "34_database", "44_data_manager"]}], "poster": "45_project_browser/poster.jpg", "silent": "45_project_browser/video/45_project_browser_silent.mp4"}, {"id": "46_napari_bridge", "number": 46, "slug": "napari_bridge", "title": "Napari Bridge: edit, import and reopen safely", "series": 5, "app_key": "napari_bridge", "host_app_key": "make_masks", "section": "Mask correction", "description": "Practise a pixel-checked round trip with synthetic image and label files, explicit backups, native Fill and Undo controls, and close/reopen between imported edits.", "objectives": ["Open Napari Bridge inside Make Masks with separate image and label files.", "Distinguish viewer edits, Undo, importing to disk and the correction history.", "Close and reopen between imports, then verify both saved corrections without claiming the same-viewer defect is fixed."], "example_files": ["SYNTHETIC_napari_example.zip"], "prerequisite": "Extract the supplied explicitly SYNTHETIC example into a NEW folder and retain an untouched backup. It contains a 256x256 uint16 image and label mask with sixteen objects; no biological corrections or segmentation accuracy are validated. The optional napari dependency is required; the recording uses napari 0.9.1 and its supported font-size preference of 20. Choose mask.tif and image.tif in Napari Bridge, nested inside Make Masks. Use native Fill to replace label 2 with 18, Undo, repeat and Take the mask back. This overwrites the working mask and records 2,197 changed pixels in mask.tif.curation.json. CLOSE and REOPEN the viewer before the next edit: an earlier check showed that a second edit in the same viewer was falsely reported unchanged and not saved. The application defect is NOT claimed fixed. After reopening, replace label 4 with 20 and import; 1,288 pixels change and both history entries remain. Both saved masks were checked across all 65,536 pixels; original synthetic source and image intensities were preserved. Added/removed label IDs do not imply an extra or missing cell. API: spacr.napari_bridge.load_handoff, open_in_napari and write_back. No model training, biological validation, unrestricted repeated-edit acceptance, publication or listening approval is claimed.", "scenes": [{"visual": "02_actual_bridge", "narration": "Open Napari Bridge inside Make Masks. It passes an image and label mask to the optional napari viewer, then imports corrected labels. This lesson uses a clearly marked synthetic practice example, not a biological experiment. Keep an untouched backup: importing corrections overwrites the selected working mask.", "focus": [460, 235, 3350, 510], "related_lessons": ["14_make_masks"], "hold_after": 0.7}, {"visual": "05_ready_to_open", "narration": "Download the example and extract it into a new folder. Browse to mask dot tif, then image dot tif, and press Open in napari. These are different inputs: integer object labels belong in Mask, while the intensity image is the visual reference. The example contains sixteen synthetic objects.", "focus": [460, 365, 3350, 370], "hold_after": 0.7}, {"visual": "06_actual_napari_layers", "narration": "Napari opens with an image layer and a mask Labels layer. Select the mask layer for editing; leave the image intensities unchanged. Label zero is background. The colours distinguish object identities, not biological classes or confidence. We enlarged the real interface font for this recording, not the source image.", "hold_after": 0.7}, {"visual": "07_unchanged_round_trip", "narration": "Return to spaCR and click Take the mask back before changing anything. The status reports that the mask is unchanged, and nothing is written. Importing is a separate action from editing in the viewer. This unchanged check does not prove that a later correction was saved; inspect that result too.", "focus": [460, 445, 3350, 295], "hold_after": 0.7}, {"visual": "08_fill_one_synthetic_object", "narration": "In napari, select label eighteen, choose Fill, and click the practice object labelled two. Only that object's label changes. This is a controlled relabelling exercise, not an improvement to a biological segmentation. The working file on disk has not changed yet.", "hold_after": 0.7}, {"visual": "09_actual_napari_undo", "narration": "Use Undo to restore the original label; this recording uses Control Z. Then repeat the same Fill operation before importing. Undo acts on the viewer's edit history. Do not confuse it with recovering an earlier file after an import: keep backups for that purpose.", "hold_after": 0.7}, {"visual": "11_imported_and_recorded", "narration": "Click Take the mask back. The status reports two thousand one hundred ninety-seven changed pixels and a correction-history file. One label was added and one removed because two became eighteen; there are still sixteen objects. Verify the saved mask and history, not just the colour displayed in napari.", "focus": [460, 445, 3350, 295], "hold_after": 0.7}, {"visual": "12d_closed_before_next_edit", "narration": "Click Close viewer now, before making another edit, then reopen it. This step is essential in the tested version: a second edit in the same viewer could be reported unchanged and lost. We demonstrate the verified close-and-reopen workflow, not a fix for that application defect.", "focus": [460, 445, 3350, 295], "hold_after": 0.7}, {"visual": "14_history_preserved_after_reopen", "narration": "After reopening, replace label four with twenty and import again. This changes one thousand two hundred eighty-eight pixels, and the earlier history entry remains. Close the viewer when finished. Keep the original image and corrected mask with their provenance, and rerun affected measurements rather than reusing results tied to old labels.", "focus": [460, 445, 3350, 295], "related_lessons": ["08_measure", "06_api"], "hold_after": 0.7}], "poster": "46_napari_bridge/poster.jpg", "silent": "46_napari_bridge/video/46_napari_bridge_silent.mp4"}, {"id": "47_barcode_qc", "number": 47, "slug": "barcode_qc", "title": "Barcode QC: real counts, threshold trade-offs and saved plots", "series": 5, "app_key": "barcode_qc", "host_app_key": "map_barcodes", "section": "Map Barcodes", "description": "Inspect the published count-table example, run Barcode QC, compare read depth and threshold trade-offs, and open its verified saved plots in a real image viewer.", "objectives": ["Find Barcode QC inside Map Barcodes and choose a real mapped-count table.", "Distinguish an illustrative target from an experimentally justified setting.", "Inspect console warnings, actual saved plots and independently checked tables.", "Separate low-read wells, over-target wells and barcode-sequence collisions."], "prerequisite": "Use plate_1_unique_combinations.csv from the downloaded example-screen data shown in the Regression tutorial. The source is an existing published count table, NOT output from this tutorial session's unsuccessful raw FASTQ mapping attempt. Its manifest specifies 4325565 bytes and SHA256 9bbfd6de409ec501b94abd2f20230611a695b142228892f5c3b8b2b564ba1f13. Use a private copy and a new output directory. Barcode QC is nested inside Map Barcodes. This real run has 172756 input rows, 49464341 mapped reads in the table, 384 wells and 1379 observed guides. Target 5 with median is demonstration only; other settings are min_reads_per_well=0, starved_read_fraction=0.1, exclude_starved_wells=True, position_effect_ratio=2, sweep_span=4, sweep_points=25, Plot/Save/Verbose on. Optional qc_data and guide/row/column reference files are omitted. Therefore no unmapped-rate, missing-reference-guide or barcode-sequence-collision conclusion is supported. The worker succeeds and independent CSV comparisons check 2884 fields with zero numeric error; original inputs and saved outputs stay unchanged. This build still emits an incorrect src preflight error despite accepting count_data, and its Figures card stays empty. We explicitly show both saved PNGs in the real external system viewer, NOT repaired GUI plotting. There is no live preview control or GPU calculation here. No AI provider is contacted. API: spacr.sequencing_qc.barcode_qc, derive_threshold and threshold_sweep. No biological validation or publication is claimed.", "scenes": [{"visual": "02_barcode_qc_fold", "narration": "Open Map Barcodes, then its nested Barcode QC tool. This workflow examines counts after mapping; it does not remap FASTQ reads. We use the published count-table example from the linked Regression lesson. It is not output from our earlier unsuccessful raw-read mapping attempt.", "related_lessons": ["12_map_barcodes", "13_regression"], "hold_after": 0.7}, {"visual": "04_actual_count_input", "narration": "Under Count data, select a copy of plate one unique combinations. Check the selected file rather than leaving a placeholder path. This actual table contains about forty-nine point five million mapped reads across three hundred eighty-four wells. Keep the original unchanged and choose a new destination for the QC outputs.", "hold_after": 0.7}, {"visual": "05_01_target_grnas_per_well", "narration": "Target gRNAs per well expresses the target used to derive a read-abundance cutoff. Here we leave the illustrative value five and use the median. That is not a recommended experimental design or proof of single-guide attribution. Choose your own target from the design and inspect the resulting trade-offs, not just the suggested number.", "hold_after": 0.7}, {"visual": "05_04_starved_read_fraction", "narration": "The starved-read fraction identifies wells with unusually few reads relative to the plate median. Here it is zero point one, and none of the three hundred eighty-four wells fall below the resulting cutoff. This is a read-depth flag, not a guarantee that every well, guide or biological measurement is trustworthy.", "hold_after": 0.7}, {"visual": "05_09_plot", "narration": "Enable Plot and Save, keep the destination explicit, and press Run. This is a small table analysis, not a GPU segmentation task, and this screen has no live-preview control. We leave the optional mapping-QC and barcode-reference inputs empty; conclusions requiring those files cannot be inferred from the count table alone.", "hold_after": 0.7}, {"visual": "07_finished_console", "narration": "Read the actual console, including its warnings. The worker finishes, but this build incorrectly complains that src is missing even though the module uses Count data. We verified the real input and saved tables; we did not repair the preflight. Do not generalize this diagnosed mismatch into permission to ignore other errors.", "hold_after": 0.7}, {"visual": "08_actual_figures_state", "narration": "The current build also leaves its Figures panel empty although two PNG plots were saved. Open barcode underscore qc dot png and threshold underscore sweep dot png from your output folder in an image viewer. The next scenes show the real system viewer, not figures inserted into spaCR or a claim that the GUI is fixed.", "hold_after": 0.7}, {"visual": "09_saved_barcode_qc", "narration": "Inspect read depth, row and column effects, and the observed library distribution. The dashed depth cutoff identifies low-read wells; the position bars compare row or column medians with the plate median. The library curve shows unequal read representation among observed guides. Without a reference library, it cannot tell you which expected guides are entirely missing.", "hold_after": 0.7}, {"visual": "10_saved_threshold_sweep", "narration": "Inspect the sweep rather than accepting a cutoff blindly. Here the derived threshold is about zero point zero one two one, or one point two one percent of a well's reads. It gives a median of five guides, retains all wells and about fifty-eight percent of mapped reads, while roughly forty percent of wells still exceed the target.", "hold_after": 0.7}, {"visual": "10_saved_threshold_sweep", "narration": "The red curve counts wells over the five-guide target. It is not a measurement of barcode-sequence similarity, and being below that target does not establish single-guide attribution. Loosening the cutoff raises the over-target fraction without gaining wells here. Compare the saved sweep table, and justify a choice for your analysis rather than treating this example as a universal threshold.", "hold_after": 0.7}, {"visual": "11_back_to_actual_gui", "narration": "Keep the source counts, settings, console log, recommendation, tables and plots together. Independent checks reproduced the saved well, position and sweep statistics with no numerical discrepancy. That verifies this computation, not its biological interpretation. AI assistance is optional and no request was submitted here; any later advice must be checked against the actual data and API.", "related_lessons": ["06_api", "13_regression"], "hold_after": 0.7}], "poster": "47_barcode_qc/poster.jpg", "silent": "47_barcode_qc/video/47_barcode_qc_silent.mp4"}, {"id": "48_hit_list", "number": 48, "slug": "hit_list", "title": "Hit List: inspect candidates with an explicit companion window", "series": 5, "app_key": "hit_list", "host_app_key": "regression", "section": "Regression", "example_files": ["Hit_List_real_results_companion.zip"], "description": "Use unchanged Regression results to explore real Hit List filters and exports, while explicitly working around the hidden native panel.", "objectives": ["Distinguish the broken native shortcut from the external companion.", "Interpret ranked candidates without claiming significant discoveries.", "Filter, restore and export the actual result rows."], "prerequisite": "Extract Hit_List_real_results_companion.zip. Activate your spaCR environment and run python hit_list_companion.py, then Browse to results. The companion wraps the unmodified HitListScreen; it does not repair Regression navigation or wire Investigate. The archive contains original Regression outputs, not a full project. There are 325 genes, 434 guide rows and zero genes passing q <= .05. Effects are standardized marginal effects, not simultaneous multivariable coefficients. Missing intervals are unavailable. Exported n_obs=0 does not report actual well support: use results_gene.csv wells_with_gene, which ranges from 2 to 48. Metadata joins, penalised ranking and Investigate are outside this demonstration. No model training, new regression, GPU or AI-provider request is needed. API: spacr.hits.build_hit_list and HitList.filter/write_csv/to_markdown/to_html.", "scenes": [{"visual": "01b_hit_list_route_failure", "narration": "Hit List belongs under Regression. In this build, clicking Hits selects a page inside a hidden panel, so the list does not appear. This tutorial shows that limitation openly. The following window is an external companion, not evidence that the native shortcut has been repaired.", "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "01c_explicit_companion_not_native_route", "narration": "Extract the linked example, activate your spaCR environment, and run the bundled Hit List companion script. The labelled companion opens spaCR's existing Hit List widget without changing its calculations. Click Browse and select the extracted results folder. No regression is rerun, and Investigate integration is not connected here.", "hold_after": 0.7}, {"visual": "03_all_325_ranked_genes_not_discoveries", "narration": "The original example loads three hundred twenty-five genes. Double-click column boundaries if values are clipped. Read effect direction, raw P, corrected q and guide agreement separately. Missing confidence intervals are unavailable. These are standardized marginal effects; the exported observation-count zero is not the true number of supporting wells.", "hold_after": 0.7}, {"visual": "04_no_genes_pass_q_point05", "narration": "Set Max q to zero point zero five. No genes remain because the smallest gene q-value is about zero point two seven one. An empty filtered table is not an import failure. Restore Max q to one to recover all candidates; this does not declare them discoveries.", "hold_after": 0.7}, {"visual": "06_at_least_two_tested_guides", "narration": "Minimum guides two keeps one hundred seventeen genes with at least two tested guide rows. This counts available evidence, not every guide originally designed for a library. The filter changes the displayed subset without recomputing the original multiple-testing correction.", "hold_after": 0.7}, {"visual": "07_all_tested_guides_same_sign", "narration": "Minimum agreement one additionally keeps fifty-seven genes whose tested guides all share the gene effect's sign. Agreement is not proof of significance or causality. The summary still reports zero significant corroborated genes, even though these candidate rows have agreeing guides.", "hold_after": 0.7}, {"visual": "08_hide_controls_not_recalculate_q", "narration": "Hide controls removes one control row, leaving fifty-six candidates in this subset. Restore it before the later export. Removing controls from view does not refit the model or change the correction family; retain their identities when interpreting your analysis.", "hold_after": 0.7}, {"visual": "10_positive_effect_magnitude_cut", "narration": "With the other filters cleared, Direction up shows positive effects. Adding a minimum absolute effect of zero point one leaves sixteen rows here. These are illustrative display choices, not recommended thresholds. Restore direction and effect controls before searching or comparing a different subset.", "hold_after": 0.7}, {"visual": "13_real_gene_returns", "narration": "Search a recorded identifier to inspect one real row. An unmatched query gives an empty table; returning to the known identifier restores it, and clearing search restores the population. This demonstrates reversible filtering. Annotation imports and the separate Investigate workflow require their own checks.", "hold_after": 0.7}, {"visual": "17_export_html_complete", "narration": "For export, restore two guides, full agreement, controls included and an empty search. All three exports contain the same fifty-seven candidates in this example. Markdown and HTML round numbers; CSV preserves numerical detail. Save the filter choices separately, because the files do not record every setting.", "hold_after": 0.7}, {"visual": "18_original_ranked_population_restored", "narration": "Clear the filters to recover all three hundred twenty-five genes. Keep exported subsets separate from unchanged originals and do not label nonsignificant candidates as validated hits. Python offers the same Hit List reader and filters, but check the format-specific row limits when exporting larger lists.", "related_lessons": ["06_api", "72_volcano_explorer"], "hold_after": 0.7}], "poster": "48_hit_list/poster.jpg", "silent": "48_hit_list/video/48_hit_list_silent.mp4"}, {"id": "49_methods_results", "number": 49, "slug": "methods_results", "title": "Methods & Results: build, review and export a draft", "series": 5, "app_key": "methods_export", "host_app_key": "regression", "section": "Regression", "description": "Open the nested reporting tool, build a digest from the real completed Regression example, identify three concrete review problems and preserve an explicitly unreviewed Markdown export.", "objectives": ["Find Methods & Results inside Regression and supply the correct completed-run sources.", "Distinguish recorded analysis facts from inferred defaults, exporter metadata and candidate wording.", "Copy the displayed sections and export an unchanged draft with its structured digest.", "Understand why successful export and AI number checks are not scientific approval."], "prerequisite": "Complete the downloaded-data Regression example first; keep its original project, run journal and guide_permutation results. This is a review-and-export lesson, NOT a scientifically approved manuscript or an application fix. The recorded run journal declares guide_permutation_seed=0 but no global random_seed; the draft separately resolves seed=42. These are not interchangeable generator identities, and the recording does not establish which global seed was applied. The original analysis environment records spaCR 1.5.0.4, while the new draft names exporter version 1.5.0.5; do not relabel the historic run. All 325 saved gene-family BH values were independently checked: no q<0.05 and minimum q=0.2708333333333333. Ten displayed candidates have matching effects/p/q, but the 'strongest hits' heading does not make them significant; not every guide count or scientific assumption is certified. The genuine Copy sections and Export Markdown actions preserve the original prose and exact digest; the new file is named UNREVIEWED_methods_results.md. All original and private input hashes remain unchanged. No provider is contacted, no regression is rerun, no manuscript is approved and nothing is published. API: spacr.methods_export.build_digest, render_methods and render_results. The earlier strict scientific-accuracy hold is preserved separately.", "scenes": [{"visual": "01_regression_methods_host", "narration": "Open Regression from Home, then its nested Methods and Results tool. This tutorial belongs under Regression in the submodule section. It uses the real completed example from the Regression lesson, not invented results. The goal here is to build, inspect and preserve a draft, not to approve a manuscript automatically.", "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "02_real_project_journal_and_result_sources", "narration": "Choose the project folder, the particular run journal, and that run's regression-results folder. Leave Classifier empty because this example is reporting a regression run, not a classifier checkpoint. Keep the original files unchanged. Matching names are not enough: confirm that the journal and results describe the same completed run.", "focus": [355, 270, 3450, 410], "hold_after": 0.7}, {"visual": "03_actual_deterministic_methods", "narration": "Click Build digest. Methods, Results, Caveats and Run digest are generated without contacting an AI provider. These sections are a starting point for review. In this recording the prose names the exporter's version, while the original run records a different analysis version. Report the version that actually produced the analysis.", "hold_after": 0.7}, {"visual": "04_actual_seed_caveat", "narration": "Read the caveats rather than treating a successful build as validation. Here the generic seed sentence says forty-two. The original journal explicitly declares the permutation seed as zero, but does not declare a global run seed. Do not replace every forty-two with zero: first distinguish the generators and their recorded provenance.", "focus": [355, 640, 3450, 760], "hold_after": 0.7}, {"visual": "05_digest_run_record", "narration": "The Run digest tab lets you inspect those structured records. Compare declared settings and the saved environment against the prose. A default inferred during export is not proof of historical execution. Preserve warnings and unresolved questions, including missing quality-control information; an absent report is not evidence that quality control passed.", "focus": [355, 680, 2400, 1120], "hold_after": 0.7}, {"visual": "06_zero_significant_genes_and_ranked_candidates", "narration": "The saved gene table contains three hundred twenty-five tests and none is significant at a q-value threshold of zero point zero five. Its smallest q-value is about zero point two seven. The heading strongest hits is therefore misleading here: these are ranked candidates, not discoveries. Check the complete corrected family, not only attractive top rows.", "focus": [355, 680, 3450, 700], "hold_after": 0.7}, {"visual": "07_copy_sections_is_not_scientific_approval", "narration": "Copy sections copies the displayed Methods and Results together. It does not correct their wording, certify their numbers or include the structured appendix. Preserve an unedited copy before making separately documented revisions. Resolve the seed, version and candidate-language issues with the source records before using this text in a report.", "hold_after": 0.7}, {"visual": "08_export_unreviewed_markdown_picker", "narration": "Export Markdown saves both sections and the run digest as an appendix. Choose a new filename; here it is explicitly labelled unreviewed. The genuine Save action creates the file, and our check confirms that its prose and structured digest match the screen. Successful file export is not scientific approval.", "focus": [1550, 780, 760, 540], "hold_after": 0.7}, {"visual": "09_actual_export_completed_not_approved", "narration": "Draft with AI is optional and is not used in this recording. It sends the digest to the configured provider; review its contents and privacy first. A number check cannot decide whether a sentence means the right thing. Python offers build_digest, render_methods and render_results for the same reporting workflow, with the same need for review.", "focus": [355, 560, 3450, 660], "related_lessons": ["06_api", "13_regression"], "hold_after": 0.7}], "poster": "49_methods_results/poster.jpg", "silent": "49_methods_results/video/49_methods_results_silent.mp4"}, {"id": "50_run_compare", "number": 50, "slug": "run_compare", "title": "Run Compare: inspect two real Measure snapshots", "series": 5, "app_key": "run_compare", "section": "Data", "example_files": ["Run_Compare_real_snapshots.zip"], "description": "Compare two preserved real Measure outputs, inspect equal settings and counts, and distinguish missing results from a negative scientific finding.", "objectives": ["Open Run Compare from the Home Data section and prepare the downloadable real-snapshot example.", "Compare distinct historical runs without changing their recorded versions or settings.", "Read settings, object counts and missing-result warnings without overstating the evidence."], "prerequisite": "Use Run_Compare_real_snapshots.zip and its README. In a spaCR environment run the included prepare_run_compare_download.py with a NEW destination folder, then Browse to that folder. This explicit helper transports only two selected, unchanged measurements databases and their historical artifact rows; it is not a GUI importer, new analysis or full project archive. The original full SHA-256 fingerprints match. Only project/path and a relocation note change: run IDs, artifact IDs, settings, versions and timestamps are retained. Runs d86c136e7261 and caa0bf7ca2ce were actually produced by spaCR 1.5.0.5 on 2026-09-11 at 03:37:56 and 04:05:56 UTC. Both contain 601 cells, 622 nuclei, 373 pathogen objects, 601 cytoplasm objects and 601 png_list rows across one plate, four wells and sixteen fields; all object identities match. Recorded settings are equal. Database hashes differ; no full-feature equality, segmentation accuracy, improved model or biological significance is claimed. No regression result is included. API: spacr.run_compare.runs_in and compare_runs with spacr.artifacts.Registry. No GPU, AI provider or new analysis is used. Original data are unchanged; nothing is published.", "scenes": [{"visual": "01_home_data", "narration": "Open Home, choose Data, then Run Compare. This is a main module, not a tool nested inside Regression. It reads recorded outputs from two runs. Our example uses two real Measure snapshots from the downloaded-data workflow; it does not invent a change just to make the comparison look interesting.", "focus_modules": ["run_compare"], "related_lessons": ["08_measure", "40_run_history"], "hold_after": 0.7}, {"visual": "02_actual_empty_compare", "narration": "Download and extract the companion snapshot archive. In your spaCR environment, run its preparation script with a new destination folder, following the included readme. This explicitly relocates two unchanged databases and their historical records. It is not an automatic import button, a new analysis, or a complete copy of either original project.", "hold_after": 0.7}, {"visual": "03_actual_snapshot_project_picker", "narration": "Click Browse and select the prepared comparison folder. The helper preserves the original run identifiers, settings, versions, times and content hashes. Only the copied index's addresses and relocation note change. Keep original projects untouched; a historical run entry pointing at a database that has since been overwritten is not a preserved snapshot.", "hold_after": 0.7}, {"visual": "04_two_actual_runs_no_setting_change", "narration": "Choose the earlier Measure run as baseline A and the later run as B, then Compare. Both were produced by spaCR version one point five point zero point five. A newer viewer does not change that history. Here settings and counts match; this is a consistency demonstration, not evidence that a model improved.", "focus": [350, 235, 3450, 190], "hold_after": 0.7}, {"visual": "05_actual_unchanged_settings", "narration": "Enable Show unchanged settings to inspect the recorded values. The zero on the Settings tab means no differences, not that no settings were saved. Expand the entries and compare the values themselves. These two runs used identical recorded settings; this example therefore cannot show the effect of changing a parameter.", "focus": [350, 360, 2300, 1400], "hold_after": 0.7}, {"visual": "06_actual_equal_object_counts", "narration": "Counts shows six hundred one cells and six hundred twenty-two nuclei in each run, across sixteen fields and four wells. Delta is B minus A; every displayed delta is zero. The independent check also matched object identities. Equal totals alone would not prove that the same objects or all measured feature values were identical.", "focus": [350, 425, 1250, 720], "hold_after": 0.7}, {"visual": "07_actual_no_hit_list", "narration": "Hits says no regression results were registered. These snapshots contain measurements only, so there is no ranked hit comparison to display. This does not mean that a regression found no significant hits: no regression result is present here. Use the Regression and Run History tutorials to trace the required outputs.", "focus": [350, 405, 2400, 330], "related_lessons": ["13_regression", "40_run_history"], "hold_after": 0.7}, {"visual": "08_actual_same_run_warning", "narration": "Selecting the same run on both sides produces a warning. Read it rather than treating a comparison result as automatic validation. Return to two distinct runs and check their source, version and scope before drawing conclusions. A warning is a reason to investigate, not an instruction to force a result.", "focus": [350, 235, 3450, 220], "hold_after": 0.7}, {"visual": "09_actual_distinct_runs_restored", "narration": "The distinct pair is restored, and the original files remain unchanged. Run Compare is a read-and-compare workflow; it does not rerun Measure or need a GPU or AI provider. Python exposes runs_in and compare_runs for the same comparison. Preserve actual output snapshots and document their provenance before comparing your own runs.", "related_lessons": ["06_api", "08_measure"], "hold_after": 0.7}], "poster": "50_run_compare/poster.jpg", "silent": "50_run_compare/video/50_run_compare_silent.mp4"}, {"id": "51_control_charts", "number": 51, "slug": "control_charts", "series": 5, "app_key": "control_chart", "host_app_key": "qc_dashboard", "section": "Data", "title": "Control Charts: inspect a campaign with explicit controls and limits", "description": "Open the specialist tool inside QC, load a clearly synthetic thirty-plate campaign, check the selected control and baseline, and export independently verified chart points.", "objectives": ["Find Control Charts inside QC and load the supplied synthetic CSV.", "Distinguish well-level input rows from plate-level means and select exactly one control.", "Compare rule sets, change and restore the control and baseline, and read the resulting warnings.", "Export the actual points table without claiming an image export or biological validation."], "prerequisite": "The CSV at tools/tutorials/fixtures/control_chart_campaign.csv is entirely synthetic, adapted from the application's seeded test campaign: thirty fictitious plates, three wells per control type per plate, and a programmed upward drift after plate twenty. The dates are illustrative order labels, not acquisition records. This specialist panel currently has no Load test data button; no microscopy download, model, GPU analysis or AI request is used. The old two-plate recording was rejected because the application refused to estimate limits. The current narrow settings column clips long choices when closed; the real open dropdowns expose their full names. The optional Z-prime and re-estimation modes are not exercised here.", "scenes": [{"visual": "01_qc_host", "narration": "Open QC, then its Control Charts button. This specialist workflow charts repeated controls across a campaign. Our supplied CSV is explicitly synthetic, including the drift: it demonstrates the software, not an acquired experiment or a validated assay.", "hold_after": 0.7, "related_lessons": ["54_qc_dashboard"]}, {"visual": "03_load_synthetic_csv", "narration": "Choose Load table and open the example CSV. It contains two hundred and seventy well-level rows: thirty plates, each with three negative-control, three positive-control and three sample wells. The chart will show one selected-control mean per plate, not one point per cell.", "hold_after": 0.7, "focus": [1550, 790, 740, 510]}, {"visual": "05_negative_control_default_rules", "narration": "Check Plate, Run order, Measurement and Control column against the displayed names. Select only neg in Control is. This list allows multiple selections; leaving every level unselected charts all rows, so never assume that loading the file has already selected your intended control.", "hold_after": 0.7, "focus": [290, 460, 740, 700]}, {"visual": "05a_sigma_choices", "narration": "Open Sigma from to read its full choices. Auto chooses the subgroup estimator here because each plate has three selected wells. The limits use baseline within-plate variation, adjusted for the mean's sample size, rather than the standard deviation of the whole drifting series.", "hold_after": 0.7, "focus": [290, 980, 1760, 600]}, {"visual": "05b_rule_choices", "narration": "Rules offers the usual four, all eight, or Limits only. More rules also create more opportunities for false alarms. We choose Limits only to isolate the three-sigma rule; changing this dropdown recomputes the chart without a separate Run button.", "hold_after": 0.7, "focus": [290, 1160, 1900, 450]}, {"visual": "06_limits_only", "narration": "Baseline plates is twenty: P zero one through P twenty set the limits, which are applied to the remaining plates. Nine points, P twenty-two through P thirty, exceed the upper limit. The report and rule table identify them; these programmed signals are not biological discoveries.", "hold_after": 0.7, "focus": [1010, 450, 2790, 1600]}, {"visual": "07_positive_control", "narration": "Untick neg and select only pos. The chart now shows the other control's means and its own baseline limits, with no rule-one violations in this example. A quiet chart alone does not prove an assay is valid. Restore neg before continuing.", "hold_after": 0.7}, {"visual": "09_shorter_baseline", "narration": "Change Baseline plates to twelve and watch the centre and limits change, then restore twenty. The app requires at least eight baseline plates, but that minimum is not a recommendation. Plan and justify the baseline; do not tune it simply to remove unwanted alerts.", "hold_after": 0.7, "focus": [295, 1400, 2600, 375]}, {"visual": "11_actual_export_picker", "narration": "With the original control and twenty-plate baseline restored, choose Export points and save a separate CSV. It contains thirty rows with plate identity, order, mean, subgroup size and spread, limits, standardized distance, baseline membership and fired rules. This is not a chart-image or full-configuration export.", "hold_after": 0.7, "focus": [1550, 790, 740, 510]}, {"visual": "12_exported", "narration": "Every exported identity and numeric field was checked against the source CSV, including rule-one flags. The original input is unchanged. For scripted use, the control chart widget module exposes ControlChartSpec and control_chart; its result provides points_frame. Keep your input, settings and acquisition notes together when investigating real alerts.", "hold_after": 0.7, "related_lessons": ["06_api", "54_qc_dashboard"]}], "poster": "51_control_charts/poster.jpg", "silent": "51_control_charts/video/51_control_charts_silent.mp4"}, {"id": "52_pipeline_graph", "number": 52, "slug": "pipeline_graph", "series": 5, "app_key": "pipeline_graph", "section": "Explore", "title": "Pipeline Graph: inspect real provenance and missing artifacts", "description": "Read actual artifact records, distinguish missing files from missing provenance, filter the graph and copy its full Graphviz representation without rerunning analysis.", "objectives": ["Open Pipeline graph under Help and choose an existing project.", "Compare recorded provenance with actual file presence and understand unrecorded dependencies.", "Use Current, Stale and Missing filters without mistaking hidden nodes for absent records.", "Redraw safely and copy the full graph, then use the appropriate workflow to investigate."], "prerequisite": "Use the real External Masks project and the completed Data Manager cleanup demonstration. This recording reads a byte-verified copy of that archived, post-cleanup snapshot at the historical project path inside an isolated namespace; original data and registry records are not rewritten. A separate real Batch Runner conversion illustrates absent provenance, not an unprocessed experiment. All 131 original project files, 26 archive files and seven conversion files remain unchanged. Three historical project records have no recorded input edges; the archive's fourth record belongs to another project path. No deletion, analysis, dedicated download, live image preview, Plot control, AI request or recovery run occurs here.", "scenes": [{"visual": "01_help_pipeline_graph", "narration": "Open Help, then Pipeline graph. This screen inspects recorded outputs and their dependencies; it does not execute the pipeline. We use acquired-data outputs from External Masks and the genuine Data Manager cleanup example, on private copies. Follow those lessons for producing and safely managing the data.", "hold_after": 0.7, "related_lessons": ["31_external_masks", "44_data_manager"]}, {"visual": "04_unregistered_is_not_unprocessed", "narration": "Browse to the converted-image folder first. Its Batch Runner conversion completed, but no artifact output was registered here, so this graph is empty. That is missing provenance, not proof that no processing happened. Declared order describes possible module dependencies; it is not a history of completed runs.", "hold_after": 0.7, "focus": [345, 230, 3450, 360], "related_lessons": ["37_batch", "40_run_history"]}, {"visual": "06_three_actual_artifacts", "narration": "Choose the measured project's post-cleanup snapshot. Three historical records appear: a measurement database, crops and a resource log. Two paths still exist, while the cropped-image folder really was removed in the earlier private cleanup. This recording removes nothing, and the original experimental project remains intact.", "hold_after": 0.7, "focus": [345, 235, 500, 470]}, {"visual": "07_measurement_provenance", "narration": "Click the measurement-database box and widen the details with the divider. Read its path, role, run identifier, production time, spaCR version and settings digest. A digest is a fingerprint, not the full settings or a restore button. Current does not establish scientific validity or complete provenance.", "hold_after": 0.7, "focus": [1940, 360, 1870, 345]}, {"visual": "08_missing_crop_provenance", "narration": "Select the red crops box. Missing means its registered path is absent. Its recorded size still says about three point four megabytes in one hundred four files: one hundred three crop images and their format record. That is historical size, not disk usage now, and not one hundred four cells.", "hold_after": 0.7, "focus": [1940, 360, 1870, 345]}, {"visual": "09_external_resource_log", "narration": "The resource log is a separate artifact outside the project folder. Its path still exists, but it was not moved into the archive. This graph has no recorded input edges. Nothing was derived from this means no downstream dependency was recorded here, not that the scientific outputs were independent.", "hold_after": 0.7, "focus": [1940, 360, 1870, 345]}, {"visual": "11_missing_detail", "narration": "Turn off Current to isolate the missing crop artifact. Current, Stale and Missing are display filters, not operations on the files. Stale is a recorded-provenance warning; this example contains no stale artifact. There are no separate module, artifact-type or workflow-branch filters in this screen.", "hold_after": 0.7, "focus": [345, 235, 3450, 470]}, {"visual": "12_no_visible_artifacts", "narration": "Turn off Missing too. No boxes remain, although the banner still reports one missing artifact out of three. In this build, the empty canvas incorrectly says nothing is registered, and the previous detail can remain visible. Check the filters before interpreting either message; hidden is not deleted.", "hold_after": 0.7, "focus": [345, 235, 3450, 470]}, {"visual": "13_copy_full_graph_not_filtered_view", "narration": "Copy Graphviz puts the full graph on the clipboard, including hidden nodes. We checked that all three actual artifact identifiers are present and no dependency arrows were invented. This is Graphviz DOT text for use elsewhere, not a saved image or an export of only the visible selection.", "hold_after": 0.7, "focus": [345, 230, 3450, 200]}, {"visual": "15_restore_all_nodes", "narration": "Restore Current, then Missing: two boxes return, then all three. Choose a box again to align its detail with the visible graph. Display filters do not repair missing files, change provenance or select a module to rerun. Investigate the actual recorded path and upstream workflow before taking action.", "hold_after": 0.7, "focus": [345, 235, 500, 470]}, {"visual": "16_redrawn_unchanged_graph", "narration": "Redraw rereads the registry and checks the artifacts again. Our records and file bytes remain unchanged. Use Run History for saved settings and journals, or Data Manager for explicit cleanup. In Python, spacr.pipeline_graph provides build_graph and to_dot. No regeneration or scientific validation is performed by this inspection.", "hold_after": 0.7, "related_lessons": ["06_api", "40_run_history", "44_data_manager", "45_project_browser"]}], "poster": "52_pipeline_graph/poster.jpg", "silent": "52_pipeline_graph/video/52_pipeline_graph_silent.mp4"}, {"id": "53_prediction_profiler", "number": 53, "slug": "prediction_profiler", "title": "Prediction Profiler", "series": 5, "app_key": "profiler", "section": "Explore", "description": "Import a fitted synthetic model, sweep one input, and verify how held values and plotting choices affect its displayed predictions.", "objectives": ["Open Prediction Profiler inside Regression and import a suitable coefficient table.", "Distinguish model fitting, inverse link, assumed input ranges and plot resolution.", "Compare both inputs, move held values and restore the default midpoint."], "example_files": ["SYNTHETIC_profiler_example.zip"], "prerequisite": "Extract the supplied explicitly SYNTHETIC example into a new folder. It includes 121 constructed observations, a genuine statsmodels OLS fit saved as feature/coefficient CSV, its manifest and a reproducible preparation script. No biological or held-out validation claim is made. The native GUI imports only coefficients, including the Intercept; it does not fit the model or load these observations. Keep the identity link. The file route assumes a two-row 0..1 design and midpoint held values. Ranking uses the 5th/95th quantiles, hence 0.05..0.95 here; plotted curves span 0..1. All 338 recorded curve values and twelve ranking values were checked independently against the saved fitted coefficients. Permutation-test marginal effects are not interchangeable with a jointly fitted predictive model. API: spacr.profiler.from_coefficients, profile, sensitivity; ProfilerScreen.set_model/set_design accept an existing fitted model/design programmatically, but those are not file-picker controls. No confidence intervals, causal effects, publication or listening approval are claimed.", "scenes": [{"visual": "01_regression_host", "narration": "Open Regression, then Prediction Profiler in its nested tools. This lesson uses a clearly labelled synthetic teaching example, not biological screening results. We inspect a fitted model by moving one input while holding the other fixed. The profiler reads the model; it does not train another one.", "focus": [460, 45, 3340, 540], "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "03_explicit_synthetic_coefficients_picker", "narration": "Download and extract the accompanying example, then Browse to its synthetic OLS coefficients file. It contains an intercept and two fitted input coefficients. The archive also supplies the observations and preparation script. These coefficients came from an actual least-squares fit to constructed data, not invented regression output.", "focus": [890, 390, 1920, 1080], "hold_after": 0.7}, {"visual": "05_link_options_keep_identity", "narration": "Keep Link at identity because this example was fitted by ordinary least squares. Other links belong to different model families; changing this selector does not convert or retrain your original model. A plausible curve on the wrong response scale is still wrong. Always use the link from the fit.", "focus": [2910, 465, 900, 610], "hold_after": 0.7}, {"visual": "04_loaded_identity_model", "narration": "Read the status message: no design matrix was supplied, so the file route assumes every input ranges from zero to one. Our synthetic inputs have that range, but yours may not. The ranking uses the fifth and ninety-fifth percentiles; its Moves by value is not the full plotted endpoint difference.", "focus": [470, 530, 3320, 240], "hold_after": 0.7}, {"visual": "06_hold_b_at_one", "narration": "Input A is selected for the sweep. Move the Input B slider from its midpoint to one. The predicted response shifts downward because B has a negative fitted coefficient. This changes the held scenario, not the training data or coefficients. Read the numeric endpoints as well as the line's shape.", "focus": [1480, 590, 2320, 1440], "hold_after": 0.7}, {"visual": "07_hold_b_at_zero", "narration": "Move B to zero and compare again. The response shifts upward. The plot rescales its vertical axis, so parallel-looking lines can represent different response levels. These are predictions within one assumed model, not evidence that changing B would cause an experimental effect.", "focus": [1480, 590, 2320, 1440], "hold_after": 0.7}, {"visual": "08_reset_midpoints", "narration": "Reset held values returns the sliders to the midpoint of the assumed ranges, one half here. It does not refit the model. For this file-only route, the midpoint is not a median measured from your original dataset: that dataset was never loaded into the profiler.", "focus": [1470, 1435, 2330, 660], "hold_after": 0.7}, {"visual": "09_sweep_second_input", "narration": "Select Input B in the ranked list. Now B is swept across the horizontal axis and A is held at one half. The descending curve matches B's negative coefficient. The list is a model-sensitivity ranking, not a significance test, a confidence interval or a list of validated biological hits.", "focus": [470, 590, 3330, 940], "hold_after": 0.7}, {"visual": "10_eleven_grid_points", "narration": "Change Points from sixty-one to eleven. This chooses how many positions are evaluated for the plotted curve; it does not change the sample size or fit quality. Our linear example keeps the same endpoints. More plotting points cannot add observations, reduce uncertainty or improve an already fitted model.", "focus": [1480, 465, 2320, 1040], "hold_after": 0.7}, {"visual": "11_hold_a_at_one", "narration": "With B still selected, move A to one and inspect the new response endpoints, then reset when finished. For your own work, supply coefficients from a suitable fitted model and check its link, intercept, encoding and ranges. Do not substitute separate permutation-test effects for a jointly fitted predictive model.", "focus": [1480, 590, 2320, 1490], "related_lessons": ["06_api", "75_regression_diagnostics"], "hold_after": 0.7}], "host_app_key": "regression", "poster": "53_prediction_profiler/poster.jpg", "silent": "53_prediction_profiler/video/53_prediction_profiler_silent.mp4"}, {"id": "54_qc_dashboard", "number": 54, "slug": "qc_dashboard", "series": 5, "app_key": "qc_dashboard", "section": "Data", "title": "QC: read the evidence, not just the headline", "description": "Read genuine downloaded and computed quality reports, distinguish missing checks from warnings and failures, and find the three nested QC tools.", "objectives": ["Find QC and its nested tools.", "Select the exact project or bounded-run folder and inspect all five evidence categories.", "Distinguish missing, warning and failure results without assuming a dashboard validates an entire analysis.", "Refresh existing evidence without recomputing or changing the source files."], "prerequisite": "Download the Annotate and Mask examples first. This recording reuses Annotate's measurement database, the original Mask example scorecards, and the genuine two-field Mask/one-field Measure tutorial run in plate1/test. QC itself downloads nothing and performs no new scoring. The parent and test folders represent different evidence scopes, not a before/after improvement experiment.", "scenes": [{"visual": "01_module", "narration": "Open QC in Home's Data category. This dashboard reads quality reports already on disk. It does not generate masks, measure images or train a classifier. The headline summarises available evidence; it is not a certificate that an entire analysis is correct.", "hold_after": 0.7}, {"visual": "02_fold_layer_viewer", "narration": "The header groups Layer Viewer, Control Charts and Outliers under QC. Their specialist lessons remain in the Submodules section beneath this parent. Use those tools to investigate an observation, not to replace missing evidence with a reassuring dashboard colour.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["57_layer_viewer", "51_control_charts", "66_outliers"]}, {"visual": "03_missing_reports_picker", "narration": "Use Browse to select the actual project folder. We first open Annotate's downloaded example, which contains measurements but no segmentation scorecards in this folder. QC has no separate example downloader; reuse the real project from the earlier workflow.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "03_missing_reports", "narration": "Missing means the reader has no usable report for that check. It is neither a pass nor proof that a check failed. A calculation performed in another view may not have saved a report this dashboard can read. Always inspect the named source and scope.", "hold_after": 0.7}, {"visual": "04_computed_subset_picker", "narration": "Now choose the test subfolder containing our genuine bounded Mask and Measure outputs. Selecting the parent folder is not equivalent. These are different populations and artifacts, so their verdicts must not be presented as a controlled before-and-after comparison.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure"]}, {"visual": "04_computed_subset", "narration": "The subset reports a segmentation warning: one cell field has a heterogeneous size distribution. Read the guidance and inspect the images. A size-based flag does not establish two biological cell types or prove that every object boundary is wrong.", "hold_after": 0.7, "focus": [450, 450, 3000, 275], "related_lessons": ["14_make_masks", "57_layer_viewer"]}, {"visual": "05_subset_remaining_checks", "narration": "The units card reports internal consistency across four measurement tables. That is narrower than independently validating calibration or every feature. Leakage, plate effects and annotator agreement still lack reports here; the green units card does not make those missing checks pass.", "hold_after": 0.7}, {"visual": "05_subset_remaining_checks", "narration": "Read all five categories, including the guidance below missing cards. Retain the original reports and investigate the relevant workflow. In particular, a leakage verdict depends on correct sample identities and grouping; a software pass alone cannot establish biological independence.", "hold_after": 0.7, "related_lessons": ["41_classify", "23_agreement", "33_plate_viewer"]}, {"visual": "07_original_plate_details", "narration": "The downloaded full-plate scorecards show failures as well as warnings. The headline names a low-count pathogen field, and the detail lists other flags. These are existing reports from the broader example, not new scores computed by opening QC or evidence that our smaller run improved the plate.", "hold_after": 0.7, "focus": [450, 400, 2950, 240]}, {"visual": "08_unchanged_refresh", "narration": "Press Refresh after reviewing the source. Here the status says nothing on disk has changed, so the existing evidence is reused. Refresh is not Run: it neither rescored the masks nor repaired a warning. Our database and report hashes remain unchanged.", "hold_after": 0.7, "focus": [450, 2070, 2950, 50]}, {"visual": "08_unchanged_refresh", "narration": "An out-of-date label, when present, needs attention to the underlying report and its inputs. This dashboard is advisory and does not block a run. Its cards are explanatory text, not buttons that automatically open or repair every failing analysis.", "hold_after": 0.7}, {"visual": "08_unchanged_refresh", "narration": "For a scripted read, spacr.qt.widgets.qc_summary provides read_dashboard and format_dashboard. They assemble existing evidence rather than running new checks. Keep the source reports with the project, and return to the relevant analysis or specialist lesson for the investigation itself.", "hold_after": 0.7, "related_lessons": ["06_api", "57_layer_viewer", "51_control_charts", "66_outliers"]}], "poster": "54_qc_dashboard/poster.jpg", "silent": "54_qc_dashboard/video/54_qc_dashboard_silent.mp4"}, {"id": "55_image_scatter", "number": 55, "slug": "image_scatter", "series": 5, "app_key": "image_scatter", "host_app_key": "umap", "section": "Explore", "title": "Image Scatter: real measurements and the crop behind each point", "description": "Explore the Image Scatter submodule inside Image UMAP with real downloaded cell measurements, checked hover previews and an exact one-cell handoff to Annotate.", "objectives": ["Find Image Scatter inside Image UMAP and load the correct cell table.", "Inspect raw measurement pairs and understand missing or constant coordinates.", "Connect a plotted cell to its real crop without changing labels or source data."], "prerequisite": "Reuse the downloadable Annotate example, including its measurements database, cell crops and crop-format markers. This lesson uses a private byte-identical copy of 2,341 cells and all 2,341 source PNGs. The independent SQLite checks cover every source value, full-field cell identity and crop path; displayed coordinates and RGB thumbnail pixels are checked. These are cell-only crop mappings: nucleus/pathogen mappings are not validated. Inspecting an unusual point is not evidence of phenotype, infection, treatment or segmentation accuracy. No UMAP fit, training, GPU computation, file export or source label edit is performed. Image Scatter has no dedicated downloader, image-column picker, colour/grouping controls, axis transform, export control or AI console. Its Plot button loads the selected table; axis choices redraw it. The loader caps tables at 200,000 rows, which is not random sampling or proof that larger tables lose no information. Shared filtering is not established by this lesson. API: spacr.qt.screens.image_scatter.load_scatter_frame, ImageScatterScreen.set_frame and ScatterCanvas.point_position.", "scenes": [{"visual": "01_image_umap_host", "narration": "Open Image UMAP from Home, then choose Image Scatter. This nested view plots two existing measurements; it does not fit a UMAP embedding. We reuse the real downloadable Annotate example, with its measurements database and cell crops kept together. The Annotate tutorial shows where to obtain it.", "hold_after": 0.7, "related_lessons": ["09_annotate", "15_image_umap"]}, {"visual": "03_choose_real_measurements", "narration": "Choose Browse and open the copied measurements database. Keep the data folder and crop-format markers when moving a project, because a table alone does not contain the images. The displayed example uses private copies; the original measurements and crop pixels remain unchanged.", "hold_after": 0.7}, {"visual": "04_choose_cell_not_children", "narration": "Choose cell in the table selector, then Plot. Plot reads this table; it is not a segmentation or training job. Our example has two thousand three hundred forty-one cells with matching cell crops. Selecting a different table requires Plot again; a changed selector alone does not load its rows.", "hold_after": 0.7}, {"visual": "05_real_measurement_scatter", "narration": "Set x to cell_area and y to cell_channel_1_mean_intensity. Axis changes redraw the loaded rows immediately. These are raw measurements, not transformed embedding coordinates. The dots describe individual cells, not independent experimental replicates, and a pattern in this picture is not a statistical test.", "hold_after": 0.7, "related_lessons": ["62_feature_dictionary"], "focus": [410, 405, 3410, 120]}, {"visual": "06_genuine_large_cell_preview", "narration": "Rest the pointer on the far-right cell. Its crop appears beside the scatter, with the full plate, row, column, field and cell identity. This thumbnail is a saved crop, not the full microscope field or a new segmentation. Looking unusual does not by itself establish a phenotype.", "hold_after": 0.7, "focus": [3500, 490, 330, 390]}, {"visual": "08_cached_same_cell", "narration": "Move away from the canvas: the temporary preview clears. Return to the same point and the cached crop appears again without another decode. Hover is temporary image inspection, not an annotation or a persistent selection. No source labels are changed.", "hold_after": 0.7, "focus": [3500, 490, 330, 390]}, {"visual": "09_swapped_raw_axes", "narration": "Swap the two measurements between x and y. The same cell keeps its identity and crop even though its screen position changes. Choose meaningful axes rather than accepting the first numeric columns automatically; numeric identifiers and acquisition metadata are also offered in these selectors.", "hold_after": 0.7, "focus": [410, 405, 3410, 120]}, {"visual": "11_missing_texture_not_plotted", "narration": "Restore cell_area on x and choose cell_channel_0_homogeneity_distance_32 on y. Seven cells lack this measurement, so only two thousand three hundred thirty-four coordinate pairs can be drawn. The loaded row count still says two thousand three hundred forty-one. Missing values are not zeros, and hidden coordinates do not renumber object identities.", "hold_after": 0.7, "focus": [410, 405, 3410, 120]}, {"visual": "12_constant_axis_is_centred", "narration": "Choose measurement_ndim on y. Every row has the value two, so the points sit on a horizontal line. This is a constant metadata column, not biological agreement. Restore cell_channel_1_mean_intensity before inspecting another cell.", "hold_after": 0.7, "focus": [410, 405, 3410, 120]}, {"visual": "16_real_annotate_grid", "narration": "To inspect a clicked crop in Annotate, first open Annotate and load this same copied project. Return through Home, Image UMAP and its existing Image Scatter tab. The annotation page must know the correct project; a plot and an unrelated open dataset are not a valid handoff.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "17c_native_point_click_target", "narration": "Click the point itself, then switch to Annotate. Hover alone only previews the image. The click sends the exact cell key, together with the two axis names, to the annotation view. It does not automatically switch pages, assign a label or prove that the object is an outlier.", "hold_after": 0.7, "focus": [3500, 490, 330, 390]}, {"visual": "18_verified_clicked_cell_in_annotate", "narration": "Annotate now shows exactly the clicked cell, with the same saved crop. Inspect its image before deciding whether to annotate it; this demonstration leaves every label unchanged. Image Scatter has no dedicated plot or selection export. Use Database Browser for table exports, or the PCA tutorial for component analysis and its documented CSV outputs.", "hold_after": 0.7, "related_lessons": ["34_database", "60_pca", "09_annotate"], "focus": [410, 330, 550, 410]}], "poster": "55_image_scatter/poster.jpg", "silent": "55_image_scatter/video/55_image_scatter_silent.mp4"}, {"id": "56_lineage", "number": 56, "slug": "lineage", "series": 5, "app_key": "lineage", "host_app_key": "db_browser", "section": "Explore", "title": "Lineage: containment identities and verified parent crops", "description": "Inspect actual stored parent-child relationships, understand the display cap and distinguish a verified single-parent crop from the unsafe missing-child fallback.", "objectives": ["Find Lineage inside Database Browser and build the real containment tree.", "Distinguish complete counts, displayed families and typed object identities.", "Recognize the incorrect family-crop fallback and inspect only a verified parent.", "Use native crop zoom and distinguish the complete Python export from GUI controls."], "prerequisite": "Use the downloaded Annotate example with matching measurements and cell crops. The linked Graph Builder archive supplies the exact database but no images; the Lineage archive supplies the verified API CSV and review, not a replacement database. Do not use the current family-crop fallback to identify or label missing child images.", "example_files": ["Lineage_real_containment_review.zip", "Graph_Builder_real_measurements.zip"], "scenes": [{"visual": "02_database_host", "narration": "Find Database Browser under Help, then open its nested Lineage tool. Here lineage means stored containment: which objects belong inside which cells. It is not a cell-division history, genetic ancestry or a new segmentation. The surrounding database controls belong to the host module.", "hold_after": 0.7, "related_lessons": ["34_database"]}, {"visual": "04_choose_real_measurements", "narration": "Browse to measurements dot db from the real Annotate example and build the tree. This lesson uses an unchanged private copy. Widen the Object column and the divider if labels are cramped. Numeric labels repeat across fields and object types, so a number alone is not an identity.", "hold_after": 0.7}, {"visual": "05_full_counts_capped_tree_and_zero_orphans", "narration": "The complete source contains two thousand three hundred forty-one cells, two thousand six hundred eighty-two nuclei and two thousand one hundred seventy-eight objects in the pathogen table. Only two thousand parent families appear in the tree; three hundred forty-one are omitted from display, not deleted from the database.", "hold_after": 0.7}, {"visual": "06_one_nucleus_no_pathogen", "narration": "The summary says no cells have nothing inside, because a nucleus also counts as a child. That does not mean every cell contains a pathogen-table object: one thousand one hundred sixty-eight do not. No unattached children means every recorded parent exists, not that the segmentation is biologically correct.", "hold_after": 0.7}, {"visual": "07_cell_with_nucleus_and_pathogen", "narration": "Expand a parent to see its children. In this field, cell three contains nucleus five and pathogen one according to the stored links. These are typed object identities, not three interchangeable numbers. Selecting a child alone is different from selecting the whole family.", "hold_after": 0.7}, {"visual": "09_publish_three_typed_objects", "narration": "Select with contents publishes the parent and its children. Selecting the parent and a child together does not need a duplicate copy of that child. Published keys preserve field and object type, but the key column is hidden here. Publishing an identity does not prove that a matching crop exists.", "hold_after": 0.7}, {"visual": "11_large_family_not_biological_validation", "narration": "Large families deserve inspection, not automatic biological interpretation. This example includes one family with thirty-three objects in total. Containment may reflect segmentation errors or other acquisition issues. The tree reports saved relationships; it does not validate unusual counts as a discovery.", "hold_after": 0.7}, {"visual": "12_actual_header_sort_preserves_containment", "narration": "Clicking a header sorts the displayed families without changing their containment. The two-thousand-parent display limit still applies. We checked every displayed identity and parent edge as well as the full hierarchy. Do not confuse a reordered or truncated view with an edited measurement table.", "hold_after": 0.7}, {"visual": "13_real_open_annotate_prerequisite", "narration": "Open crops needs the Annotate screen, which supplies the image viewer. The actual message tells us to open Annotate first. A missing viewer is different from a missing image. Before requesting crops, load the matching example project in Annotate, not another run with coincidentally similar labels.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "16_real_downloaded_cell_crops", "narration": "The downloaded project provides real cell crops. The database-only archive linked here cannot supply those images by itself. We use the complete matching example and preserve every original crop. Opening the source does not train a classifier or establish new labels.", "hold_after": 0.7}, {"visual": "20_wrong_typed_children_are_unrelated_cell_crops", "narration": "There is a serious limitation in this build. Opening the three-object family displays cell three, then unrelated cell five and cell one crops instead of the requested nucleus and pathogen. The source has only cell crops. Reject this substitution: do not label those images as the missing children. This tutorial does not repair it.", "hold_after": 0.7}, {"visual": "22_verified_parent_only_real_cell_crop", "narration": "The verified alternative is narrower: return to Lineage and double-click the parent cell alone. Unlike Open crops, this sends only that parent, not its family. Annotate now shows exactly the requested cell crop. We checked its identity and original image bytes; no child-crop support is implied.", "hold_after": 0.7}, {"visual": "22a_zoom_parent_without_labelling", "narration": "Shift-click the parent thumbnail to enlarge its existing preview without assigning a class. Escape returns to the grid. This helps visual inspection but creates no extra image resolution. Use the correct gesture: an ordinary left click is an annotation action, not the zoom demonstrated here.", "hold_after": 0.7}, {"visual": "24_rebuild_preserves_full_containment", "narration": "Build tree refreshes the containment view. For Python, read_object_tables, build_forest and lineage_frame expose the same structure. The linked CSV contains all seven thousand two hundred one nodes, including families omitted from display. It was written by the API, not a Lineage export button, and is not biological validation.", "hold_after": 0.7, "related_lessons": ["06_api"]}], "poster": "56_lineage/poster.jpg", "silent": "56_lineage/video/56_lineage_silent.mp4"}, {"id": "57_layer_viewer", "number": 57, "slug": "layer_viewer", "series": 5, "app_key": "layer_viewer", "section": "Explore", "title": "Layer Viewer: real image-mask overlays, display controls and source-safe inspection", "description": "Open Layer Viewer inside QC, inspect a genuine matched intensity image and cell mask, test visibility, opacity, blending and layer order, navigate in world coordinates and distinguish display changes from editing or calibrated measurements.", "objectives": ["Find the current QC submodule and load genuine matched image and mask files with its own controls.", "Use selected-layer visibility, opacity, blending, colour and order without changing source measurements.", "Recognize the pane-shape limitation of Fit and verify native zoom, pan and label picking.", "Distinguish empty auxiliary layers, absent export/drawing controls and unassigned field identity from supported API workflows."], "prerequisite": "Reuse the verified fov01 TIFF pair from the External Masks tutorial: a 1994×1994 uint16 intensity plane and aligned 44-object cell-label plane. They exactly match planes 1 and 4 of the preserved acquired plate1_E01_1_1 array, with 3,976,036 pixels and no physical calibration supplied. Neutral fov01 filenames are not acquisition metadata. Private copies and all originals remain byte-identical. Nineteen small oracle tests and observed-red mutations accompany independent checks of 5,041 actual screen pixels in each of 26 states, with zero RGB-byte discrepancy. Full source arrays, histogram-derived 2/98 contrast limits, layer properties and gesture geometry are also checked; this is not complete pixel-by-pixel validation of arbitrary layers, multichannel/3D data, soft coverage, biological segmentation accuracy or physical calibration. Fit can stretch the image to its pane. No pipeline, AI request, image editing, direct export, linked-view object handoff or Points/Shapes drawing was performed. This screen's controls differ from the other image previews.", "scenes": [{"visual": "01_qc_host", "narration": "Open QC from Home, then choose its nested Layer Viewer button. The QC project selector belongs to the parent dashboard; this viewer has its own image and mask buttons. We reuse the genuine, matched image and cell-mask pair from the External Masks tutorial on private copies. Layer Viewer has no dedicated test-data downloader.", "hold_after": 0.7, "related_lessons": ["31_external_masks", "54_qc_dashboard"]}, {"visual": "04_raw_image_in_wide_pane", "narration": "Choose plus Image and open the single-channel TIFF. The field is one thousand nine hundred ninety-four pixels square, with sixteen-bit intensity values. The display uses a two-to-ninety-eight percentile stretch: one hundred eighteen to twenty-three thousand two hundred twenty-three here. Bright displayed pixels do not mean the source values were overwritten or converted to eight-bit measurements.", "hold_after": 0.7}, {"visual": "05_fit_after_actual_splitter_resize", "narration": "In this build, Fit fills the canvas and can stretch a square field in a wide pane. Drag the actual divider until the image pane is approximately square, then choose Fit again. Do not infer physical shape from the distorted view. Our data use one pixel per world unit, not a calibrated micrometre spacing.", "hold_after": 0.7}, {"visual": "07_real_44_label_overlay", "narration": "Choose plus Mask and load the matching cell-label TIFF, not another intensity image. It contains forty-four nonzero object labels aligned to the same source field. Zero is background and is transparent in the overlay. The colours distinguish labels; they do not identify treatments, cell types or verified segmentation quality.", "hold_after": 0.7}, {"visual": "09_mask_visible_again", "narration": "Select mask in the layer list before adjusting its controls. The selected row determines which layer changes; adding a layer need not select it automatically. Use the mask's checkbox to hide and reveal it while inspecting the image underneath. Neither the labels nor the underlying intensity measurements change.", "hold_after": 0.7, "focus": [1970, 365, 1840, 100]}, {"visual": "10_opacity_zero_not_deleted", "narration": "Set the selected mask's Opacity to zero. Its coloured pixels disappear, but the mask remains in the layer list and its forty-four labels remain in memory. This is a display choice, not deletion, filtering or a correction to the segmentation. Keep the layer selection in view so you know what the slider controls.", "hold_after": 0.7, "focus": [1970, 1800, 1840, 250]}, {"visual": "11_full_label_colours", "narration": "Move mask Opacity to one hundred percent. The label colours now cover the underlying image wherever the mask has a nonzero label. Background stays transparent. This can help inspect the label shapes, but it hides the intensity texture beneath them. It does not turn labelled regions into new measurements.", "hold_after": 0.7}, {"visual": "12_half_opacity_restored", "narration": "Return mask Opacity to fifty percent with translucent blending. The image and label colour contribute to the visible overlay. Our independent checks compare real screen samples with the source image and labels; they do not establish that the segmentation is biologically correct. Use the raw image when judging boundaries.", "hold_after": 0.7}, {"visual": "13_blend_additive", "narration": "Open the blending menu and choose additive. Label colour is added to the image and values can saturate in the displayed composite. The source intensities remain unchanged. These are display operations, not intensity normalization for analysis. Select the intended layer before experimenting with the other blending choices.", "hold_after": 0.7}, {"visual": "15_blend_minimum", "narration": "The multiply and minimum modes produce different darkening effects. Multiply attenuates the image using the overlay colour; minimum mixes in the darker value in each colour channel. This scene shows minimum. Compare them on the same source field, but do not interpret a darker composite as a lower measured fluorescence intensity.", "hold_after": 0.7}, {"visual": "16_blend_opaque", "narration": "Choose opaque while keeping mask Opacity at fifty percent. For this binary coverage mask, it looks like translucent at the same opacity: opaque does not force the slider to one hundred. Its different treatment of soft coverage is not demonstrated by these integer labels. Restore translucent before continuing.", "hold_after": 0.7}, {"visual": "18_cyan_image_not_changed_measurements", "narration": "Select image, then choose cyan in the colour-map selector. The single-channel intensity image changes colour while the mask keeps its object colours. No measurement or biological channel identity changes. This screen has no channel selector or editable contrast range; do not promise those controls from a different preview. Restore gray afterward.", "hold_after": 0.7}, {"visual": "19_mask_under_image", "narration": "Select mask and use the down arrow to move it below the image. The list is top-first: the upper entry is drawn in front. The opaque image now hides the mask, even though the mask is still visible and its data remain intact. Move the mask up again before inspecting or picking its objects.", "hold_after": 0.7}, {"visual": "21_actual_label_no_field_identity", "narration": "Click a visible labelled region. The status reports its world position and label nine in this example. A bare mask loaded through this file picker has no assigned field key, so this click does not identify an experiment-wide object or open its crop elsewhere. Do not infer plate and well metadata from the neutral demonstration filename.", "hold_after": 0.7, "focus": [295, 1920, 3500, 165]}, {"visual": "22_native_wheel_zoom_keeps_world_anchor", "narration": "Roll the mouse wheel over the object to zoom. Three upward steps increase magnification by one point two cubed, keeping the same world coordinate under the pointer. The viewer redraws from the source layers at the new scale. Zoom changes your view, not the mask, pixel values or physical calibration.", "hold_after": 0.7}, {"visual": "23_native_pan", "narration": "Hold Shift and drag with the left mouse button to pan; the middle button is another pan gesture. Here we move the displayed field without changing its source coordinates. The tested gesture preserves the current zoom. Use panning to inspect another region rather than treating a shifted view as a shifted or registered image.", "hold_after": 0.7}, {"visual": "24_fit_restores_original_view", "narration": "Choose Fit to return to the full field in the current pane. This restores the pre-zoom view in our recording. Remember the pane-shape limitation: Fit does not independently guarantee equal horizontal and vertical display scale. Source spacing and the current canvas geometry are separate concepts; neither should be guessed from a screenshot.", "hold_after": 0.7}, {"visual": "25_empty_shapes_layer", "narration": "Plus Points and plus Shapes create empty auxiliary layers; this scene shows the empty shapes layer. They do not activate a drawing tool in this screen, and ordinary clicks did not add points or regions in our checks. Remove the empty layer when finished. For actual mask-editing gestures, use the Make Masks tutorial and its real editing controls.", "hold_after": 0.7, "related_lessons": ["14_make_masks"]}, {"visual": "28_remove_mask_only_from_view", "narration": "Select mask and choose the remove control. Only the layer leaves this view; the image remains and the source mask file is still unchanged. Removing a layer is not saving an edit or deleting a file. We verified both private TIFFs and the original acquired data stayed unchanged throughout this demonstration.", "hold_after": 0.7}, {"visual": "28_remove_mask_only_from_view", "narration": "For code, stack_from_paths in spaCR's Qt layer_viewer module loads the layers, and LayerStack.render_uint8 returns a composite image array for your export code. Spacing and FieldKey require known calibration and identity metadata. This screen has no dedicated export button, analysis run, GPU pipeline or spaCR AI console. Keep viewing separate from measurement and saved mask editing.", "hold_after": 0.7, "related_lessons": ["06_api", "14_make_masks", "31_external_masks"]}], "host_app_key": "qc_dashboard", "poster": "57_layer_viewer/poster.jpg", "silent": "57_layer_viewer/video/57_layer_viewer_silent.mp4"}, {"id": "58_graph_builder", "number": 58, "slug": "graph_builder", "series": 5, "app_key": "graph_builder", "section": "Explore", "title": "Graph Builder: real measurements, live filters and an explicit handoff limit", "description": "Drag actual measurement columns into graphs, split by acquisition metadata, filter reversibly and recognize the current annotation-selection defect.", "objectives": ["Load the real example database and choose the cell table.", "Build a histogram, scatter plot, colour grouping and row facets.", "Verify changing populations while filtering and restoring the chart.", "Distinguish internal brush publication from a working annotation handoff."], "prerequisite": "Download and unzip the linked real measurement database, or use the downloaded Annotate example. The archive contains measurements, not image crops; no new model run is needed.", "example_files": ["Graph_Builder_real_measurements.zip"], "scenes": [{"visual": "01_module", "narration": "Graph Builder explores an existing table. Open it from Home; this is a main module, with Plate Viewer and Small Multiples nested inside it. We will use actual example measurements, not train a model or ask an AI service to generate results.", "hold_after": 0.7}, {"visual": "03_choose_database", "narration": "Choose Load table and open measurements dot db from the linked archive or the downloaded Annotate example. Select the cell table: two thousand three hundred forty-one rows. The archive preserves the recorded database exactly. It does not include the images referenced by other tables.", "hold_after": 0.7, "related_lessons": ["09_annotate", "34_database"]}, {"visual": "05_area_histogram", "narration": "Search for cell_area and drag that column onto X. Automatic plotting makes a thirty-bin histogram. Each bar counts cell rows in an area interval; it is not a treatment comparison or a significance test. The values retain their stored units, without new physical calibration.", "hold_after": 0.7}, {"visual": "06_real_scatter", "narration": "Drag cell_channel_1_mean_intensity onto Y. Now each point represents a cell's area and channel-one mean intensity. Overlapping points can hide one another visually, although all rows are represented here. Inspect the row-count notice; larger datasets may use a different drawing policy.", "hold_after": 0.7}, {"visual": "07_well_column_colour", "narration": "Put columnID on Colour and read the legend. The colours distinguish acquisition columns, not inferred classes or known treatments. A visual separation is descriptive evidence to investigate, not proof of an effect. We checked the plotted coordinates and colour assignments against the source rows.", "hold_after": 0.7}, {"visual": "08_acquisition_row_facets", "narration": "Put rowID on the downward facet channel to split the chart into plate-row panels. Their counts are one thousand one hundred forty and one thousand two hundred one. Shared axes help comparison, but cells within a well are not independent experimental replicates.", "hold_after": 0.7}, {"visual": "09_live_area_filter", "narration": "In the right-hand filter panel, add cell_area and set its minimum to twenty-one thousand nine hundred twenty-five. The chart updates immediately to one thousand one hundred seventy-one rows. This rounded median illustrates the filter; it is not a recommended biological threshold. Notice that the axis limits also change.", "hold_after": 0.7}, {"visual": "10_filter_cleared", "narration": "Choose Clear all in the filter panel to restore all two thousand three hundred forty-one cells. This is different from Clear all channels on the left, which removes plot mappings. Recheck the count and axes after filtering; a changed population is not a new measurement.", "hold_after": 0.7}, {"visual": "11_actual_brush_state", "narration": "Remove the row facet with its small cross, then drag a rectangle on the scatter. This build has a defect: the recorded gesture publishes six hundred fifty-three object keys internally, but shows zero selected and leaves Open selection in Annotate disabled. Do not assume annotations were opened or created.", "hold_after": 0.7}, {"visual": "12_selection_cleared", "narration": "A plain click clears that internal selection too. The tutorial verifies this recovery but does not repair the handoff. Filtering and pointing at objects are different operations, and other views may share their state. Always check the active population rather than treating a graph as the full database automatically.", "hold_after": 0.7}, {"visual": "02_fold_trellis", "narration": "Use the header shortcuts for the nested Plate Viewer and Small Multiples workflows; their separate tutorials cover those tools. This screen has no chart or specification export button. The linked database archive is an external tutorial download, not a Graph Builder export.", "hold_after": 0.7, "related_lessons": ["33_plate_viewer", "63_small_multiples"]}, {"visual": "12_selection_cleared", "narration": "For Python work, read_table loads the data, GraphSpec describes plot channels and facets, and the selection API distinguishes filters from explicit object keys. Save the source, settings and version with your interpretation. These APIs neither validate a biological conclusion nor fix the annotation handoff.", "hold_after": 0.7, "related_lessons": ["06_api"]}], "poster": "58_graph_builder/poster.jpg", "silent": "58_graph_builder/video/58_graph_builder_silent.mp4"}, {"id": "59_anndata_export", "number": 59, "slug": "anndata_export", "title": "AnnData Export: current route and a verified API workaround", "series": 5, "app_key": "anndata_export", "host_app_key": "measure", "section": "Measure", "description": "Find the nested exporter, understand the observed missing-metadata failure, and export the real downloaded measurement example through an explicit, checked Python workaround.", "objectives": ["Find AnnData Export inside Measure and identify the source measurements database.", "Distinguish a failed GUI export from the verified API workaround without inventing missing metadata.", "Compare joined, cell-only and nucleus-only matrices and four missing-value policies.", "Reopen saved files and preserve object identities, annotations, source images and provenance."], "example_files": ["AnnData_API_workaround.zip"], "prerequisite": "Use the real downloaded measurement example from Annotate, retaining an untouched measurements.db and its source images. The recording uses spaCR 1.5.0.6 and AnnData in the same Python environment. Download the linked helper beside a COPY of measurements.db; it imports spacr.anndata_export.build_anndata. The unmodified GUI/API writer fails on entirely missing object-typed observation metadata, including unknown voxel calibration. A partial .h5ad is not a valid export. The helper explicitly encodes ONLY all-missing object metadata as empty pandas categoricals; it preserves missingness, does not invent calibration or labels, does not change X for this storage step, and does not repair the GUI. It writes a new destination, reloads and compares all values before accepting it; existing destinations are refused. Six exports were independently checked against SQLite: joined/keep 2341x1136 (400320 missing); cell/keep 2341x261 (28 missing); cell/mean 2341x261 (28 imputed); cell/drop_features 2341x257; cell/drop_objects 2334x261; nucleus/keep 2682x341 (1912 missing). No UMAP, GPU operation, image embedding, AI request, biological validation or publication is claimed. API: spacr.anndata_export.build_anndata and export_anndata. The original GUI failure remains preserved separately.", "scenes": [{"visual": "gui_02_current_anndata_form", "narration": "Open Measure, then its nested AnnData Export workflow. AnnData stores an object-by-feature matrix together with observation metadata and feature names. This lesson shows the current GUI route, but the demonstrated successful exports use an explicit Python workaround. We are not claiming that the GUI export defect is fixed.", "related_lessons": ["08_measure", "09_annotate"], "hold_after": 0.7}, {"visual": "gui_03_private_downloaded_project", "narration": "Use a copy of the real downloaded measurements database, not an invented table. Keep its images and original database unchanged. The GUI accepts the project folder; our command-line example takes the measurements database file itself. Disable the optional embedding for this export comparison. Exporting a matrix does not require a GPU.", "hold_after": 0.7}, {"visual": "api_01_unmodified_failure", "narration": "First observe the unmodified writer failing. Some observation columns contain only missing values with an object data type, which this writer cannot serialize. Unknown voxel calibration is one example. Exit status one and a partial file are not success. Do not replace unknown values with zero or the text None to silence the error.", "focus": [190, 1660, 3450, 340], "hold_after": 0.7}, {"visual": "api_02_explicit_workaround", "narration": "Download the linked helper and inspect its storage workaround. It uses the real build_anndata function, then encodes only entirely missing object metadata as empty categorical columns. Missing values remain missing; known metadata and the feature matrix are not changed by that encoding. This does not mean that physical calibration is a categorical scientific quantity.", "focus": [190, 80, 3450, 1400], "related_lessons": ["06_api"], "hold_after": 0.7}, {"visual": "api_03_joined_keep", "narration": "Run the helper with your source database, a new output path, and the keep policy. The joined example has two thousand three hundred forty-one cell rows and one thousand one hundred thirty-six features. Related nucleus and pathogen measurements are aggregated onto cells. Four hundred thousand three hundred twenty missing feature values remain missing, not zero.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_04_cell_keep", "narration": "For one object's own measurements, add single-table cell and keep the missing values. This file has the same two thousand three hundred forty-one cell rows but only two hundred sixty-one features. Twenty-eight feature values are missing. Compare feature names and row identities, not just file size or the number of columns.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_05_cell_mean", "narration": "The mean policy is a separate analytical choice, not part of the storage workaround. Here it fills twenty-eight missing feature values using the observed column means. The exported missing-value layer records their original positions. Check that imputation is appropriate for your analysis; a complete matrix is not automatically a better or unbiased dataset.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_06_cell_drop_features", "narration": "The drop-features policy removes columns containing missing values. In this example four columns are removed, leaving two hundred fifty-seven features and every cell row. Inspect which measurements were removed and why. This policy changes the feature set and can discard useful information; it is not a universal cleaning recommendation.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_07_cell_drop_objects", "narration": "The drop-objects policy instead removes rows containing missing feature values. Seven cells are removed here, leaving two thousand three hundred thirty-four rows and all two hundred sixty-one features. Missingness can be related to phenotype, acquisition or segmentation. Check what was excluded before treating the retained cells as representative.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_08_nucleus_keep", "narration": "Choose single-table nucleus for one row per nucleus, rather than aggregated nucleus features on cell rows. This example has two thousand six hundred eighty-two nuclei and three hundred forty-one features. Keep the parent links and object identities. More nuclei than cells does not mean that extra cells appeared during export.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_09_saved_shape", "narration": "Reopen each saved file. The helper compares the full matrix, ordered object and feature identities, missingness, and observation metadata; independent SQLite checks also passed for all six files. Annotations remain metadata, not training features inserted into the matrix. Images are not embedded, so retain the source files and their paths with the export.", "focus": [190, 80, 3450, 650], "hold_after": 0.7}, {"visual": "api_03_joined_keep", "narration": "Use a new output name for each policy and keep the script, settings and package versions. The helper refuses an existing destination instead of overwriting it. These checks establish data preservation for this example, not biological validity or a repaired GUI. Return to the linked API and measurement lessons for the surrounding workflow.", "focus": [190, 80, 3450, 650], "related_lessons": ["06_api", "08_measure"], "hold_after": 0.7}], "poster": "59_anndata_export/poster.jpg", "silent": "59_anndata_export/video/59_anndata_export_silent.mp4"}, {"id": "60_pca", "number": 60, "slug": "pca", "series": 5, "app_key": "pca", "host_app_key": "umap", "section": "Explore", "title": "PCA: real measurements, live refits and missing values", "description": "Explore the PCA submodule inside Image UMAP using genuine downloaded cells, checked component scores, reversible filters, explicit missing-value policies and three real CSV exports.", "objectives": ["Find PCA inside Image UMAP and choose an explicit measurement feature set.", "Read component variance and correlation arrows without claiming biological separation.", "Compare standardisation, live population refits and four missing-value policies.", "Export object scores, feature loadings and component variance while preserving the source."], "prerequisite": "Reuse a private byte-identical copy of the downloadable Annotate example: 2,341 cell rows, 276 source columns and four wells. This lesson fits cell_area, cell_channel_1_mean_intensity and cell_perimeter, then adds cell_channel_0_homogeneity_distance_32, which has seven genuinely missing values. The missingness mechanism and treatment identities are not established. Independent covariance eigendecomposition checks the application's small-table SVD, retained row positions, scores, loadings, correlations and variances; actual plotted coordinates and every exported source cell are checked. This is bounded to these full-rank, nondegenerate three- and four-feature fits, not a validation of all automatic features, arrow pixel geometry, rank-deficient inputs, image-linked brushing or biological conclusions. CPU NumPy PCA is separate from UMAP fitting and its GPU options. PCA has no dedicated test-data downloader, image preview, AI console or Run-level Plot switch. The three CSVs are not a fitted-model bundle, saved settings or exported figure. API: spacr.qt.widgets.pca_model.pca and PCASpec; PCAResult.scores_frame, loadings_frame and variance_frame.", "scenes": [{"visual": "01_image_umap_host", "narration": "Open Image UMAP from Home, then choose its nested PCA button. PCA is a linear summary of measurements, not another UMAP embedding. We reuse the downloadable Annotate example on a private copy. The Annotate tutorial shows where to obtain that real dataset.", "hold_after": 0.7, "related_lessons": ["09_annotate", "15_image_umap"]}, {"visual": "03_real_measurement_picker", "narration": "Use Load table beside the PCA heading and choose the copied measurements database, then cell. There are two thousand three hundred forty-one objects across four wells. This screen can also read a measurement CSV. A previously loaded host path is not proof that the intended table is open.", "hold_after": 0.7}, {"visual": "04_three_features_before_run", "narration": "Clear the feature search before choosing None, because that button unticks only the features currently shown. Search and tick cell_area, cell_channel_1_mean_intensity and cell_perimeter. Clear the search again, set Components to three, and choose Run PCA. Searching narrows the feature list, not the cell population.", "hold_after": 0.7, "related_lessons": ["62_feature_dictionary"], "focus": [300, 1490, 3350, 610]}, {"visual": "05_standardised_three_features", "narration": "Keep Standardise and read the scree plot. The first component explains about sixty-five point seven percent of these three features' standardised variance; the second explains thirty-one point seven percent. The points are individual measured cells, not independent experimental replicates. Explained variance is not classification accuracy.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "07_pc3_against_pc1", "narration": "Choose rowID in Colour, then PC three on X and PC one on Y. These controls redraw the existing decomposition without fitting again. The colours identify spatial rows, not established treatments. A separated-looking cloud is a prompt to investigate measurements and confounding, not proof of a biological effect.", "hold_after": 0.7, "focus": [1420, 335, 2220, 1600]}, {"visual": "09_biplot_restored", "narration": "Return to PC one and PC two. Toggle Loadings biplot off and back on. The arrows show feature correlations with these two components; their absolute length is scaled for display, with the dashed circle as a ruler. Nearby arrow directions do not establish causation.", "hold_after": 0.7, "focus": [1600, 500, 1660, 1070]}, {"visual": "11_raw_units_pca", "narration": "Change Scale to Centre only. The first component now explains about ninety point one percent, because the raw measurement scales change the analysis. That higher percentage does not make the model better. Restore Standardise before continuing; it centres each feature and divides by its sample standard deviation.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "13_live_filter_refits_basis", "narration": "In the right-hand filter, add cell_area and set the minimum to twenty-one thousand nine hundred twenty-five. The fit now uses one thousand one hundred seventy-one cells. This is a live refit: the population mean, scale and component directions change. It is not merely hiding points on the old axes.", "hold_after": 0.7, "focus": [3360, 325, 470, 620]}, {"visual": "14_clear_restores_full_basis", "narration": "Choose Clear all in the filter. All two thousand three hundred forty-one cells return, and the original decomposition is restored. Filtering never deletes database rows. Compare the population and report after every change; scores from separately fitted populations do not automatically share a common coordinate system.", "hold_after": 0.7, "focus": [1410, 1890, 2400, 225]}, {"visual": "15_missing_feature_ticked_not_run", "narration": "Now search for cell_channel_0_homogeneity_distance_32 and tick it. The existing result still contains three features until you choose Run PCA. This texture feature has seven genuinely missing values. We do not know why they are missing, so we must not call these cells uninfected or replace missing measurements with zero.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "16_auto_seven_rows_removed", "narration": "Run with Auto. All four features remain, but seven cells are removed, leaving two thousand three hundred thirty-four. Auto drops features missing in more than two percent of rows, then drops remaining incomplete rows. The three requested components capture about ninety-eight point six percent; a fourth direction still exists.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "18_drop_feature_keeps_objects", "narration": "Choose Drop features in NaN. All two thousand three hundred forty-one cells remain, but the texture feature is excluded from this fit. Four checkboxes can remain ticked while only three features are actually analysed. Read the result and dropped-feature notice, not just the requested selections.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "19_mean_imputes_seven_values", "narration": "Choose Mean-impute. All cells and all four features remain, with seven values replaced by that feature's mean for the calculation. These are invented values, not recovered measurements. The report states the replacement count. Disclose imputation whenever you present this result; the source database has not been rewritten.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "20_complete_cases", "narration": "Choose Complete cases. It keeps the four selected features and removes the same seven incomplete cells in this example. That agreement with Auto is specific to these data. Return to Auto, untick the texture feature, clear the search, choose Run PCA, and set Colour back to none.", "hold_after": 0.7, "focus": [300, 1490, 3350, 610]}, {"visual": "22_actual_three_file_export", "narration": "Choose Export and save a base name such as pca_example. The screen writes three CSV files: scores for each analysed object, loadings and correlations for each feature, and variance for each component. The scores file also retains the original measurement columns; it is not just three coordinate columns.", "hold_after": 0.7}, {"visual": "23_export_confirmation", "narration": "These exports preserve two thousand three hundred forty-one object rows and leave both databases unchanged. Record your feature list, filters, scaling and missing-value policy separately: this button does not save settings or a fitted-model bundle. For code, use pca and PCASpec in spaCR's Qt pca_model module. This CPU table view is separate from image previews, GPU analysis and spaCR AI.", "hold_after": 0.7, "related_lessons": ["06_api", "15_image_umap"]}], "poster": "60_pca/poster.jpg", "silent": "60_pca/video/60_pca_silent.mp4"}, {"id": "61_tabulate", "number": 61, "slug": "tabulate", "series": 5, "app_key": "tabulate", "section": "Explore", "title": "Tabulate: group real measurements, inspect counts and refresh the summary plot", "description": "Open Tabulate inside Database Browser, pivot downloaded measurements by well and field, inspect real missing values, export checked statistics and distinguish a live pivot from a stale or categorical chart.", "objectives": ["Find the nested Tabulate route and build well and field summaries with actual column drags.", "Read counts, missing combinations, sample standard deviations and quantiles without inventing independent replicates.", "Apply a live measurement filter, explicitly refresh its summary chart and distinguish categorical from numeric axes.", "Export the full checked pivot and keep a reproducible record of its grouping, statistics and filter."], "prerequisite": "Use the downloadable Annotate example on a byte-identical private copy of its measurements.db. The cell table contains 2,341 measured objects across four wells and 51 observed well/field combinations. These are not 2,341 independent experiments, and rowID is a spatial label, not an established treatment assignment. This lesson independently checks every demonstrated pivot statistic and CSV cell, plus all 51 final scatter-point ordinates. It does not validate biological effects, arbitrary missing axis labels, infinite values or capped large grids. Tabulate has no dedicated test-data downloader, image preview, GPU pipeline, AI console or run-level Plot switch; it summarizes existing data. Use its own Load table and Export CSV controls, not the surrounding Database Browser controls.", "scenes": [{"visual": "02_database_host", "narration": "Open Help, then Database browser, and choose the nested Tabulate button. This is a submodule of Database Browser, not a separate Home tile. We use the real downloadable Annotate example on a private copy. The earlier Annotate lesson shows how to obtain that dataset.", "hold_after": 0.7, "related_lessons": ["09_annotate", "34_database"]}, {"visual": "03_choose_real_measurements", "narration": "Inside Tabulate, choose Load table, open the private measurements database and select cell. The full table contains two thousand three hundred forty-one objects. The surrounding Database Browser has its own controls; those are not this pivot's input or export. Loading alone does not choose your grouping.", "hold_after": 0.7}, {"visual": "05_well_count_preset", "narration": "Choose Plate slash row slash column. The three keys appear in Rows in hierarchy order. Leave Values empty to count source rows: four wells contain six hundred fifteen, five hundred twenty-five, seven hundred and five hundred one objects. These counts are cells, not independent experimental replicates.", "hold_after": 0.7}, {"visual": "06b_blank_not_zero_tooltip", "narration": "Search for fieldID and drag it into Columns. Four wells by thirteen field labels gives fifty-two possible combinations, but only fifty-one contain measurements. Hover over the blank at row five, column two, field twenty. It means no source rows for that combination, not a measured value of zero.", "hold_after": 0.7, "focus": [985, 405, 2300, 260]}, {"visual": "08_area_mean_sample_sd", "narration": "Clear the Columns well, then search for cell_area and drag it into Values. The default statistics are count, mean and sample standard deviation. The table recomputes as you change the axes or statistics. The search box filters column names, not the cell population.", "hold_after": 0.7}, {"visual": "08b_read_full_cell_statistics", "narration": "In this build, the short table rows can hide the later lines, including n. Hover over a result cell to read its complete statistics and contributing count. Standard deviation describes variation among those objects; it is not uncertainty across independent wells. The popup rounds numbers for display.", "hold_after": 0.7, "focus": [985, 405, 1190, 450]}, {"visual": "09b_full_median_sem_quantile", "narration": "Turn on median, sem and quantile. At zero point seven five, quantile is the upper quartile, using linear interpolation. SEM is sample standard deviation divided by the square root of the available count. It does not correct for objects sharing a field or well, so do not treat it as independent biological uncertainty.", "hold_after": 0.7, "focus": [295, 410, 2050, 890]}, {"visual": "10b_half_quantile_tooltip", "narration": "Change Quantile at to zero point five. The quantile now matches the median: twenty-two thousand four hundred in the first well. The other statistics remain unchanged. Restore zero point seven five and turn the extra statistics off before returning to the simpler summary.", "hold_after": 0.7, "focus": [295, 410, 2050, 890]}, {"visual": "11b_source_count_vs_feature_n", "narration": "Replace area with the channel-zero homogeneity feature at distance thirty-two. It has seven genuinely missing values, leaving two thousand three hundred thirty-four available measurements. In this well, five hundred one source rows contribute only four hundred ninety-eight values. Count depends on the selected feature; missing measurements are not zeros.", "hold_after": 0.7, "focus": [295, 410, 1760, 890]}, {"visual": "13_all_well_statistics_picker", "narration": "Restore cell_area and choose Tabulate's Export CSV with a new filename. This well summary has four rows and six columns: three grouping keys, n, mean and standard deviation. We checked every exported value against the source. Keep the grouping, statistic and filter choices separately; the CSV is not a saved live specification.", "hold_after": 0.7}, {"visual": "14_four_group_means_not_2341_objects", "narration": "Choose Plot this table, then drag columnID onto X, mean onto Y and rowID onto Colour. The chart receives four summary rows, not thousands of individual cells. There is a trap: Automatic treats these four distinct means as categories and draws a heatmap. This is not a continuous-scale plot of their magnitudes.", "hold_after": 0.7, "related_lessons": ["58_graph_builder"], "focus": [295, 1300, 3340, 690]}, {"visual": "15_live_pivot_old_plot", "narration": "Use the right-hand filter to add cell_area and set its minimum to twenty-one thousand nine hundred twenty-five. The pivot immediately summarizes one thousand one hundred seventy-one remaining objects. The chart still contains the old summary until you press Plot this table again. A visible chart is not proof that it reflects the current filter.", "hold_after": 0.7}, {"visual": "16_plot_this_table_refreshes_summary", "narration": "Press Plot this table again to transfer the newly computed means. The chart now holds the four filtered groups, though Automatic still treats those means categorically. A note says the original area filter cannot apply directly to this summary table: it has mean, not cell_area. That does not mean the upstream pivot ignored the filter.", "hold_after": 0.7, "focus": [295, 1300, 3340, 690]}, {"visual": "19_replot_restores_original_summary", "narration": "Choose Clear all in the right-hand filter, then Plot this table again. The original two thousand three hundred forty-one objects and well means return. Filtering here does not delete source measurements. Export the filtered and unfiltered summaries under different names if both are needed.", "hold_after": 0.7, "focus": [295, 1300, 3340, 690]}, {"visual": "20_field_level_is_a_different_unit", "narration": "For a separate field-level view, drag fieldID into Rows after the well keys. There are fifty-two grid rows and fifty-one observed groups. The statistic now describes a field within a well, not the whole well. Fifteen to eighty-eight objects contribute to each observed group; adding groups does not create independent experiments.", "hold_after": 0.7}, {"visual": "21_actual_plot_choices", "narration": "Press Plot this table, put fieldID on X, keep mean on Y and rowID on Colour, then choose Scatter from Plot. With these fifty-one distinct field means, the actual column list identifies mean as continuous. Check the role and axis labels rather than assuming that a number is always treated numerically.", "hold_after": 0.7}, {"visual": "22_fifty_one_actual_field_means", "narration": "The chart now displays fifty-one real field means on a continuous vertical scale. Each plotted height was checked against the independently computed summary. Repeated field labels belong to different wells; colours show spatial row labels, not verified treatments. This grouped table has no object keys, so brushing cannot select individual images.", "hold_after": 0.7, "related_lessons": ["58_graph_builder", "09_annotate"], "focus": [295, 1300, 3340, 690]}, {"visual": "23_field_level_statistics_complete", "narration": "Export the field summary: fifty-two rows and seven columns, with one genuinely empty combination kept blank. The plotting hand-off omits that empty group, leaving fifty-one points. For reproducible code, pivot and PivotSpec in spacr's Qt pivot_spec module consume these choices, and to_csv writes the result. Preserve your source and record the exact grouping and filter.", "hold_after": 0.7, "related_lessons": ["06_api"]}], "host_app_key": "db_browser", "poster": "61_tabulate/poster.jpg", "silent": "61_tabulate/video/61_tabulate_silent.mp4"}, {"id": "62_feature_dictionary", "number": 62, "slug": "feature_dictionary", "series": 5, "app_key": "feature_dict", "section": "Help", "title": "Feature Dictionary: look up meanings, units and computing functions", "description": "Use the actual Help dictionary to find feature definitions, narrow them by concept and object, and distinguish general documentation from measurements available in a project.", "objectives": ["Find the dictionary under Help and search by idea or measurement name.", "Use the actual concept and object filters without changing project data.", "Read units, computing functions and caveats, including area versus volume.", "Copy definition text and distinguish this lookup panel from a project-specific Python export."], "prerequisite": "No project, download or model is required: this lesson browses the built-in definitions. No measurements, plots, AI requests, GPU jobs or file exports are performed. The example column names are present in the real measurements database used by Database Browser, but the dictionary does not load that database here. The actual panel currently lists hundreds of organelle role names; native scrolling exposes the computing functions and notes below them. Text is copied only inside the recording's private desktop clipboard.", "scenes": [{"visual": "01_help_dictionary", "narration": "Open Help, then Feature Dictionary. This is a lookup window for built-in measurement definitions, not a separate Home workflow or a pipeline to run. No dataset or model needs to be downloaded.", "hold_after": 0.7, "related_lessons": ["34_database"]}, {"visual": "03_search_by_idea", "narration": "Type an idea such as size. Results update as you type, and selecting Area displays its definition. The count describes matching definitions, not measured cells or columns confirmed to exist in your project.", "hold_after": 0.7, "focus": [420, 150, 3020, 550]}, {"visual": "04_actual_concept_object_filters", "narration": "The actual dropdowns filter by concept and object type. Here, intensity and cell return thirteen definitions. These filters narrow the dictionary, not your image data or analysis settings. Reset both to Any concept and Any object before another lookup.", "hold_after": 0.7, "focus": [420, 150, 3020, 450]}, {"visual": "05_measurement_name", "narration": "Search for cell channel one mean intensity, using the exact column name shown. The selected Mean intensity entry explains the pixel statistic and its units. Searching a name retrieves documentation; it does not inspect that column's values or prove it is available in the current project.", "hold_after": 0.7, "focus": [1620, 265, 1780, 355]}, {"visual": "06_computing_function", "narration": "Scroll down to Channel, Module and Computed by. The displayed reference identifies the measurement implementation, including the extended region-properties function. The dictionary looks up that definition; it does not recompute the measurement. The Python lookup APIs are in the feature dictionary module.", "hold_after": 0.7, "focus": [1630, 1650, 1760, 225], "related_lessons": ["06_api"]}, {"visual": "07_conditional_area_units", "narration": "Now look up cell area. Read the conditional Unit text: a two-dimensional run reports pixel area, while this same name represents volume in three dimensions. The row's measurement units determine whether that volume uses cubic image-pixel units or cubic micrometres. Do not infer physical units from the column name alone.", "hold_after": 0.7, "focus": [1620, 265, 1780, 380]}, {"visual": "08_area_caveats", "narration": "Read the Note as well as the headline definition. A three-dimensional value already expressed in physical units must not be converted a second time. For project-specific documentation, the Python describe database and export dictionary functions inspect the database and resolve its recorded measurement units; they are not buttons in this panel.", "hold_after": 0.7, "focus": [1630, 1520, 1760, 355], "related_lessons": ["06_api", "34_database"]}, {"visual": "09_unknown_search", "narration": "An unmatched query shows no definition. That means the dictionary found no match, not that your data cannot contain a custom feature. Return to a known name or a broader idea; do not treat missing documentation as a scientific result.", "hold_after": 0.7, "focus": [420, 150, 3020, 450]}, {"visual": "11_actual_text_copy", "narration": "Restore the Area entry, select its detail text and copy it. This recording verifies the actual copied selection. The GUI has no Run or Export action: copying text is different from creating a project-specific dictionary file through Python. Close the window when you are done; no analysis has been changed.", "hold_after": 0.7, "related_lessons": ["06_api", "34_database"]}], "poster": "62_feature_dictionary/poster.jpg", "silent": "62_feature_dictionary/video/62_feature_dictionary_silent.mp4"}, {"id": "63_small_multiples", "number": 63, "slug": "small_multiples", "series": 5, "app_key": "trellis", "section": "Explore", "title": "Small Multiples: real groups, live filters and honest scales", "description": "Open the nested Small Multiples view, compare genuine downloaded measurements on matched or independent scales, inspect real empty groups and capped wrapping, and create a reversible derived column.", "objectives": ["Find Small Multiples inside Graph Builder and build a real object-level scatter grid.", "Compare shared, free, per-row and per-column limits without confusing scale changes with data changes.", "Filter live, distinguish empty groups from unused wrap slots and account for omitted facet levels.", "Create and remove an in-memory rescaling, preserving the source and recording reproducible chart choices."], "prerequisite": "Use the downloadable Annotate example on a byte-identical private copy of measurements.db: 2,341 objects across four wells. The source includes 13 field labels and 51 observed well/field combinations. Object counts are not independent experimental replication, and spatial labels are not established treatments. All demonstrated continuous scatter-point coordinates, exact group memberships, axis limits, group titles and visible-versus-hidden panels are independently checked against source rows. The proof is bounded to finite, nondegenerate axes and this unsampled dataset; it does not validate arbitrary plots, linked-view brushing, biological effects or physical-unit calibration. Small Multiples is a table-only Graph Builder submodule, with no dedicated download, image preview, GPU pipeline, AI console, Run-level Plot switch or export button. Reuse Annotate's test data and its own Load table control.", "scenes": [{"visual": "01_graph_builder_host", "narration": "Open Graph Builder from Home, then choose its nested Small Multiples button. This is the current submodule route, not a separate Home tile. We reuse the genuine downloadable Annotate measurements on a private copy; the Annotate tutorial shows how to obtain that example.", "hold_after": 0.7, "related_lessons": ["09_annotate", "58_graph_builder"]}, {"visual": "03_choose_real_measurements", "narration": "Use Load table inside Small Multiples and select the private measurements database, then cell. It contains two thousand three hundred forty-one measured objects across four wells. The host Graph Builder has a separate Load table button. Use the one beside the Small Multiples heading for this workflow.", "hold_after": 0.7}, {"visual": "05_four_wells_shared_axes", "narration": "Search for cell_area and drag it onto X, then put cell_channel_1_mean_intensity on Y. Choose Scatter in Plot. Drag rowID onto Facet down and columnID onto Facet across. Search narrows the column list, not the cell population. Each plotted point here is an existing measured object.", "hold_after": 0.7, "focus": [300, 1720, 700, 390]}, {"visual": "05_four_wells_shared_axes", "narration": "With both scales shared, all four panels use the same horizontal and vertical limits. Their titles report six hundred fifteen, five hundred twenty-five, seven hundred and five hundred one objects. The row and column labels describe position, not verified treatments. These cells are not independent experimental replicates.", "hold_after": 0.7}, {"visual": "06_both_axes_free", "narration": "Set both X scale and Y scale to free. Each panel now uses its own range. This reveals within-group shape, but equally wide clouds need not span equal measurement values. Read the tick labels before comparing panels. Changing the scales does not alter any source measurements.", "hold_after": 0.7}, {"visual": "07_both_axes_row", "narration": "Choose per row for both scales. Panels on the same grid row now share limits, while different grid rows can differ. This is a layout-based scale group, not a statistical correction. Here the two columns within each row are directly comparable on their matched axes.", "hold_after": 0.7}, {"visual": "08_both_axes_col", "narration": "Choose per column for both scales. Panels in the same grid column now share limits. X and Y can also be configured separately; this demonstration changes both together. Restore shared for both before comparing all four wells. Shared means common within the current grid, not fixed across every later filter.", "hold_after": 0.7}, {"visual": "10_live_area_filter", "narration": "In the Filter tab, add cell_area and set its lower bound to twenty-one thousand nine hundred twenty-five. The actual grid updates immediately to one thousand one hundred seventy-one objects. The panel counts and points change together. This is a live measurement filter, not image segmentation or a new analysis run.", "hold_after": 0.7}, {"visual": "11_all_cells_restored", "narration": "Choose Clear all in the Filter tab. All two thousand three hundred forty-one objects return, with their original point positions and shared limits. This button clears the filter; Clear all channels on the left instead removes the chart assignments. Neither action deletes rows from the database.", "hold_after": 0.7}, {"visual": "12_real_empty_group", "narration": "To inspect a genuine missing group, filter columnID to c two and fieldID to f twenty and f twenty-one, scrolling the category list as needed. Put fieldID on Facet across and keep rowID on Facet down. One hundred seventy-four cells remain. The row-five, field-twenty panel has n equals zero: no source objects, not a measured zero intensity.", "hold_after": 0.7, "related_lessons": ["61_tabulate"]}, {"visual": "14_two_way_wrap_ignored", "narration": "Clear the filters and restore columnID on Facet across. Set Wrap at to five while both facet channels are assigned. The grid remains two by two, and the notice says wrapping is ignored. Wrapping applies when only one facet channel is in use; it does not rearrange a two-way grid.", "hold_after": 0.7}, {"visual": "15_twelve_fields_and_three_unused_slots", "narration": "Clear Facet down, put fieldID on Facet across and keep Wrap at five. The retained fields now form three rows, five slots wide. Only twelve field levels are drawn, although the source has thirteen. The three unused positions are hidden layout padding, unlike a real group displayed with n equals zero.", "hold_after": 0.7}, {"visual": "15_twelve_fields_and_three_unused_slots", "narration": "Read the notice below the grid. Field twenty-one falls outside the twelve displayed levels, excluding two hundred sixty-four source objects from the panels. Two thousand seventy-seven points are actually drawn, even though the loaded table still contains two thousand three hundred forty-one rows. A loaded-row count is not proof that every row is visible.", "hold_after": 0.7, "focus": [1000, 1460, 2150, 650]}, {"visual": "17_actual_area_formula", "narration": "Turn wrapping off and restore rowID and columnID as the two facets. In Columns, enter area_k as the name and cell_area divided by one thousand as the expression, exactly as shown. The preview checks the first two thousand rows. Choose Add column to compute the derived values for the full table, without rewriting the database.", "hold_after": 0.7, "focus": [3120, 315, 460, 940]}, {"visual": "18_rescaled_area_not_new_measurement", "narration": "Drag area_k onto X. Every horizontal coordinate is now the original cell area divided by one thousand; Y values and group membership remain unchanged. This is a numerical rescaling, not calibration to square micrometres, a new measurement or evidence of a biological effect. All two thousand three hundred forty-one derived values were checked.", "hold_after": 0.7}, {"visual": "19_formula_removed_original_points", "narration": "Put cell_area back on X before selecting area_k in Columns and choosing Remove. The original four-panel plot returns and the derived column disappears. Both the private database and the original downloaded data remain unchanged. Record your variables, grouping, filters and scale choices so someone else can reproduce the view.", "hold_after": 0.7}, {"visual": "19_formula_removed_original_points", "narration": "For code, trellis and TrellisSpec in spaCR's Qt trellis_spec module define the grouping, scales and wrap; GraphSpec defines the chart channels. This screen has no dedicated export button or downloadable dataset of its own. Use Tabulate for checked summary CSV exports. Image previews, GPU pipelines and spaCR AI belong to the relevant analysis lessons, not this table-only view.", "hold_after": 0.7, "related_lessons": ["06_api", "61_tabulate"]}], "host_app_key": "graph_builder", "poster": "63_small_multiples/poster.jpg", "silent": "63_small_multiples/video/63_small_multiples_silent.mp4"}, {"id": "64_gate_editor", "number": 64, "slug": "gate_editor", "series": 5, "app_key": "gate_editor", "section": "Tools", "title": "Gate Editor: real populations, reversible views and exact exports", "description": "Draw gates on downloaded cell measurements, verify saved membership, compare real three-dimensional and projected views, and inspect bounded clustering without inventing biological labels.", "objectives": ["Load real measurements and distinguish gates, view filters and visibility.", "Save and restore feature boundaries, then export membership with exact object identities.", "Explore three-dimensional bounds and principal components without confusing a projection with a reusable fitted transform.", "Compare actual cluster-search outcomes and use the local measurement console."], "prerequisite": "Download the Annotate example first, then make a private copy of its measurements database. Gate Editor has no separate example-download button. This recording uses all 2,341 real cell rows and modifies only that private copy when exporting; tutorial gate names are inspection labels, not biological ground truth.", "scenes": [{"visual": "01b_readable_panels", "narration": "Open Gate Editor in Home's Tools category. Drag the dividers to give the plot, gate table and side controls enough room. This lesson uses the downloaded Annotate measurements; Gate Editor does not have its own example-download button.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "02_real_database_picker", "narration": "Use Load table to open a private copy of measurements dot D B. Choose the cell table: this example contains two thousand three hundred and forty-one real objects. Export gates writes to a database, so keep the original example unchanged and work on the copy.", "hold_after": 0.7}, {"visual": "04_real_scatter", "narration": "Choose cell area for X and cell channel one mean intensity for Y, with the Rectangle tool. Each point represents a measured object. Inspect the feature names and units before drawing; an area-intensity region alone does not establish an infected cell or another biological class.", "hold_after": 0.7}, {"visual": "05_name_drawn_gate", "narration": "Drag across the scatter, release and enter a descriptive gate name. Our tutorial population is deliberately an inspection example. The shape records numerical boundaries in these two measurements; it is not a model trained to recognise cells from their images.", "hold_after": 0.7}, {"visual": "06_real_gate_and_counts", "narration": "This drawn region contains six hundred and fifty-five objects, about twenty-eight percent of the table. Read the count and percentages beside the gate name. Different mouse positions produce different boundaries and counts, so use the saved strategy when you need an exact repeat.", "hold_after": 0.7, "focus": [2420, 375, 820, 430]}, {"visual": "07_gate_hidden_not_deleted", "narration": "Unticking the gate hides its overlay without deleting its definition or changing membership. Tick it again to restore the view. This is different from Delete gate, and different from the Filter tab, which changes the objects displayed beneath the gates.", "hold_after": 0.7, "focus": [2420, 375, 820, 430]}, {"visual": "09_save_strategy", "narration": "Use Save gates to keep the named feature boundaries in a JSON strategy. Here we save, actually delete the gate, and then load the saved file. Reusing a strategy requires matching measurement names, units and preprocessing, not simply a table with the same number of columns.", "hold_after": 0.7}, {"visual": "12_strategy_restored", "narration": "Load gates restores the same boundaries and all six hundred and fifty-five members. We checked membership after actually deleting and reloading the gate, rather than merely saving a file. On another dataset, verify the restored boundaries and object identities before relying on its counts.", "hold_after": 0.7}, {"visual": "12b_save_graph", "narration": "Save graph writes the actual figure; this recording's preferences produce a PNG and a PDF. A figure is different from a gate strategy or exported membership. Keep the corresponding data and strategy when you need to reproduce how a displayed population was defined.", "hold_after": 0.7}, {"visual": "12c_exported_gate_membership", "narration": "Export gates writes membership flags to the private database's filters table. Our first gate marks exactly six hundred and fifty-five cell identities, matched by plate, row, column, field, object label and object type. The original download and underlying cell measurements remain unchanged.", "hold_after": 0.7}, {"visual": "14_second_gate_not_automatically_nested", "narration": "Draw a second shape while the first is selected. Its two hundred and fifty-nine objects include some outside the first: new drawing is not automatically nested, despite older status wording. Save this two-gate strategy separately and inspect any parent relationships explicitly when loading an existing hierarchy.", "hold_after": 0.7, "focus": [2420, 375, 820, 520]}, {"visual": "16_actual_three_dimensional_view", "narration": "Choose three D and cell perimeter for Z to inspect three actual measurements. The spin-axis buttons guide rotation. Rotating changes the view, not the saved boundaries of the two existing area-intensity gates; return to two D to inspect those shapes again.", "hold_after": 0.7}, {"visual": "17c_actual_volume_gate", "narration": "From view creates a named box with bounds on all three displayed measurements. Our full-volume example includes every loaded object: it demonstrates the control, not an enriched biological population. Save the three-gate strategy separately so the earlier two-gate file remains available.", "hold_after": 0.7}, {"visual": "18_actual_projection_2d", "narration": "The x D toggle computes principal components from eligible measurements. It is separate from the two D or three D view choice. Here the source label reports seventeen, thirteen and six percent explained variance for the first three components; these are variance fractions, not classification accuracy.", "hold_after": 0.7}, {"visual": "20_projection_off_keeps_columns", "narration": "Turning x D off retains the component columns; choose the raw axes again when returning to raw-feature gates. A saved gate strategy does not save the fitted projection. Component names alone do not make independently fitted projections compatible, so do not reuse their gate boundaries blindly.", "hold_after": 0.7}, {"visual": "21_bounded_walk_settings", "narration": "For Search, widen the side panel and remove the temporary gates after saving them. Use the same two raw features, scaling enabled, twenty minimum neighbours and five Walk steps. Run walk opens a confirmation in this build; check that its values match the visible controls.", "hold_after": 0.7}, {"visual": "22_walk_outcome", "narration": "The actual Walk selects a radius near zero point one six seven and reports two populations, with thirty-three percent of objects outside them. Inspect the resulting outlines. Density clustering and its saved polygon gates are exploratory descriptions, not validated cell types or proof that excluded objects are invalid.", "hold_after": 0.7}, {"visual": "25_fixed_radius_result", "narration": "Save the Walk strategy, remove its temporary gates, turn Walk off and run radius zero point five. This separate choice creates one larger polygon gate, containing two thousand two hundred and thirty-nine objects. It is not a better answer merely because it includes more cells.", "hold_after": 0.7}, {"visual": "28_live_area_filter", "narration": "Reload the saved two-gate raw-feature strategy, then add cell area in Filter. Setting the lower cutoff to twenty-one thousand nine hundred and twenty-five leaves one thousand one hundred and seventy-one displayed objects. This live preview narrows the view without rewriting the saved gate boundaries.", "hold_after": 0.7}, {"visual": "29_live_filter_cleared", "narration": "Clear the filter and all two thousand three hundred and forty-one objects return. Check both the active view filter and the gate definition before interpreting counts or exporting. Hiding an overlay, filtering a view and deleting a gate are three different operations.", "hold_after": 0.7}, {"visual": "31_real_console_answer", "narration": "Drag the far-right divider left to reveal the console. Enter len, open parenthesis, D F, close parenthesis: the real table returns two thousand three hundred and forty-one. The expression console works locally; it is not an answer generated by an artificial-intelligence model.", "hold_after": 0.7, "focus": [3090, 320, 740, 1795]}, {"visual": "32_chat_draft_not_sent", "narration": "The chat box is separate from expressions. We leave an unsent draft, without demonstrating an assistant or biological interpretation. In Python, GateSet from spacr.qt.widgets.gate_spec stores definitions; gate_mask_over_table and export_gate in spacr.filters evaluate and save full-table object flags. Verify the identities before downstream annotation.", "hold_after": 0.7, "focus": [3090, 320, 740, 1795], "related_lessons": ["06_api", "09_annotate"]}], "poster": "64_gate_editor/poster.jpg", "silent": "64_gate_editor/video/64_gate_editor_silent.mp4"}, {"id": "65_feature_explorer", "number": 65, "slug": "feature_explorer", "series": 5, "app_key": "feature_explorer", "section": "Explore", "title": "Feature Explorer: rank real measurements and keep the comparison explicit", "description": "Open the Classify submodule, compare real plate-row measurements, inspect distributions, filter live, add a computed column and export the intended ranking without training a classifier.", "objectives": ["Find Feature Explorer inside Classify and load existing cell measurements.", "Distinguish AUC from separation, and inspect class counts and distribution differences.", "Filter live without overlooking an automatic change of comparison column.", "Use Top deliberately, verify a scaled computed column and export the actual ranking."], "prerequisite": "Use the downloaded Annotate example, not invented measurements. The recording opens a byte-identical private copy of its 2,341-cell, 276-column measurement database. The two rowID groups are spatial plate rows r12 and r5, not asserted treatments; cells share fields and wells and are not independent experiments. Original data remain unchanged. AUC, KS, ranking order and finite class counts are independently checked for the intended two-class comparisons. The automatically selected eight-class comparison is a warning example, not independently validated inference. Shuffle test stays off. No classifier training, new image analysis, dedicated download, GPU operation or AI request occurs here; the displayed histograms are the module's own plots.", "scenes": [{"visual": "01_classify_host", "narration": "Open Classify, then its Feature Explorer button. This nested tool ranks existing measurements; opening it does not train a classifier. We use the real downloadable Annotate example on a private database copy. Follow the Annotate lesson to obtain the example, and keep your experimental source unchanged.", "hold_after": 0.7, "related_lessons": ["09_annotate"]}, {"visual": "04_real_row_comparison", "narration": "Choose Load table, select the measurement database and its cell table, then set Split by to rowID. There are two thousand three hundred forty-one cells and two hundred seventy-six columns. Our two groups are recorded plate rows, not established treatments; these cells are not independent experiments.", "hold_after": 0.7, "focus": [345, 280, 3460, 370]}, {"visual": "05_four_distributions", "narration": "Rank by AUC and read both numeric columns. Separation is the absolute value of twice AUC minus one, so about zero point three four separation is not a zero point three four AUC. Higher in names the direction; min n counts finite measurements in the smaller class, not replicate experiments.", "hold_after": 0.7, "focus": [345, 380, 950, 275]}, {"visual": "05_four_distributions", "narration": "Set Top to four to inspect four overlaid histograms. Classes share the same bin edges within each feature, and bar heights are counts. The largest ranking is not automatically a useful biomarker. Read the warning: AUC can miss differences in spread even when the distributions differ.", "hold_after": 0.7, "focus": [1290, 460, 1810, 1590]}, {"visual": "06_top_four_ranking_complete", "narration": "Export ranking with Top four writes four feature rows. In this build the export follows Top, despite wording that suggests the whole ranking. It does not export the underlying cells or save a trained model. We compared every exported value with the actual current ranking.", "hold_after": 0.7}, {"visual": "08_full_ranking_complete", "narration": "Set Top to five hundred before exporting all scored features in this example. Two hundred sixty-one features can be scored; two numeric candidates cannot. The export contains all two hundred sixty-one rows, while the display draws at most eight distributions. Feature counts, table rows and plotted panels are different quantities.", "hold_after": 0.7, "focus": [345, 375, 2760, 1650]}, {"visual": "09_ks_comparison", "narration": "Switch Rank by to KS to compare the largest gap between cumulative distributions, then return to AUC. KS can reveal distribution differences that AUC misses but does not provide direction itself. Other offered statistics have their own limitations; read the visible warning rather than treating a rank as a significance test.", "hold_after": 0.7, "focus": [345, 375, 2760, 400]}, {"visual": "10_live_area_filter", "narration": "In Filter, add cell_area and set the minimum to twenty-one thousand nine hundred twenty-five. The visible population changes to one thousand one hundred seventy-one cells, and two hundred fifty-five features remain scorable. This median-based demonstration threshold is not a biological quality cutoff. Rankings and distributions update without remeasuring images.", "hold_after": 0.7, "focus": [3105, 375, 355, 420]}, {"visual": "11_restore_all_cells", "narration": "Clear all removes the display filters, not the data. All two thousand three hundred forty-one cells and the original ranking return. Recheck the population and Split by whenever you change filters. A difference that changes after filtering describes a different selected population, not a new experiment.", "hold_after": 0.7}, {"visual": "12_one_row_changes_comparison", "narration": "There is an important trap in this build. Filtering rowID to r12 removes the other row, but the screen silently switches Split by to cell_channel_0_maxima_count. It now compares eight groups, with only one object in the smallest. Those impressive scores are not the original row comparison or evidence of a biological discovery.", "hold_after": 0.7, "focus": [345, 375, 3460, 400]}, {"visual": "13_restore_two_classes", "narration": "Clear the filter and explicitly choose rowID again. Clearing alone does not necessarily restore the original comparison. Verify both the class column and the population before exporting. Shuffle test offers fifty label shuffles, but we leave it off: freely shuffling these correlated cells would not establish well-level or treatment-level evidence.", "hold_after": 0.7, "focus": [345, 375, 3460, 275]}, {"visual": "14_scaled_area_formula", "narration": "Open Columns and name a new column area_k. Enter cell_area divided by one e three, meaning one thousand, and choose Add column with replacement off. This rescales area; it does not calibrate physical units or add a new measurement. Preview checks the first two thousand rows; adding applies the formula to the full table.", "hold_after": 0.7, "focus": [3105, 375, 355, 1030]}, {"visual": "16_ranking_with_derived_area_complete", "narration": "The scaled column joins the ranking and export, giving two hundred sixty-two scored features. Its AUC and KS equal those of cell_area because positive rescaling preserves order. We checked every computed value. Remove the formula to return to the original two hundred sixty-one features; the measurement database remains unchanged.", "hold_after": 0.7}, {"visual": "17_original_features_restored", "narration": "Use these rankings for descriptive exploration, not independent validation of a selected feature or a trained classifier. In Python, spacr.qt.widgets.feature_rank provides rank_features and ExplorerSpec. For inspecting raw tables or drawing other comparisons, continue with Database Browser and Graph Builder. No new image-analysis pipeline or AI request was run.", "hold_after": 0.7, "related_lessons": ["06_api", "34_database", "58_graph_builder"]}], "host_app_key": "classify_merged", "poster": "65_feature_explorer/poster.jpg", "silent": "65_feature_explorer/video/65_feature_explorer_silent.mp4"}, {"id": "66_outliers", "number": 66, "slug": "outliers", "series": 5, "app_key": "outliers", "section": "Explore", "title": "Outliers: inspect real flags without deleting observations", "description": "Open Outliers inside QC, compare robust rules on real cell measurements, distinguish unscored wells from clean wells, inspect an actual log-transform refusal and export every row with its flags.", "objectives": ["Find the QC submodule and select measured features deliberately before Scan.", "Compare MAD, IQR and explicit log transforms without treating flags as validated errors.", "Distinguish object counts, displayed rows and unscored well comparisons.", "Export original measurements with flags and recover safely from an invalid transform."], "prerequisite": "Use the downloadable Annotate example on a byte-identical private database copy. Its 2,341 cells occupy four recorded wells; they are not independent experiments or known defective objects. Original measurements are never edited or deleted. The lesson independently checks finite, nondegenerate single-feature MAD/IQR arithmetic, each object's flag position, well medians/counts and the explicit fewer-than-five-wells refusal. It does not validate the automatic all-feature scan, zero-scale fallback, multivariate MCD inference or biological quality. These are scans of an existing measurement table, not new image segmentation, GPU analysis or classifier training. This screen has no image preview, Plot toggle, dedicated test-data downloader or AI console; its Objects, Wells and Report tabs are the actual outputs.", "scenes": [{"visual": "02_qc_host", "narration": "Open QC from Home, then choose its Outliers button. QC's dashboard reads stored checks, while this nested tool computes flags from a measurement table. We use the real downloadable Annotate example on a private database copy. Follow that lesson to obtain the example and leave your experimental source unchanged.", "hold_after": 0.7, "related_lessons": ["09_annotate", "54_qc_dashboard"]}, {"visual": "04_automatic_all_features", "narration": "Choose Load table and the database's cell table. Loading automatically scans all selected continuous features: two hundred fifty-five here, over two thousand three hundred forty-one cells. This broad default flags two thousand three hundred thirty-eight objects. That does not prove nearly every cell is bad. Loading the wide result table can take time.", "hold_after": 0.7, "focus": [295, 345, 3515, 170]}, {"visual": "05_choose_one_feature_before_scan", "narration": "With the feature search empty, choose None to untick everything. Search for cell_area and tick only that exact feature, then press Scan. The search narrows feature names, not cell rows. Changing the selection does not automatically rescan: the old result can remain visible until you run the new rule.", "hold_after": 0.7, "focus": [3295, 455, 390, 1595]}, {"visual": "06_area_mad_3_5", "narration": "For MAD, leave the transform at none and k at three point five. The rule divides the absolute distance from the median by about one point four eight two six times the median absolute deviation. It flags twenty-six cells. These are candidates for inspection, not confirmed segmentation mistakes, and no row has been removed.", "hold_after": 0.7, "focus": [295, 455, 1510, 315]}, {"visual": "07_four_wells_not_scored", "narration": "Open Wells. All four wells contain over five hundred objects, but none is scored: the across-well comparison needs at least five eligible wells. Read well_scored and the specific reason, not just Wells zero. Flagged share summarizes object flags; it is not a well-level score or evidence that the well is clean.", "hold_after": 0.7, "focus": [295, 455, 3005, 300]}, {"visual": "08_area_report", "narration": "The Report gives the rule, measured centre, scale and caveats. One caveat in this build wrongly says these four wells had fewer than twenty objects. Their actual counts are five hundred one to seven hundred; the reason is too few wells. Use the specific well-table reason, and do not repeat the incorrect count explanation.", "hold_after": 0.7, "focus": [295, 455, 3005, 550]}, {"visual": "10_broad_rule_not_quality_cutoff", "narration": "A stricter distance requirement flags fewer objects. Lowering k to two produced one hundred forty-two flags; at zero point five it produces one thousand four hundred seventy-nine. That last setting is deliberately broad for demonstration, not a recommended quality cutoff. The object table displays only five hundred rows, so its row count is not the flag count.", "hold_after": 0.7, "focus": [3295, 1745, 390, 330]}, {"visual": "11_all_rows_not_display_cap_complete", "narration": "Choose Export and a new filename. The objects CSV keeps all two thousand three hundred forty-one rows and appends flags; flagged contains the one thousand four hundred seventy-nine flagged rows. Wells contains four summaries, and report is a text file. Every exported measurement and flag was checked. Export is not deletion, and it is not limited to the displayed five hundred rows.", "hold_after": 0.7, "focus": [295, 345, 3515, 170]}, {"visual": "13_area_iqr", "narration": "Restore the original rule, then choose IQR. The threshold now means c times the interquartile range, not robust standard deviations. With c at one point five, raw cell area gives fifty-five flags. We independently checked both quartile fences and every flagged position. A tail of a skewed distribution can be flagged even when its measurements are valid.", "hold_after": 0.7, "focus": [295, 455, 1510, 315]}, {"visual": "14_iqr_report", "narration": "There is another wording error to recognize. This IQR report labels twenty-two thousand six hundred sixty-three as the median, but that number is the midpoint of the first and third quartiles. The actual median is twenty-one thousand nine hundred twenty-five. The checked fences are correct; do not cite that displayed centre as the median.", "hold_after": 0.7, "focus": [295, 455, 3005, 550]}, {"visual": "16_log_area_mad", "narration": "Choose log10 explicitly and scan again. On these positive areas, IQR gives seventy-nine flags, while switching back to MAD at three point five gives thirty-six. Log transformation changes distances and the question being asked; it does not guarantee fewer flags or biological correctness. The reported centres and scales are now in log10 units.", "hold_after": 0.7, "focus": [3295, 1745, 390, 330]}, {"visual": "17_real_intensity_raw", "narration": "For a real refusal example, return to no transform and select cell_channel_0_min_intensity alone. Scan succeeds and flags sixty-eight objects. One measured value is actually zero. This positive counterpart matters: the table and feature work before we ask for a transform whose domain excludes that value.", "hold_after": 0.7, "focus": [295, 455, 1700, 315]}, {"visual": "18_real_zero_refusal", "narration": "Now select log10 and press Scan. The real error names the one zero or negative value and its feature. No pseudocount is invented and no object is dropped; export is disabled. Old object-table rows and its count can remain visible after failure, so they are not a successful new result. Read the error and restore a valid rule.", "hold_after": 0.7, "focus": [295, 375, 3540, 230]}, {"visual": "21_low_count_reasons", "narration": "Return to raw cell_area and MAD three point five, then scan to recover the original twenty-six flags. Raising Min objects per well to seven hundred changes eligibility: only one well reaches that count, while the other three retain explicit low-count reasons. Lowering this minimum cannot create the missing fifth well. Not scored is never the same as cleared.", "hold_after": 0.7, "focus": [295, 455, 3005, 300]}, {"visual": "22_objects_only", "narration": "Restore the minimum to twenty and switch Score wells too off, then scan. Object flags remain twenty-six and no well comparison is requested. Switch it back on and scan to restore the four unscored well summaries. This setting changes the analysis level; it is not a filter that deletes cells or wells from your database.", "hold_after": 0.7, "focus": [3295, 1745, 390, 330]}, {"visual": "24_final_flags_and_report_complete", "narration": "Export the restored rule under a different filename. The final files contain two thousand three hundred forty-one object rows, twenty-six flagged rows, four well summaries and the report. Both the original and private measurement database are unchanged. Keep the rule and report with the flags so a different threshold is not mistaken for the same analysis.", "hold_after": 0.7, "focus": [295, 345, 3515, 170]}, {"visual": "method_choices_mad", "narration": "The menu also offers robust multivariate Mahalanobis, which we have not run in this lesson. Its alpha depends on distribution assumptions and is not a guaranteed error rate. The Python consumer is detect_outliers with OutlierSpec in spacr.qt.widgets.outlier_model. To inspect distributions or images, continue with Feature Explorer or Annotate; no image preview or AI request happened here.", "hold_after": 0.7, "related_lessons": ["06_api", "09_annotate", "65_feature_explorer"], "focus": [3435, 1785, 395, 155]}], "host_app_key": "qc_dashboard", "poster": "66_outliers/poster.jpg", "silent": "66_outliers/video/66_outliers_silent.mp4"}, {"id": "67_experiment_design", "number": 67, "slug": "experiment_design", "series": 5, "app_key": "experiment_design", "section": "Data", "title": "Experiment Design: a reproducible plate plan and exact export", "description": "Edit a proposed plate layout through the actual controls, inspect capacity and replication warnings, reproduce random assignments and export the exact well map.", "objectives": ["Plan conditions and control roles before acquisition.", "Demonstrate warning and recovery states without treating layout checks as biological validation.", "Reproduce the same random layout and distinguish selected wells from assigned conditions.", "Export and retain the exact well table when row/column settings cannot express the design."], "prerequisite": "No acquired images or downloaded dataset are required for this planning module. The recording uses the application's real draft of six negative-control, six positive-control and twelve treatment wells, named tutorial_plan. These counts illustrate the interface; they are not a power calculation or acquired experimental result.", "scenes": [{"visual": "01_module", "narration": "Open Experiment Design in Home's Data category before acquisition. This module creates a proposed plate layout, not measured biological results. Our negative, positive and treatment names are draft labels; choose meaningful names and controls for your own experiment.", "hold_after": 0.7}, {"visual": "02_named_draft", "narration": "Name the plate so its identifier will match the images and measurements later. If a table column is narrow, double-click its header boundary to fit the contents. Review Condition, Replicates and Role together. The example's six, six and twelve wells demonstrate the interface, not a justified sample size.", "hold_after": 0.7, "related_lessons": ["68_power_design"]}, {"visual": "03_capacity_warning", "narration": "Choosing a six-well format while requesting twenty-four wells produces a capacity error. The map does not quietly drop excess replicates. Read the message, then change the format or experimental plan; do not treat an empty map as a valid allocation.", "hold_after": 0.7, "focus": [450, 1910, 3150, 205]}, {"visual": "04_capacity_restored", "narration": "Returning to ninety-six wells restores all twenty-four assignments. The plate map updates from the current table. Add condition and Remove selected manage condition rows; the square wells below are a separate selection surface, not those table rows.", "hold_after": 0.7, "focus": [450, 365, 3370, 285]}, {"visual": "05_single_replicate_warning", "narration": "Select a replicate cell and press F two to edit it. Reducing the negative control to one well raises a warning; restoring six removes that warning. Many cells within one well do not substitute for independent experimental replication.", "hold_after": 0.7}, {"visual": "06_block_layout_warning", "narration": "Block layout places conditions together and raises positional-confounding warnings. Read these as prompts to inspect the design, not automatic biological conclusions. Optical illumination correction does not correct evaporation or temperature effects; experimental layout and image shading are different problems.", "hold_after": 0.7}, {"visual": "07_random_interior_seed42", "narration": "Choose random layout, leave edge empty, and seed forty-two. The outer ring leaves sixty usable wells on this ninety-six-well plate; our plan assigns twenty-four. Avoiding the outer ring costs capacity and does not guarantee freedom from all spatial effects.", "hold_after": 0.7, "focus": [450, 635, 620, 445]}, {"visual": "08_seed43", "narration": "Changing the seed to forty-three changes the actual assignments while preserving the requested condition counts. Randomisation reduces systematic placement bias, but a single random layout still needs review. Do not pick a seed to favour a desired outcome.", "hold_after": 0.7, "focus": [450, 635, 620, 445]}, {"visual": "09_seed42_restored", "narration": "Returning to forty-two restores exactly the same well-to-condition mapping. Record the seed together with the plate format, edge policy and condition table. The seed alone does not define a design if those other inputs change.", "hold_after": 0.7, "focus": [450, 635, 620, 445]}, {"visual": "10_selected_wells_not_reassigned", "narration": "Drag across B zero two to C zero four to select six wells. The selection outline changes, but their conditions do not: this gesture selects wells and does not assign a treatment. Check the condition table and the displayed map when revising an allocation.", "hold_after": 0.7, "focus": [450, 635, 620, 445]}, {"visual": "11_export_folder", "narration": "Use Export plate map and choose a dedicated folder. The real export writes plate_map dot CSV, plate_map dot JSON and plate_map_settings dot JSON. Keep the three files together; selecting a destination is not the same as acquiring the planned experiment.", "hold_after": 0.7}, {"visual": "12_real_export_complete", "narration": "The CSV contains one row per assigned well: twenty-four here, matching every displayed condition and role. It joins to measurements using plate I D, row I D and column I D together. The JSON records the seed, design and findings, including warnings rather than hiding them.", "hold_after": 0.7, "focus": [450, 2070, 3300, 50]}, {"visual": "09_seed42_restored", "narration": "This random layout cannot be represented by the row-or-column treatment settings. The settings file explicitly reports expressible as false; it is not a complete analysis configuration. Use the exact exported well table and an explicit join, rather than approximating mixed wells with whole-row labels.", "hold_after": 0.7, "focus": [450, 2070, 3300, 50]}, {"visual": "12_real_export_complete", "narration": "The Python interface lives in spacr.qt.widgets.plate_layout: Condition and PlateDesign describe the plan; assign_wells, check_design and write_design allocate, inspect and save it. Layout checks do not establish statistical power or biological validity. Review the design before acquisition and keep its exact map for downstream analysis.", "hold_after": 0.7, "related_lessons": ["06_api", "68_power_design", "33_plate_viewer"]}], "poster": "67_experiment_design/poster.jpg", "silent": "67_experiment_design/video/67_experiment_design_silent.mp4"}, {"id": "68_power_design", "number": 68, "slug": "power_design", "title": "Power / Design: read the simulator and its limitations", "series": 5, "app_key": "power", "section": "Design", "example_files": ["Power_recorded_simulation_review.zip"], "description": "Understand the actual planning controls, simulated detection curves and warnings without mistaking a small demonstration or contradictory headline for validated design advice.", "objectives": ["Distinguish simulation assumptions from acquired experimental data.", "Read usable fits, detection fractions and uncertainty correctly.", "Recognize the same-design recommendation error and preserve the recorded evidence."], "prerequisite": "This is a critical review of the actual recorded simulator, not calibrated statistical power or sample-size advice. Power_recorded_simulation_review.zip preserves the original JSON and an explanatory review; it is not a GUI-importable completed run or a native export demonstration. The recorded spaCR 1.5.0.4 screen, design adapter, simulator and fitting code still match current source bytes. Two marginal scans produced 18 fits and nine points, two replicates per point; four nonconverged fits remain in the denominator. Two simulations clipped probabilities. The same nominal baseline has different random draws: 1/2 versus 2/2 detections. The advice to increase to the existing well count is explicitly rejected and remains unfixed. Some plot endpoint labels are clipped; the verified table contains all nine coordinates. No new simulation, acquired data, biological calibration, GPU task, AI-provider request or publication is claimed. API: spacr.qt.widgets.power_design.DesignSpec/simulator_kwargs/power_curve and spacr.qt.screens.power.run_power_sweep; spacr.power_simulate and spacr.power_model perform simulation and fitting.", "scenes": [{"visual": "01_module", "narration": "Power and Design explores assumptions with simulated data. It does not load an acquired experiment or establish that its assumptions match yours. This lesson reads a real recorded run, including its warnings and a misleading recommendation. Do not use this small demonstration as validated sample-size advice.", "related_lessons": ["67_experiment_design"], "hold_after": 0.7}, {"visual": "03_guide_library", "narration": "Start with the library and scoring unit. Switching between guide and gene changes what the model scores: the displayed example has forty genes and four guides per gene, so guide scoring has one hundred sixty units. Gene scoring pools the guide information. These are teaching assumptions, not new biological measurements.", "hold_after": 0.7}, {"visual": "04_bounded_library_plate", "narration": "The plate and effect controls describe the assumed design. A positive-call rate is a simulated classification probability, not a count of organisms or a measured infection rate. Inspect the background, effect and prevalence together, and remember that the displayed assumptions do not validate the model.", "hold_after": 0.7}, {"visual": "05_unsupported_effect_warning", "narration": "An effect below one triggers the native unsupported-direction warning and disables Run. The recording then restores a supported value so the controls recover. This is a software guard, not a claim that effects in the other direction are biologically impossible. Do not bypass the warning to obtain a convenient curve.", "hold_after": 0.7}, {"visual": "08_run_settings", "narration": "This bounded demonstration uses only two replicates per point. The detection rule is a usable fit reaching the chosen area under the receiver operating characteristic curve threshold. It is not a hypothesis-test P-value cutoff. The seed and backend are recorded; selecting Torch alone does not prove GPU execution.", "hold_after": 0.7}, {"visual": "09_real_simulation_running", "narration": "Run starts the actual threaded simulator. It varies the cell-count and well-count axes separately, rather than evaluating every combination. The recording completed eighteen fits across nine points. Keep the settings and raw replicate records together so a plotted fraction can be traced to the fits that produced it.", "hold_after": 0.7}, {"visual": "10_actual_results", "narration": "Read detections as counts over all requested replicates. Four fits did not converge and remain in the denominator as non-detections; they are not silently discarded. A plotted hundred percent here means only two out of two. Such a small sample cannot establish a precise detection probability.", "hold_after": 0.7}, {"visual": "10_actual_results", "focus": [1450, 1590, 2380, 460], "narration": "The table separates detection fractions from mean performance among usable fits. An unavailable mean is not zero. Average precision also needs its prevalence baseline for context. Read the table when a plot-end label is clipped, and inspect nonconvergence counts instead of judging the design from the blue line alone.", "hold_after": 0.7}, {"visual": "12_results_and_limitations", "focus": [1450, 210, 2380, 110], "narration": "The headline contains an error. Both baseline estimates already use ninety-six wells, but different random draws produce one of two detections in one scan and two of two in the other. Going to the same ninety-six wells is not an improvement in design. Reject that recommendation; this tutorial does not repair it.", "hold_after": 0.7}, {"visual": "11_full_caveats", "narration": "Expand the remaining caveats. Two simulated screens clipped probabilities above one, so their realised occupancy differs from the requested value. The model has other assumptions and limitations; listing them is not validation. Review these warnings and the failed fits before drawing conclusions from any simulation.", "hold_after": 0.7}, {"visual": "12_results_and_limitations", "narration": "The linked archive preserves the actual recorded specification, replicate outputs, curves, table and incorrect headline for inspection. It is an external evidence download, not a native GUI export or an imported result. The Python design adapter and simulation APIs expose the same workflow, but real planning requires separate validation of assumptions and uncertainty.", "related_lessons": ["06_api"], "hold_after": 0.7}], "poster": "68_power_design/poster.jpg", "silent": "68_power_design/video/68_power_design_silent.mp4"}, {"id": "69_dose_response", "number": 69, "slug": "dose_response", "series": 5, "app_key": "dose_response", "section": "Data", "title": "Dose Response: fitted curves, uncertainty and honest refusals", "description": "Use the current Dose Response screen with a reproducible synthetic table, compare profile and Wald intervals, and distinguish fitted, unbounded and refused results.", "objectives": ["Load explicit concentrations and responses and fit one curve per named series.", "Interpret midpoint estimates, interval methods, vehicle controls and refused curves.", "Compare results before sorting, copy the actual report and distinguish GUI controls from API exports."], "example_files": ["SYNTHETIC_dose_response_examples.csv"], "prerequisite": "Download the accompanying SYNTHETIC CSV. It has 120 constructed rows: four named series, nine positive concentrations plus a zero-dose vehicle, and three observations per concentration. Balanced offsets of minus 0.5, zero and plus 0.5 are not biological replicates or a calibration study. Planted midpoints are 1.5, 2 and an out-of-range 500; the fourth series reverses. No registered Dose Response dataset downloader, normalization, weighting, replicate selector, GUI export button or AI console is demonstrated. The Unit field changes a label, not the data. In this build, refitting after sorting can corrupt the displayed row identities; this recording completes every refit before sorting. Preserve refusals and inspect the full report. API: spacr.qt.widgets.dose_response.DoseResponseSpec, fit_frame and DoseResponseSet.table. The example data and plot checks are independent of spaCR's fitting functions; profile endpoints are checked to the implementation's declared log10 bracket precision, not as a coverage guarantee.", "scenes": [{"visual": "01_home_data", "narration": "Open Dose Response in Home's Data section. This standalone viewer fits a four-parameter logistic curve to a concentration series. It needs the actual concentrations and responses; it does not infer doses from well names, image coordinates or treatment labels.", "hold_after": 0.7, "focus_modules": ["dose_response"]}, {"visual": "03_choose_disclosed_synthetic_csv", "narration": "Download the synthetic CSV linked in this lesson's prerequisites, then choose Load table. These are deliberately constructed software examples, not measured compounds. The file and every series name say synthetic, so the clean curves must not be mistaken for experimental results.", "hold_after": 0.7}, {"visual": "04_loaded_120_synthetic_rows", "narration": "The file contains one hundred twenty rows across four series. Each has nine positive concentrations, a zero-dose vehicle, and three observations at each concentration. The small, balanced artificial offsets preserve the model mean at every dose; this convenient example does not validate statistical performance on real experiments.", "hold_after": 0.7, "focus": [285, 40, 2200, 170]}, {"visual": "05_explicit_columns_and_profile", "narration": "Select concentration as the concentration column, response as the response column, and series under One curve per. Supply raw concentrations, not their logarithms. Grouping is important: fitting all four different series as one curve would answer the wrong question.", "hold_after": 0.7, "focus": [285, 145, 1470, 75]}, {"visual": "05_explicit_columns_and_profile", "narration": "The Unit field is only a label. Here we type u M to label the illustrative concentrations as micromolar; changing this text never rescales the numbers. Prepare any required normalization or unit conversion upstream, because this screen has no normalization or weighting controls.", "hold_after": 0.7, "focus": [285, 145, 1470, 75], "related_lessons": ["61_tabulate"]}, {"visual": "06_profile_results", "narration": "Leave Profile likelihood selected and Fit non-monotone data switched off, then choose Fit. The curve panel and results table update together. All four series stay accounted for, including an unbounded result and a refusal; a missing estimate is not the same as a missing series.", "hold_after": 0.7, "focus": [2000, 190, 1810, 210]}, {"visual": "07_inhibition_midpoint", "narration": "Select synthetic inhibition. The recovered midpoint is one point five, with a negative Hill slope because the response falls as concentration increases. Half-maximum means halfway between the fitted plateaus, which are five and ninety-five here; it does not automatically mean fifty percent viability.", "hold_after": 0.7, "focus": [285, 210, 1710, 1900]}, {"visual": "08_activation_midpoint", "narration": "Select synthetic activation. Its recovered midpoint is two and its Hill slope is positive. The selected curve is emphasized while the other fitted curves remain visible. Read the selected row and report together rather than assigning another curve's estimate to this series.", "hold_after": 0.7, "focus": [285, 210, 1710, 1900]}, {"visual": "09_unbounded_not_a_point_estimate", "narration": "The beyond-range example was constructed with a midpoint of five hundred, but its concentrations stop at one hundred. The screen reports an unbounded result, leaves the midpoint and interval cells blank, and shows a bound at the edge. A fitted extrapolation is not a supported point estimate.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 450]}, {"visual": "10_refused_reversing_series", "narration": "The reversing series is refused because a monotonic logistic curve is the wrong shape. Read the full explanation below the table. A turning response does not by itself establish cytotoxicity or another biological cause; investigate the experiment instead of blindly removing doses or forcing a fit.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 450]}, {"visual": "07_inhibition_midpoint", "narration": "The inhibition report counts twenty-seven fitted observations and three zero-dose controls. Zero concentrations are excluded from the logarithmic fit and summarized separately; they are not silently converted to tiny positive doses. The synthetic vehicle mean is ninety-five, matching the constructed low-dose plateau.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 450]}, {"visual": "07_inhibition_midpoint", "narration": "Also read residual error and the lack-of-fit assessment, not just R squared. This deliberately balanced example has exceptionally tidy diagnostics. Repeated observations at each concentration are used without a separate replicate selector, and these artificial repeats do not establish the independence of measurements in a real experiment.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 450]}, {"visual": "13_choose_wald", "narration": "To compare interval methods, choose Wald and press Fit again. Changing the selector alone does not recompute an existing result. The interval is calculated for the logarithm of the midpoint and transformed back; it is not a symmetric error bar added directly to concentration.", "hold_after": 0.7, "focus": [285, 145, 1470, 75]}, {"visual": "14_wald_results", "narration": "The well-bracketed examples keep their midpoint estimates while the interval endpoints change slightly. The beyond-range example still withholds its midpoint. Finite intervals on these tidy examples do not prove that another experiment identifies its midpoint or that nominal coverage holds for its noise and sampling design.", "hold_after": 0.7, "focus": [2000, 190, 1810, 210]}, {"visual": "15_profile_restored", "narration": "Restore Profile likelihood and choose Fit again. Check that the results now correspond to that method. The curve, table and selected report are linked views of the completed fit; they are not a live preview that automatically refits whenever a control changes.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 450]}, {"visual": "16_select_after_sorting", "narration": "Finish the fitting comparisons before sorting the table. This build can misalign displayed rows when a sorted table is refitted, so do not rely on that sequence. Here we sort only after fitting, then select inhibition and verify that its matching report is shown.", "hold_after": 0.7, "focus": [2000, 190, 1810, 210]}, {"visual": "17_copy_actual_report", "narration": "Select and copy the report text using the normal copy shortcut. Keep the warnings, refusal explanations, input concentrations and chosen interval method with the result. Copying a single midpoint without that context discards the information that determines whether it can be interpreted.", "hold_after": 0.7, "focus": [2000, 1140, 1810, 500]}, {"visual": "15_profile_restored", "narration": "There is no export button in this screen. For programmatic output, the dose-response API provides fit_frame and a result table; the API lesson explains working from Python. Preserve unbounded and refused rows when exporting, rather than keeping only the compounds that produced convenient numbers.", "hold_after": 0.7, "related_lessons": ["06_api"], "focus": [2000, 190, 1810, 210]}], "poster": "69_dose_response/poster.jpg", "silent": "69_dose_response/video/69_dose_response_silent.mp4"}, {"id": "70_explain_cv", "number": 70, "slug": "explain_cv", "title": "Explain CV Model", "series": 5, "app_key": "explain_cv", "section": "Results and quality control", "host_app_key": "classify_merged", "description": "Inspect a real surrogate fit inside Classify, verify its held-out fidelity and recognise when feature explanations must not be interpreted.", "objectives": ["Select matching measurements and existing classifier predictions through the nested workbench.", "Distinguish surrogate agreement from independent classifier validation.", "Inspect failed fidelity, class errors, table limits and complete saved artifacts."], "prerequisite": "Use a measurements database and predictions CSV from the same cropped objects. This recording reuses 234 genuine saved predictions from the one-epoch Annotate/Classify example, not the separate portable Evaluation inspector bundle. Original filename and predicted_label columns are preserved. The earlier classifier split shares wells with training, so this is not independent classifier validation. The surrogate uses 89 complete cases and 1126 features; 145 joined rows are excluded for nonfinite features. It fits 68 objects from two wells and tests 21 from a third. All surrogate calls are class 1: fidelity 17/21, balanced accuracy 0.5. The displayed majority baseline is 81/89 across all complete cases. Importance is withheld; visible SHAP values are not a faithful account of the CV model. Eighteen cv_intensity measurement names are excluded by the name heuristic, which does not prove actual leakage. GUI correlations and distributions stop at 1000 rows; inspect full CSV exports. API: spacr.surrogate.explain_classifier, fit_surrogate and write_surrogate_result. No GUI controls for permutation repeats, feature exclusions or SHAP budget are claimed. CPU demonstration only; no new training, external AI request, native-listening approval or publication.", "scenes": [{"visual": "01_classify_host", "narration": "Open Classify, then the Explain CV Model icon at the upper right. It opens a nested workbench, not another Home module. We reuse existing image-classifier predictions and the matching measurements from the example workflow. Explaining those predictions does not validate the classifier itself.", "focus": [3579, 100, 80, 80], "related_lessons": ["09_annotate", "39_classifier_evaluation"], "hold_after": 0.7}, {"visual": "04_recorded_predictions_picker", "narration": "Choose the matching measurements database and saved predictions CSV. The file must identify the same cropped objects, not just use similar well names. Here we use unchanged copies of two hundred thirty-four real saved predictions. This is not a new training run or a newly validated dataset.", "hold_after": 0.7}, {"visual": "06_ready_existing_predictions_not_retraining", "narration": "If Browse leaves the old column choices, confirm the prediction path with Enter. Select filename for the crop path and predicted underscore label for the model's class calls, not the true labels or a continuous probability. Choose Random Forest, well grouping and a new output folder.", "focus": [462, 463, 2680, 459], "hold_after": 0.7}, {"visual": "07_actual_fitting", "narration": "Click Explain model. The surrogate learns from measured features to imitate existing class calls; it does not rerun the vision model. This example uses CPU processing. The GUI offers backend and grouping choices; permutation repeats, feature exclusions and the SHAP budget are API options, not controls on this form.", "focus": [462, 678, 2200, 365], "related_lessons": ["06_api"], "hold_after": 0.7}, {"visual": "08_result_tab_0", "narration": "Read Fidelity first. All predictions joined, but only eighty-nine rows had complete features. The surrogate fits sixty-eight objects from two wells and tests twenty-one from a third. Fidelity is about eighty-one percent, below the displayed ninety-one percent majority baseline. That baseline uses all complete cases, not only the held-out well.", "focus": [474, 1010, 2900, 890], "hold_after": 0.7}, {"visual": "09_result_tab_1", "narration": "Importance is withheld because the fidelity gate failed. Do not turn this fit into a claim about what the vision classifier recognises. Also review automatic exclusions: the warning calls eighteen measurement names leaky, but names containing coefficient-of-variation intensity do not by themselves establish label leakage.", "focus": [465, 937, 2420, 810], "hold_after": 0.7}, {"visual": "11_result_tab_3", "narration": "Confusion compares the original model's class calls with the surrogate's calls, not biological truth. Here the surrogate calls every held-out object class one: seventeen agreements and four errors. Balanced accuracy is one half. A high-looking overall percentage can hide failure on the smaller class.", "focus": [465, 948, 2000, 650], "hold_after": 0.7}, {"visual": "12_result_tab_4", "narration": "Per-cell SHAP is still visible even though fidelity failed. These values describe this surrogate; they do not rescue its explanation of the vision model or establish a biological mechanism. Keep this limitation attached to exported attribution tables. Activation maps answer a different, spatial question, covered in their own lesson.", "focus": [465, 948, 2700, 1050], "related_lessons": ["16_activation"], "hold_after": 0.7}, {"visual": "14_result_tab_6", "narration": "Inspect Correlations and Feature distributions as data summaries, not proof of causation. Each GUI table stops at a thousand rows. The full exports here contain one thousand eighty-seven correlation pairs and two thousand two hundred fifty-two distribution rows. Read the saved files before reporting totals or missing features.", "focus": [465, 948, 2910, 1050], "hold_after": 0.7}, {"visual": "15_result_tab_7", "narration": "Held-out cells retains the object identities and both sets of predictions. Open held-out objects is disabled in this recording, so no crop handoff is demonstrated. Keep the eleven saved artifacts, settings and fidelity warning together. The Evaluation lesson explains classifier validation limits; a plot, SHAP table or spaCR AI response cannot certify a classifier.", "focus": [465, 865, 2910, 1150], "related_lessons": ["39_classifier_evaluation", "06_api"], "hold_after": 0.7}], "poster": "70_explain_cv/poster.jpg", "silent": "70_explain_cv/video/70_explain_cv_silent.mp4"}, {"id": "71_investigate_hit", "number": 71, "slug": "investigate_hit", "title": "Investigate Hit", "series": 5, "app_key": "investigate_hit", "section": "Results and quality control", "description": "This tutorial is not available yet. Please explore the other tutorials.", "objectives": [], "prerequisite": "", "scenes": [], "status": "coming_soon", "availability_title": "Coming soon", "host_app_key": "regression"}, {"id": "72_volcano_explorer", "number": 72, "slug": "volcano_explorer", "title": "Volcano Explorer: inspect existing results and export a figure", "series": 5, "app_key": "volcano_explorer", "host_app_key": "regression", "section": "Regression", "example_files": ["Volcano_real_guide_family.zip"], "description": "Explore the real Regression example, synchronize the current style controls, distinguish visual thresholds from statistical testing, and save reproducible figure styles and exports.", "objectives": ["Open the nested Volcano Explorer with the completed Regression guide family.", "Synchronize initial controls through the verified Save style and Load style workaround.", "Inspect point identities, effect and P-value axes, colour and reference lines without inventing new hits.", "Restore a saved style and inspect vector PDF and PNG exports."], "prerequisite": "Extract Volcano_real_guide_family.zip and open its results folder. These are unchanged outputs from the downloaded-data Regression tutorial, not a new analysis or a complete project archive. One family contains 434 guides, outcome log_pred, minimum_wells_threshold=2, plus-one permutation P values and BH correction. Minimum raw P=0.005, minimum adjusted P=0.39454545454545453; zero significant at original alpha=0.05. Standardized marginal effects are not simultaneously fitted multivariable coefficients or log2 fold changes. The native initial style-control defect remains: displayed alpha=1e-6, multiplier=0 and log=False disagree with rendered .05/3/True. Before editing, Save style then Load that same style synchronizes controls. All 67 style fields survive the later roundtrip. Moving alpha to .5 puts nineteen adjusted values below that cutoff but preserves zero source significance flags; it is not new testing. Restore .05 and adjusted_p_value before export. An explicit effect cut .1 with multiplier 3 gives lines at +/-0.3. Actual point coordinates, identities, source flags and support colours are checked. Nominal 7-by-5-inch, 150-DPI settings export a tightly cropped 492.536-by-348.485-point PDF and 1026-by-726-pixel PNG. The PDF has embedded fonts and no raster images; labels were visually rechecked. Some GUI labels remain clipped and the application warns about white marker outlines on light paper. Annotation merging, broken axes, localization and control-MAD rules are not certified by this example. The preserved recording was made with spaCR 1.5.0.4; its screen, widget and renderer source bytes still match the current checkout. No new regression, GPU, AI provider request, application modification, biological validation or publication. API: spacr.volcano_style.VolcanoStyle and render_volcano.", "scenes": [{"visual": "01_regression_host", "narration": "Open Regression and its nested Volcano Explorer. This lesson belongs under Regression in the submodule section. The explorer reads completed results; it does not rerun the analysis. We use the real downloaded-data Regression example, with a companion archive containing the exact result tables and recorded figure styles.", "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "03_real_guide_family_no_adjusted_hits", "narration": "Choose Open results and select the extracted results folder. Each point here is one guide from a single family of four hundred thirty-four tests, using the same outcome and minimum-well rule. Do not pool different correction families. No guide is significant at the original adjusted-P cutoff of zero point zero five.", "hold_after": 0.7}, {"visual": "03a_save_rendered_baseline_style", "narration": "Before changing any setting, use Save style to save the actual rendered style, then Load style from that same file. In this build the initial controls disagree with the figure, and editing immediately can pull incorrect defaults into the plot. This normal save-and-load workaround synchronizes them; it does not fix the application.", "hold_after": 0.7}, {"visual": "03c_rendered_baseline_and_controls_agree", "narration": "After reloading, confirm alpha zero point zero five, multiplier three, and the negative-log transform. Some setting labels remain clipped in this build, so check the values and saved JSON. The horizontal axis is standardized marginal effect, not log-two fold change or a coefficient from a simultaneously fitted multivariable model.", "focus": [2305, 270, 1500, 570], "hold_after": 0.7}, {"visual": "05_selected_real_guide", "narration": "Click an existing point to inspect its source row. The selected guide has raw P zero point zero zero five, but adjusted P about zero point three nine. Its large marginal effect and four supporting wells do not make it significant. Use the identity and source fields rather than guessing from a dot's position.", "focus": [305, 1830, 1990, 275], "hold_after": 0.7}, {"visual": "07_raw_p_values_not_new_hits", "narration": "Switching the vertical column to raw permutation P changes the plotted quantity, not the analysis. Small raw values do not replace the family-adjusted values. Restore adjusted P afterwards. The saved source significance flags remain unchanged; the explorer is a reader and figure editor, not a new statistical test.", "hold_after": 0.7}, {"visual": "10_log_transform_restored", "narration": "The negative-log-ten switch changes how P values are displayed. With it on, smaller P values appear higher; turning it off displays the original values. We restore the transformed adjusted-P view here. Always read the axis label, and do not confuse the transform with a different multiple-testing correction.", "hold_after": 0.7}, {"visual": "11_reference_line_does_not_retest", "narration": "For demonstration, moving alpha to zero point five moves the reference line. Nineteen adjusted values fall below that new P cutoff, but none gains a new source significance flag. This is not a valid claim of nineteen discoveries. Restore the original zero point zero five before exporting or interpreting this example.", "hold_after": 0.7}, {"visual": "13_explicit_effect_cut_times_multiplier", "narration": "An explicit effect cutoff of zero point one combines with multiplier three, placing vertical lines at minus and plus zero point three. Check the multiplier rather than reading the cutoff field alone. An effect threshold does not replace statistical correction. Restore Auto after this exercise; no result-table values are rewritten.", "hold_after": 0.7}, {"visual": "15_colour_by_actual_support", "narration": "Colour by wells with guide displays actual support from the source table. It is not a confidence score or proof of accuracy. Return to the original significance colours before the final export. Optional annotation joins and other layouts need their own validation and are outside this verified example.", "hold_after": 0.7}, {"visual": "17_publication_size_settings", "narration": "Set the intended figure size, font sizes and resolution, then inspect the result. Here the nominal size is seven by five inches at one hundred fifty dots per inch. Tight bounding-box cropping changes the final dimensions. A readable exported figure does not mean every native settings label fits this window.", "hold_after": 0.7}, {"visual": "21_saved_style_restored", "narration": "Save the final style as JSON. After a temporary marker-size change, Load style restores every recorded style field. Keep that file with the original result table so another session can reproduce the appearance. Style settings describe presentation; they do not establish that a different regression or significance test was run.", "hold_after": 0.7}, {"visual": "24_export_finished_source_preserved", "narration": "Export PDF and PNG re-render the figure rather than capture the screen. Our PDF contains vector marks and embedded fonts; inspect labels, contrast and the warning about white marker outlines on light paper. Original data remain unchanged. Python provides VolcanoStyle and render_volcano for the same rendering workflow, without a GPU or AI provider.", "related_lessons": ["06_api", "13_regression"], "hold_after": 0.7}], "poster": "72_volcano_explorer/poster.jpg", "silent": "72_volcano_explorer/video/72_volcano_explorer_silent.mp4"}, {"id": "73_parameter_sweep", "number": 73, "slug": "parameter_sweep", "title": "Parameter Sweep", "series": 5, "app_key": "parameter_sweep", "section": "Results and quality control", "host_app_key": "regression", "description": "Run two bounded trials inside Regression, inspect saved guide and gene results, and distinguish execution success from valid inference.", "objectives": ["Find the nested sweep and select four ordered score/count pairs from Regression’s test data.", "Limit a grid to two trials and one worker, then inspect saved results without refitting.", "Keep failed inference checks and separate coefficient families visible when comparing outputs."], "prerequisite": "Use the four downloaded plate score/count pairs from the Regression lesson and a new output folder. This is a computational demonstration, not a validated hit-discovery analysis: both recorded ridge trials fail inference QC. The full recipe is visible in the sweep form; only alpha varies, 0.01 and 0.1. Parametric inference, well aggregation, mean response and no transform are fixed explicitly. Other parent settings are not automatically inherited. Do not use the displayed n_rows_fitted as sample size: it counts 1174 coefficient rows here, not 620 wells or 2955 prepared long-form rows. The trial table omits alpha and the saved QC verdicts; inspect sweep_results.csv and each trial’s actual settings. API: spacr.parameter_sweep.SweepSpace and run_sweep_parallel. No GPU acceleration benchmark, external AI request, native-speaker sign-off or publication is claimed.", "scenes": [{"visual": "01_regression_with_four_existing_pairs", "narration": "Open Regression, then Parameter sweep at the bottom right. This workflow lives inside Regression, not on a separate Home tile. The Regression lesson explains downloading the four example score and count pairs that we reuse here.", "focus": [3380, 1880, 440, 150], "related_lessons": ["13_regression"], "hold_after": 0.7}, {"visual": "03_count_file_picker", "narration": "Check the sweep’s own input lists. They are initially empty even when the parent form contains paired data. Add the four score files and four count files in matching plate order. Choose a new output folder so this demonstration cannot overwrite an earlier analysis.", "hold_after": 0.7}, {"visual": "05_two_trials_one_worker_budget", "narration": "Only tick alpha: the values are zero point zero one and zero point one. Unticked rows still supply fixed settings. Here we explicitly choose ridge, parametric inference, well-level mean aggregation and no transform. This bounded recipe demonstrates operation; it is not a recommendation for your experiment.", "focus": [850, 490, 680, 680], "hold_after": 0.7}, {"visual": "06_actual_estimate", "narration": "Set grid sampling, maximum trials two, and one worker, then click Estimate. Two valid combinations means the settings combinations are allowed, not that the statistical conclusions are valid. The time estimate assumes a minute per trial; it is not a benchmark. Read the available resource limits before starting.", "focus": [850, 1190, 680, 375], "hold_after": 0.7}, {"visual": "07_actual_sweep_running", "narration": "Click Start sweep, not the parent Regression Run button. Each trial writes into its own folder. These two real trials run sequentially; adding workers increases resource demand. This example demonstrates CPU regression, not GPU acceleration, and no request to spaCR AI is needed.", "hold_after": 0.7}, {"visual": "08_actual_sweep_finished", "narration": "Both rows report ok because computation finished. Crucially, both saved inference quality checks report fail. The table omits those verdicts and the varied alpha, so inspect the full sweep results file and each trial’s settings. Do not select a model just because it produces more small adjusted P values.", "focus": [1550, 205, 2215, 290], "hold_after": 0.7}, {"visual": "10_saved_guide_family", "narration": "Select the first row and click Show figures for selected row. This reads its saved results without refitting. The guide view contains seven hundred ninety-two coefficient rows, including an intercept; the plot excludes that nuisance term and shows seven hundred ninety-one guides. Height represents negative log ten of the raw P value.", "focus": [1545, 510, 2255, 1040], "hold_after": 0.7}, {"visual": "11_saved_gene_family", "narration": "Switch Level to Gene. The table now contains three hundred eighty-two rows, including its intercept, and the plot shows three hundred eighty-one genes. Guides and genes are separate coefficient families. Changing this view does not make the failed inference valid or create independent evidence.", "focus": [1545, 555, 2255, 995], "hold_after": 0.7}, {"visual": "12_saved_guide_family_restored", "narration": "Switch back to guides: the original rows and points return, and the saved files are unchanged. The summary’s rows fitted field is misleading here: it reports coefficient rows, not wells. Keep the input sample count, output coefficient count and plotted family distinct when reporting an analysis.", "focus": [1545, 555, 2255, 995], "hold_after": 0.7}, {"visual": "13_actual_saved_model_summary", "narration": "Use the saved settings, summary and quality-control files together. A plot or an AI explanation cannot certify a study design. Regression Diagnostics explains further inspection, while the API reference documents sweep execution. This example teaches a reproducible workflow and its limitations, not validated biological hits.", "related_lessons": ["75_regression_diagnostics", "06_api"], "hold_after": 0.7}], "poster": "73_parameter_sweep/poster.jpg", "silent": "73_parameter_sweep/video/73_parameter_sweep_silent.mp4"}, {"id": "74_import_images", "number": 74, "slug": "import_images", "title": "Import Images: inspect the plan before importing", "series": 2, "app_key": "import_images", "host_app_key": "foreign", "section": "spaCR", "description": "Open Import Images inside Import, check a real microscopy subset before writing, and save a reusable plan. The example explicitly distinguishes unsupported raw naming from prepared copies.", "objectives": ["Find Import Images inside the Import module and distinguish it from importing existing measurements and masks.", "Check image identities and unresolved filename tokens before writing a project.", "Choose copying or linking, save and reload a plan, and verify the completed import."], "prerequisite": "Download Mask's real example first. This recording uses copied E01/F001 and L01/F009 fields, four C channels each. Prepared copies omit only the A token immediately before Z; originals remain unchanged. This is a specifically checked example, not a general instruction to delete unfamiliar filename metadata.", "scenes": [{"visual": "02_import_fold", "narration": "Open Import from Home's Data category, then choose Import Images. This nested tool prepares raw image files. Import Project, Format Converter, and External Masks are related workflows with their own tutorials.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["36_import", "35_converter", "31_external_masks"]}, {"visual": "04_source_options", "narration": "Our eight images are real microscopy data from Mask's downloadable example: one field from each of two wells, with four channels per field. We work on separate copies and leave the downloaded originals untouched.", "hold_after": 0.7, "related_lessons": ["07_mask"]}, {"visual": "04a_unresolved_acquisition_token", "narration": "Scan reveals an unresolved acquisition token in these raw names. Import stays disabled and nothing is written. Do not guess a channel mapping: two different channels share this acquisition value, so that answer would corrupt their identities.", "hold_after": 0.7}, {"visual": "05_scan_proposal", "narration": "For this checked example, prepared copies omit only the redundant acquisition token. Their well, field, and channel names remain intact. Scan now shows eight rows, two wells, two field numbers, and four channels. This does not mean the original naming was accepted.", "hold_after": 0.7}, {"visual": "06_check_filename", "narration": "Compare the proposal with the filenames before importing. Read inside each file checks embedded axis metadata as well as names. Sample limits the files inspected; ensure the proposal includes the images you intend to import. Resolve questions from acquisition records, not guesses.", "hold_after": 0.7, "focus": [350, 665, 1770, 675]}, {"visual": "07_copy_destination", "narration": "Choose a destination outside the input folder and set the plate name. We turn off Link instead of copy for an independent project. Links save disk space, but depend on the originals staying accessible at their existing locations.", "hold_after": 0.7, "focus": [345, 1600, 3420, 210]}, {"visual": "07_copy_destination", "narration": "These example files are not tiles. For tiled acquisitions, read the Tiles choice carefully: stitching assembles fields, keeping tiles separately changes what a field means, and skipping loses those images. Check the report and any unverified seams before measuring.", "hold_after": 0.7, "related_lessons": ["32_align_stitch"]}, {"visual": "09_saved_plan", "narration": "Save plan writes a JSON record of the source and your mapping answers, not a backup of the images. Keep it with the acquisition notes. The same plan can be read through the Python image import API.", "hold_after": 0.7, "related_lessons": ["06_api"]}, {"visual": "11_reloaded_plan", "narration": "Load plan reads the source folder again and reuses the saved answers. Check the new proposal before importing; a saved plan does not guarantee that a changed acquisition is correct. Here it restores the same eight checked image identities.", "hold_after": 0.7}, {"visual": "12_import_complete", "narration": "Press Import and read the summary. This run wrote eight independent image copies with no skipped files; their contents match the source. Next, point Mask at the project and inspect its live preview before segmentation. Importing alone does not generate masks or measurements.", "hold_after": 0.7, "related_lessons": ["07_mask", "08_measure"]}], "poster": "74_import_images/poster.jpg", "silent": "74_import_images/video/74_import_images_silent.mp4"}, {"id": "75_regression_diagnostics", "number": 75, "slug": "regression_diagnostics", "title": "Regression Diagnostics: read the evidence behind the results", "series": 2, "app_key": "regression_diagnostics", "host_app_key": "regression", "section": "spaCR", "description": "Open the diagnostic files produced by a real example-screen analysis, distinguish design warnings from permutation results, and recognize the limits of a short demonstration run.", "objectives": ["Open Diagnostics inside Regression and verify the output folder being inspected.", "Interpret design identifiability, guide support and inference panels in the context of the selected analysis.", "Recognize missing fitted-residual panels and limited permutation resolution without inventing a model fit."], "prerequisite": "Complete the Regression example using its four downloadable score/count pairs. This recording inspects a bounded nonparametric run with 199 permutations, a minimum of two wells, and both guide and gene results. It demonstrates the software and diagnostic interpretation, not final discovery-quality inference.", "scenes": [{"visual": "02_diagnostics_button", "narration": "Inside Regression, hover over Diagnostics and open it after an analysis has completed. This button reads saved output; it does not fit another model. It opens the newest diagnostics folder found in the project, so verify the path when several runs exist.", "hold_after": 0.7, "focus_buttons": "FoldButton", "related_lessons": ["13_regression"]}, {"visual": "03_diagnostics_folder", "narration": "The system file manager shows the actual files from our downloaded example-screen analysis. Here the figure preference was PNG. The folder contains design identifiability, design diagnostics, inference diagnostics, a summary table, and a table of collinear guide pairs.", "hold_after": 0.7, "focus": [535, 230, 1420, 285]}, {"visual": "04_design_identifiability", "narration": "The design has six hundred and six wells, seven hundred and ninety-three parameters, and rank five hundred and ninety-nine. It cannot identify a unique simultaneous coefficient for every guide. This warning explains why we used a permutation analysis; it does not mean a simultaneous model was fitted successfully.", "hold_after": 0.7}, {"visual": "04_design_identifiability", "narration": "Guide support is uneven: three hundred and fifty-five guides occur in just one well in this design. Sparse support limits what the experiment can establish. Inspect coverage before interpreting effects, and distinguish the full design from the filtered family of guides actually tested.", "hold_after": 0.7}, {"visual": "05_design_diagnostics", "narration": "The design panel helps locate poor support and dependencies between guide predictors. Guides that always occur together are hard to distinguish statistically. Use the collinear-pairs table to inspect specific pairs rather than treating a warning badge as a complete explanation.", "hold_after": 0.7}, {"visual": "06_inference_diagnostics", "narration": "The inference panel summarizes four hundred and thirty-four guide tests: their p-value distribution, comparison with a uniform null, and discoveries across adjusted thresholds. This short run has no discoveries at the displayed threshold. A calibration warning is a prompt to investigate, not proof of biological effects.", "hold_after": 0.7}, {"visual": "06_inference_diagnostics", "narration": "We used only one hundred and ninety-nine permutations to keep the demonstration short. The minimum attainable empirical p-value is therefore zero point zero zero five. That resolution can be inadequate after multiple-testing correction; use an appropriately planned permutation count for the real analysis.", "hold_after": 0.7}, {"visual": "03_diagnostics_folder", "narration": "There is no fitted-residual panel for this permutation run because it did not fit the simultaneous regression model. The p-value comparison we just viewed is not a residual diagnostic. Other analysis modes can write residual panels when they supply observed and fitted values.", "hold_after": 0.7}, {"visual": "03_diagnostics_folder", "narration": "The summary records individual panel assessments and the worst assessment for the suite. Read each assessment in context rather than interpreting the overall badge as a software error. The Python regression diagnostics API writes the same kinds of panels from the inputs it is given.", "hold_after": 0.7, "related_lessons": ["06_api"]}, {"visual": "07_back_to_regression", "narration": "Return to Regression to investigate the inputs or change an analysis choice deliberately. A change needs a new run and new diagnostics; opening this folder never updates old results. Use the Regression tutorial for the full dataset, console, interactive results, and assistance workflow.", "hold_after": 0.7, "related_lessons": ["13_regression", "48_hit_list", "72_volcano_explorer"]}], "poster": "75_regression_diagnostics/poster.jpg", "silent": "75_regression_diagnostics/video/75_regression_diagnostics_silent.mp4"}, {"id": "77_embeddings", "number": 77, "slug": "embeddings", "title": "Embeddings: current screen and a real Python example", "series": 2, "app_key": "embeddings", "section": "Data", "description": "Inspect the new Home module, encode real downloaded crops with the supported API, and compare channel policies without claiming a repaired GUI or a validated phenotype.", "objectives": ["Find Embeddings and distinguish its current GUI limitation from the working API.", "Encode sixteen real crops, preserve identities and inspect both channel policies.", "Read saved vectors and exploratory plots with appropriate limitations."], "example_files": ["Embeddings_API_example.zip"], "prerequisite": "spaCR 1.5.0.7 with its embeddings extra; the recording uses timm 1.0.29 and cached pretrained ResNet18 weights on CPU. Download Annotate's real example as shown in that tutorial. Extract the helper ZIP, locate plate1/data/single_nucleus/uninfected/plate1_E02/cell_png, and use NEW output directories. The helper reads sixteen sorted PNGs without resizing; filenames identify the demonstration rows, not verified database join keys. The standalone Embeddings screen still lacks a crop-loading control. Successful operations here use the public Python API, not programmatic injection disguised as a GUI action. The default encoder is ImageNet-supervised, not microscopy-trained. No native-speaker signoff, biological validation, GPU benchmark or provider request is claimed. Read the included README for normalization, provenance, device and channel-mapping details.", "scenes": [{"visual": "gui_00_home", "narration": "Embeddings is a new Home module in spaCR. It turns image crops into numerical vectors without training on your annotations. This lesson demonstrates the current screen and a working Python example, using real downloaded images.", "focus_modules": ["embeddings"], "related_lessons": ["05_home", "06_api"], "hold_after": 0.7}, {"visual": "gui_01_no_gui_crop_input", "narration": "In version one point five point zero point seven, this screen has no crop-loading control, and Embed remains disabled. We will not simulate a successful GUI run. The supported Python API performs the actual encoding shown next.", "focus": [340, 55, 3480, 190], "hold_after": 0.7}, {"visual": "gui_02_channel_policies", "narration": "Per channel encodes each stored channel separately, then concatenates the vectors. Project to three encodes the combined image instead. That changes the representation, not just its speed. A saved PNG slot is not automatically a verified stain identity.", "focus": [340, 145, 1050, 270], "hold_after": 0.7}, {"visual": "api_00_version", "narration": "Install the optional embeddings extra in your spaCR environment. The default ResNet eighteen uses ImageNet-supervised weights, not a cell-trained self-supervised model. This small example uses the CPU; no GPU or remote AI service is required.", "focus": [200, 100, 3440, 700], "hold_after": 0.7}, {"visual": "api_01_inputs", "narration": "Use Annotate's downloadable example and the crop folder named in the instructions. The linked helper selects sixteen existing images in sorted filename order. Each is two hundred twenty-four pixels square, with three stored channels. No resizing or new segmentation is performed.", "focus": [200, 100, 3440, 1100], "related_lessons": ["09_annotate"], "hold_after": 0.7}, {"visual": "api_02_per_channel", "narration": "Run the helper with a new output directory. It calls embed_array with the real pretrained encoder and batches of four. Per-channel encoding produces sixteen rows and one thousand five hundred thirty-six dimensions. The saved matrix is reopened and checked value by value.", "focus": [200, 100, 3440, 1000], "hold_after": 0.7}, {"visual": "api_03_project", "narration": "Now choose project and a different output directory. The same images produce sixteen rows and five hundred twelve dimensions. These combined-channel columns are not interchangeable with the earlier per-channel columns. Compare policies deliberately and retain the settings for each run.", "focus": [200, 100, 3440, 1000], "hold_after": 0.7}, {"visual": "api_05_input_crops", "narration": "Inspect the actual input montage in the image viewer. Its numbers match the output row order. Check crop quality and the export's channel mapping before interpreting vectors. Filenames identify this example; validate the object keys before joining to a measurements database.", "hold_after": 0.7}, {"visual": "api_06_per_channel_pca", "narration": "This saved plot projects the per-channel vectors onto two principal components. The numbered points refer to those same crops. It is exploratory visualization of a tiny sample, not proof of distinct phenotypes. A single embedding dimension is not a biological measurement.", "hold_after": 0.7}, {"visual": "api_07_project_pca", "narration": "The combined-channel vectors have their own projection. Do not compare axis coordinates across these separate plots as if they shared a fitted transformation. Neither picture measures retrieval accuracy or establishes that embeddings outperform the hand-measured feature panel.", "hold_after": 0.7}, {"visual": "api_04_provenance", "narration": "Keep the vectors, source identities, weights checksum, settings and package versions. The helper checks that source images remain unchanged and refuses existing destinations. Match input crops, normalization and channel mapping between comparisons. Use the linked instructions to reproduce this API example.", "focus": [200, 100, 3440, 1200], "related_lessons": ["06_api", "08_measure"], "hold_after": 0.7}], "poster": "77_embeddings/poster.jpg", "silent": "77_embeddings/video/77_embeddings_silent.mp4"}, {"id": "76_ops", "number": 76, "slug": "ops", "title": "OPS: current screen and four-tile image alignment", "series": 2, "app_key": "ops", "host_app_key": "mask", "section": "Segmentation models", "description": "Find OPS under Mask, then follow a measured four-tile geometry and composition example on real acquisition images. This is not a completed full-plate, segmentation or decoding workflow.", "objectives": ["Find the current nested OPS screen and understand the demonstration's limits.", "Register four real neighboring image tiles while retaining their original acquisition coordinates.", "Inspect independently checked overlaps, coverage and saved provenance."], "prerequisite": "The recording uses spaCR 1.5.0.7 nightly's ops_layout, ops_stitch and ops_compose Python APIs on CPU. The current GUI Run dispatches to a different legacy engine and is not run here. Source: screenA/20200202_6W-LaC024A, sequencing/images/input/c1, sites 0, 1, 10 and 11. These are existing maintainer NAS data, NOT a bundled or publicly downloadable OPS example. You need authorized access to that acquisition to reproduce the exact measurements; the tutorial does not grant data redistribution rights. Each original TIFF is uint16, five planes by 1480 by 1480 pixels, with DAPI at plane zero. The helper retains the acquisition's 333-site layout while processing only four neighbors. Do not reuse its layout, overlap or acceptance thresholds for an unmeasured acquisition. No source file is edited; choose a new output folder outside the acquisition. Full-well validation, segmentation, sequencing-cycle registration, barcode decoding and biological hit analysis are outside this lesson's demonstrated scope.", "scenes": [{"visual": "gui_00_home", "narration": "Optical pooled screening begins with images acquired across neighboring fields and repeated imaging cycles. In spaCR, open Mask to find the nested OPS screen. This lesson shows its location and a small, verified image-alignment example.", "focus_modules": ["mask"], "related_lessons": ["05_home", "07_mask"], "hold_after": 0.7}, {"visual": "gui_01_mask_host", "narration": "Use the OPS toggle in Mask's action row. It opens a separate page inside the host module. OPS is not a second Home tile, and it is not the Map Barcodes workflow for sequencing read files.", "hold_after": 0.7}, {"visual": "gui_02_ops_settings", "narration": "The current OPS page exposes input, stitching, mosaic, alignment and quality-control settings. Its Run button uses a different, legacy engine. We do not start it here or imply that a complete screening pipeline has been validated. The next steps use the geometry APIs directly.", "focus": [340, 170, 1210, 1310], "hold_after": 0.7}, {"visual": "api_00_scope", "narration": "This CPU demonstration registers and composes four real image tiles from an existing acquisition. It does not segment cells, decode barcodes or process a whole plate. The original acquisition is not a bundled test download; exact reproduction requires authorized access to those files.", "focus": [200, 100, 3440, 800], "related_lessons": ["06_api"], "hold_after": 0.7}, {"visual": "api_01_inputs", "narration": "Select sites zero, one, ten and eleven from the first imaging cycle. Each original file has five planes; plane zero contains the nuclear stain. Keep the original three hundred thirty-three-site layout and site numbers. Four selected tiles do not define a new four-tile well.", "focus": [200, 100, 3440, 1000], "hold_after": 0.7}, {"visual": "api_02_geometry", "narration": "The helper calls stitch_well, checks all four neighboring overlaps, and then calls compose_window. All four tiles are placed. Their patch is two thousand seven hundred fifty-six pixels square. The loop closes within a quarter pixel in this acquisition, not a universal accuracy guarantee.", "focus": [200, 100, 3440, 900], "hold_after": 0.7}, {"visual": "api_03_independent_checks", "narration": "Do not trust placement alone. Compare actual overlapping pixels independently of the registration score. Here, aligned correlations are much stronger than correlations after deliberately shifting either axis by seventeen pixels. Those wrong-offset controls help detect a plausible-looking but incorrect placement.", "focus": [200, 100, 3440, 1000], "hold_after": 0.7}, {"visual": "api_05_geometry_figure", "narration": "Inspect the actual saved image and coverage map. The left panel shows the composed nuclear image; the right counts contributing tiles. Zero coverage means no acquisition pixel, not biological background. This combines spatial neighbors within one plane, never different sequencing cycles.", "focus": [600, 390, 2630, 1400], "hold_after": 0.7}, {"visual": "api_04_provenance", "narration": "Save the array, coverage, placements, source checksums and run report together. The helper reopens its outputs and confirms all four source files are unchanged. Treat this as a reproducible geometry checkpoint. A full optical screening tutorial still needs separately validated downstream stages.", "focus": [200, 100, 3440, 1100], "hold_after": 0.7}], "poster": "76_ops/poster.jpg", "silent": "76_ops/video/76_ops_silent.mp4"}]});
